  // Admin endpoint to fully purge user(s) and all related rows.
  // POST { userIds: string[] }. Auth: isAuthenticated + isAdmin. Refuses to delete admins or the requester.
  app.post("/api/admin/purge-users", isAuthenticated, async (req: any, res) => {
    try {
      const requesterId = await getEffectiveUserId(req);
      const [requester] = await db.select({ isAdmin: users.isAdmin }).from(users).where(eq(users.id, requesterId));
      if (!requester?.isAdmin) return res.status(403).json({ message: "Admin only" });

      const userIds = Array.isArray(req.body?.userIds) ? req.body.userIds.filter((x: any) => typeof x === 'string') : [];
      if (userIds.length === 0) return res.status(400).json({ message: "userIds required" });

      const targets = await db.select({ id: users.id, email: users.email, isAdmin: users.isAdmin })
        .from(users).where(inArray(users.id, userIds));
      const blocked = targets.filter(t => t.isAdmin || t.id === requesterId);
      if (blocked.length > 0) {
        return res.status(400).json({ message: "Cannot purge admins or yourself", blocked: blocked.map(b => b.email) });
      }
      const validIds = targets.map(t => t.id);
      if (validIds.length === 0) return res.status(404).json({ message: "No matching users" });

      // Tables with user_id column
      const userIdTables = [
        'affiliates','ai_actions','ai_assistant_calls','ai_assistant_usage','ai_message_drafts',
        'appointment_reminders','appointment_sessions','appointments','blocked_numbers','booking_forms',
        'booking_requests','campaigns','client_error_logs','color_submissions','communications',
        'company_settings','company_users','contacts','crew_group_members','crew_groups',
        'crew_receipt_submissions','device_tokens','document_photos','documents','employee_overhead_costs',
        'feature_requests','financial_settings','game_plan_queue','gift_card_requests','job_schedule_dates',
        'jobs','manual_labor_entries','materials','message_templates','notifications','onboarding_bookings',
        'overhead_expenses','package_features_library','paint_orders','payments','production_calculators',
        'project_activities','project_color_groups','project_color_selections','project_crew_assignments',
        'project_crew_note_reads','project_expense_photos','project_expenses','projects','proposal_packages',
        'proposal_templates','proposal_upsells','push_subscriptions','refresh_tokens','scheduled_automations',
        'scheduled_messages','service_templates','shared_photo_links','suppliers','support_messages',
        'surfaces','tax_profiles','team_members','team_message_reads','templates','time_entries',
        'work_order_settings','work_orders',
      ];
      // Tables with owner_id pointing to users
      const ownerIdTables = ['company_invitations','company_users','crew_receipt_submissions'];

      const results: Record<string, number> = {};
      for (const table of userIdTables) {
        const ident = sql.identifier(table);
        const r: any = await db.execute(sql`DELETE FROM ${ident} WHERE user_id = ANY(${validIds}::text[])`);
        results[table] = r.rowCount ?? 0;
      }
      for (const table of ownerIdTables) {
        const ident = sql.identifier(table);
        const r: any = await db.execute(sql`DELETE FROM ${ident} WHERE owner_id = ANY(${validIds}::text[])`);
        results[`${table}(owner_id)`] = (results[`${table}(owner_id)`] ?? 0) + (r.rowCount ?? 0);
      }
      const userDel: any = await db.execute(sql`DELETE FROM users WHERE id = ANY(${validIds}::text[])`);
      results['users'] = userDel.rowCount ?? 0;

      console.log(`[admin/purge-users] requester=${requesterId} purged=${JSON.stringify(targets.map(t => t.email))} counts=${JSON.stringify(results)}`);
      res.json({ success: true, purged: targets.map(t => ({ id: t.id, email: t.email })), counts: results });
    } catch (err: any) {
      console.error('[admin/purge-users] failed:', err);
      res.status(500).json({ success: false, error: err?.message || String(err) });
    }
  });

