  // One-shot backfill for legacy proposals/estimates/change_orders that
  // pre-date the publish-snapshot feature. They have a valid public token
  // already in the customer's inbox but published_at IS NULL, so the customer
  // portal returns 404 when the customer reopens the link. This endpoint
  // copies content/totalAmount into the snapshot fields and sets published_at
  // = COALESCE(updated_at, created_at, NOW()) — using updated_at keeps the
  // contractor-side "Unpublished changes" banner quiet (it only triggers when
  // updated_at > published_at + 2s). Idempotent: only touches rows still
  // missing the snapshot. Protected by ADMIN_SETUP_KEY (same pattern as the
  // other admin endpoints in this file).
  app.post("/api/admin/backfill-document-publish-snapshots", async (req, res) => {
    const expectedKey = process.env.ADMIN_SETUP_KEY;
    if (!expectedKey) {
      return res.status(503).json({ message: 'ADMIN_SETUP_KEY not configured' });
    }
    const adminKey = req.query.key || req.body?.key;
    if (adminKey !== expectedKey) return res.status(403).json({ message: 'Unauthorized' });

    try {
      const before = await db.execute<{ type: string; total: number; unpublished: number; published: number }>(sql`
        SELECT type,
               COUNT(*)::int AS total,
               COUNT(*) FILTER (WHERE published_at IS NULL)::int AS unpublished,
               COUNT(*) FILTER (WHERE published_at IS NOT NULL)::int AS published
        FROM documents
        WHERE type IN ('proposal', 'estimate', 'change_order')
        GROUP BY type
        ORDER BY type
      `);

      const updated = await db.execute<{ id: number }>(sql`
        UPDATE documents
        SET published_content = content,
            published_total_amount = total_amount,
            published_at = COALESCE(updated_at, created_at, NOW())
        WHERE type IN ('proposal', 'estimate', 'change_order')
          AND published_at IS NULL
        RETURNING id
      `);

      const after = await db.execute<{ type: string; total: number; unpublished: number; published: number }>(sql`
        SELECT type,
               COUNT(*)::int AS total,
               COUNT(*) FILTER (WHERE published_at IS NULL)::int AS unpublished,
               COUNT(*) FILTER (WHERE published_at IS NOT NULL)::int AS published
        FROM documents
        WHERE type IN ('proposal', 'estimate', 'change_order')
        GROUP BY type
        ORDER BY type
      `);

      const updatedCount = updated.rows.length;
      console.log(`[Admin Backfill] Publish-snapshot backfill: updated ${updatedCount} document(s).`);
      res.json({
        success: true,
        updatedCount,
        before: before.rows,
        after: after.rows,
      });
    } catch (err: any) {
      console.error('[Admin Backfill] Publish-snapshot backfill failed:', err);
      res.status(500).json({ error: err.message });
    }
  });

