  app.post('/api/admin/fix-mms/:commId', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const commId = parseInt(req.params.commId);
      const { messageSid } = req.body;

      const settings = await storage.getCompanySettings(userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken) {
        return res.status(400).json({ message: 'Twilio not configured' });
      }

      const twilioAuth = Buffer.from(`${settings.twilioAccountSid}:${settings.twilioAuthToken}`).toString('base64');
      const mediaListRes = await fetch(
        `https://api.twilio.com/2010-04-01/Accounts/${settings.twilioAccountSid}/Messages/${messageSid}/Media.json`,
        { headers: { 'Authorization': `Basic ${twilioAuth}` } }
      );
      const mediaList = await mediaListRes.json();

      if (!mediaList.media_list || mediaList.media_list.length === 0) {
        return res.status(404).json({ message: 'No media found for this message' });
      }

      const media = mediaList.media_list[0];
      const mediaUrl = `https://api.twilio.com/2010-04-01/Accounts/${settings.twilioAccountSid}/Messages/${messageSid}/Media/${media.sid}`;
      const contentType = media.content_type;
      const mediaType = contentType?.startsWith('image/') ? 'image' : contentType?.startsWith('video/') ? 'video' : 'file';

      await storage.updateCommunication(commId, { mediaUrl, mediaType });

      res.json({ success: true, mediaUrl, mediaType, contentType });
    } catch (err: any) {
      console.error('[Fix MMS] Error:', err);
      res.status(500).json({ message: err.message });
    }
  });

