  app.put(api.companySettings.update.path, isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const input = api.companySettings.update.input.parse(req.body);

      if (input.aiSmsMode && !['suggest_only', 'auto_respond'].includes(input.aiSmsMode)) {
        return res.status(400).json({ message: "Invalid SMS mode" });
      }
      if (input.aiSmsResponseDelay != null) {
        input.aiSmsResponseDelay = Math.max(10, Math.min(120, input.aiSmsResponseDelay));
      }

      if (input.logo && typeof input.logo === 'string' && input.logo.startsWith('data:')) {
        try {
          const hostedUrl = await uploadBase64LogoToStorage(userId, input.logo);
          if (hostedUrl) {
            input.logo = hostedUrl;
          } else {
            delete input.logo;
            console.warn('[Logo Upload] Could not convert base64 logo, skipping logo update');
          }
        } catch (logoErr) {
          delete input.logo;
          console.error('[Logo Upload] Failed to upload logo to object storage:', logoErr);
        }
      }
      
      if (input.bookingSlug) {
        const slug = input.bookingSlug.toLowerCase().replace(/[^a-z0-9-]/g, '').replace(/-+/g, '-').replace(/^-+|-+$/g, '');
        if (slug.length < 3) {
          return res.status(400).json({ message: "Booking URL must be at least 3 characters" });
        }
        const available = await storage.isSlugAvailable(slug, userId);
        if (!available) {
          return res.status(409).json({ message: "This booking URL is already taken" });
        }
        input.bookingSlug = slug;
      }
      
      // Auto-generate booking slug from company name if none exists yet
      if (input.companyName && !input.bookingSlug) {
        const existingSettings = await storage.getCompanySettings(userId);
        if (!existingSettings?.bookingSlug && input.companyName !== 'My Company') {
          const compactSlug = generateSlugCompact(input.companyName);
          if (compactSlug && compactSlug.length >= 3) {
            if (await storage.isSlugAvailable(compactSlug, userId)) {
              input.bookingSlug = compactSlug;
            } else {
              const hyphenatedSlug = generateSlugHyphenated(input.companyName);
              if (hyphenatedSlug !== compactSlug && await storage.isSlugAvailable(hyphenatedSlug, userId)) {
                input.bookingSlug = hyphenatedSlug;
              } else {
                const suggestions = generateSlugSuggestions(compactSlug);
                for (const s of suggestions) {
                  if (await storage.isSlugAvailable(s, userId)) {
                    input.bookingSlug = s;
                    break;
                  }
                }
              }
            }
          }
        }
      }
      
      const settings = await storage.updateCompanySettings(userId, input);
      emitToUser(userId, userId, { type: "settings.updated", tenantId: userId });
      res.json(settings);
    } catch (err) {
      if (err instanceof z.ZodError) {
        return res.status(400).json({ message: err.errors[0].message });
      }
      throw err;
    }
  });

