  // Slug availability check
  app.get("/api/settings/check-slug", isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const slug = req.query.slug as string;
      if (!slug || slug.length < 3) {
        return res.json({ available: false, suggestions: [] });
      }
      const normalizedSlug = slug.toLowerCase().replace(/[^a-z0-9-]/g, '').replace(/-+/g, '-').replace(/^-+|-+$/g, '');
      if (!normalizedSlug || normalizedSlug.length < 3) {
        return res.json({ available: false, suggestions: [] });
      }
      const available = await storage.isSlugAvailable(normalizedSlug, userId);
      let suggestions: string[] = [];
      if (!available) {
        const allSuggestions = generateSlugSuggestions(normalizedSlug);
        for (const s of allSuggestions) {
          if (await storage.isSlugAvailable(s, userId)) {
            suggestions.push(s);
          }
          if (suggestions.length >= 3) break;
        }
      }
      res.json({ available, slug: normalizedSlug, suggestions });
    } catch (err) {
      res.status(500).json({ message: "Failed to check slug" });
    }
  });

  // Generate slug from company name
  app.post("/api/settings/generate-slug", isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const { companyName } = req.body;
      if (!companyName) {
        return res.status(400).json({ message: "Company name is required" });
      }
      const compactSlug = generateSlugCompact(companyName);
      const hyphenatedSlug = generateSlugHyphenated(companyName);
      if (!compactSlug || compactSlug.length < 2) {
        return res.status(400).json({ message: "Company name too short for a URL" });
      }
      if (await storage.isSlugAvailable(compactSlug, userId)) {
        return res.json({ slug: compactSlug, available: true, suggestions: [] });
      }
      if (hyphenatedSlug !== compactSlug && await storage.isSlugAvailable(hyphenatedSlug, userId)) {
        return res.json({ slug: hyphenatedSlug, available: true, suggestions: [] });
      }
      const allSuggestions = [
        ...generateSlugSuggestions(compactSlug),
        ...generateSlugSuggestions(hyphenatedSlug),
      ];
      const seen = new Set<string>();
      const validSuggestions: string[] = [];
      for (const s of allSuggestions) {
        if (seen.has(s)) continue;
        seen.add(s);
        if (await storage.isSlugAvailable(s, userId)) {
          validSuggestions.push(s);
        }
        if (validSuggestions.length >= 3) break;
      }
      res.json({ slug: compactSlug, available: false, suggestions: validSuggestions });
    } catch (err) {
      res.status(500).json({ message: "Failed to generate slug" });
    }
  });

  // === Financial Settings ===
  app.get("/api/financial-settings", isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const settings = await storage.getFinancialSettings(userId);
      const expenses = await storage.getOverheadExpenses(userId);
      const employeeOverheadCosts = await storage.getEmployeeOverheadCosts(userId);

      let computedSellRate = settings?.sellRatePerHour ?? 0;
      if (settings) {
        const members = await storage.getTeamMembers(userId);
        const productionMembers = members.filter((m: any) => m.role === 'production' || m.role === 'owner');
        const crewSize = productionMembers.length;

        let laborCost = settings.manualLaborCostPerHour ?? 0;
        if (settings.useProductionTeamForLaborCost !== false && crewSize > 0) {
          const burden = settings.payrollBurdenPercentage ?? 0.12;
          const wc = settings.workersCompPercentage ?? 0.18;
          const benefits = settings.benefitsPerHour ?? 0;
          let totalTrueCost = 0;
          for (const m of productionMembers) {
            const base = (m as any).hourlyRate ?? 0;
            const empOverhead = employeeOverheadCosts.filter((e: any) => e.teamMemberId === m.id);
            const monthlyEmpOH = empOverhead.reduce((s: number, e: any) => {
              const amt = e.monthlyCost ?? 0;
              const freq = e.frequency ?? 'monthly';
              if (freq === 'weekly') return s + amt * 4.33;
              if (freq === 'quarterly') return s + amt / 3;
              if (freq === 'yearly') return s + amt / 12;
              return s + amt;
            }, 0);
            totalTrueCost += base * (1 + burden + wc) + benefits + (monthlyEmpOH / 160);
          }
          laborCost = totalTrueCost / crewSize;
        }

        let totalMonthlyOverhead = 0;
        for (const exp of expenses) {
          const amt = (exp as any).amount ?? 0;
          const freq = (exp as any).frequency ?? 'monthly';
          if (freq === 'weekly') totalMonthlyOverhead += amt * 4.33;
          else if (freq === 'quarterly') totalMonthlyOverhead += amt / 3;
          else if (freq === 'yearly') totalMonthlyOverhead += amt / 12;
          else totalMonthlyOverhead += amt;
        }
        const overheadPerHour = crewSize > 0 ? totalMonthlyOverhead / (160 * crewSize) : 0;

        const netPct = settings.targetNetProfitPercentage ?? 0.2;
        if (netPct > 0 && netPct < 1 && (laborCost > 0 || overheadPerHour > 0)) {
          computedSellRate = (laborCost + overheadPerHour) / (1 - netPct);
        }

        if (computedSellRate > 0 && computedSellRate !== (settings.sellRatePerHour ?? 0)) {
          await storage.updateFinancialSettings(userId, { sellRatePerHour: computedSellRate });
        }
      }

      const settingsWithRate = settings ? { ...settings, sellRatePerHour: computedSellRate } : null;
      res.json({ settings: settingsWithRate, expenses, employeeOverheadCosts });
    } catch (err) {
      console.error("[FinancialSettings GET] Error:", err);
      res.status(500).json({ message: "Failed to load financial settings" });
    }
  });

