      const passthrough = new Set(['serviceSectionTypes', 'customCategoriesByService', 'useProductionTeamForLaborCost', 'defaultShowLaborHrs', 'defaultShowLaborPrice', 'defaultShowMaterialQty', 'defaultShowMaterialPrice', 'defaultShowSurfaceDetails', 'defaultSameColorAllAreas', 'defaultsPopulated']);
