  app.post("/api/production-calculators", isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const { name, surfaceId, materialId, teamMemberId, painters } = req.body;
      if (!name || typeof name !== 'string' || !name.trim()) {
        return res.status(400).json({ message: "Calculator name is required" });
      }
      const painterEntries = Array.isArray(painters) ? painters.slice(0, 5) : [{ name: "Painter 1" }];
      const rates = painterEntries.map((p: any) => {
        if (p.sqftPerHour && p.sqftPerHour > 0) return p.sqftPerHour;
        if (p.areaPainted && p.timeTaken && p.timeTaken > 0) return p.areaPainted / p.timeTaken;
        return 0;
      }).filter((r: number) => r > 0);
      const averageRate = rates.length > 0 ? rates.reduce((a: number, b: number) => a + b, 0) / rates.length : 0;

      let validatedTeamMemberId = null;
      if (teamMemberId) {
        const tmId = parseInt(teamMemberId);
        if (!isNaN(tmId)) {
          const [member] = await db.select().from(teamMembers).where(and(eq(teamMembers.id, tmId), eq(teamMembers.userId, userId)));
          if (member) validatedTeamMemberId = tmId;
        }
      }

      const [calc] = await db.insert(productionCalculators).values({
        userId,
        name: name.trim(),
        surfaceId: surfaceId || null,
        materialId: materialId || null,
        teamMemberId: validatedTeamMemberId,
        painters: painterEntries,
        averageRate: Math.round(averageRate * 100) / 100,
        useAsProductionRate: false,
      }).returning();
      emitToUser(userId, userId, { type: "settings.updated", tenantId: userId });
      res.json(calc);
    } catch (err) {
      res.status(500).json({ message: "Failed to create calculator" });
    }
  });

  app.put("/api/production-calculators/:id", isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ message: "Invalid ID" });

      const existing = await db.select().from(productionCalculators).where(and(eq(productionCalculators.id, id), eq(productionCalculators.userId, userId)));
      if (!existing.length) return res.status(404).json({ message: "Not found" });

      const updates: Record<string, any> = {};
      if (req.body.name !== undefined) {
        if (typeof req.body.name !== 'string' || !req.body.name.trim()) return res.status(400).json({ message: "Name must be a non-empty string" });
        updates.name = req.body.name.trim();
      }
      if (req.body.surfaceId !== undefined) updates.surfaceId = req.body.surfaceId || null;
      if (req.body.materialId !== undefined) updates.materialId = req.body.materialId || null;
      if (req.body.teamMemberId !== undefined) {
        if (req.body.teamMemberId) {
          const tmId = parseInt(req.body.teamMemberId);
          if (!isNaN(tmId)) {
            const [member] = await db.select().from(teamMembers).where(and(eq(teamMembers.id, tmId), eq(teamMembers.userId, userId)));
            updates.teamMemberId = member ? tmId : null;
          } else {
            updates.teamMemberId = null;
          }
        } else {
          updates.teamMemberId = null;
        }
      }
      if (req.body.painters !== undefined) {
        const painterEntries = Array.isArray(req.body.painters) ? req.body.painters.slice(0, 5) : [];
        updates.painters = painterEntries;
        const rates = painterEntries.map((p: any) => {
          if (p.sqftPerHour && p.sqftPerHour > 0) return p.sqftPerHour;
          if (p.areaPainted && p.timeTaken && p.timeTaken > 0) return p.areaPainted / p.timeTaken;
          return 0;
        }).filter((r: number) => r > 0);
        updates.averageRate = rates.length > 0 ? Math.round((rates.reduce((a: number, b: number) => a + b, 0) / rates.length) * 100) / 100 : 0;
      }
      if (req.body.useAsProductionRate !== undefined) {
        updates.useAsProductionRate = !!req.body.useAsProductionRate;
      }

      const [updated] = await db.update(productionCalculators).set(updates).where(and(eq(productionCalculators.id, id), eq(productionCalculators.userId, userId))).returning();

      const calcData = updated;
      if (calcData.useAsProductionRate && calcData.surfaceId && calcData.averageRate > 0) {
        await db.update(surfaces).set({ productionRateUnitsPerLaborHour: calcData.averageRate }).where(and(eq(surfaces.id, calcData.surfaceId), eq(surfaces.userId, userId)));
        emitToUser(userId, userId, { type: "surfaces.updated", tenantId: userId });
      }
      emitToUser(userId, userId, { type: "settings.updated", tenantId: userId });
      res.json(updated);
    } catch (err) {
      res.status(500).json({ message: "Failed to update calculator" });
    }
  });

