  app.get("/api/public/custom-domain/document/:docType/:docId", async (req, res) => {
    try {
      const { docType, docId } = req.params;
      const workerAuth = req.get('x-worker-auth');
      const customDomainHeader = req.get('x-custom-domain');
      const hostHeader = req.get('host') || '';
      const host = (workerAuth === process.env.WORKER_AUTH_SECRET && customDomainHeader)
        ? customDomainHeader
        : hostHeader;

      const normalizedType = docType === 'change-order' ? 'change_order' : docType;
      const validTypes = ['proposal', 'estimate', 'invoice', 'change_order'];
      if (!docType || !validTypes.includes(normalizedType)) {
        return res.status(400).json({ message: "Invalid link" });
      }

      const cleanHost = host.replace(/:\d+$/, '').toLowerCase();
      const allSettings = await db.select().from(companySettings).where(
        and(eq(companySettings.customDomain, cleanHost), eq(companySettings.customDomainVerified, true))
      );
      if (!allSettings.length) {
        return res.status(404).json({ message: "Domain not found" });
      }
      const settings = allSettings[0];

      const docIdNum = parseInt(docId, 10);
      let docs;
      if (!isNaN(docIdNum) && String(docIdNum) === docId) {
        docs = await db.select().from(documents).where(
          and(eq(documents.id, docIdNum), eq(documents.userId, settings.userId), eq(documents.type, normalizedType))
        );
      } else {
        docs = await db.select().from(documents).where(
          and(eq(documents.publicToken, docId), eq(documents.userId, settings.userId), eq(documents.type, normalizedType))
        );
      }
      if (!docs.length) {
        return res.status(404).json({ message: "Document not found" });
      }

      res.json({ token: docs[0].publicToken });
    } catch (err) {
      console.error("[CustomDomain] Error resolving document:", err);
      res.status(500).json({ message: "Failed to load document" });
    }
  });

