  // Communications
  app.get(api.communications.list.path, isAuthenticated, async (req, res) => {
    const userId = await getEffectiveUserId(req);
    const contactId = req.query.contactId ? Number(req.query.contactId) : undefined;
    const comms = await storage.getCommunications(userId, contactId);

    if (contactId) {
      try {
        const userProjects = await storage.getProjects(userId, { contactId });
        for (const project of userProjects) {
          const allRecips = await db.select().from(projectRecipients)
            .where(eq(projectRecipients.projectId, project.id));
          const otherRecips = allRecips.filter(r => r.contactId && r.contactId !== contactId && r.role === 'additional');
          if (otherRecips.length > 0) {
            const recipContactIds = otherRecips.map(r => r.contactId!);
            const recipNameMap = new Map<number, string>();
            for (const r of otherRecips) {
              if (r.contactId && r.name) {
                recipNameMap.set(r.contactId, r.name.split(' ')[0]);
              }
            }
            const recipComms = await db.select().from(communications)
              .where(and(
                eq(communications.userId, userId),
                inArray(communications.contactId, recipContactIds),
                isNull(communications.projectId)
              ))
              .orderBy(desc(communications.timestamp));
            const filtered = recipComms.filter(msg => {
              const msgContactId = msg.contactId;
              if (!msgContactId) return false;
              const entries = otherRecips.filter(r => r.contactId === msgContactId);
              const msgTime = new Date(msg.timestamp || 0).getTime();
              return entries.some(entry => {
                const addedTime = entry.createdAt ? new Date(entry.createdAt).getTime() : 0;
                const removedTime = entry.removedAt ? new Date(entry.removedAt).getTime() : Infinity;
                return msgTime >= addedTime && msgTime <= removedTime;
              });
            });
            if (filtered.length > 0) {
              const seen = new Set(comms.map(c => c.id));
              for (const fc of filtered) {
                if (!seen.has(fc.id)) {
                  const senderName = fc.contactId ? recipNameMap.get(fc.contactId) : undefined;
                  comms.push({ ...fc, senderName: senderName || undefined } as any);
                  seen.add(fc.id);
                }
              }
            }
          }
        }
        if (comms.length > 0) {
          comms.sort((a, b) => new Date(b.timestamp || 0).getTime() - new Date(a.timestamp || 0).getTime());
        }
      } catch (err) {
        console.error('[Communications] Failed to merge recipient messages:', err);
      }
    }

    res.json(comms);
  });
  
  app.get('/api/communications/calls', isAuthenticated, async (req, res) => {
    const userId = await getEffectiveUserId(req);
    const comms = await storage.getCommunications(userId);
    const blocked = await storage.getBlockedNumbers(userId);
    const blockedSet = new Set(blocked.map(b => b.phoneNumber.replace(/\D/g, '').slice(-10)));
    const calls = comms
      .filter(c => c.type === 'call')
      .filter(c => {
        if (!c.phoneNumber) return true;
        const normalized = c.phoneNumber.replace(/\D/g, '').slice(-10);
        return !blockedSet.has(normalized);
      })
      .sort((a, b) => new Date(b.timestamp || 0).getTime() - new Date(a.timestamp || 0).getTime());
    res.json(calls);
  });

