  app.get('/api/communications/conversation-contacts', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      // NOTE: When the contact has unread inbound messages, prefer the
      // latest UNREAD INBOUND row for the inbox preview (content +
      // direction + type). This keeps "📋 New Booking Request" (and any
      // other inbound that needs attention) visible in the inbox even
      // after we fire an automated outbound auto-reply 1s later. Without
      // this, the outbound text would hijack the preview and the row
      // would look like a normal handled conversation — causing missed
      // bookings. last_message_time still reflects the absolute latest
      // message so sort order is correct.
      // NOTE: We deliberately do NOT filter by `project_id IS NULL` here.
      // The conversation tray must show every contact's TRUE latest
      // message (direct OR project-tagged) so the preview never lags
      // behind reality. Previously the project_id filters caused
      // contacts whose recent messages were sent in a project context
      // to appear stuck on an old direct message preview, or be hidden
      // from the tray entirely. The project-conversations endpoint
      // still groups messages by project for the project-only view.
      const result = await db.execute(sql`
        SELECT c.*,
          MAX(cm.timestamp) as last_message_time,
          (SELECT cm2.content FROM communications cm2 
           WHERE cm2.contact_id = c.id AND cm2.user_id = ${userId} AND cm2.type IN ('sms', 'email')
           AND (
             NOT EXISTS (SELECT 1 FROM communications cmU WHERE cmU.contact_id = c.id AND cmU.user_id = ${userId} AND cmU.type IN ('sms', 'email') AND cmU.direction = 'inbound' AND cmU.is_read = false)
             OR (cm2.direction = 'inbound' AND cm2.is_read = false)
           )
           ORDER BY cm2.timestamp DESC LIMIT 1) as last_message,
          (SELECT cm2.direction FROM communications cm2 
           WHERE cm2.contact_id = c.id AND cm2.user_id = ${userId} AND cm2.type IN ('sms', 'email')
           AND (
             NOT EXISTS (SELECT 1 FROM communications cmU WHERE cmU.contact_id = c.id AND cmU.user_id = ${userId} AND cmU.type IN ('sms', 'email') AND cmU.direction = 'inbound' AND cmU.is_read = false)
             OR (cm2.direction = 'inbound' AND cm2.is_read = false)
           )
           ORDER BY cm2.timestamp DESC LIMIT 1) as last_message_direction,
          (SELECT cm2.type FROM communications cm2 
           WHERE cm2.contact_id = c.id AND cm2.user_id = ${userId} AND cm2.type IN ('sms', 'email')
           AND (
             NOT EXISTS (SELECT 1 FROM communications cmU WHERE cmU.contact_id = c.id AND cmU.user_id = ${userId} AND cmU.type IN ('sms', 'email') AND cmU.direction = 'inbound' AND cmU.is_read = false)
             OR (cm2.direction = 'inbound' AND cm2.is_read = false)
           )
           ORDER BY cm2.timestamp DESC LIMIT 1) as last_message_type,
          (SELECT cm2.id FROM communications cm2 
           WHERE cm2.contact_id = c.id AND cm2.user_id = ${userId} AND cm2.type IN ('sms', 'email')
           AND (
             NOT EXISTS (SELECT 1 FROM communications cmU WHERE cmU.contact_id = c.id AND cmU.user_id = ${userId} AND cmU.type IN ('sms', 'email') AND cmU.direction = 'inbound' AND cmU.is_read = false)
             OR (cm2.direction = 'inbound' AND cm2.is_read = false)
           )
           ORDER BY cm2.timestamp DESC LIMIT 1) as last_message_id,
          (SELECT COUNT(*) FROM communications cm3 
           WHERE cm3.contact_id = c.id AND cm3.user_id = ${userId} AND cm3.type IN ('sms', 'email')
           AND cm3.direction = 'inbound' AND cm3.is_read = false)::int as unread_count,
          (SELECT pr.project_id FROM project_recipients pr
           INNER JOIN projects p ON p.id = pr.project_id AND p.user_id = ${userId}
           WHERE pr.contact_id = c.id AND pr.role = 'additional' AND pr.removed_at IS NULL
           LIMIT 1) as recipient_of_project_id,
          (SELECT pr2.name FROM project_recipients pr2
           INNER JOIN projects p2 ON p2.id = pr2.project_id AND p2.user_id = ${userId}
           WHERE p2.contact_id = c.id AND pr2.role = 'additional' AND pr2.contact_id IS NOT NULL AND pr2.removed_at IS NULL
           ORDER BY pr2.id DESC LIMIT 1
          ) as project_recipient_names
        FROM contacts c
        INNER JOIN communications cm ON cm.contact_id = c.id AND cm.user_id = ${userId} AND cm.type IN ('sms', 'email')
        WHERE c.user_id = ${userId} AND c.archived = false
        GROUP BY c.id
        ORDER BY last_message_time DESC NULLS LAST
      `);
      res.json(result.rows);
    } catch (err) {
      console.error('Failed to get conversation contacts:', err);
      res.status(500).json({ message: "Failed to get conversation contacts" });
    }
  });

  app.get('/api/communications/project-conversations', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const [user] = await db.select().from(users).where(eq(users.id, userId));
      const isElite = user?.isAdmin || user?.subscriptionTier === 'elite' || (user?.eliteBonusEndsAt && user?.eliteBonusEndsAt > new Date());
      if (!isElite) {
        return res.json([]);
      }

      const result = await db.execute(sql`
        WITH projects_with_additional AS (
          SELECT DISTINCT p.id as project_id, p.title as project_name
          FROM projects p
          INNER JOIN project_recipients pr ON pr.project_id = p.id
          WHERE p.user_id = ${userId}
            AND p.stage NOT IN ('completed')
            AND p.archived = false
            AND p.lost_at IS NULL
            AND pr.contact_id IS NOT NULL
            AND pr.role = 'additional'
            AND pr.removed_at IS NULL
        ),
        all_recipients AS (
          SELECT pwa.project_id, pwa.project_name,
            pr.contact_id, pr.name as recipient_name, pr.phone as recipient_phone, pr.role
          FROM projects_with_additional pwa
          INNER JOIN project_recipients pr ON pr.project_id = pwa.project_id
          WHERE pr.contact_id IS NOT NULL
            AND (pr.role != 'additional' OR pr.removed_at IS NULL)
        ),
        project_comms AS (
          SELECT ar.project_id, ar.project_name, ar.contact_id, ar.recipient_name, ar.recipient_phone, ar.role,
            cm.id as comm_id, cm.content, cm.direction, cm.timestamp, cm.is_read
          FROM all_recipients ar
          LEFT JOIN communications cm ON cm.contact_id = ar.contact_id 
            AND cm.user_id = ${userId} AND cm.type = 'sms'
            AND cm.project_id = ar.project_id
        )
        SELECT 
          project_id,
          project_name,
          (SELECT json_agg(r ORDER BY CASE WHEN r->>'role' = 'additional' THEN 1 ELSE 0 END)
           FROM (SELECT DISTINCT jsonb_build_object(
             'contactId', contact_id,
             'name', recipient_name,
             'phone', recipient_phone,
             'role', role
           ) as r FROM project_comms pc_r WHERE pc_r.project_id = project_comms.project_id) sub
          ) as recipients,
          MAX(timestamp) as last_message_time,
          (SELECT content FROM project_comms pc2 
           WHERE pc2.project_id = project_comms.project_id 
           ORDER BY pc2.timestamp DESC NULLS LAST LIMIT 1) as last_message,
          (SELECT direction FROM project_comms pc3 
           WHERE pc3.project_id = project_comms.project_id 
           ORDER BY pc3.timestamp DESC NULLS LAST LIMIT 1) as last_message_direction,
          (SELECT recipient_name FROM project_comms pc4 
           WHERE pc4.project_id = project_comms.project_id AND pc4.direction = 'inbound'
           ORDER BY pc4.timestamp DESC NULLS LAST LIMIT 1) as last_sender_name,
          COALESCE(SUM(CASE WHEN direction = 'inbound' AND is_read = false THEN 1 ELSE 0 END), 0)::int as unread_count
        FROM project_comms
        GROUP BY project_id, project_name
        HAVING MAX(timestamp) IS NOT NULL
        ORDER BY last_message_time DESC NULLS LAST
      `);

      res.json(result.rows);
    } catch (err) {
      console.error('Failed to get project conversations:', err);
      res.status(500).json({ message: "Failed to get project conversations" });
    }
  });

  app.get('/api/communications/project-thread/:projectId', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const projectId = Number(req.params.projectId);
      if (isNaN(projectId)) {
        return res.status(400).json({ message: "Invalid projectId" });
      }

      const [user] = await db.select().from(users).where(eq(users.id, userId));
      const isElite = user?.isAdmin || user?.subscriptionTier === 'elite' || (user?.eliteBonusEndsAt && user?.eliteBonusEndsAt > new Date());
      if (!isElite) {
        return res.status(403).json({ message: "Elite plan required" });
      }

      const recipientRows = await db.select({
        contactId: projectRecipients.contactId,
        name: projectRecipients.name,
        phone: projectRecipients.phone,
      }).from(projectRecipients)
        .where(and(
          eq(projectRecipients.projectId, projectId),
          isNotNull(projectRecipients.contactId)
        ));

      const [proj] = await db.select({ contactId: projects.contactId })
        .from(projects)
        .where(and(eq(projects.id, projectId), eq(projects.userId, userId)));

      const contactIds = recipientRows.map(r => r.contactId!);
      if (proj?.contactId && !contactIds.includes(proj.contactId)) {
        contactIds.push(proj.contactId);
        const [ownerContact] = await db.select({ name: contacts.name, phone: contacts.phone })
          .from(contacts)
          .where(eq(contacts.id, proj.contactId));
        if (ownerContact) {
          recipientRows.push({ contactId: proj.contactId, name: ownerContact.name, phone: ownerContact.phone });
        }
      }
      const contactNameMap = new Map(recipientRows.map(r => [r.contactId!, r.name]));

      const comms = await db.select().from(communications)
        .where(and(
          eq(communications.userId, userId),
          eq(communications.type, 'sms'),
          eq(communications.projectId, projectId)
        ))
        .orderBy(communications.timestamp);

      const deduped: typeof comms = [];
      const seenOutbound: Array<{ content: string; time: number; idx: number }> = [];
      const recipientNamesMap = new Map<number, string[]>();
      for (let i = 0; i < comms.length; i++) {
        const c = comms[i];
        if (c.direction === 'outbound') {
          const time = c.timestamp ? new Date(c.timestamp).getTime() : 0;
          const existing = seenOutbound.find(s => s.content === c.content && Math.abs(s.time - time) < 5000);
          if (existing) {
            const name = c.contactId ? contactNameMap.get(c.contactId) : null;
            if (name) {
              const names = recipientNamesMap.get(existing.idx) || [];
              names.push(name);
              recipientNamesMap.set(existing.idx, names);
            }
            continue;
          }
          seenOutbound.push({ content: c.content || '', time, idx: deduped.length });
        }
        deduped.push(c);
      }

      const enriched = deduped.map((c, idx) => {
        const extraNames = recipientNamesMap.get(idx) || [];
        const primaryName = c.direction === 'outbound' && c.contactId ? contactNameMap.get(c.contactId) || null : null;
        const allNames = primaryName ? [primaryName, ...extraNames] : extraNames;
        return {
          ...c,
          senderName: c.direction === 'inbound' && c.contactId ? contactNameMap.get(c.contactId) || null : null,
          recipientName: allNames.length > 0 ? allNames.join(' & ') : null,
        };
      });

      res.json({
        messages: enriched,
        recipients: recipientRows,
      });
    } catch (err) {
      console.error('Failed to get project thread:', err);
      res.status(500).json({ message: "Failed to get project thread" });
    }
  });

