  app.delete('/api/communications/:id', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const commId = Number(req.params.id);
      if (isNaN(commId)) {
        return res.status(400).json({ message: "Invalid communication ID" });
      }
      const result = await db.delete(communications).where(
        and(eq(communications.id, commId), eq(communications.userId, userId))
      );
      emitToUser(userId, userId, { type: "message.created", tenantId: userId });
      res.json({ success: true });
    } catch (err) {
      console.error('Failed to delete communication:', err);
      res.status(500).json({ message: "Failed to delete message" });
    }
  });

