  // Native Device Token Registration (FCM)
  app.post('/api/push/register-device', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { token, platform, environment } = req.body;
      const apnsEnv = environment === 'sandbox' ? 'sandbox' : 'production';
      console.log(`[Push Debug] Register device request from user ${userId}:`, { 
        platform, 
        environment: apnsEnv,
        tokenLength: token?.length,
        tokenPrefix: token?.substring(0, 20) + '...',
      });
      if (!token || !platform) {
        console.warn('[Push Debug] Missing token or platform in register request');
        return res.status(400).json({ message: 'Token and platform required' });
      }
      if (platform === 'ios' && /^[0-9A-Fa-f]{64}$/.test(token)) {
        console.warn('[Push Debug] REJECTED: Token appears to be raw APNs device token (hex), not FCM token. Token prefix:', token.substring(0, 20));
        return res.status(400).json({ message: 'Raw APNs token rejected. FCM token required for iOS push.' });
      }
      await storage.saveDeviceToken(userId, token, platform, apnsEnv);
      const allTokens = await storage.getDeviceTokens(userId);
      console.log(`[Push Debug] Device token SAVED for ${platform} (${apnsEnv}). User now has ${allTokens.length} registered token(s).`);
      res.json({ success: true, tokenCount: allTokens.length });
    } catch (err: any) {
      console.error('[Push Debug] Device registration error:', {
        message: err?.message,
        code: err?.code,
        detail: err?.detail,
        table: err?.table,
        column: err?.column,
        stack: err?.stack?.substring(0, 300),
      });
      res.status(500).json({ message: 'Failed to register device', detail: err?.message });
    }
  });

