  // Twilio Integration
  app.get(api.twilio.getNumbers.path, isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const settings = await storage.getCompanySettings(userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken) {
        return res.status(400).json({ message: "Twilio credentials not configured" });
      }
      
      const twilio = await import('twilio');
      const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);
      const numbers = await client.incomingPhoneNumbers.list({ limit: 20 });

      let messagingServiceNumbers = new Set<string>();
      try {
        const services = await client.messaging.v1.services.list({ limit: 50 });
        for (const service of services) {
          const serviceNumbers = await client.messaging.v1.services(service.sid).phoneNumbers.list();
          for (const sn of serviceNumbers) {
            messagingServiceNumbers.add(sn.phoneNumber);
          }
        }
      } catch (err) {
        console.warn('[Twilio] Could not check messaging services:', err);
      }
      
      res.json(numbers.map(n => ({
        sid: n.sid,
        phoneNumber: n.phoneNumber,
        friendlyName: n.friendlyName,
        inMessagingService: messagingServiceNumbers.has(n.phoneNumber)
      })));
    } catch (err: any) {
      res.status(400).json({ message: err.message || "Failed to fetch Twilio numbers" });
    }
  });

  app.post(api.twilio.sendSms.path, isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const [tierUser] = await db.select({ tier: users.subscriptionTier, isAdmin: users.isAdmin })
        .from(users).where(eq(users.id, userId));
      let effectiveTier = tierUser?.tier || 'starter';
      if (!tierUser?.isAdmin) {
        const [membership] = await db.select().from(companyUsers)
          .where(and(eq(companyUsers.userId, userId), eq(companyUsers.status, 'active')));
        if (membership) {
          const [owner] = await db.select({ tier: users.subscriptionTier })
            .from(users).where(eq(users.id, membership.ownerId));
          if (owner?.tier) effectiveTier = owner.tier;
        }
      }
      const isElite = effectiveTier === 'elite' || effectiveTier === 'early_access';
      const allowed = !!tierUser?.isAdmin || isElite;
      if (!allowed) {
        return res.status(403).json({
          message: "SMS messaging requires the Elite plan. Upgrade to send texts to customers.",
          code: 'TIER_REQUIRED',
          requiredTier: 'elite',
        });
      }
      const { to, body, contactId, mediaUrl, mediaUrls: rawMediaUrls, mediaContentTypes: rawContentTypes, projectId: reqProjectId, skipAutoSend: reqSkipAutoSend } = req.body;
      console.log(`[SMS] send-sms called: to=${to}, contactId=${contactId}, projectId=${reqProjectId}, skipAutoSend=${reqSkipAutoSend}`);
      const resolvedMediaUrls: string[] = rawMediaUrls && Array.isArray(rawMediaUrls) && rawMediaUrls.length > 0
        ? rawMediaUrls
        : mediaUrl ? [mediaUrl] : [];
      const resolvedContentTypes: string[] = rawContentTypes && Array.isArray(rawContentTypes) ? rawContentTypes : [];
      const settings = await storage.getCompanySettings(userId);
      
      if (!settings) {
        return res.status(400).json({ message: "Company settings not found" });
      }

      const { sendSms } = await import('./sms-provider.js');
      const provider = settings.phoneProvider || 'twilio';

      if (provider === 'openphone') {
        if (!settings.openphoneApiKey || !settings.openphonePhoneNumber) {
          return res.status(400).json({ message: "OpenPhone not fully configured" });
        }
      } else {
        if (!settings.twilioAccountSid || !settings.twilioAuthToken || !settings.twilioPhoneNumber) {
          return res.status(400).json({ message: "Twilio not fully configured" });
        }
      }

      const replitDomains = process.env.REPLIT_DOMAINS || process.env.REPLIT_DEV_DOMAIN || '';
      const primaryDomain = replitDomains.split(',')[0]?.trim() || req.headers.host || '';
      const baseUrl = `https://${primaryDomain}`;

      const twilioMediaUrls = resolvedMediaUrls.map(u => {
        if (u.startsWith('/objects/') || u.startsWith('/uploads/')) {
          return `${baseUrl}${u}`;
        }
        return u;
      });

      const result = await sendSms(settings, {
        to,
        body: body || '',
        mediaUrl: twilioMediaUrls.length > 0 ? twilioMediaUrls : undefined,
      });

      if (!result.success) {
        return res.status(400).json({ message: result.error || "Failed to send SMS" });
      }
      
      const primaryMediaUrl = resolvedMediaUrls[0] || null;
      let mediaType: string | undefined;
      if (resolvedContentTypes.length > 0) {
        const typeSet = new Set<string>();
        for (const ct of resolvedContentTypes) {
          if (ct.startsWith('image/')) typeSet.add('image');
          else if (ct.startsWith('video/')) typeSet.add('video');
          else if (ct.startsWith('audio/')) typeSet.add('audio');
          else if (ct === 'application/pdf') typeSet.add('pdf');
        }
        if (typeSet.size > 1) mediaType = 'mixed';
        else if (typeSet.size === 1) mediaType = [...typeSet][0];
      }
      if (!mediaType && primaryMediaUrl) {
        const ext = primaryMediaUrl.split('.').pop()?.toLowerCase();
        if (['jpg', 'jpeg', 'png', 'gif', 'webp'].includes(ext || '')) mediaType = 'image';
        else if (['mp3', 'wav', 'ogg', 'm4a'].includes(ext || '')) mediaType = 'audio';
        else if (ext === 'pdf') mediaType = 'pdf';
      }
      
      let effectiveProjectId = reqProjectId ? Number(reqProjectId) : null;
      
      if (contactId && req.body.skipAutoSend) {
        try {
          if (!effectiveProjectId) {
            const [recipRow] = await db.select({ projectId: projectRecipients.projectId })
              .from(projectRecipients)
              .where(and(
                eq(projectRecipients.contactId, contactId),
                isNull(projectRecipients.removedAt)
              ))
              .limit(1);
            if (recipRow?.projectId) {
              const [proj] = await db.select({ id: projects.id })
                .from(projects)
                .where(and(eq(projects.id, recipRow.projectId), eq(projects.userId, userId)));
              if (proj) {
                effectiveProjectId = recipRow.projectId;
                console.log(`[SMS] Auto-detected projectId=${effectiveProjectId} (contact is recipient)`);
              }
            }
          }
          if (!effectiveProjectId) {
            const [ownerProj] = await db.select({ id: projects.id })
              .from(projects)
              .where(and(
                eq(projects.contactId, contactId),
                eq(projects.userId, userId)
              ))
              .orderBy(desc(projects.id))
              .limit(1);
            if (ownerProj) {
              const [hasRecips] = await db.select({ id: projectRecipients.id })
                .from(projectRecipients)
                .where(and(
                  eq(projectRecipients.projectId, ownerProj.id),
                  isNull(projectRecipients.removedAt)
                ))
                .limit(1);
              if (hasRecips) {
                effectiveProjectId = ownerProj.id;
                console.log(`[SMS] Auto-detected projectId=${effectiveProjectId} (contact is project owner)`);
              }
            }
          }
          if (effectiveProjectId) {
            console.log(`[SMS] Group send: projectId=${effectiveProjectId}, to=${to}, contactId=${contactId}`);
          } else {
            console.log(`[SMS] WARNING: skipAutoSend=true but could not detect projectId for contactId=${contactId}`);
          }
        } catch (e) {
          console.error('[SMS] Failed to auto-detect projectId:', e);
        }
      } else if (effectiveProjectId) {
        console.log(`[SMS] Sending with projectId=${effectiveProjectId} to ${to}`);
      }
      
      const createdComm = await storage.createCommunication(userId, {
        contactId: contactId || null,
        projectId: effectiveProjectId,
        phoneNumber: to,
        type: 'sms',
        direction: 'outbound',
        content: body || '',
        mediaUrl: primaryMediaUrl,
        mediaUrls: resolvedMediaUrls.length > 0 ? resolvedMediaUrls : undefined,
        mediaContentTypes: resolvedContentTypes.length > 0 ? resolvedContentTypes : undefined,
        mediaType,
        messageSid: result.sid || null,
      });

      const alsoSentTo: string[] = [];

      if (contactId) {
        automations.cancelAllContactFollowups(userId, contactId, 'user_messaged').catch(e => console.error('[Automations]', e));
        const contactProject = await storage.getProjectByContact(userId, contactId);
        if (contactProject) {
          await db.update(projects).set({ stageChangedAt: new Date(), updatedAt: new Date() }).where(and(eq(projects.id, contactProject.id), eq(projects.userId, userId)));

          if (!req.body.skipAutoSend && !effectiveProjectId) {
            const recipients = await storage.getProjectRecipients(contactProject.id);
            for (const recipient of recipients) {
              if (recipient.contactId && recipient.contactId !== contactId && recipient.phone) {
                try {
                  const recipResult = await sendSms(settings, {
                    to: recipient.phone,
                    body: body || '',
                    mediaUrl: twilioMediaUrls.length > 0 ? twilioMediaUrls : undefined,
                  });
                  if (recipResult.success) {
                    await storage.createCommunication(userId, {
                      contactId: recipient.contactId,
                      projectId: effectiveProjectId,
                      phoneNumber: recipient.phone,
                      type: 'sms',
                      direction: 'outbound',
                      content: body || '',
                      mediaUrl: primaryMediaUrl,
                      mediaUrls: resolvedMediaUrls.length > 0 ? resolvedMediaUrls : undefined,
                      mediaContentTypes: resolvedContentTypes.length > 0 ? resolvedContentTypes : undefined,
                      mediaType,
                      messageSid: recipResult.sid || null,
                    });
                    alsoSentTo.push(recipient.name);
                    console.log(`[SMS] Auto-sent to project recipient ${recipient.name} (${recipient.phone})`);
                  }
                } catch (e) {
                  console.error(`[SMS] Failed auto-send to recipient ${recipient.name}:`, e);
                }
              }
            }
          }
        }
      }
      
      emitToOwnerAndTeam(userId, {
        type: "sms.sent",
        tenantId: userId,
        contactId: contactId || null,
        projectId: effectiveProjectId || null,
        payload: createdComm,
      }).catch(() => {});
      res.json({ success: true, messageSid: result.sid, alsoSentTo, communication: createdComm });
    } catch (err: any) {
      res.status(400).json({ message: err.message || "Failed to send SMS" });
    }
  });

