  app.post('/api/openphone/webhook', async (req, res) => {
    try {
      const event = req.body;
      const eventType = event?.type;

      if (!eventType || !event?.data) {
        console.warn('[OpenPhone Webhook] Invalid payload - missing type or data');
        return res.status(400).json({ error: 'Invalid webhook payload' });
      }

      console.log(`[OpenPhone Webhook] Received event: ${eventType}`);

      if (eventType === 'message.received') {
        const messageData = event?.data?.object;
        if (!messageData) {
          return res.status(200).json({ received: true });
        }

        const fromNumber = messageData.from;
        const toNumber = messageData.to?.[0] || messageData.phoneNumberId;
        const messageBody = messageData.content || messageData.body || '';

        if (fromNumber && toNumber) {
          const settings = await storage.getCompanySettingsByOpenPhone(toNumber);

          if (settings && settings.userId) {
            const userId = settings.userId;
            // Block inbound for deleted/purged accounts (Apple compliance).
            try {
              const [ownerStatus] = await db
                .select({ status: users.accountStatus })
                .from(users)
                .where(eq(users.id, userId))
                .limit(1);
              if (ownerStatus && ownerStatus.status && ownerStatus.status !== 'active') {
                console.log(`[OpenPhone Webhook] Dropping inbound — owner ${userId} is ${ownerStatus.status}`);
                return res.status(200).json({ received: true });
              }
            } catch { /* best-effort */ }
            const contact = await storage.getContactByPhone(userId, fromNumber);

            if (contact) {
              if (contact.archived) {
                await storage.updateContact(userId, contact.id, { archived: false, archivedAt: null, pauseAutomations: false } as any);
                console.log(`[OpenPhone Webhook] Auto-unarchived contact ${contact.id} (${contact.name}) on inbound SMS`);
              }

              // Inbound SMS always lands in the contact's individual thread.
              // See Twilio webhook for the same routing rationale.
              const opComm = await storage.createCommunication(userId, {
                contactId: contact.id,
                projectId: null,
                phoneNumber: fromNumber,
                type: 'sms',
                direction: 'inbound',
                content: messageBody,
                from: fromNumber,
                to: settings.openphonePhoneNumber || toNumber,
                status: 'received',
              });
              console.log(`[OpenPhone Webhook] Saved incoming SMS from ${fromNumber} for user ${userId}, contact ${contact.id} (contact-thread routing)`);

              const opPushBody = (messageBody || '').substring(0, 200);

              emitToOwnerAndTeam(userId, { type: "message.created", tenantId: userId, contactId: contact.id, projectId: null, payload: { id: opComm.id, contactId: contact.id, contactName: contact.name, phoneNumber: fromNumber, type: 'sms', direction: 'inbound', content: messageBody, createdAt: opComm.createdAt, timestamp: opComm.createdAt, projectId: null } }).catch(e => console.error('[Realtime] fan-out failed:', e));
              emitToOwnerAndTeam(userId, { type: "notification.created", tenantId: userId }).catch(e => console.error('[Realtime] fan-out failed:', e));

              automations.cancelAllContactFollowups(userId, contact.id, 'customer_replied').catch(e => console.error('[Automations]', e));

              sendPushToOwnerAndTeam(userId, {
                title: `${contact.name}`,
                body: opPushBody,
                url: `/messages?contactId=${contact.id}`,
                tag: `sms-${contact.id}-${Date.now()}`,
                messageId: opComm.id,
                contactId: contact.id,
                phoneNumber: fromNumber,
                timestamp: opComm.createdAt ? new Date(opComm.createdAt).toISOString() : new Date().toISOString(),
              }).catch(err => console.error('[Push] Error:', err));
            } else {
              const opComm = await storage.createCommunication(userId, {
                phoneNumber: fromNumber,
                type: 'sms',
                direction: 'inbound',
                content: messageBody,
                from: fromNumber,
                to: settings.openphonePhoneNumber || toNumber,
                status: 'received',
              });
              console.log(`[OpenPhone Webhook] Saved incoming SMS from unknown number ${fromNumber} for user ${userId}`);

              emitToOwnerAndTeam(userId, { type: "message.created", tenantId: userId, payload: { id: opComm.id, phoneNumber: fromNumber, type: 'sms', direction: 'inbound', content: messageBody, createdAt: opComm.createdAt } }).catch(e => console.error('[Realtime] fan-out failed:', e));
              emitToOwnerAndTeam(userId, { type: "notification.created", tenantId: userId }).catch(e => console.error('[Realtime] fan-out failed:', e));

              sendPushToOwnerAndTeam(userId, {
                title: `${fromNumber}`,
                body: (messageBody || '').substring(0, 200),
                url: `/messages?phone=${encodeURIComponent(fromNumber)}`,
                tag: `sms-${fromNumber}-${Date.now()}`,
                messageId: opComm.id,
                phoneNumber: fromNumber,
                timestamp: opComm.createdAt ? new Date(opComm.createdAt).toISOString() : new Date().toISOString(),
              }).catch(err => console.error('[Push] Error:', err));
            }
          } else {
            console.warn(`[OpenPhone Webhook] No user found for OpenPhone number: ${toNumber}`);
          }
        }
      }

      res.status(200).json({ received: true });
    } catch (err: any) {
      console.error('OpenPhone webhook error:', err);
      res.status(200).json({ received: true });
    }
  });

  app.post('/api/twilio/create-messaging-service', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const settings = await storage.getCompanySettings(userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken || !settings?.twilioPhoneNumber) {
        return res.status(400).json({ message: "Twilio not fully configured. Please save credentials and select a phone number first." });
      }
      if (settings.twilioMessagingServiceSid) {
        return res.json({ success: true, messagingServiceSid: settings.twilioMessagingServiceSid, message: "Messaging Service already exists" });
      }
      const twilio = await import('twilio');
      const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);
      const serviceName = `${settings.companyName || 'FusePhone'} Messaging`;
      const service = await client.messaging.v1.services.create({
        friendlyName: serviceName,
        useInboundWebhookOnNumber: true,
      });
      const phoneNumberSid = await (async () => {
        const numbers = await client.incomingPhoneNumbers.list({ phoneNumber: settings.twilioPhoneNumber! });
        return numbers[0]?.sid;
      })();
      if (phoneNumberSid) {
        await client.messaging.v1.services(service.sid).phoneNumbers.create({ phoneNumberSid });
      }
      await storage.updateCompanySettings(userId, {
        twilioMessagingServiceSid: service.sid,
      });
      console.log(`[Twilio] Created Messaging Service ${service.sid} for user ${userId}`);
      res.json({ success: true, messagingServiceSid: service.sid });
    } catch (err: any) {
      console.error('[Twilio] Create messaging service error:', err);
      res.status(500).json({ message: err.message || "Failed to create Messaging Service" });
    }
  });

  app.post('/api/twilio/register-a2p-brand', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { businessType, ein } = req.body;
      const settings = await storage.getCompanySettings(userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken) {
        return res.status(400).json({ message: "Twilio credentials not configured" });
      }
      if (!settings.twilioMessagingServiceSid) {
        return res.status(400).json({ message: "Please create a Messaging Service first" });
      }
      if (settings.twilioA2pBrandSid) {
        return res.json({ success: true, brandSid: settings.twilioA2pBrandSid, status: settings.twilioA2pBrandStatus, message: "Brand already registered" });
      }
      if (!businessType) {
        return res.status(400).json({ message: "Business type is required (sole_proprietor or standard)" });
      }
      if (businessType === 'standard' && !ein) {
        return res.status(400).json({ message: "EIN is required for standard business registration" });
      }

      const twilio = await import('twilio');
      const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);

      await storage.updateCompanySettings(userId, {
        twilioBusinessType: businessType,
        twilioEin: businessType === 'standard' ? ein : null,
      });

      if (businessType === 'sole_proprietor') {
        const brand = await client.messaging.v1.brandRegistrations.create({
          a2PProfileBundleSid: 'BNXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX',
          customerProfileBundleSid: 'BUXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX',
        }).catch(async () => {
          const brandResult = await client.messaging.v1.services(settings.twilioMessagingServiceSid!).usAppToPerson.create({
            brandRegistrationSid: undefined as any,
            description: `${settings.companyName || 'Home services company'} uses this number to send appointment reminders, estimates, invoices, and project updates to customers who have opted in.`,
            messageFlow: 'Customers provide their phone number when requesting service or during in-person consultations. They consent to receive text messages about their projects, appointments, estimates, and invoices.',
            messageSamples: [
              `Hi! Your estimate for the project is ready. View it here: https://app.fusephone.com/portal/doc123`,
              `Reminder: You have an appointment scheduled for tomorrow at 10 AM. Reply STOP to opt out.`,
            ],
            usAppToPersonUsecase: 'MIXED',
            hasEmbeddedLinks: true,
            hasEmbeddedPhone: false,
            optInType: 'VERBAL',
          }).catch((e: any) => {
            console.log('[Twilio A2P] Sole proprietor registration via usAppToPerson failed, storing pending status:', e.message);
            return null;
          });
          return brandResult;
        });

        await storage.updateCompanySettings(userId, {
          twilioA2pBrandStatus: 'pending',
          twilioA2pBrandSid: (brand as any)?.sid || 'pending_review',
        });

        console.log(`[Twilio] A2P sole proprietor brand registration initiated for user ${userId}`);
        res.json({ success: true, status: 'pending', message: "Sole proprietor registration submitted. Approval typically takes 1-3 business days." });
      } else {
        try {
          const campaign = await client.messaging.v1.services(settings.twilioMessagingServiceSid!).usAppToPerson.create({
            brandRegistrationSid: undefined as any,
            description: `${settings.companyName || 'Home services company'} uses this number to send appointment reminders, estimates, invoices, and project updates to customers who have opted in.`,
            messageFlow: 'Customers provide their phone number when requesting service or during in-person consultations. They consent to receive text messages about their projects, appointments, estimates, and invoices.',
            messageSamples: [
              `Hi! Your estimate for the project is ready. View it here: https://app.fusephone.com/portal/doc123`,
              `Reminder: You have an appointment scheduled for tomorrow at 10 AM. Reply STOP to opt out.`,
            ],
            usAppToPersonUsecase: 'MIXED',
            hasEmbeddedLinks: true,
            hasEmbeddedPhone: false,
            optInType: 'VERBAL',
          });

          await storage.updateCompanySettings(userId, {
            twilioA2pBrandStatus: 'pending',
            twilioA2pBrandSid: (campaign as any)?.sid || 'pending_review',
          });

          console.log(`[Twilio] A2P standard brand registration initiated for user ${userId}`);
          res.json({ success: true, status: 'pending', message: "Standard business registration submitted. Approval typically takes 5-10 business days." });
        } catch (err: any) {
          await storage.updateCompanySettings(userId, {
            twilioA2pBrandStatus: 'pending',
            twilioA2pBrandSid: 'pending_manual',
          });
          console.log(`[Twilio] A2P standard registration needs manual setup:`, err.message);
          res.json({ success: true, status: 'pending', message: "Registration initiated. A2P brand verification may require additional steps in your Twilio console. We've saved your details." });
        }
      }
    } catch (err: any) {
      console.error('[Twilio] A2P brand registration error:', err);
      res.status(500).json({ message: err.message || "Failed to register A2P brand" });
    }
  });

