  interface ActiveCallParticipant {
    label: string;
    phone: string;
    callSid?: string;
    role: 'office' | 'customer' | 'added';
    onHold?: boolean;
  }

  interface ActiveCall {
    conferenceName: string;
    userId: string;
    direction: 'inbound' | 'outbound';
    contactId?: number;
    contactName?: string;
    customerPhone: string;
    status: 'ringing' | 'in-progress' | 'completed' | 'voicemail';
    endReason?: string;
    participants: ActiveCallParticipant[];
    startedAt: number;
    conferenceSid?: string;
    manuallyEnded?: boolean;
    communicationLogged?: boolean;
    communicationId?: number;
    aiFallbackEnabled?: boolean;
    officeAnswered?: boolean;
    aiFallbackTriggered?: boolean;
    isAfterHours?: boolean;
    parentCallSid?: string;
    useDirectDial?: boolean;
  }

  const activeCalls = new Map<string, ActiveCall>();
  // LOCKED 2026-04-25: Use the shared map from server/callMeta.ts so that
  // aiAssistantCall.ts can register transfer-conf entries the moment AI
  // initiates an office transfer. Do NOT create a local Map here — it would
  // silently desync from the AI module and drop transferred-call recordings.
  const conferenceCallMeta = sharedConferenceCallMeta;

  function getActiveCallForUser(userId: string): ActiveCall | undefined {
    for (const call of activeCalls.values()) {
      if (call.userId === userId && call.status !== 'completed') return call;
    }
    return undefined;
  }

  async function updateCallCommunication(call: ActiveCall, finalContent: string) {
    if (call.communicationId) {
      try {
        await storage.updateCommunication(call.communicationId, { content: finalContent });
      } catch (e: any) {
        console.error(`[Call] Failed to update communication ${call.communicationId}:`, e.message);
      }
    }
  }

  function cleanupCall(conferenceName: string, immediate = false) {
    const call = activeCalls.get(conferenceName);
    if (call) {
      call.status = 'completed';
      notifyCallUpdate(call.userId);
      setTimeout(() => {
        activeCalls.delete(conferenceName);
        if (call) notifyCallUpdate(call.userId);
      }, immediate ? 2000 : 5000);
    }
    setTimeout(() => conferenceCallMeta.delete(conferenceName), 5 * 60 * 1000);
  }

  async function endRemainingParticipants(call: ActiveCall) {
    try {
      const settings = await storage.getCompanySettings(call.userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken) return;
      const twilio = await import('twilio');
      const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);
      for (const p of call.participants) {
        if (p.callSid) {
          try {
            await client.calls(p.callSid).update({ status: 'completed' });
            console.log(`[Call] Auto-ended remaining participant ${p.role} (${p.callSid})`);
          } catch (e: any) {
            console.log(`[Call] Could not end participant ${p.callSid}: ${e.message}`);
          }
        }
      }
    } catch (e: any) {
      console.error('[Call] Error ending remaining participants:', e.message);
    }
  }

  const callUpdateClients = new Map<string, Set<import('express').Response>>();

  function notifyCallUpdate(userId: string) {
    const clients = callUpdateClients.get(userId);
    if (clients) {
      for (const client of clients) {
        try {
          client.write(`data: ${JSON.stringify({ type: 'call-update', timestamp: Date.now() })}\n\n`);
        } catch (e) {
          clients.delete(client);
        }
      }
    }
    const userCall = Array.from(activeCalls.values()).find(c => c.userId === userId && c.status !== 'completed');
    const callPayload = userCall ? {
      conferenceName: userCall.conferenceName,
      direction: userCall.direction,
      contactId: userCall.contactId,
      contactName: userCall.contactName,
      customerPhone: userCall.customerPhone,
      status: userCall.status,
      endReason: userCall.endReason,
      participants: userCall.participants.map(p => ({ label: p.label, phone: p.phone, callSid: p.callSid, role: p.role })),
      startedAt: userCall.startedAt,
    } : null;
    emitToUser(userId, userId, { type: "call.updated", tenantId: userId, payload: callPayload });
  }

  app.get('/api/calls/events', isAuthenticated, (req, res) => {
    const userId = getUserId(req);

    res.writeHead(200, {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
      'X-Accel-Buffering': 'no',
    });
    res.flushHeaders();
    res.write(`data: ${JSON.stringify({ type: 'connected' })}\n\n`);

    if (!callUpdateClients.has(userId)) {
      callUpdateClients.set(userId, new Set());
    }
    callUpdateClients.get(userId)!.add(res);

    const heartbeat = setInterval(() => {
      try { res.write(': heartbeat\n\n'); } catch (e) { clearInterval(heartbeat); }
    }, 30000);

    req.on('close', () => {
      clearInterval(heartbeat);
      const clients = callUpdateClients.get(userId);
      if (clients) {
        clients.delete(res);
        if (clients.size === 0) callUpdateClients.delete(userId);
      }
    });
  });

  app.get('/api/calls/active', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const call = getActiveCallForUser(userId);
      if (!call) return res.json(null);
      res.json({
        conferenceName: call.conferenceName,
        direction: call.direction,
        contactId: call.contactId,
        contactName: call.contactName,
        customerPhone: call.customerPhone,
        status: call.status,
        endReason: call.endReason || null,
        participants: call.participants,
        startedAt: call.startedAt,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post('/api/calls/add-participant', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { phoneNumber, label } = req.body;
      if (!phoneNumber) return res.status(400).json({ message: "Phone number required" });

      const call = getActiveCallForUser(userId);
      if (!call || call.status !== 'in-progress') {
        return res.status(400).json({ message: "No active call to add participant to" });
      }

      const settings = await storage.getCompanySettings(userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken || !settings?.twilioPhoneNumber) {
        return res.status(400).json({ message: "Twilio not configured" });
      }

      const twilio = await import('twilio');
      const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);
      const baseUrl = getWebhookBaseUrl();

      const newCall = await client.calls.create({
        url: `${baseUrl}/api/twilio/webhook/participant-answer?conference=${encodeURIComponent(call.conferenceName)}`,
        to: toE164(phoneNumber),
        from: settings.twilioPhoneNumber,
        statusCallback: `${baseUrl}/api/twilio/webhook/participant-status?conference=${encodeURIComponent(call.conferenceName)}&phone=${encodeURIComponent(phoneNumber)}`,
        statusCallbackEvent: ['completed', 'busy', 'no-answer', 'failed', 'canceled'],
      });

      call.participants.push({
        label: label || phoneNumber,
        phone: phoneNumber,
        callSid: newCall.sid,
        role: 'added',
      });

      res.json({ success: true, callSid: newCall.sid });
    } catch (err: any) {
      res.status(400).json({ message: err.message || "Failed to add participant" });
    }
  });

  app.post('/api/calls/remove-participant', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { callSid } = req.body;
      if (!callSid) return res.status(400).json({ message: "callSid required" });

      const call = getActiveCallForUser(userId);
      if (!call) return res.status(400).json({ message: "No active call" });
      if (call.status === 'completed') return res.status(409).json({ message: "Call has already ended" });

      const settings = await storage.getCompanySettings(userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken) {
        return res.status(400).json({ message: "Twilio not configured" });
      }

      const twilio = await import('twilio');
      const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);

      await client.calls(callSid).update({ status: 'completed' });
      call.participants = call.participants.filter(p => p.callSid !== callSid);

      if (call.participants.length === 0) {
        cleanupCall(call.conferenceName);
      }

      res.json({ success: true });
    } catch (err: any) {
      res.status(400).json({ message: err.message || "Failed to remove participant" });
    }
  });

  app.post('/api/calls/transfer', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { phoneNumber, label } = req.body;
      if (!phoneNumber) return res.status(400).json({ message: "Phone number required" });

      const call = getActiveCallForUser(userId);
      if (!call || call.status !== 'in-progress') {
        return res.status(400).json({ message: "No active call to transfer" });
      }

      const settings = await storage.getCompanySettings(userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken || !settings?.twilioPhoneNumber) {
        return res.status(400).json({ message: "Twilio not configured" });
      }

      const twilio = await import('twilio');
      const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);
      const baseUrl = getWebhookBaseUrl();

      const newCall = await client.calls.create({
        url: `${baseUrl}/api/twilio/webhook/participant-answer?conference=${encodeURIComponent(call.conferenceName)}`,
        to: toE164(phoneNumber),
        from: settings.twilioPhoneNumber,
        statusCallback: `${baseUrl}/api/twilio/webhook/participant-status?conference=${encodeURIComponent(call.conferenceName)}&phone=${encodeURIComponent(phoneNumber)}`,
        statusCallbackEvent: ['completed', 'busy', 'no-answer', 'failed', 'canceled'],
      });

      call.participants.push({
        label: label || phoneNumber,
        phone: phoneNumber,
        callSid: newCall.sid,
        role: 'added',
      });

      const officeParticipant = call.participants.find(p => p.role === 'office');
      if (officeParticipant?.callSid) {
        try {
          await client.calls(officeParticipant.callSid).update({ status: 'completed' });
          call.participants = call.participants.filter(p => p.role !== 'office');
        } catch (e) {
          console.log('[Call] Office participant already disconnected');
        }
      }

      res.json({ success: true, callSid: newCall.sid });
    } catch (err: any) {
      res.status(400).json({ message: err.message || "Failed to transfer call" });
    }
  });

  app.post('/api/calls/end', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const call = getActiveCallForUser(userId);
      if (!call) return res.status(400).json({ message: "No active call" });
      if (call.status === 'completed') return res.status(409).json({ message: "Call has already ended" });

      const settings = await storage.getCompanySettings(userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken) {
        return res.status(400).json({ message: "Twilio not configured" });
      }

      const twilio = await import('twilio');
      const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);

      if (call.useDirectDial && call.parentCallSid) {
        try { await client.calls(call.parentCallSid).update({ status: 'completed' }); } catch (e) {}
      }
      for (const p of call.participants) {
        if (p.callSid) {
          try { await client.calls(p.callSid).update({ status: 'completed' }); } catch (e) {}
        }
      }

      const contactLabel = call.contactName || call.customerPhone;
      const previousStatus = call.status;

      if (previousStatus === 'ringing') {
        await updateCallCommunication(call, `${call.direction === 'inbound' ? 'Missed call from' : 'Outbound call to'} ${contactLabel} - Call was canceled`);
      } else if (previousStatus === 'in-progress') {
        const duration = Math.floor((Date.now() - call.startedAt) / 1000);
        const mins = Math.floor(duration / 60);
        const secs = duration % 60;
        const durationStr = mins > 0 ? `${mins}m ${secs}s` : `${secs}s`;
        await updateCallCommunication(call, `Call ${call.direction === 'inbound' ? 'from' : 'to'} ${contactLabel} ended (${durationStr})`);
      } else if (previousStatus === 'voicemail') {
        await updateCallCommunication(call, `Missed call from ${contactLabel} - Voicemail`);
      }

      call.manuallyEnded = true;
      cleanupCall(call.conferenceName, true);
      res.json({ success: true });
    } catch (err: any) {
      res.status(400).json({ message: err.message || "Failed to end call" });
    }
  });

  app.post('/api/calls/leave', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const call = getActiveCallForUser(userId);
      if (!call) return res.status(400).json({ message: "No active call" });
      if (call.status === 'completed') return res.status(409).json({ message: "Call has already ended" });

      const settings = await storage.getCompanySettings(userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken) {
        return res.status(400).json({ message: "Twilio not configured" });
      }

      const twilio = await import('twilio');
      const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);

      if (call.useDirectDial) {
        if (call.parentCallSid) {
          try { await client.calls(call.parentCallSid).update({ status: 'completed' }); } catch (e) {}
        }
        for (const p of call.participants) {
          if (p.callSid) {
            try { await client.calls(p.callSid).update({ status: 'completed' }); } catch (e) {}
          }
        }
        const contactLabel = call.contactName || call.customerPhone;
        const duration = Math.floor((Date.now() - call.startedAt) / 1000);
        const mins = Math.floor(duration / 60);
        const secs = duration % 60;
        const durationStr = mins > 0 ? `${mins}m ${secs}s` : `${secs}s`;
        await updateCallCommunication(call, `Call ${call.direction === 'inbound' ? 'from' : 'to'} ${contactLabel} ended (${durationStr})`);
        call.manuallyEnded = true;
        cleanupCall(call.conferenceName, true);
      } else {
        const officeParticipant = call.participants.find(p => p.role === 'office');
        if (officeParticipant?.callSid) {
          await client.calls(officeParticipant.callSid).update({ status: 'completed' });
          call.participants = call.participants.filter(p => p.role !== 'office');
        }

        if (call.participants.length <= 1) {
          const contactLabel = call.contactName || call.customerPhone;
          const duration = Math.floor((Date.now() - call.startedAt) / 1000);
          const mins = Math.floor(duration / 60);
          const secs = duration % 60;
          const durationStr = mins > 0 ? `${mins}m ${secs}s` : `${secs}s`;
          await updateCallCommunication(call, `Call ${call.direction === 'inbound' ? 'from' : 'to'} ${contactLabel} ended (${durationStr})`);
          await endRemainingParticipants(call);
          cleanupCall(call.conferenceName, true);
        } else {
          notifyCallUpdate(userId);
        }
      }

      res.json({ success: true });
    } catch (err: any) {
      res.status(400).json({ message: err.message || "Failed to leave call" });
    }
  });

