  async function transcribeRecording(recordingUrl: string, twilioAccountSid: string, twilioAuthToken: string): Promise<string> {
    try {
      const audioUrl = `${recordingUrl}.mp3`;
      const response = await fetch(audioUrl, {
        headers: {
          'Authorization': 'Basic ' + Buffer.from(`${twilioAccountSid}:${twilioAuthToken}`).toString('base64'),
        },
      });
      if (!response.ok) {
        console.error(`[Transcribe] Failed to fetch recording: ${response.status}`);
        return '';
      }
      const audioBuffer = Buffer.from(await response.arrayBuffer());
      const { speechToText } = await import('./replit_integrations/audio/client');
      const transcript = await speechToText(audioBuffer, 'mp3');
      return transcript.trim().replace(/\.$/, '');
    } catch (err: any) {
      console.error('[Transcribe] Error transcribing recording:', err);
      return '';
    }
  }

