  app.post('/api/twilio/webhook/appointment-save', async (req, res) => {
    try {
      const { userId, from, firstName: fName, lastName: lName, project, name } = req.query;
      const callerPhone = from as string;
      const uid = userId as string;

      const firstName = ((fName as string) || '').trim();
      const lastName = ((lName as string) || '').trim();
      const projectDesc = ((project as string) || '').trim();
      const legacyName = ((name as string) || '').trim();

      const resolvedFirst = firstName || (legacyName ? legacyName.split(' ')[0] : '');
      const resolvedLast = lastName || (legacyName ? legacyName.split(' ').slice(1).join(' ') : '');
      const fullName = [resolvedFirst, resolvedLast].filter(Boolean).join(' ') || callerPhone;

      console.log(`[Appointment Save] firstName="${resolvedFirst}", lastName="${resolvedLast}", project="${projectDesc}", phone=${callerPhone}`);

      const contact = await storage.getContactByPhone(uid, callerPhone);
      let contactId = contact?.id || null;

      if (!contact) {
        const newContact = await storage.createContact(uid, {
          name: fullName,
          phone: callerPhone,
          status: 'lead',
          leadSource: 'phone_estimate',
        });
        contactId = newContact.id;
        console.log(`[Appointment] Created new lead contact #${contactId} for ${callerPhone}`);

        sendPushToUser(uid, {
          title: 'New Lead',
          body: `${fullName} via phone estimate request`,
          url: `/contacts/${newContact.id}`,
          tag: `lead-${newContact.id}-${Date.now()}`,
        }).catch(err => console.error('[Push] Error:', err));

        try {
          const existingProject = await storage.getProjectByContact(uid, newContact.id);
          if (!existingProject) {
            const projectNumber = await storage.getNextProjectNumber(uid);
            const project = await storage.createProject(uid, {
              contactId: newContact.id,
              title: `${newContact.name} #${projectNumber}`,
              stage: 'new_lead',
              source: newContact.leadSource || null,
            });
            const ivrActivityContent = projectDesc
              ? `Project created automatically from phone estimate request\n\nProject description: ${projectDesc}`
              : 'Project created automatically from phone estimate request';
            await storage.createProjectActivity(uid, {
              projectId: project.id,
              type: 'system',
              content: ivrActivityContent,
            });
            automations.scheduleLeadFollowups(uid, newContact.id, project.id).catch(e => console.error('[Automations]', e));
          }
        } catch (e) {
          console.error('[Projects] Failed to auto-create project:', e);
        }
      }

      const bookingReq = await storage.createBookingRequest(uid, {
        firstName: resolvedFirst || callerPhone,
        lastName: resolvedLast || '-',
        phone: callerPhone,
        email: contact?.email || '',
        address: contact?.address || '',
        projectDescription: projectDesc || 'Estimate requested via phone call',
      });
      if (contactId) {
        await storage.updateBookingRequest(uid, bookingReq.id, { contactId });
      }

      await storage.createCommunication(uid, {
        contactId,
        phoneNumber: callerPhone,
        type: 'sms',
        direction: 'inbound',
        content: `Estimate request via phone from ${fullName}${projectDesc ? ` - ${projectDesc}` : ''}`,
      });

      sendPushToUser(uid, {
        title: 'New Appointment Request',
        body: `${fullName} requested an estimate via phone`,
        url: '/calendar',
        tag: `booking-${bookingReq.id}-${Date.now()}`,
      }).catch(err => console.error('[Push] Error:', err));

      console.log(`[Appointment] Created booking request for ${fullName}`);
      notifyCallUpdate(uid);

      const greetName = resolvedFirst ? escapeXml(resolvedFirst) : '';
      res.type('text/xml');
      res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Joanna">Thank you${greetName ? ', ' + greetName : ''}. Your estimate request has been submitted. We will contact you shortly. Goodbye.</Say>
  <Hangup/>
</Response>`);
    } catch (err: any) {
      console.error('[Appointment Save] Error:', err);
      res.type('text/xml');
      res.send('<?xml version="1.0" encoding="UTF-8"?><Response><Say>An error occurred. Goodbye.</Say><Hangup/></Response>');
    }
  });

  app.post('/api/twilio/webhook/office-answer', async (req, res) => {
    try {
      const { conference, customerName } = req.query;
      const conferenceName = conference as string;
      const rawName = (customerName as string) || 'the customer';
      const isPhoneNumber = /^[+\d\s()-]{7,}$/.test(rawName.trim());
      const name = isPhoneNumber ? 'the customer' : rawName;
      
      console.log(`[Call] Office answered! conference=${conferenceName}, direct-dialing ${name}`);

      const activeCall = activeCalls.get(conferenceName);
      if (!activeCall) {
        res.type('text/xml');
        res.send(`<?xml version="1.0" encoding="UTF-8"?><Response><Say>No pending call found. Goodbye.</Say><Hangup/></Response>`);
        return;
      }

      const settings = await storage.getCompanySettings(activeCall.userId);
      const callerIdNumber = settings?.twilioPhoneNumber || '';
      const baseUrl = getWebhookBaseUrl();
      const customerE164 = toE164(activeCall.customerPhone);

      activeCall.officeAnswered = true;
      await updateCallCommunication(activeCall, `Calling ${name}...`);

      const actionUrl = `${baseUrl}/api/twilio/webhook/outbound-dial-result?conference=${encodeURIComponent(conferenceName)}&amp;userId=${encodeURIComponent(activeCall.userId)}`;
      const recordingUrl = `${baseUrl}/api/twilio/webhook/call-recording-status?conference=${encodeURIComponent(conferenceName)}&amp;userId=${encodeURIComponent(activeCall.userId)}`;
      const custStatusUrl = escapeXml(`${baseUrl}/api/twilio/webhook/customer-status?conference=${encodeURIComponent(conferenceName)}`);
      
      res.type('text/xml');
      res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Connecting you to ${escapeXml(name)}.</Say>
  <Dial record="record-from-ringing-dual" timeout="30" callerId="${callerIdNumber}" action="${actionUrl}" recordingStatusCallback="${recordingUrl}" recordingStatusCallbackEvent="completed">
    <Number statusCallback="${custStatusUrl}" statusCallbackEvent="initiated ringing answered completed">${customerE164}</Number>
  </Dial>
</Response>`);
    } catch (err: any) {
      console.error('Office answer webhook error:', err);
      res.type('text/xml');
      res.send(`<?xml version="1.0" encoding="UTF-8"?><Response><Say>An error occurred. Goodbye.</Say><Hangup/></Response>`);
    }
  });
  
