  // Browser calling - Enable/disable browser VoIP and manage TwiML App
  app.post('/api/twilio/browser-calling/toggle', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { enabled } = req.body;
      const settings = await storage.getCompanySettings(userId);

      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken || !settings?.twilioPhoneNumber) {
        return res.status(400).json({ message: "Twilio credentials not configured" });
      }

      if (enabled) {
        const twilio = await import('twilio');
        const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);
        const baseUrl = getWebhookBaseUrl();

        if (!baseUrl) {
          return res.status(400).json({ message: "Could not determine app URL for webhook configuration" });
        }

        let twimlAppSid = settings.twilioTwimlAppSid;
        let apiKeySid = settings.twilioApiKeySid;
        let apiKeySecret = settings.twilioApiKeySecret;

        if (!twimlAppSid) {
          const app = await client.applications.create({
            friendlyName: `FusePhone Browser Calls - ${settings.companyName || userId}`,
            voiceUrl: `${baseUrl}/api/twilio/webhook/client-voice`,
            voiceMethod: 'POST',
          });
          twimlAppSid = app.sid;
        } else {
          await client.applications(twimlAppSid).update({
            voiceUrl: `${baseUrl}/api/twilio/webhook/client-voice`,
            voiceMethod: 'POST',
          });
        }

        if (!apiKeySid || !apiKeySecret) {
          const key = await client.newKeys.create({
            friendlyName: `FusePhone Browser - ${settings.companyName || userId}`,
          });
          apiKeySid = key.sid;
          apiKeySecret = key.secret;
        }

        await storage.updateCompanySettings(userId, {
          browserCallsEnabled: true,
          twilioTwimlAppSid: twimlAppSid,
          twilioApiKeySid: apiKeySid,
          twilioApiKeySecret: apiKeySecret,
        });

        res.json({ success: true, enabled: true, twimlAppSid });
      } else {
        await storage.updateCompanySettings(userId, {
          browserCallsEnabled: false,
          browserCallActiveDeviceId: null,
          browserCallActiveDeviceName: null,
          browserCallActiveAt: null,
        });
        res.json({ success: true, enabled: false });
      }
    } catch (err: any) {
      console.error('[Browser Calling] Toggle error:', err);
      res.status(400).json({ message: err.message || "Failed to toggle browser calling" });
    }
  });

  app.post('/api/twilio/browser-calling/claim-device', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { deviceId, deviceName } = req.body;

      if (!deviceId) {
        return res.status(400).json({ message: "Device ID is required" });
      }

      const settings = await storage.getCompanySettings(userId);
      if (!settings?.browserCallsEnabled) {
        return res.status(400).json({ message: "Browser calling is not enabled" });
      }

      if (settings.browserCallActiveDeviceId && settings.browserCallActiveDeviceId !== deviceId) {
        const activeAt = settings.browserCallActiveAt ? new Date(settings.browserCallActiveAt) : null;
        const staleMinutes = 5;
        const isStale = activeAt && (Date.now() - activeAt.getTime()) > staleMinutes * 60 * 1000;

        if (!isStale) {
          return res.status(409).json({
            message: "Browser calling is active on another device",
            activeDeviceName: settings.browserCallActiveDeviceName || "Unknown device",
            activeDeviceId: settings.browserCallActiveDeviceId,
          });
        }
      }

      await storage.updateCompanySettings(userId, {
        browserCallActiveDeviceId: deviceId,
        browserCallActiveDeviceName: deviceName || "Unknown device",
        browserCallActiveAt: new Date(),
      });

      res.json({ success: true, deviceId });
    } catch (err: any) {
      console.error('[Browser Calling] Claim device error:', err);
      res.status(400).json({ message: err.message || "Failed to claim device" });
    }
  });

