  async function sendAppointmentNotification(userId: string, contactId: number, date: string, time: string | null, type: string, action: 'confirmed' | 'updated' | 'cancelled') {
    const notificationsSent: string[] = [];
    try {
      const contact = await storage.getContact(userId, contactId);
      const settings = await storage.getCompanySettings(userId);
      if (!contact || !settings) return notificationsSent;
      const clientName = contact.name;
      const companyName = settings.companyName || '';

      let appointmentAddress = '';
      try {
        const contactProjects = await storage.getProjects(userId, { contactId });
        const activeProject = contactProjects?.find(p => !['completed', 'lost'].includes(p.stage));
        const proj = activeProject || contactProjects?.[0];
        const addr = proj?.jobAddress || contact.address;
        const city = proj?.jobCity || contact.city;
        const state = proj?.jobState || contact.state;
        const parts = [addr, city, state].filter(Boolean);
        if (parts.length > 0) {
          appointmentAddress = `Address: ${parts.join(', ')}`;
        }
      } catch {}

      let formattedDate = date;
      try {
        const { format: fmtDate, parseISO: parseISODate } = await import('date-fns');
        formattedDate = fmtDate(parseISODate(date), 'EEEE, MMMM d, yyyy');
      } catch {}

      let formattedTime = time || '';
      if (time) {
        try {
          const [h, m] = time.split(':').map(Number);
          const period = h >= 12 ? 'PM' : 'AM';
          const h12 = h % 12 || 12;
          formattedTime = `${h12}:${String(m).padStart(2, '0')} ${period}`;
        } catch {}
      }

      const actionText = action === 'confirmed' ? 'has been confirmed' : action === 'updated' ? 'has been updated' : 'has been cancelled';
      const subjectAction = action === 'confirmed' ? 'Confirmation' : action === 'updated' ? 'Update' : 'Cancellation';

      const template = await storage.getMessageTemplate(userId, `appointment_${action === 'confirmed' ? 'confirmation' : action}`);
      let messageBody: string;
      if (template && template.content) {
        messageBody = template.content
          .replace(/\{\{client_name\}\}/g, clientName)
          .replace(/\{\{company_name\}\}/g, companyName)
          .replace(/\{\{company_phone\}\}/g, settings.phone || '')
          .replace(/\{\{company_email\}\}/g, settings.email || '')
          .replace(/\{\{appointment_date\}\}/g, formattedDate)
          .replace(/\{\{appointment_time\}\}/g, formattedTime || 'TBD')
          .replace(/\{\{appointment_address\}\}/g, appointmentAddress);
      } else {
        const addrLine = appointmentAddress ? `\n${appointmentAddress}` : '';
        messageBody = action === 'cancelled'
          ? `Hi ${clientName}, this is ${companyName}. Your appointment has been cancelled. Please contact us if you'd like to reschedule. ${settings.phone || ''}`
          : `Hi ${clientName}, this is ${companyName}. Your appointment ${actionText} for ${formattedDate}${formattedTime ? ` at ${formattedTime}` : ''}.${addrLine}\nWe look forward to seeing you! ${settings.phone || ''}`;
      }
      messageBody = messageBody.replace(/\n\n\n+/g, '\n\n').trim();

      try {
        if (contact.phone && settings.twilioAccountSid && settings.twilioAuthToken && settings.twilioPhoneNumber) {
          const twilio = await import('twilio');
          const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);
          const phoneE164 = toE164(contact.phone);
          const messageOptions: any = { body: messageBody, to: phoneE164 };
          if (settings.twilioMessagingServiceSid) {
            messageOptions.messagingServiceSid = settings.twilioMessagingServiceSid;
          } else {
            messageOptions.from = settings.twilioPhoneNumber;
          }
          await client.messages.create(messageOptions);
          await createOutboundComm(userId, { contactId, type: 'sms', direction: 'outbound', content: messageBody, status: 'sent' });
          notificationsSent.push('sms');
        }
      } catch (smsErr) {
        console.error('[AppointmentNotify] SMS send failed:', smsErr);
      }

      try {
        if (contact.email) {
          const subject = `Appointment ${subjectAction} - ${companyName}`;
          const plainBody = `Appointment ${subjectAction}\n\n${messageBody}${action !== 'cancelled' ? `\n\nDate: ${formattedDate}\nTime: ${formattedTime || 'TBD'}` : ''}`;
          const emailHtml = wrapEmailInTemplate(plainBody, {
            companyName,
            companyLicense: settings.companyLicense || undefined,
            companyLogo: settings.logo,
            companyPhone: settings.phone || undefined,
            companyEmail: settings.email || undefined,
            companyWebsite: settings.website || undefined,
            accentColor: settings.brandColor || undefined,
          });
          const smtpEmail = await import('./smtpEmail.js');
          const googleIntegration = await import('./google.js');
          await smtpEmail.sendEmailWithFallback(userId, contact.email, subject, emailHtml, companyName, googleIntegration.sendEmail);
          await createOutboundComm(userId, { contactId, type: 'email', direction: 'outbound', content: `Subject: ${subject}\n\n${messageBody}`, status: 'sent' });
          notificationsSent.push('email');
        }
      } catch (emailErr) {
        console.error('[AppointmentNotify] Email send failed:', emailErr);
      }
    } catch (err) {
      console.error('[AppointmentNotify] Error:', err);
    }
    return notificationsSent;
  }

  app.post(api.appointments.create.path, isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const { sendNotification: shouldNotify, ...appointmentData } = req.body;
      const input = api.appointments.create.input.parse(appointmentData);
      const appt = await storage.createAppointment(userId, input);

      res.status(201).json({ ...appt, notifyMsg: shouldNotify ? 'Sending notification...' : '' });

      (async () => {
        try {
          await scheduleAppointmentReminders(userId, appt.id, appt.date, appt.time);
          syncAppointmentToGoogleCalendar(userId, appt.id, appt.date, appt.time, appt.contactId, appt.type, appt.notes);

          try {
            const contactProjects = await storage.getProjects(userId, { contactId: input.contactId });
            if (contactProjects && contactProjects.length > 0) {
              for (const proj of contactProjects) {
                if (!proj.leadQuality || proj.leadQuality === '') {
                  await storage.updateProject(userId, proj.id, { leadQuality: 'good' } as any);
                  console.log(`[Appointments] Auto-set lead quality to 'good' for project ${proj.id}`);
                }

                if (proj.stage === 'new_lead') {
                  await advanceProjectStage(userId, proj.id, proj.stage, 'appointment_requested', 'Stage changed to Appointment Requested (appointment scheduled)');
                  console.log(`[Appointments] Auto-advanced project ${proj.id} to appointment_requested`);
                }
              }
            }
          } catch (autoErr: any) {
            console.error('[Appointments] Auto-advance error:', autoErr.message);
          }

          if (shouldNotify) {
            const sent = await sendAppointmentNotification(userId, appt.contactId, appt.date, appt.time, appt.type, 'confirmed');
            console.log(`[Appointments] Notification sent via ${sent.join(' and ') || 'no channels'}`);
          }

          emitToUser(userId, userId, { type: 'appointment.updated', tenantId: userId });
        } catch (bgErr: any) {
          console.error('[Appointments] Background tasks error:', bgErr.message);
        }
      })();
    } catch (err) {
      if (err instanceof z.ZodError) {
        return res.status(400).json({ message: err.errors[0].message });
      }
      throw err;
    }
  });

  app.put(api.appointments.update.path, isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const id = Number(req.params.id);
      const { sendNotification: shouldNotify, ...updateData } = req.body;
      const input = api.appointments.update.input.parse(updateData);
      const existing = await storage.getAppointment(userId, id);
      const appt = await storage.updateAppointment(userId, id, input);
      if (!appt) {
        return res.status(404).json({ message: "Appointment not found" });
      }
      if (existing && (input.date || input.time) && (existing.date !== appt.date || existing.time !== appt.time)) {
        await rescheduleAppointmentReminders(userId, id, appt.date, appt.time);
      }
      if (input.status === 'cancelled' && appt.googleEventId) {
        deleteGoogleCalendarEvent(userId, appt.googleEventId);
        await storage.updateAppointment(userId, id, { googleEventId: null } as any);
      } else {
        syncAppointmentToGoogleCalendar(userId, appt.id, appt.date, appt.time, appt.contactId, appt.type, appt.notes, appt.googleEventId);
      }

      let notifyMsg = '';
      if (shouldNotify) {
        const action = input.status === 'cancelled' ? 'cancelled' as const : 'updated' as const;
        const sent = await sendAppointmentNotification(userId, appt.contactId, appt.date, appt.time, appt.type, action);
        notifyMsg = sent.length > 0 ? `Notification sent via ${sent.join(' and ')}` : 'No notification channels available';
      }

      emitToUser(userId, userId, { type: 'appointment.updated', tenantId: userId });
      res.json({ ...appt, notifyMsg });
    } catch (err) {
      if (err instanceof z.ZodError) {
        return res.status(400).json({ message: err.errors[0].message });
      }
      throw err;
    }
  });

