  app.put('/api/appointment-sessions/:id', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const id = Number(req.params.id);
      const session = await storage.getAppointmentSession(userId, id);
      if (!session) {
        return res.status(404).json({ message: "Session not found" });
      }
      const { result, status } = req.body;
      const updates: any = {};
      if (status === 'completed' && session.status === 'active') {
        const endTime = new Date();
        const durationMs = endTime.getTime() - new Date(session.startTime).getTime();
        const durationSeconds = Math.floor(durationMs / 1000);
        updates.endTime = endTime;
        updates.duration = durationSeconds;
        updates.status = 'completed';
      }
      if (result) {
        updates.result = result;
      }
      const updated = await storage.updateAppointmentSession(userId, id, updates);
      if (updates.status === 'completed' && result) {
        const appt = await storage.getAppointment(userId, session.appointmentId);
        if (appt) {
          const project = await storage.getProjectByContact(userId, appt.contactId);
          if (project) {
            const durationMins = Math.floor((updates.duration || 0) / 60);
            const resultLabel = result.replace(/_/g, ' ').replace(/\b\w/g, (c: string) => c.toUpperCase());
            await logProjectActivity(
              userId,
              project.id,
              'appointment_completed',
              `Appointment Completed\nDuration: ${durationMins} minutes\nResult: ${resultLabel}`
            );
          }
        }
        await storage.updateAppointment(userId, session.appointmentId, { status: 'completed' });
      }
      emitToUser(userId, userId, { type: 'appointment_session.ended', tenantId: userId });
      res.json(updated);
    } catch (err) {
      console.error('[AppointmentSessions] Error updating:', err);
      res.status(500).json({ message: "Failed to update session" });
    }
  });

