  app.get('/api/projects/:id/smart-suggestions', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const projectId = parseInt(req.params.id);
      const project = await storage.getProject(userId, projectId);
      if (!project) return res.status(404).json({ error: 'Project not found' });

      const comms = await storage.getCommunications(userId, project.contactId);
      const allDocs = await storage.getDocuments(userId);
      const docs = allDocs.filter(d => d.projectId === projectId);

      const now = new Date();
      const sortedComms = [...comms].sort((a, b) =>
        new Date(b.timestamp!).getTime() - new Date(a.timestamp!).getTime()
      );
      const lastComm = sortedComms[0] || null;
      const lastInbound = sortedComms.find(c => c.direction === 'inbound') || null;
      const lastOutbound = sortedComms.find(c => c.direction === 'outbound') || null;

      const daysSinceLastContact = lastComm
        ? Math.floor((now.getTime() - new Date(lastComm.timestamp!).getTime()) / (1000 * 60 * 60 * 24))
        : null;
      const daysSinceLastOutbound = lastOutbound
        ? Math.floor((now.getTime() - new Date(lastOutbound.timestamp!).getTime()) / (1000 * 60 * 60 * 24))
        : null;
      const daysSinceLastInbound = lastInbound
        ? Math.floor((now.getTime() - new Date(lastInbound.timestamp!).getTime()) / (1000 * 60 * 60 * 24))
        : null;

      const hasUnansweredInbound = lastInbound && lastOutbound
        ? new Date(lastInbound.timestamp!).getTime() > new Date(lastOutbound.timestamp!).getTime()
        : (lastInbound && !lastOutbound);

      const hasProposal = docs.some(d => d.type === "estimate" || d.type === "proposal");
      const hasSentDoc = docs.some(d => (d.type === "estimate" || d.type === "proposal") && d.status === "sent");
      const hasAcceptedDoc = docs.some(d => (d.type === "estimate" || d.type === "proposal") && d.status === "accepted");
      const hasInvoice = docs.some(d => d.type === "invoice");
      const hasSchedule = !!project.scheduledDate;

      type Urgency = 'fresh' | 'attention' | 'cold';
      let urgency: Urgency = 'fresh';
      if (daysSinceLastContact === null) {
        urgency = 'attention';
      } else if (daysSinceLastContact >= 5) {
        urgency = 'cold';
      } else if (daysSinceLastContact >= 2 || hasUnansweredInbound) {
        urgency = 'attention';
      }

      const contactName = project.contact?.name?.split(' ')[0] || '';
      const greeting = contactName ? `Hi ${contactName}` : 'Hi';
      const stage = project.stage;

      interface SmartSuggestion {
        label: string;
        description: string;
        action: string;
        variant: 'default' | 'outline';
        icon: string;
        draftMessage?: string;
        urgencyNote?: string;
      }
      const suggestions: SmartSuggestion[] = [];

      if (hasUnansweredInbound) {
        const snippet = lastInbound?.content
          ? lastInbound.content.substring(0, 60) + (lastInbound.content.length > 60 ? '...' : '')
          : '';
        const timeSinceInbound = daysSinceLastInbound !== null && daysSinceLastInbound > 0
          ? `${daysSinceLastInbound} day${daysSinceLastInbound > 1 ? 's' : ''} ago`
          : 'today';

        suggestions.push({
          label: 'Reply to Message',
          description: `They messaged ${timeSinceInbound}${snippet ? `: "${snippet}"` : ''}`,
          action: 'message',
          variant: 'default',
          icon: 'MessageSquare',
          draftMessage: undefined,
          urgencyNote: daysSinceLastInbound !== null && daysSinceLastInbound >= 2
            ? `Waiting ${daysSinceLastInbound} days for your reply`
            : undefined,
        });
      }

      if (stage === 'draft' || stage === 'new_lead' || stage === 'appointment_requested') {
        if (!hasUnansweredInbound) {
          if (daysSinceLastContact === null) {
            suggestions.push({
              label: 'Reach Out',
              description: 'No contact yet — introduce yourself',
              action: 'message',
              variant: 'default',
              icon: 'MessageSquare',
              draftMessage: `${greeting}, thank you for reaching out! I'd love to learn more about your project. When would be a good time to discuss the details?`,
            });
          } else if (daysSinceLastContact >= 3) {
            suggestions.push({
              label: 'Follow Up Again',
              description: `No response in ${daysSinceLastContact} days — try calling`,
              action: 'call',
              variant: 'default',
              icon: 'Phone',
              urgencyNote: `${daysSinceLastContact} days since last contact`,
            });
            suggestions.push({
              label: 'Send Follow-Up',
              description: 'Try a different approach via text',
              action: 'message',
              variant: 'outline',
              icon: 'MessageSquare',
              draftMessage: `${greeting}, just following up on our previous conversation. I'd still love to help with your project. Do you have a few minutes to chat this week?`,
            });
          } else if (daysSinceLastContact >= 1) {
            suggestions.push({
              label: 'Check In',
              description: `Last contact ${daysSinceLastContact} day${daysSinceLastContact > 1 ? 's' : ''} ago`,
              action: 'message',
              variant: 'default',
              icon: 'MessageSquare',
              draftMessage: `${greeting}, thank you for reaching out! I'd love to learn more about your project. When would be a good time to discuss the details?`,
            });
          }
        }
        if (!hasProposal) {
          suggestions.push({
            label: 'Create Proposal',
            description: 'Send a price quote to the customer',
            action: 'create_proposal',
            variant: suggestions.length === 0 ? 'default' : 'outline',
            icon: 'ClipboardList',
          });
        }
      } else if (stage === 'proposal_sent') {
        if (!hasUnansweredInbound) {
          if (daysSinceLastOutbound !== null && daysSinceLastOutbound >= 5) {
            suggestions.push({
              label: 'Final Follow-Up',
              description: `No response in ${daysSinceLastOutbound} days — consider calling or moving on`,
              action: 'call',
              variant: 'default',
              icon: 'Phone',
              urgencyNote: `Proposal sent ${daysSinceLastOutbound} days ago with no response`,
            });
          } else if (daysSinceLastOutbound !== null && daysSinceLastOutbound >= 2) {
            suggestions.push({
              label: 'Follow Up on Proposal',
              description: `Sent ${daysSinceLastOutbound} days ago — check in`,
              action: 'message',
              variant: 'default',
              icon: 'MessageSquare',
              draftMessage: `${greeting}, just checking in on the estimate I sent over. Let me know if you have any questions or if you'd like to go over anything together.`,
              urgencyNote: `${daysSinceLastOutbound} days waiting`,
            });
          } else {
            suggestions.push({
              label: 'Follow Up',
              description: 'Check if they reviewed the proposal',
              action: 'message',
              variant: 'default',
              icon: 'MessageSquare',
              draftMessage: `${greeting}, just checking in on the estimate I sent over. Let me know if you have any questions or if you'd like to go over anything together.`,
            });
          }
        }
      } else if (stage === 'accepted') {
        if (!hasSchedule) {
          suggestions.push({
            label: 'Schedule Job',
            description: 'Set a date to start the work',
            action: 'schedule',
            variant: 'default',
            icon: 'Calendar',
            draftMessage: `${greeting}, great news that you've accepted the proposal! Let's get your project scheduled. What dates work best for you?`,
          });
        }
        if (!hasUnansweredInbound) {
          suggestions.push({
            label: 'Confirm Details',
            description: 'Call to confirm project details',
            action: 'call',
            variant: 'outline',
            icon: 'Phone',
          });
        }
      } else if (stage === 'scheduled') {
        suggestions.push({
          label: 'Mark In Progress',
          description: 'Start working on the job',
          action: 'start_work',
          variant: 'default',
          icon: 'Hammer',
        });
        if (!hasUnansweredInbound) {
          suggestions.push({
            label: 'Confirm Before Start',
            description: 'Remind customer about the scheduled date',
            action: 'message',
            variant: 'outline',
            icon: 'MessageSquare',
            draftMessage: `${greeting}, just a reminder that we're scheduled to start your project soon. Please let me know if anything has changed or if you have any questions before we begin.`,
          });
        }
      } else if (stage === 'in_progress') {
        if (!hasInvoice) {
          suggestions.push({
            label: 'Create Invoice',
            description: 'Bill the customer for the work',
            action: 'create_invoice',
            variant: 'default',
            icon: 'Receipt',
          });
        }
        suggestions.push({
          label: 'Send Update',
          description: 'Keep the customer informed',
          action: 'message',
          variant: 'outline',
          icon: 'MessageSquare',
          draftMessage: `${greeting}, quick update on your project — things are going well! I'll keep you posted as we make more progress.`,
        });
      } else if (stage === 'invoiced') {
        if (daysSinceLastOutbound !== null && daysSinceLastOutbound >= 5) {
          suggestions.push({
            label: 'Payment Reminder',
            description: `Invoice sent ${daysSinceLastOutbound} days ago — follow up`,
            action: 'message',
            variant: 'default',
            icon: 'Send',
            draftMessage: `${greeting}, just a friendly reminder about the invoice I sent over. Please let me know if you have any questions about it.`,
            urgencyNote: `${daysSinceLastOutbound} days since invoice sent`,
          });
        } else {
          suggestions.push({
            label: 'Record Payment',
            description: 'Mark when you receive payment',
            action: 'record_payment',
            variant: 'default',
            icon: 'DollarSign',
          });
        }
      } else if (stage === 'paid') {
        suggestions.push({
          label: 'Complete Project',
          description: 'Mark the job as finished',
          action: 'complete',
          variant: 'default',
          icon: 'CheckCircle2',
        });
      } else if (stage === 'completed') {
        suggestions.push({
          label: 'Send Thank You',
          description: 'Thank the customer and ask for a review',
          action: 'message',
          variant: 'default',
          icon: 'Sparkles',
          draftMessage: `${greeting}, thank you so much for your business! It was a pleasure working on your project. If you're happy with the results, I'd really appreciate a review. Thank you!`,
        });
      }

      res.json({
        suggestions,
        urgency,
        daysSinceLastContact,
        daysSinceLastInbound,
        daysSinceLastOutbound,
        hasUnansweredInbound: !!hasUnansweredInbound,
        lastMessagePreview: lastComm?.content?.substring(0, 80) || null,
        lastMessageDirection: lastComm?.direction || null,
      });
    } catch (err: any) {
      console.error('[SmartSuggestions] Error:', err.message);
      res.status(500).json({ error: 'Failed to compute suggestions' });
    }
  });

