  async function computeOverheadPerHourCents(userId: string): Promise<number> {
    const [userOverheadExpenses, allTeamMembersData] = await Promise.all([
      storage.getOverheadExpenses(userId),
      storage.getTeamMembers(userId),
    ]);
    let monthlyOverhead = 0;
    for (const exp of userOverheadExpenses) {
      const amt = exp.amount || 0;
      if (exp.frequency === 'weekly') monthlyOverhead += amt * 4.33;
      else if (exp.frequency === 'quarterly') monthlyOverhead += amt / 3;
      else if (exp.frequency === 'yearly' || exp.frequency === 'annually') monthlyOverhead += amt / 12;
      else monthlyOverhead += amt;
    }
    const nonProdMembers = allTeamMembersData.filter(m => m.employeeType !== 'production' && m.isActive);
    const STANDARD_HOURS_PER_MONTH = 40 * 4.33;
    monthlyOverhead += nonProdMembers.reduce((s, m) => s + ((m.hourlyRate || 0) / 100) * STANDARD_HOURS_PER_MONTH, 0);
    const productionMembers = allTeamMembersData.filter(m => m.employeeType === 'production' && m.isActive && m.activeForPricing);
    const monthlyProductionHours = productionMembers.length * 160;
    return monthlyProductionHours > 0 ? Math.round((monthlyOverhead / monthlyProductionHours) * 100) : 0;
  }

  async function lockOverheadOnProject(userId: string, projectId: number): Promise<void> {
    try {
      const project = await storage.getProject(userId, projectId);
      if (!project || project.lockedOverheadPerHour != null) return;
      const overheadCents = await computeOverheadPerHourCents(userId);
      await storage.updateProject(userId, projectId, { lockedOverheadPerHour: overheadCents } as any);
      console.log(`[JobCosting] Locked overhead rate $${(overheadCents / 100).toFixed(2)}/hr on project ${projectId}`);
    } catch (err: any) {
      console.error(`[JobCosting] Failed to lock overhead on project ${projectId}:`, err.message);
    }
  }

  async function lockRatesOnTimeEntry(userId: string, entryId: number, teamMemberId: number): Promise<void> {
    try {
      const members = await storage.getTeamMembers(userId);
      const member = members.find(m => m.id === teamMemberId);
      if (!member) return;
      await db.update(timeEntries).set({
        lockedHourlyRate: member.hourlyRate || 0,
        lockedPayrollBurden: String(member.payrollBurdenPercentage || 0),
        lockedWorkersComp: String(member.workersCompPercentage || 0),
        lockedBenefitsPerHour: String(member.benefitsPerHour || 0),
      }).where(eq(timeEntries.id, entryId));
    } catch (err: any) {
      console.error(`[JobCosting] Failed to lock rates on time entry ${entryId}:`, err.message);
    }
  }

  async function computeAndSnapshotJobCosting(userId: string, projectId: number): Promise<any> {
    try {
      const [project, expenses, timeEntriesData, userOverheadExpenses, allTeamMembersData] = await Promise.all([
        storage.getProject(userId, projectId),
        storage.getProjectExpenses(userId, projectId),
        storage.getTimeEntries(userId, { projectId }),
        storage.getOverheadExpenses(userId),
        storage.getTeamMembers(userId),
      ]);

      const totalMaterials = expenses.reduce((sum, e) => sum + e.amount, 0);

      let totalLaborMinutes = 0;
      let productionLaborMinutes = 0;
      const missingRateMembers: string[] = [];
      const totalLabor = timeEntriesData.reduce((sum, entry) => {
        if (!entry.totalMinutes) return sum;
        totalLaborMinutes += entry.totalMinutes;
        const hasLockedRate = entry.lockedHourlyRate != null;
        const baseRate = hasLockedRate ? entry.lockedHourlyRate! : (entry.teamMember?.hourlyRate || 0);
        const isAdHoc = !entry.teamMemberId && !!entry.adHocWorkerName;
        if (!baseRate) {
          const memberName = entry.teamMember?.name || entry.adHocWorkerName || `Member #${entry.teamMemberId}`;
          if (!missingRateMembers.includes(memberName)) missingRateMembers.push(memberName);
          return sum;
        }
        // Ad-hoc one-time workers are always treated as production labor for costing,
        // matching the behavior of the live job-costing endpoint so completed-project
        // snapshots don't diverge from live numbers.
        const isProduction = isAdHoc || entry.teamMember?.employeeType === 'production';
        if (!isProduction) return sum;
        productionLaborMinutes += entry.totalMinutes;
        const hours = entry.totalMinutes / 60;
        const burden = hasLockedRate ? parseFloat(entry.lockedPayrollBurden || '0') : (entry.teamMember?.payrollBurdenPercentage || 0);
        const comp = hasLockedRate ? parseFloat(entry.lockedWorkersComp || '0') : (entry.teamMember?.workersCompPercentage || 0);
        const benefits = hasLockedRate ? parseFloat(entry.lockedBenefitsPerHour || '0') : (entry.teamMember?.benefitsPerHour || 0);
        const burdenMultiplier = 1 + burden + comp;
        const benefitsCents = Math.round(benefits * 100);
        const fullyLoadedPerHour = Math.round(baseRate * burdenMultiplier) + benefitsCents;
        return sum + Math.round(hours * fullyLoadedPerHour);
      }, 0);

      let overheadPerHourCents: number;
      const lockedOverhead = project?.lockedOverheadPerHour;
      if (lockedOverhead != null) {
        overheadPerHourCents = lockedOverhead;
      } else {
        const productionMembers = allTeamMembersData.filter(
          m => m.employeeType === 'production' && m.isActive && m.activeForPricing
        );
        const monthlyProductionHours = productionMembers.length * 160;
        let monthlyOverhead = 0;
        for (const exp of userOverheadExpenses) {
          const amt = exp.amount || 0;
          if (exp.frequency === 'weekly') monthlyOverhead += amt * 4.33;
          else if (exp.frequency === 'quarterly') monthlyOverhead += amt / 3;
          else if (exp.frequency === 'yearly' || exp.frequency === 'annually') monthlyOverhead += amt / 12;
          else monthlyOverhead += amt;
        }
        const nonProdMembers = allTeamMembersData.filter(
          m => m.employeeType !== 'production' && m.isActive
        );
        const STANDARD_HOURS_PER_MONTH = 40 * 4.33;
        monthlyOverhead += nonProdMembers.reduce((s, m) => s + ((m.hourlyRate || 0) / 100) * STANDARD_HOURS_PER_MONTH, 0);
        const monthlyProductionHrs = productionMembers.length * 160;
        overheadPerHourCents = monthlyProductionHrs > 0 ? Math.round((monthlyOverhead / monthlyProductionHrs) * 100) : 0;
      }

      const projectLaborHours = productionLaborMinutes / 60;
      const overheadAllocation = Math.round((overheadPerHourCents / 100) * projectLaborHours * 100);

      const totalCosts = totalMaterials + totalLabor + overheadAllocation;

      const snapshot = {
        totalMaterials,
        totalLabor,
        overheadAllocation,
        overheadPerHour: overheadPerHourCents,
        totalCosts,
        totalLaborMinutes,
        productionLaborMinutes,
        expenseCount: expenses.length,
        timeEntryCount: timeEntriesData.length,
        missingRateMembers,
        snapshotAt: new Date().toISOString(),
      };

      await storage.updateProject(userId, projectId, { costingSnapshot: snapshot } as any);
      console.log(`[JobCosting] Snapshot saved for project ${projectId}: overhead $${(overheadAllocation / 100).toFixed(2)}, labor $${(totalLabor / 100).toFixed(2)}`);
      return snapshot;
    } catch (err: any) {
      console.error(`[JobCosting] Failed to snapshot project ${projectId}:`, err.message);
      return null;
    }
  }

  type LiteProjectPnL = {
    revenue: number;
    materialsAndReceipts: number;
    manualLaborCostCents: number | null;
    netProfit: number;
    margin: number;
  };

  async function isCoreTierOwner(userId: string): Promise<boolean> {
    const [u] = await db.select({ tier: users.subscriptionTier, isAdmin: users.isAdmin }).from(users).where(eq(users.id, userId));
    if (!u) return false;
    if (u.isAdmin) return true;
    return (u.tier || 'starter') === 'core';
  }

  async function computeLiteProjectPnL(userId: string, projectId: number): Promise<LiteProjectPnL | null> {
    const [project, expenses, laborTotalFromEntries] = await Promise.all([
      storage.getProject(userId, projectId),
      storage.getProjectExpenses(userId, projectId),
      storage.getManualLaborTotalCents(userId, projectId),
    ]);
    if (!project) return null;
    const revenue = project.totalAmount || 0;
    const materialsAndReceipts = expenses.reduce((sum, e) => sum + (e.amount || 0), 0);
    const laborForCalc = laborTotalFromEntries || 0;
    const manualLaborCostCents = laborForCalc > 0 ? laborForCalc : null;
    const netProfit = revenue - materialsAndReceipts - laborForCalc;
    const margin = revenue > 0 ? (netProfit / revenue) * 100 : 0;
    return { revenue, materialsAndReceipts, manualLaborCostCents, netProfit, margin };
  }

  app.get('/api/projects/:id/lite-pnl', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      if (!(await isCoreTierOwner(userId))) {
        return res.status(403).json({ error: 'Lite P&L is available on the Core plan' });
      }
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: 'Invalid project id' });
      const pnl = await computeLiteProjectPnL(userId, id);
      if (!pnl) return res.status(404).json({ error: 'Project not found' });
      res.json(pnl);
    } catch (err: any) {
      res.status(500).json({ error: err.message || 'Failed to load P&L' });
    }
  });

