  app.put('/api/projects/:id', isAuthenticated, async (req, res) => {
    const userId = await getEffectiveUserId(req);
    const id = parseInt(req.params.id);
    const existing = await storage.getProject(userId, id);
    if (!existing) return res.status(404).json({ error: 'Project not found' });
    
    let autoStage: string | null = null;
    if (req.body.scheduledDate && !existing.scheduledDate && ['new_lead', 'appointment_requested', 'proposal_sent', 'accepted'].includes(existing.stage) && !req.body.stage) {
      autoStage = 'scheduled';
      req.body.stage = 'scheduled';
    }

    if (req.body.stage === 'lost') {
      req.body.lostAt = new Date();
      if (!req.body.lostReason) req.body.lostReason = null;
    } else if (req.body.stage && existing.stage === 'lost' && req.body.stage !== 'lost') {
      req.body.lostReason = null;
      req.body.lostAt = null;
    }

    const { sendReviewRequest, ...projectUpdates } = req.body;
    const updated = await storage.updateProject(userId, id, projectUpdates);

    const newStage = projectUpdates.stage || autoStage;
    const stageChanged = newStage && newStage !== existing.stage;

    if (autoStage) {
      await storage.createProjectActivity(userId, {
        projectId: id,
        type: 'stage_change',
        content: 'Stage changed to Scheduled (date set)',
      });
    }
    
    if (req.body.stage && req.body.stage !== existing.stage && !autoStage) {
      const stageLabels: Record<string, string> = {
        new_lead: 'New Lead',
        appointment_requested: 'Appointment Requested',
        proposal_sent: 'Proposal Sent',
        accepted: 'Accepted',
        scheduled: 'Scheduled',
        in_progress: 'In Progress',
        invoiced: 'Invoiced',
        paid: 'Paid',
        completed: 'Completed',
        lost: 'Lost',
      };
      const activityContent = req.body.stage === 'lost' && req.body.lostReason
        ? `Stage changed to Lost (${req.body.lostReason})`
        : `Stage changed to ${stageLabels[req.body.stage] || req.body.stage}`;
      await storage.createProjectActivity(userId, {
        projectId: id,
        type: 'stage_change',
        content: activityContent,
      });
    }

    emitToUser(userId, userId, { type: "project.updated", tenantId: userId, projectId: id });
    emitToUser(userId, userId, { type: "dashboard.refresh", tenantId: userId });
    res.json(updated);

    if (stageChanged && existing.contactId) {
      const reqScheduledDate = req.body.scheduledDate;
      const reqNotifyCustomer = req.body.notifyCustomer;
      const reqSendReviewRequest = req.body.sendReviewRequest;
      const reqLeadQuality = req.body.leadQuality;
      const reqCookie = req.headers.cookie || '';

      (async () => {
        try {
          if (existing.stage === 'new_lead' && newStage !== 'new_lead') {
            await automations.cancelLeadFollowups(userId, existing.contactId, undefined);
            console.log(`[Projects] Cancelled lead follow-ups for contact ${existing.contactId} (manual stage change to ${newStage})`);
          }

          if (newStage === 'lost') {
            await storage.cancelAutomations(userId, { contactId: existing.contactId, category: 'followup_not_viewed' });
            await storage.cancelAutomations(userId, { contactId: existing.contactId, category: 'followup_viewed' });
            await automations.cancelLeadFollowups(userId, existing.contactId, undefined);
            console.log(`[Projects] Cancelled all automations for contact ${existing.contactId} (marked as lost)`);
          }

          const postProposalStages = ['accepted', 'scheduled', 'in_progress', 'invoiced', 'paid', 'completed'];
          if (postProposalStages.includes(newStage)) {
            await storage.cancelAutomations(userId, { contactId: existing.contactId, category: 'followup_not_viewed' });
            await storage.cancelAutomations(userId, { contactId: existing.contactId, category: 'followup_viewed' });
            console.log(`[Projects] Cancelled document follow-ups for contact ${existing.contactId} (manual stage change to ${newStage})`);
          }

          await storage.updateProject(userId, id, {
            automationPausedReason: null,
            automationPausedAt: null,
            automationPausedCategory: null,
            automationPausedStep: null,
            automationPausedDocumentId: null,
          } as any);

          if (newStage === 'scheduled' && reqNotifyCustomer !== false) {
            const settings = await storage.getCompanySettings(userId);
            const nextWindow = settings ? automations.getNextBusinessWindow(settings) : null;
            
            if (nextWindow) {
              const automationId = await automations.scheduleJobNotification(userId, existing.contactId, id, 'job_scheduled');
              await storage.rescheduleAutomation(automationId, nextWindow);
              console.log(`[Automations] Deferred job_scheduled for project ${id} to ${nextWindow.toISOString()} (outside business hours)`);
            } else {
              automations.scheduleJobNotification(userId, existing.contactId, id, 'job_scheduled').catch(e => console.error('[Automations]', e));
            }
            
            const scheduledRecipients = await storage.getProjectRecipients(id);
            for (const recipient of scheduledRecipients) {
              if (recipient.contactId && recipient.contactId !== existing.contactId) {
                automations.scheduleJobNotification(userId, recipient.contactId, id, 'job_scheduled').catch(e => console.error('[Automations] recipient scheduled:', e));
              }
            }
            
            if (reqScheduledDate || existing.scheduledDate) {
              const schedDate = new Date(reqScheduledDate || existing.scheduledDate);
              automations.scheduleJobReminder(userId, existing.contactId, id, schedDate).catch(e => console.error('[Automations]', e));
              for (const recipient of scheduledRecipients) {
                if (recipient.contactId && recipient.contactId !== existing.contactId) {
                  automations.scheduleJobReminder(userId, recipient.contactId, id, schedDate).catch(e => console.error('[Automations] recipient reminder:', e));
                }
              }
            }
          } else if (newStage === 'completed') {
            const shouldSendReview = reqSendReviewRequest !== false;
            const completedSettings = await storage.getCompanySettings(userId);
            if (shouldSendReview) {
              const nextWindow = completedSettings ? automations.getNextBusinessWindow(completedSettings) : null;
              
              if (nextWindow) {
                const automationId = await automations.scheduleJobNotification(userId, existing.contactId, id, 'job_completed');
                await storage.rescheduleAutomation(automationId, nextWindow);
                console.log(`[Automations] Deferred job_completed for project ${id} to ${nextWindow.toISOString()} (outside business hours)`);
              } else {
                automations.scheduleJobNotification(userId, existing.contactId, id, 'job_completed').catch(e => console.error('[Automations]', e));
              }
              
              const recipients = await storage.getProjectRecipients(id);
              if (recipients.length > 0) {
                for (const recipient of recipients) {
                  if (recipient.contactId && recipient.contactId !== existing.contactId) {
                    automations.scheduleJobNotification(userId, recipient.contactId, id, 'job_completed').catch(e => console.error('[Automations] recipient review:', e));
                  }
                }
              }
            }
            if (!completedSettings?.reviewLink && shouldSendReview) {
              await storage.createProjectActivity(userId, {
                projectId: id,
                type: 'system',
                content: 'Tip: Add a Google review link in Company Profile so customers are asked for reviews when projects complete.',
              });
            }
          }
        } catch (e) { console.error('[Automations] stage notification error:', e); }

        if (newStage === 'in_progress' || newStage === 'completed') {
          try {
            const contact = existing.contactId ? await storage.getContact(userId, existing.contactId) : null;
            const triggerType = newStage === 'in_progress' ? 'project_started' : 'project_completed';
            const triggerBody = {
              trigger: triggerType,
              projectId: id,
              contactName: contact?.name || '',
              city: (existing as any).city || contact?.city || '',
              serviceTypes: (existing as any).serviceTypes || [],
            };
            fetch(`http://localhost:${process.env.PORT || 5000}/api/admin/gameplan/automation/trigger`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', 'Cookie': reqCookie },
              body: JSON.stringify(triggerBody),
            }).catch(e => console.error(`[GamePlan Auto] ${triggerType} trigger failed:`, e.message));
          } catch (e) { console.error('[GamePlan Auto] stage trigger error:', e); }
        }

        if (newStage === 'completed') {
          try {
            await computeAndSnapshotJobCosting(userId, id);
          } catch (e) {
            console.error('[JobCosting] Snapshot error (will use live calculation):', e);
          }
        }
      })();
    }
    
    if (req.body.leadQuality && req.body.leadQuality !== existing.leadQuality && existing.contactId) {
      (async () => {
        try {
          const contact = await storage.getContact(userId, existing.contactId);
          if (contact?.leadSource === 'facebook') {
            const fbSettings = await storage.getCompanySettings(userId);
            if (fbSettings) {
              await sendFBQualityEvent(userId, contact, fbSettings, id, req.body.leadQuality);
            }
          }
        } catch (e: any) {
          console.error('[Facebook CAPI] Lead quality event error:', e.message);
        }
      })();
    }
  });

