  app.get('/api/projects/:id/remaining-automations', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const project = await storage.getProject(userId, parseInt(req.params.id));
      if (!project) return res.status(404).json({ message: 'Project not found' });
      if (!project.automationPausedCategory || !project.automationPausedStep) {
        return res.json({ steps: [], category: null });
      }

      let effectiveCategory = project.automationPausedCategory;
      let switchedSequence = false;
      let switchReason = "";

      if (project.automationPausedCategory === 'followup_not_viewed' && project.automationPausedDocumentId) {
        const doc = await storage.getDocument(userId, project.automationPausedDocumentId);
        if (doc && doc.firstViewedAt) {
          effectiveCategory = 'followup_viewed';
          switchedSequence = true;
          switchReason = "Customer has now viewed the document";
        }
      }

      const startStep = switchedSequence
        ? automations.getScheduleForCategory(effectiveCategory)[0]?.slug || project.automationPausedStep
        : project.automationPausedStep;
      const allSteps = automations.getRemainingSteps(effectiveCategory, startStep);

      const sentSlugsOriginal = await storage.getSentAutomationSlugs(
        userId,
        project.id,
        project.automationPausedCategory!
      );
      const sentSlugsEffective = switchedSequence
        ? await storage.getSentAutomationSlugs(userId, project.id, effectiveCategory)
        : [];
      const sentSet = new Set([...sentSlugsOriginal, ...sentSlugsEffective]);
      const steps = allSteps.filter(s => !sentSet.has(s.slug));

      res.json({
        steps,
        category: effectiveCategory,
        originalCategory: project.automationPausedCategory,
        switchedSequence,
        switchReason,
      });
    } catch (err: any) {
      console.error('[Remaining Automations]', err);
      res.status(500).json({ message: err.message || 'Failed to get remaining automations' });
    }
  });

  app.post('/api/projects/:id/resume-automations', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const project = await storage.getProject(userId, parseInt(req.params.id));
      if (!project) return res.status(404).json({ message: 'Project not found' });
      if (!project.automationPausedCategory || !project.automationPausedStep) {
        return res.status(400).json({ message: 'No paused automations to resume' });
      }
      const resumeCategory = req.body?.category || project.automationPausedCategory;
      const startFromStep = req.body?.startFromStep || project.automationPausedStep;
      const schedule = automations.getScheduleForCategory(resumeCategory);
      if (!schedule.some(s => s.slug === startFromStep)) {
        return res.status(400).json({ message: `Invalid step "${startFromStep}" for category "${resumeCategory}"` });
      }
      let firstStepScheduledFor: Date | null = null;
      if (req.body?.firstStepScheduledFor) {
        const parsed = new Date(req.body.firstStepScheduledFor);
        if (!isNaN(parsed.getTime()) && parsed.getTime() > Date.now()) {
          firstStepScheduledFor = parsed;
        }
      }
      const result = await automations.resumeAutomations(
        userId,
        project.id,
        resumeCategory,
        startFromStep,
        project.contactId,
        project.automationPausedDocumentId,
        firstStepScheduledFor
      );
      const categoryLabel = resumeCategory !== project.automationPausedCategory
        ? ` (switched to ${resumeCategory === 'followup_viewed' ? 'viewed' : resumeCategory} sequence)`
        : '';
      await logProjectActivity(userId, project.id, 'automation', `Follow-up automations resumed from "${startFromStep}"${categoryLabel} (${result.scheduled} messages scheduled)`);
      res.json({ success: true, ...result });
    } catch (err: any) {
      console.error('[Resume Automations]', err);
      res.status(500).json({ message: err.message || 'Failed to resume automations' });
    }
  });

