  // === USER STRIPE CONNECT (ACCOUNT LINKS) ===

  app.post("/api/stripe/connect/create-account", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const settings = await storage.getCompanySettings(userId);

      if (settings?.squareMerchantId) {
        return res.status(400).json({ message: "Please disconnect Square first before connecting Stripe." });
      }

      const { getUncachableStripeClient } = await import("./stripeClient");
      const platformStripe = await getUncachableStripeClient();

      let accountId = settings?.stripeAccountId;

      if (accountId) {
        const account = await platformStripe.accounts.retrieve(accountId);
        if (account.charges_enabled && account.details_submitted) {
          return res.json({ success: true, alreadyConnected: true, message: "Stripe account is already connected" });
        }
      } else {
        const [user] = await db.select().from(users).where(eq(users.id, userId));
        const account = await platformStripe.accounts.create({
          type: 'standard',
          email: user?.email || undefined,
        });
        accountId = account.id;

        await storage.updateCompanySettings(userId, {
          stripeAccountId: accountId,
          activePaymentProcessor: 'stripe',
        });
      }

      const baseUrl = `${req.protocol}://${req.get('host')}`;
      const crypto = await import("crypto");
      const secret = process.env.SESSION_SECRET || 'fallback-secret';
      const timestamp = Date.now().toString();
      const sig = crypto.createHmac('sha256', secret).update(`${userId}.${timestamp}`).digest('hex').substring(0, 16);
      const refreshToken = `${userId}.${timestamp}.${sig}`;

      const accountLink = await platformStripe.accountLinks.create({
        account: accountId,
        refresh_url: `${baseUrl}/api/stripe/connect/refresh?token=${refreshToken}`,
        return_url: `${baseUrl}/settings/integrations?stripe=connected`,
        type: 'account_onboarding',
      });

      res.json({ success: true, url: accountLink.url });
    } catch (err: any) {
      console.error("Error creating Stripe Connect account:", err?.message || err, err?.statusCode, err?.type);
      const detail = err?.message || "Unknown error";
      res.status(500).json({ message: `Failed to start Stripe Connect setup: ${detail}` });
    }
  });

  app.get("/api/stripe/connect/refresh", async (req, res) => {
    try {
      const { token } = req.query;
      if (!token || typeof token !== 'string') {
        return res.redirect('/settings/integrations?stripe=error');
      }

      const crypto = await import("crypto");
      const secret = process.env.SESSION_SECRET || 'fallback-secret';
      const parts = token.split('.');
      if (parts.length !== 3) return res.redirect('/settings/integrations?stripe=error');
      const [userId, timestamp, signature] = parts;
      const expectedSig = crypto.createHmac('sha256', secret).update(`${userId}.${timestamp}`).digest('hex').substring(0, 16);
      if (signature !== expectedSig) return res.redirect('/settings/integrations?stripe=error');
      const elapsed = Date.now() - parseInt(timestamp, 10);
      if (elapsed > 3600000) return res.redirect('/settings/integrations?stripe=error');

      const settings = await storage.getCompanySettings(userId);
      if (!settings?.stripeAccountId) {
        return res.redirect('/settings/integrations?stripe=error');
      }

      const { getUncachableStripeClient } = await import("./stripeClient");
      const platformStripe = await getUncachableStripeClient();

      const baseUrl = `${req.protocol}://${req.get('host')}`;
      const newTimestamp = Date.now().toString();
      const newSig = crypto.createHmac('sha256', secret).update(`${userId}.${newTimestamp}`).digest('hex').substring(0, 16);
      const newToken = `${userId}.${newTimestamp}.${newSig}`;

      const accountLink = await platformStripe.accountLinks.create({
        account: settings.stripeAccountId,
        refresh_url: `${baseUrl}/api/stripe/connect/refresh?token=${newToken}`,
        return_url: `${baseUrl}/settings/integrations?stripe=connected`,
        type: 'account_onboarding',
      });

      res.redirect(accountLink.url);
    } catch (err: any) {
      console.error("Error refreshing Stripe Connect link:", err);
      res.redirect('/settings/integrations?stripe=error');
    }
  });

  app.get("/api/stripe/connect/status", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const settings = await storage.getCompanySettings(userId);

      if (!settings?.stripeAccountId) {
        const isLegacy = !!(settings?.stripeSecretKey && settings?.stripePublishableKey);
        return res.json({ connected: isLegacy, legacy: isLegacy, accountId: null, chargesEnabled: isLegacy, detailsSubmitted: isLegacy });
      }

      const { getUncachableStripeClient } = await import("./stripeClient");
      const platformStripe = await getUncachableStripeClient();

      const account = await platformStripe.accounts.retrieve(settings.stripeAccountId);

      if (account.charges_enabled && account.details_submitted && !settings.stripeConnectedAt) {
        await storage.updateCompanySettings(userId, {
          stripeConnectedAt: new Date(),
        });
      }

      res.json({
        connected: account.charges_enabled && account.details_submitted,
        legacy: false,
        accountId: settings.stripeAccountId,
        chargesEnabled: account.charges_enabled,
        detailsSubmitted: account.details_submitted,
        businessName: account.business_profile?.name || null,
        email: account.email || null,
      });
    } catch (err: any) {
      console.error("Error checking Stripe Connect status:", err);
      res.status(500).json({ message: "Failed to check Stripe status" });
    }
  });

  app.post("/api/stripe/connect", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { publishableKey, secretKey } = req.body;

      if (!publishableKey || !secretKey) {
        return res.status(400).json({ message: "Both Publishable Key and Secret Key are required" });
      }

      if (!publishableKey.startsWith('pk_')) {
        return res.status(400).json({ message: "Invalid Publishable Key format. It should start with 'pk_'" });
      }

      if (!secretKey.startsWith('sk_') && !secretKey.startsWith('rk_')) {
        return res.status(400).json({ message: "Invalid Secret Key format. It should start with 'sk_' or 'rk_'" });
      }

      const Stripe = (await import("stripe")).default;
      try {
        const stripe = new Stripe(secretKey);
        await stripe.balance.retrieve();
      } catch (stripeErr: any) {
        return res.status(400).json({ message: "Invalid Stripe credentials. Please check your API keys and try again." });
      }

      await storage.updateCompanySettings(userId, {
        stripePublishableKey: publishableKey,
        stripeSecretKey: secretKey,
        stripeConnectedAt: new Date(),
      });

      res.json({ success: true, message: "Stripe connected successfully" });
    } catch (err: any) {
      console.error("Error connecting Stripe:", err);
      res.status(500).json({ message: "Failed to connect Stripe" });
    }
  });

  app.post("/api/stripe/disconnect", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      await storage.updateCompanySettings(userId, {
        stripePublishableKey: null,
        stripeSecretKey: null,
        stripeConnectedAt: null,
        stripeAccountId: null,
        activePaymentProcessor: null,
      });
      res.json({ success: true, message: "Stripe disconnected" });
    } catch (err: any) {
      console.error("Error disconnecting Stripe:", err);
      res.status(500).json({ message: "Failed to disconnect Stripe" });
    }
  });

  // === SQUARE CONNECT ROUTES ===

  async function refreshSquareTokenIfNeeded(userId: string, accessToken: string, refreshToken: string | null): Promise<string> {
    try {
      const testResponse = await fetch('https://connect.squareup.com/v2/locations', {
        headers: { 'Authorization': `Bearer ${accessToken}`, 'Square-Version': '2024-01-18' },
      });
      if (testResponse.ok) return accessToken;

      if (testResponse.status === 401 && refreshToken) {
        const appId = process.env.SQUARE_APPLICATION_ID;
        const appSecret = process.env.SQUARE_APPLICATION_SECRET;
        if (!appId || !appSecret) return accessToken;

        const refreshResponse = await fetch('https://connect.squareup.com/oauth2/token', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Square-Version': '2024-01-18' },
          body: JSON.stringify({
            client_id: appId,
            client_secret: appSecret,
            grant_type: 'refresh_token',
            refresh_token: refreshToken,
          }),
        });
        const refreshData = await refreshResponse.json() as any;
        if (refreshResponse.ok && refreshData.access_token) {
          console.log("[Square] Token refreshed for user:", userId);
          await storage.updateCompanySettings(userId, {
            squareAccessToken: refreshData.access_token,
            squareRefreshToken: refreshData.refresh_token || refreshToken,
          });
          return refreshData.access_token;
        }
        console.error("[Square] Token refresh failed:", refreshData);
      }
    } catch (err) {
      console.error("[Square] Token refresh check error:", err);
    }
    return accessToken;
  }

  app.post("/api/square/connect", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const settings = await storage.getCompanySettings(userId);

      if (settings?.stripeAccountId || settings?.stripeSecretKey) {
        return res.status(400).json({ message: "Please disconnect Stripe first before connecting Square." });
      }

      const appId = process.env.SQUARE_APPLICATION_ID;
      if (!appId) {
        return res.status(500).json({ message: "Square is not configured on this platform." });
      }

      const crypto = await import("crypto");
      const secret = process.env.SESSION_SECRET || 'fallback-secret';
      const timestamp = Date.now().toString();
      const sig = crypto.createHmac('sha256', secret).update(`${userId}.${timestamp}.square`).digest('hex').substring(0, 16);
      const stateData = `${userId}.${timestamp}.${sig}`;

      const host = req.get('host') || '';
      const proto = host.includes('replit') || host.includes('fusephone') ? 'https' : req.protocol;
      const baseUrl = `${proto}://${host}`;
      const redirectUri = `${baseUrl}/api/square/callback`;
      const scopes = [
        'MERCHANT_PROFILE_READ',
        'PAYMENTS_WRITE',
        'PAYMENTS_READ',
        'ORDERS_WRITE',
        'ORDERS_READ',
      ].join('+');

      const squareBaseUrl = 'https://connect.squareup.com';
      const authUrl = `${squareBaseUrl}/oauth2/authorize?client_id=${appId}&scope=${scopes}&session=false&state=${encodeURIComponent(stateData)}&redirect_uri=${encodeURIComponent(redirectUri)}`;

      res.json({ success: true, url: authUrl });
    } catch (err: any) {
      console.error("Error starting Square Connect:", err?.message || err);
      res.status(500).json({ message: `Failed to start Square Connect: ${err?.message || 'Unknown error'}` });
    }
  });

  app.get("/api/square/callback", async (req, res) => {
    try {
      const { code, state, error: sqError } = req.query;
      if (sqError || !code || !state) {
        console.error("Square OAuth error:", sqError);
        return res.redirect('/settings/integrations?square=error');
      }

      const stateStr = state as string;
      const parts = stateStr.split('.');
      if (parts.length !== 3) return res.redirect('/settings/integrations?square=error');
      const [userId, timestamp, signature] = parts;

      const crypto = await import("crypto");
      const secret = process.env.SESSION_SECRET || 'fallback-secret';
      const expectedSig = crypto.createHmac('sha256', secret).update(`${userId}.${timestamp}.square`).digest('hex').substring(0, 16);
      if (signature !== expectedSig) {
        console.error("Square OAuth state signature mismatch");
        return res.redirect('/settings/integrations?square=error');
      }
      const elapsed = Date.now() - parseInt(timestamp, 10);
      if (elapsed > 3600000) {
        console.error("Square OAuth state expired");
        return res.redirect('/settings/integrations?square=error');
      }

      const existingSettings = await storage.getCompanySettings(userId);
      if (existingSettings?.stripeAccountId || existingSettings?.stripeSecretKey) {
        console.error("Square OAuth callback: Stripe is already connected, rejecting");
        return res.redirect('/settings/integrations?square=error');
      }

      const appId = process.env.SQUARE_APPLICATION_ID;
      const appSecret = process.env.SQUARE_APPLICATION_SECRET;
      if (!appId || !appSecret) {
        return res.redirect('/settings/integrations?square=error');
      }

      const cbHost = req.get('host') || '';
      const cbProto = cbHost.includes('replit') || cbHost.includes('fusephone') ? 'https' : req.protocol;
      const baseUrl = `${cbProto}://${cbHost}`;
      const redirectUri = `${baseUrl}/api/square/callback`;
      const tokenBody = {
        client_id: appId,
        client_secret: appSecret,
        code: code as string,
        grant_type: 'authorization_code',
        redirect_uri: redirectUri,
      };
      console.log("[Square] Token exchange - client_id:", appId?.substring(0, 10) + "...", "secret prefix:", appSecret?.substring(0, 8) + "...", "code length:", (code as string)?.length, "redirect_uri:", redirectUri);
      const tokenResponse = await fetch('https://connect.squareup.com/oauth2/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Square-Version': '2024-01-18' },
        body: JSON.stringify(tokenBody),
      });

      const tokenData = await tokenResponse.json() as any;
      if (!tokenResponse.ok || !tokenData.access_token) {
        console.error("Square token exchange failed:", tokenData, "status:", tokenResponse.status);
        return res.redirect('/settings/integrations?square=error');
      }

      const merchantId = tokenData.merchant_id;
      const accessToken = tokenData.access_token;
      const refreshToken = tokenData.refresh_token;

      let locationId: string | null = null;
      try {
        const locResponse = await fetch('https://connect.squareup.com/v2/locations', {
          headers: { 'Authorization': `Bearer ${accessToken}`, 'Square-Version': '2024-01-18' },
        });
        const locData = await locResponse.json() as any;
        if (locData.locations && locData.locations.length > 0) {
          const mainLoc = locData.locations.find((l: any) => l.status === 'ACTIVE') || locData.locations[0];
          locationId = mainLoc.id;
        }
      } catch (locErr) {
        console.error("Error fetching Square locations:", locErr);
      }

      await storage.updateCompanySettings(userId, {
        squareMerchantId: merchantId,
        squareAccessToken: accessToken,
        squareRefreshToken: refreshToken,
        squareLocationId: locationId,
        activePaymentProcessor: 'square',
      });

      res.redirect('/settings/integrations?square=connected');
    } catch (err: any) {
      console.error("Error in Square OAuth callback:", err?.message || err);
      res.redirect('/settings/integrations?square=error');
    }
  });

  app.get("/api/square/status", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const settings = await storage.getCompanySettings(userId);

      if (!settings?.squareMerchantId || !settings?.squareAccessToken) {
        return res.json({ connected: false });
      }

      const freshToken = await refreshSquareTokenIfNeeded(userId, settings.squareAccessToken, settings.squareRefreshToken);

      let merchantName = '';
      try {
        const merchResponse = await fetch(`https://connect.squareup.com/v2/merchants/${settings.squareMerchantId}`, {
          headers: { 'Authorization': `Bearer ${freshToken}`, 'Square-Version': '2024-01-18' },
        });
        const merchData = await merchResponse.json() as any;
        if (merchData.merchant) {
          merchantName = merchData.merchant.business_name || '';
        }
      } catch (e) {}

      res.json({
        connected: true,
        merchantId: settings.squareMerchantId,
        locationId: settings.squareLocationId,
        merchantName,
      });
    } catch (err: any) {
      console.error("Error checking Square status:", err);
      res.status(500).json({ message: "Failed to check Square status" });
    }
  });

  app.post("/api/square/disconnect", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const settings = await storage.getCompanySettings(userId);

      if (settings?.squareAccessToken) {
        try {
          const appId = process.env.SQUARE_APPLICATION_ID;
          await fetch('https://connect.squareup.com/oauth2/revoke', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Square-Version': '2024-01-18',
              'Authorization': `Client ${process.env.SQUARE_APPLICATION_SECRET}`,
            },
            body: JSON.stringify({
              client_id: appId,
              access_token: settings.squareAccessToken,
            }),
          });
        } catch (revokeErr) {
          console.error("Error revoking Square token (continuing with disconnect):", revokeErr);
        }
      }

      await storage.updateCompanySettings(userId, {
        squareMerchantId: null,
        squareAccessToken: null,
        squareRefreshToken: null,
        squareLocationId: null,
        activePaymentProcessor: null,
      });

      res.json({ success: true, message: "Square disconnected" });
    } catch (err: any) {
      console.error("Error disconnecting Square:", err);
      res.status(500).json({ message: "Failed to disconnect Square" });
    }
  });

