  app.post("/api/custom-domain", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const [user] = await db.select().from(users).where(eq(users.id, userId));
      if (!user) return res.status(404).json({ message: "User not found" });

      const isElite = user.isAdmin || user.subscriptionTier === 'elite' || (user.eliteBonusEndsAt && user.eliteBonusEndsAt > new Date());
      if (!isElite) {
        return res.status(403).json({ message: "Custom domain is available for Elite plan subscribers only." });
      }
      if (user.whiteLabelStatus !== 'active' && !user.isAdmin) {
        return res.status(403).json({ message: "Make It Your Own add-on is required for custom domains." });
      }

      const { domain } = req.body;
      if (!domain || typeof domain !== 'string') {
        return res.status(400).json({ message: "Domain is required" });
      }

      const cleanBase = domain.toLowerCase().replace(/^(https?:\/\/)?(www\.)?/, '').replace(/\/$/, '').replace(/^portal\./, '');
      if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(cleanBase)) {
        return res.status(400).json({ message: "Invalid domain format. Enter your domain like: yourbusiness.com" });
      }

      const portalDomain = `portal.${cleanBase}`;

      const existing = await db.select().from(companySettings).where(
        and(eq(companySettings.customDomain, portalDomain), sql`${companySettings.userId} != ${userId}`)
      );
      if (existing.length > 0) {
        return res.status(409).json({ message: "This domain is already in use by another account." });
      }

      const currentSettings = await storage.getCompanySettings(userId);
      if (currentSettings?.cloudflareHostnameId && process.env.CLOUDFLARE_API_TOKEN && process.env.CLOUDFLARE_ZONE_ID) {
        try {
          await fetch(
            `https://api.cloudflare.com/client/v4/zones/${process.env.CLOUDFLARE_ZONE_ID}/custom_hostnames/${currentSettings.cloudflareHostnameId}`,
            {
              method: "DELETE",
              headers: { "Authorization": `Bearer ${process.env.CLOUDFLARE_API_TOKEN}` },
            }
          );
          console.log(`[CustomDomain] Removed old hostname ${currentSettings.customDomain} from Cloudflare before domain change`);
        } catch (cfErr) {
          console.error("[CustomDomain] Error removing old Cloudflare hostname:", cfErr);
        }
      }

      await storage.updateCompanySettings(userId, {
        customDomain: portalDomain,
        customDomainVerified: false,
        customDomainVerifiedAt: null,
        cloudflareHostnameId: null,
      });

      res.json({ domain: portalDomain, verified: false });
    } catch (error) {
      console.error("Error saving custom domain:", error);
      res.status(500).json({ message: "Failed to save custom domain" });
    }
  });

  app.get("/api/custom-domain/verify", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const settings = await storage.getCompanySettings(userId);
      if (!settings?.customDomain) {
        return res.status(400).json({ message: "No custom domain configured" });
      }

      const dns = await import("dns");
      const dnsPromises = dns.promises;

      let verified = false;
      try {
        const records = await dnsPromises.resolveCname(settings.customDomain);
        verified = records.some(r => r.toLowerCase().includes('fusephone.com') || r.toLowerCase().includes('replit'));
      } catch (dnsErr: any) {
        try {
          const aRecords = await dnsPromises.resolve4(settings.customDomain);
          if (aRecords.length > 0) {
            verified = true;
          }
        } catch {
          // no records found
        }
      }

      if (verified) {
        let cloudflareHostnameId = settings.cloudflareHostnameId || null;
        let cloudflareError: string | null = null;
        const isReverify = settings.customDomainVerified;

        if (process.env.CLOUDFLARE_API_TOKEN && process.env.CLOUDFLARE_ZONE_ID) {
          if (isReverify && cloudflareHostnameId) {
            try {
              const statusResponse = await fetch(
                `https://api.cloudflare.com/client/v4/zones/${process.env.CLOUDFLARE_ZONE_ID}/custom_hostnames/${cloudflareHostnameId}`,
                {
                  headers: { "Authorization": `Bearer ${process.env.CLOUDFLARE_API_TOKEN}` },
                }
              );
              const statusData = await statusResponse.json() as any;
              if (statusData.success && statusData.result) {
                const sslStatus = statusData.result.ssl?.status;
                const hostnameStatus = statusData.result.status;
                console.log(`[CustomDomain] Re-verify: hostname=${settings.customDomain} status=${hostnameStatus} ssl=${sslStatus}`);

                if (sslStatus !== 'active') {
                  console.log(`[CustomDomain] SSL not active (${sslStatus}), deleting and re-creating hostname`);
                  await fetch(
                    `https://api.cloudflare.com/client/v4/zones/${process.env.CLOUDFLARE_ZONE_ID}/custom_hostnames/${cloudflareHostnameId}`,
                    {
                      method: "DELETE",
                      headers: { "Authorization": `Bearer ${process.env.CLOUDFLARE_API_TOKEN}` },
                    }
                  );
                  cloudflareHostnameId = null;
                }
              } else {
                console.log(`[CustomDomain] Re-verify: hostname not found in Cloudflare, will re-create`);
                cloudflareHostnameId = null;
              }
            } catch (cfErr) {
              console.error("[CustomDomain] Error checking Cloudflare hostname status:", cfErr);
              cloudflareHostnameId = null;
            }
          }

          if (!cloudflareHostnameId) {
            try {
              const cfResponse = await fetch(
                `https://api.cloudflare.com/client/v4/zones/${process.env.CLOUDFLARE_ZONE_ID}/custom_hostnames`,
                {
                  method: "POST",
                  headers: {
                    "Authorization": `Bearer ${process.env.CLOUDFLARE_API_TOKEN}`,
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify({
                    hostname: settings.customDomain,
                    ssl: {
                      method: "http",
                      type: "dv",
                      settings: {
                        http2: "on",
                        min_tls_version: "1.2",
                      },
                    },
                  }),
                }
              );
              const cfData = await cfResponse.json() as any;
              if (cfData.success && cfData.result?.id) {
                cloudflareHostnameId = cfData.result.id;
                console.log(`[CustomDomain] Registered ${settings.customDomain} with Cloudflare, ID: ${cloudflareHostnameId}`);
              } else {
                const errorMsg = cfData.errors?.[0]?.message || "Unknown error";
                if (errorMsg.includes("already exists")) {
                  console.log(`[CustomDomain] Hostname ${settings.customDomain} already exists in Cloudflare`);
                  const listResponse = await fetch(
                    `https://api.cloudflare.com/client/v4/zones/${process.env.CLOUDFLARE_ZONE_ID}/custom_hostnames?hostname=${settings.customDomain}`,
                    {
                      headers: { "Authorization": `Bearer ${process.env.CLOUDFLARE_API_TOKEN}` },
                    }
                  );
                  const listData = await listResponse.json() as any;
                  if (listData.success && listData.result?.length > 0) {
                    cloudflareHostnameId = listData.result[0].id;
                    console.log(`[CustomDomain] Found existing hostname ID: ${cloudflareHostnameId}`);
                  }
                } else {
                  cloudflareError = `SSL provisioning failed: ${errorMsg}`;
                  console.error(`[CustomDomain] Cloudflare registration failed: ${errorMsg}`);
                }
              }
            } catch (cfErr) {
              cloudflareError = "SSL provisioning service unavailable";
              console.error("[CustomDomain] Cloudflare API error:", cfErr);
            }
          }
        }

        if (cloudflareError && !cloudflareHostnameId) {
          return res.json({
            domain: settings.customDomain,
            verified: false,
            message: `DNS verified but ${cloudflareError}. Please try again shortly.`,
          });
        }

        await storage.updateCompanySettings(userId, {
          customDomainVerified: true,
          customDomainVerifiedAt: new Date(),
          whiteLabelEnabled: true,
          ...(cloudflareHostnameId ? { cloudflareHostnameId } : {}),
        });

        res.json({
          domain: settings.customDomain,
          verified: true,
          message: isReverify ? "SSL re-verified! It may take a few minutes for the certificate to become active." : "Domain verified successfully!",
        });
      } else {
        res.json({
          domain: settings.customDomain,
          verified: false,
          message: "CNAME record not found. Please add a CNAME record pointing to app.fusephone.com",
        });
      }
    } catch (error) {
      console.error("Error verifying custom domain:", error);
      res.status(500).json({ message: "Failed to verify domain" });
    }
  });

