  app.post("/api/stripe/upgrade/preview", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { priceId } = req.body;
      if (!priceId) return res.status(400).json({ message: "Price ID required" });

      const [user] = await db.select().from(users).where(eq(users.id, userId));
      if (!user) return res.status(404).json({ message: "User not found" });
      if (!user.stripeSubscriptionId) {
        return res.status(400).json({ message: "No active subscription to upgrade." });
      }

      const { getUncachableStripeClient } = await import("./stripeClient");
      const stripe = await getUncachableStripeClient();

      const currentSub = await stripe.subscriptions.retrieve(user.stripeSubscriptionId);
      if (currentSub.status !== 'active' && currentSub.status !== 'trialing') {
        return res.status(400).json({ message: "Current subscription is not active" });
      }

      const invoice = await stripe.invoices.createPreview({
        customer: user.stripeCustomerId!,
        subscription: user.stripeSubscriptionId,
        subscription_details: {
          items: [{
            id: currentSub.items.data[0].id,
            price: priceId,
          }],
          proration_behavior: 'create_prorations',
        },
      });

      const prorationItems = (invoice.lines?.data || []).filter((line: any) => line.proration);
      const credit = prorationItems
        .filter((line: any) => line.amount < 0)
        .reduce((sum: number, line: any) => sum + Math.abs(line.amount), 0);
      const charge = prorationItems
        .filter((line: any) => line.amount > 0)
        .reduce((sum: number, line: any) => sum + line.amount, 0);

      res.json({
        totalDue: Math.max(0, (invoice.amount_due || 0)),
        credit,
        charge,
        currency: invoice.currency || 'usd',
        periodEnd: currentSub.items.data[0]?.current_period_end || currentSub.current_period_end,
      });
    } catch (error: any) {
      console.error("Error previewing upgrade:", error);
      res.status(500).json({ message: error.message || "Failed to preview upgrade" });
    }
  });

  app.post("/api/stripe/upgrade", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { priceId } = req.body;
      if (!priceId) return res.status(400).json({ message: "Price ID required" });

      const [user] = await db.select().from(users).where(eq(users.id, userId));
      if (!user) return res.status(404).json({ message: "User not found" });
      if (!user.stripeSubscriptionId) {
        return res.status(400).json({ message: "No active subscription to upgrade. Please subscribe first." });
      }

      const { getUncachableStripeClient } = await import("./stripeClient");
      const stripe = await getUncachableStripeClient();

      const currentSub = await stripe.subscriptions.retrieve(user.stripeSubscriptionId);
      if (currentSub.status !== 'active' && currentSub.status !== 'trialing') {
        return res.status(400).json({ message: "Current subscription is not active" });
      }

      const updatedSub = await stripe.subscriptions.update(user.stripeSubscriptionId, {
        items: [{
          id: currentSub.items.data[0].id,
          price: priceId,
        }],
        cancel_at_period_end: false,
        proration_behavior: 'create_prorations',
        payment_behavior: 'error_if_incomplete',
      });

      if (updatedSub.status !== 'active' && updatedSub.status !== 'trialing') {
        console.log(`[Upgrade] Subscription status after update: ${updatedSub.status}`);
        return res.status(402).json({ 
          message: "Payment failed. Please update your payment method and try again.",
          status: updatedSub.status,
        });
      }

      const priceItem = updatedSub.items.data[0];
      const product = await stripe.products.retrieve(priceItem.price.product as string);
      const tier = product.metadata?.tier ||
        (product.name?.toLowerCase().includes('elite') ? 'elite' : 'core');

      await db.update(users).set({
        subscriptionTier: tier,
        subscriptionStatus: 'active',
        subscriptionEndsAt: new Date((updatedSub.items.data[0]?.current_period_end || updatedSub.current_period_end || Math.floor(Date.now() / 1000) + 30 * 86400) * 1000),
      }).where(eq(users.id, userId));

      console.log(`[Upgrade] User ${userId} upgraded to ${tier}, proration applied`);
      res.json({ success: true, tier });
    } catch (error: any) {
      console.error("Error upgrading subscription:", error);
      if (error.type === 'StripeCardError') {
        return res.status(402).json({ message: "Payment failed. Please update your payment method and try again." });
      }
      res.status(500).json({ message: error.message || "Failed to upgrade subscription" });
    }
  });

