  app.post("/api/stripe/sync-subscription", isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const [user] = await db.select().from(users).where(eq(users.id, userId));
      console.log(`[Sync] Syncing subscription for user ${userId}, customerId: ${user?.stripeCustomerId}`);
      
      if (!user?.stripeCustomerId) {
        const { sessionId } = req.body || {};
        if (sessionId) {
          console.log(`[Sync] No customer ID, but have session ${sessionId}. Trying to retrieve...`);
          try {
            const { getUncachableStripeClient } = await import("./stripeClient");
            const stripe = await getUncachableStripeClient();
            const session = await stripe.checkout.sessions.retrieve(sessionId);
            if (session.customer && session.metadata?.userId === userId) {
              await db.update(users).set({ stripeCustomerId: session.customer as string }).where(eq(users.id, userId));
              console.log(`[Sync] Set customer ID from session: ${session.customer}`);
            }
          } catch (e) {
            console.error('[Sync] Failed to retrieve session:', e);
          }
        }
        const [refreshedUser] = await db.select().from(users).where(eq(users.id, userId));
        if (!refreshedUser?.stripeCustomerId) {
          console.log(`[Sync] No Stripe customer ID found for user ${userId}`);
          return res.json({ synced: false });
        }
      }

      const { getUncachableStripeClient } = await import("./stripeClient");
      const stripe = await getUncachableStripeClient();

      const [currentUser] = await db.select().from(users).where(eq(users.id, userId));
      const customerId = currentUser?.stripeCustomerId || user.stripeCustomerId;

      const allSubscriptions = await stripe.subscriptions.list({
        customer: customerId!,
        limit: 10,
      });
      console.log(`[Sync] Found ${allSubscriptions.data.length} subscriptions for customer ${customerId}:`, allSubscriptions.data.map(s => `${s.id} (${s.status})`).join(', '));

      // Sort by created date descending and find active/trialing subscriptions
      const activeSubs = allSubscriptions.data
        .filter(s => s.status === 'active' || s.status === 'trialing')
        .sort((a, b) => b.created - a.created);

      if (activeSubs.length > 0) {
        const sub = activeSubs[0]; // newest active subscription
        const priceId = sub.items.data[0]?.price?.id;
        
        let tier = 'core';
        if (priceId) {
          const price = await stripe.prices.retrieve(priceId);
          tier = (price.metadata?.tier as string) || 'core';
          if (!price.metadata?.tier || tier === 'core') {
            const product = await stripe.products.retrieve(price.product as string);
            tier = (product.metadata?.tier as string) || 
              (product.name?.toLowerCase().includes('early access') ? 'early_access' : product.name?.toLowerCase().includes('elite') ? 'elite' : product.name?.toLowerCase().includes('starter') ? 'starter' : 'core');
          }
        }

        if (activeSubs.length > 1) {
          console.log(`[Sync] Found ${activeSubs.length} active subscriptions, using newest (${sub.id}), canceling old ones`);
          for (let i = 1; i < activeSubs.length; i++) {
            try {
              await stripe.subscriptions.cancel(activeSubs[i].id);
              console.log(`[Sync] Canceled old duplicate subscription ${activeSubs[i].id}`);
            } catch (cancelErr) {
              console.error(`[Sync] Error canceling old sub ${activeSubs[i].id}:`, cancelErr);
            }
          }
        }

        const updateData: any = {
          stripeSubscriptionId: sub.id,
          subscriptionTier: tier,
          subscriptionStatus: 'active',
          subscriptionEndsAt: new Date((sub.items.data[0]?.current_period_end || sub.current_period_end || Math.floor(Date.now() / 1000) + 30 * 86400) * 1000),
        };

        await db.update(users).set(updateData).where(eq(users.id, userId));
        console.log(`[Sync] Updated user ${userId}: tier=${tier}, subId=${sub.id}`);

        res.json({ synced: true, tier, status: 'active' });
      } else {
        const pendingSub = allSubscriptions.data.find(s => s.status === 'incomplete' || s.status === 'past_due');
        if (pendingSub) {
          res.json({ synced: false, status: pendingSub.status, message: "Payment is still processing" });
        } else {
          res.json({ synced: false });
        }
      }
    } catch (error) {
      console.error("Error syncing subscription:", error);
      res.status(500).json({ message: "Failed to sync subscription" });
    }
  });

  // === iOS In-App Purchases (Apple App Store direct) ===
  // Source of truth: Apple App Store Server API (verifyTransaction) +
  // App Store Server Notifications V2 webhook (signed JWS, x5c rooted at
  // Apple Root CA G3). The client posts /api/iap/sync after a successful
  // StoreKit purchase or restore; we re-fetch the transaction from Apple
  // (so a malicious client cannot forge a tier upgrade). Apple's webhook
  // then keeps state accurate for renewals, cancellations, expirations,
  // refunds, and grace periods.

  // In-memory dedup of Apple notificationUUIDs within process lifetime.
  // Webhook re-deliveries beyond this window simply re-apply the same
  // state (which is itself idempotent at the DB level).
  const recentIAPEvents = new Map<string, number>();

  // Mirror the Stripe-side add-on prerequisite rules
  // (see /api/stripe/fuse-ai/checkout) on the iOS path. Returns the reason
  // an add-on cannot be activated, or null if it can.
  // Apple already collected payment by the time we see a transaction, so
  // callers should still record the originalTransactionId — they just
  // shouldn't flip status to active. Support can manually reconcile later.
  // Order:
  //   1) Active base tier (active or trialing) is required for ALL add-ons,
  //      including admins, so that Apple receipts never grant entitlements
  //      on accounts whose tier itself has lapsed.
  //   2) ALL add-ons (whiteLabel / Make It Your Own, fuseAi, aiAssistant)
  //      require Elite (or admin / eliteBonus override). This matches the
  //      product policy: add-ons are Elite-only on every surface.
  function addonActivationBlockedReason(
    addon: AppleAddon,
    user: { subscriptionTier?: string | null; subscriptionStatus?: string | null; isAdmin?: boolean | null; eliteBonusEndsAt?: Date | null },
  ): string | null {
    const tierActive =
      user.subscriptionStatus === "active" || user.subscriptionStatus === "trialing";
    if (!tierActive) {
      console.warn(`[IAP gate] addon=${addon} blocked: no active base tier (tier=${user.subscriptionTier}, status=${user.subscriptionStatus})`);
      return "no active base tier";
    }
    const isAdmin = !!user.isAdmin;
    const isElite =
      isAdmin ||
      user.subscriptionTier === "elite" ||
      (user.eliteBonusEndsAt && user.eliteBonusEndsAt > new Date());
    if (!isElite) {
      const niceName =
        addon === "fuseAi" ? "FuseAI" :
        addon === "whiteLabel" ? "Make It Your Own" :
        "AI Virtual Assistant";
      console.warn(`[IAP gate] addon=${addon} blocked: ${niceName} requires Elite (tier=${user.subscriptionTier}, isAdmin=${isAdmin}, eliteBonusEndsAt=${user.eliteBonusEndsAt || 'null'})`);
      return `${niceName} requires the Elite plan`;
    }
    return null;
  }

  // ────────────────────────────────────────────────────────────────────────
  // Self-heal endpoint: the iOS paywall keeps a per-device list of every
  // Apple subscription it has ever activated (Capacitor Preferences =
  // iOS UserDefaults). That list survives logout, account switches, and
  // app updates — only an uninstall clears it. If a user previously
  // logged in as Account A on this iPhone and bought / restored a sub,
  // the entry stays even after Account A is deleted from our database,
  // which falsely blocks Account B from subscribing with the same Apple
  // ID. This endpoint lets the client confirm whether the alleged
  // owner still exists AND still owns that originalTransactionId on the
  // server. If not (account deleted, or txn was reassigned), the client
  // prunes the ghost entry and the paywall stops showing the bogus
  // "Subscription already linked" modal. No native rebuild needed —
  // ships with the next JS publish.
  // ────────────────────────────────────────────────────────────────────────
  app.post("/api/iap/check-device-history-entry", isAuthenticated, async (req, res) => {
    try {
      const originalTransactionId = String(req.body?.originalTransactionId || "").trim();
      const allegedUserId = String(req.body?.allegedUserId || "").trim();
      if (!originalTransactionId || !allegedUserId) {
        return res.status(400).json({ stillValid: false, reason: "missing_params" });
      }
      // Look up any user who currently owns this originalTransactionId in
      // any of the four Apple txn columns (base sub + 3 add-ons). Raw SQL
      // because the column names are stable and this avoids 4 OR clauses
      // through the Drizzle DSL.
      const result = await db.execute(sql`
        SELECT id, email
        FROM users
        WHERE apple_original_transaction_id = ${originalTransactionId}
           OR apple_fuse_ai_original_txn_id = ${originalTransactionId}
           OR apple_ai_assistant_original_txn_id = ${originalTransactionId}
           OR apple_white_label_original_txn_id = ${originalTransactionId}
        LIMIT 1
      `);
      const rows = (result as any).rows || [];
      const owner = rows[0] as { id: string; email: string | null } | undefined;
      const maskOwnerEmail = (e: string | null | undefined): string => {
        if (!e || typeof e !== "string") return "***";
        const at = e.indexOf("@");
        if (at <= 0) return "***";
        const local = e.slice(0, at);
        const domain = e.slice(at + 1);
        if (local.length <= 2) return `${local[0] || "*"}***@${domain}`;
        if (local.length === 3) return `${local[0]}***${local[2]}@${domain}`;
        return `${local.slice(0, 2)}***${local.slice(-1)}@${domain}`;
      };
      if (!owner) {
        console.log(
          `[device-history check] PRUNE originalTxn=${originalTransactionId} allegedUserId=${allegedUserId}: no current owner in DB (account deleted or never bound)`,
        );
        return res.json({ stillValid: false, reason: "no_owner_in_db" });
      }
      // Owner still exists. Tell the client the canonical (current) owner
      // so it can refresh its cached entry — the email we recorded at
      // purchase time may be stale if the owner changed their email.
      const masked = maskOwnerEmail(owner.email);
      console.log(
        `[device-history check] OK originalTxn=${originalTransactionId} allegedUserId=${allegedUserId} → currentOwnerUserId=${owner.id} maskedEmail=${masked}`,
      );
      return res.json({
        stillValid: true,
        currentOwnerUserId: owner.id,
        currentOwnerMaskedEmail: masked,
      });
    } catch (e: any) {
      console.error("[device-history check] failed (failing safe = keep entry):", e?.message || e);
      // Fail safe: when the server check itself errors, tell the client to
      // KEEP the local entry. We don't want to accidentally let a real
      // first-writer-wins conflict slip through during a transient outage.
      return res.status(500).json({ stillValid: true, reason: "server_error" });
    }
  });

  app.post("/api/iap/sync", isAuthenticated, async (req, res) => {
    // reqId tags every log line for this single sync attempt so the user can
    // grep one purchase end-to-end. Echoed back in the response so the client
    // can correlate too.
    const reqId = `iap_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
    try {
      const userId = getUserId(req);
      const clientReqId = String(req.body?.clientReqId || "").slice(0, 40);
      console.log(
        `[IAP sync ${reqId}] ENTRY userId=${userId} clientReqId=${clientReqId || "-"} ` +
        `bodyKeys=${Object.keys(req.body || {}).join(",")} jwsLen=${String(req.body?.jws || "").length} ` +
        `restore=${req.body?.restore === true} ua=${(req.headers["user-agent"] || "").slice(0, 80)}`,
      );
      // SK2-only path: client sends Apple's signed JWS string. We verify the
      // signature chain (Apple Root CA G3 → intermediate → leaf) and trust
      // the decoded payload — no second App Store API round-trip needed.
      const jws = String(req.body?.jws || "").trim();
      if (!jws) {
        console.warn(`[IAP sync ${reqId}] REJECT: missing jws (userId=${userId})`);
        return res.status(400).json({ message: "jws required", reqId });
      }
      const transactionId = "(jws)";

      // Apple Guideline 2.1: the reviewer account MUST always show the IAP
      // paywall. The IAP plugin auto-replays prior approved transactions on
      // every app launch / restore, which would re-activate this account
      // ~1 second after login. Skip DB writes for the reviewer so they always
      // see the clean starter/inactive state and can re-test the purchase flow.
      try {
        const [u] = await db.select({ email: users.email }).from(users).where(eq(users.id, userId));
        if (u && isAppleReviewerEmail(u.email)) {
          console.log(`[IAP sync ${reqId}] SKIP apple-reviewer userId=${userId}`);
          return res.json({ synced: false, skipped: true, reason: 'apple_reviewer', reqId });
        }
      } catch (e) {
        console.error(`[IAP sync ${reqId}] reviewer lookup failed (userId=${userId}):`, e);
      }

      const verified: any = await verifyAppleSignedPayload(jws);
      if (!verified) {
        console.warn(`[IAP sync ${reqId}] REJECT: JWS signature verification failed (userId=${userId})`);
        return res.status(401).json({ message: "Invalid Apple signature", reqId });
      }
      const txn = {
        transactionId: String(verified.transactionId || ""),
        originalTransactionId: String(verified.originalTransactionId || ""),
        productId: String(verified.productId || ""),
        expiresDate: typeof verified.expiresDate === "number" ? verified.expiresDate : undefined,
        purchaseDate: typeof verified.purchaseDate === "number" ? verified.purchaseDate : undefined,
        originalPurchaseDate:
          typeof verified.originalPurchaseDate === "number" ? verified.originalPurchaseDate : undefined,
        appAccountToken:
          typeof verified.appAccountToken === "string" ? verified.appAccountToken : undefined,
      };
      const nowMs = Date.now();
      const expiresInMs = typeof txn.expiresDate === "number" ? txn.expiresDate - nowMs : null;
      console.log(
        `[IAP sync ${reqId}] JWS_VERIFIED userId=${userId} txn=${txn.transactionId} originalTxn=${txn.originalTransactionId} ` +
        `productId=${txn.productId} appAccountToken=${txn.appAccountToken || "NONE"} ` +
        `purchaseDate=${txn.purchaseDate ? new Date(txn.purchaseDate).toISOString() : "null"} ` +
        `originalPurchaseDate=${txn.originalPurchaseDate ? new Date(txn.originalPurchaseDate).toISOString() : "null"} ` +
        `expiresDate=${txn.expiresDate ? new Date(txn.expiresDate).toISOString() : "null"} ` +
        `expiresInMs=${expiresInMs} (${expiresInMs !== null ? Math.round(expiresInMs / 1000) + "s" : "n/a"})`,
      );

      const productId = txn.productId || "";
      const addon = addonFromAppleProductId(productId);
      const tier = addon ? null : tierFromAppleProductId(productId);
      console.log(
        `[IAP sync ${reqId}] PRODUCT_MAPPED productId=${productId} → tier=${tier || "-"} addon=${addon || "-"}`,
      );

      if (!addon && !tier) {
        console.warn(`[IAP sync ${reqId}] REJECT: unrecognized productId=${productId} userId=${userId}`);
        return res.status(400).json({ message: "Unrecognized product", reqId, productId });
      }

      // Ownership: SK2 always sets appAccountToken = user.id at purchase
      // time on the client. The signed JWS proves Apple saw it. If it
      // doesn't match the authenticated user, this is either a replayed
      // receipt from another account on the same device, or someone trying
      // to bind a leaked transaction. Reject unconditionally.
      if (!txn.appAccountToken) {
        console.warn(
          `[IAP sync ${reqId}] REJECT: missing appAccountToken userId=${userId} txn=${txn.transactionId} product=${productId} — SK2 should always set this`,
        );
        return res.status(403).json({ message: "Purchase is missing account binding. Please subscribe again.", reqId });
      }
      // appAccountToken mismatch is NOT a hard reject anymore.
      //
      // Apple's subscription-group rule: every renewal/upgrade/downgrade
      // within the same Subscription Group reuses the SAME
      // originalTransactionId AND preserves the appAccountToken from the
      // very first purchase. So if user A buys starter on a device, then
      // signs out and user B (same Apple ID) upgrades to core, the JWS
      // for B's core purchase still carries A's appAccountToken. A hard
      // reject here was blocking every legitimate "switched app account
      // on the same Apple ID" flow — which is exactly what hit production
      // (see the upgrade→ "couldn't verify" timeout we just debugged).
      //
      // Real cross-account theft is caught by the FIRST-WRITER-WINS guard
      // a few lines below, which checks the database for any OTHER user
      // already holding this originalTransactionId. If nobody else owns
      // it, the current user is allowed to take ownership (which is the
      // correct outcome — Apple has charged THIS Apple ID and the user
      // is signed into our app right now).
      if (txn.appAccountToken !== userId) {
        console.warn(
          `[IAP sync ${reqId}] APPACCOUNT_MISMATCH (allowing, first-writer-wins decides): ` +
          `appAccountToken=${txn.appAccountToken} signedInUser=${userId} txn=${txn.transactionId} ` +
          `originalTxn=${txn.originalTransactionId} product=${productId}`,
        );
      } else {
        console.log(`[IAP sync ${reqId}] APPACCOUNT_OK matches signed-in user`);
      }

      // NOTE: previously had an "ACCOUNT-AGE GUARD" here that rejected any
      // sync where Apple's originalPurchaseDate was earlier than this user's
      // createdAt. That was wrong: it broke the legitimate "deleted account
      // re-signs in with same Apple ID" and the TestFlight test-wipe flows,
      // because StoreKit (correctly) keeps the SAME originalTransactionId
      // and originalPurchaseDate forever for a given subscription group on a
      // given Apple ID — even across new FusePhone signups. The
      // first-writer-wins guard immediately below is the right check: it
      // rejects only when ANOTHER live user row still holds this Apple
      // originalTransactionId. If nobody else holds it, the current
      // signed-in user is the rightful owner (Apple just verified the JWS
      // and charged THIS Apple ID). Removing the age guard.
      // (originalPurchaseDate is still logged via the JWS-verified line
      // above for audit trails.)

      // FIRST-WRITER-WINS cross-account guard.
      // The IAP plugin auto-replays prior approved transactions on app
      // launch / restore. If those receipts were originally claimed by a
      // different FusePhone account (e.g. a previous account on the same
      // device, or another Apple ID), they must NOT silently transfer
      // entitlements to whoever is logged in now.
      // Rule: if this Apple originalTransactionId is already stored on a
      // different user row (in any of: tier, white_label, fuse_ai, ai_assistant
      // columns), reject the sync.
      try {
        const otxn = txn.originalTransactionId || txn.transactionId;
        const conflictRows = await db.execute(sql`
          SELECT id, email FROM users
          WHERE id <> ${userId}
            AND (
              apple_original_transaction_id = ${otxn}
              OR apple_white_label_original_txn_id = ${otxn}
              OR apple_fuse_ai_original_txn_id = ${otxn}
              OR apple_ai_assistant_original_txn_id = ${otxn}
            )
          LIMIT 1
        `);
        if (conflictRows.rows.length > 0) {
          const other = conflictRows.rows[0] as { id: string; email: string };
          // Mask the owner's email before sending it to the client. We
          // want the rejected user to RECOGNIZE the account if it's
          // their own, but we don't want to leak the full address of
          // an unrelated user. Format: ga***l@gmail.com
          const maskOwnerEmail = (e: string | null | undefined): string => {
            if (!e || typeof e !== "string") return "***";
            const at = e.indexOf("@");
            if (at <= 0) return "***";
            const local = e.slice(0, at);
            const domain = e.slice(at + 1);
            if (local.length <= 2) return `${local[0] || "*"}***@${domain}`;
            if (local.length === 3) return `${local[0]}***${local[2]}@${domain}`;
            return `${local.slice(0, 2)}***${local.slice(-1)}@${domain}`;
          };
          const masked = maskOwnerEmail(other.email);
          console.warn(
            `[IAP sync ${reqId}] REJECT first-writer-wins: originalTxn ${otxn} already owned by user ${other.id} (${other.email}); refusing to bind to user ${userId}`,
          );
          return res.status(409).json({
            synced: false,
            blockedReason: "owned_by_other_account",
            otherAccountEmail: masked,
            originalTransactionId: otxn,
            message: `This Apple ID's subscription is already linked to ${masked}. Sign in to that account to use it, or cancel the subscription in iPhone Settings → Subscriptions before subscribing on a new account.`,
            reqId,
          });
        }
        console.log(`[IAP sync ${reqId}] FIRST_WRITER_OK no other user owns originalTxn=${otxn}`);
      } catch (conflictErr) {
        console.error(`[IAP sync ${reqId}] conflict check FAILED (continuing):`, conflictErr);
      }

      const expiresMs = typeof txn.expiresDate === "number" ? txn.expiresDate : null;
      const expiresAt = expiresMs ? new Date(expiresMs) : null;
      const originalTransactionId = txn.originalTransactionId || txn.transactionId;

      // Stale-transaction guard: auto-renewable subscriptions always have a
      // future expiresDate when currently entitled. Reject expired or
      // missing-expiry transactions so a leaked old transactionId can't be
      // replayed to re-grant access. Renewals come in via the webhook
      // (DID_RENEW), which carries the new expiresDate.
      if (!expiresMs || expiresMs <= Date.now()) {
        const ageSec = expiresMs ? Math.round((Date.now() - expiresMs) / 1000) : null;
        console.warn(
          `[IAP sync ${reqId}] REJECT stale-transaction: txn=${txn.transactionId} userId=${userId} ` +
          `productId=${productId} expiresMs=${expiresMs} expiresAt=${expiresMs ? new Date(expiresMs).toISOString() : "null"} ` +
          `nowMs=${Date.now()} expiredBySec=${ageSec}`,
        );
        return res.status(409).json({
          message: "This transaction is no longer active. Please subscribe again or restore purchases.",
          reqId,
          blockedReason: "stale_transaction",
          expiresAt: expiresMs ? new Date(expiresMs).toISOString() : null,
          expiredBySec: ageSec,
        });
      }
      console.log(`[IAP sync ${reqId}] STALE_GUARD_OK expires in ${Math.round((expiresMs - Date.now()) / 1000)}s`);
      // (Recency guard removed: SK2 always provides appAccountToken, so the
      // first-writer-wins + appAccountToken match above already prevent
      // cross-account auto-replay binding.)

      const updateData: any = {};
      let activated = true;
      let blockedReason: string | null = null;
      if (tier) {
        // ROOT-FIX: Apple treats "buy lower tier while higher tier is still
        // active" as a QUEUED downgrade — current entitlement stays on the
        // higher tier until next renewal. If we naively overwrite the user
        // row with the lower tier here, our DB falls out of sync with
        // Apple's actual active entitlement, which then causes:
        //   - User's UI shows "Starter" but Apple still has Core active
        //   - User taps "Upgrade to Core" → Apple shows native
        //     "You're currently subscribed to this" dialog
        //   - Looks broken to the user; impossible to recover without
        //     opening Sandbox Settings and cancelling
        // Detection: incoming tier is LOWER rank than current AND current
        // subscription has not yet expired. In that case we record the
        // originalTransactionId for reconciliation (so the future webhook
        // DID_RENEW for the new chain still finds this user) but do NOT
        // change tier/status/expiry. Apple's webhook will flip the tier
        // for real when the active entitlement actually crosses over.
        const TIER_RANK: Record<string, number> = { starter: 1, core: 2, elite: 3 };
        const [currentUser] = await db.select({
          subscriptionTier: users.subscriptionTier,
          subscriptionStatus: users.subscriptionStatus,
          subscriptionEndsAt: users.subscriptionEndsAt,
        }).from(users).where(eq(users.id, userId));
        const currentRank = TIER_RANK[currentUser?.subscriptionTier || ""] ?? 0;
        const incomingRank = TIER_RANK[tier] ?? 0;
        const currentEndsMs = currentUser?.subscriptionEndsAt ? new Date(currentUser.subscriptionEndsAt).getTime() : 0;
        const currentStillActive =
          (currentUser?.subscriptionStatus === "active" || currentUser?.subscriptionStatus === "trialing") &&
          currentEndsMs > Date.now();
        // STALE-EVENT GUARD: a real queued downgrade always has an incoming
        // expiresDate that's LATER than the current higher tier's expiry —
        // because the new lower-tier subscription period only starts when
        // the current Elite period ends. A stale event for a tier we already
        // replaced (e.g. the user did Starter → Elite, then the OLD Starter
        // chain replays a renewal/restore event) has an expiresDate at or
        // BEFORE the current Elite expiry. Without this check, the stale
        // Starter event was being misread as "user queued a downgrade to
        // Starter on May 15" and the banner kept popping up after upgrades.
        // 60-second skew tolerance keeps us safe from clock drift.
        const STALE_SKEW_MS = 60 * 1000;
        const incomingIsAfterCurrent = !!(expiresMs && currentEndsMs && expiresMs > currentEndsMs + STALE_SKEW_MS);
        if (currentRank > 0 && incomingRank > 0 && incomingRank < currentRank && currentStillActive && incomingIsAfterCurrent) {
          console.warn(
            `[IAP sync] QUEUED-DOWNGRADE detected: user ${userId} currently on ${currentUser?.subscriptionTier} ` +
            `(rank ${currentRank}, expires ${currentUser?.subscriptionEndsAt?.toISOString?.() || 'n/a'}) ` +
            `received sync for lower tier ${tier} (rank ${incomingRank}, incoming expires ${expiresAt?.toISOString?.() || 'n/a'}). ` +
            `Apple still considers ${currentUser?.subscriptionTier} active until renewal — recording originalTxn ` +
            `${originalTransactionId} + pendingTier=${tier} effectiveAt=${currentUser?.subscriptionEndsAt?.toISOString?.() || 'n/a'} for UI banner; ` +
            `NOT changing tier on user row.`,
          );
          // Persist the originalTransactionId so the future DID_RENEW
          // webhook can match this user. Also persist pendingTier so the
          // UI can surface a "Downgrading to X on Y" banner. Do NOT touch
          // tier/status/endsAt — the current higher tier stays active.
          updateData.appleOriginalTransactionId = originalTransactionId;
          updateData.pendingTier = tier;
          updateData.pendingTierEffectiveAt = currentUser?.subscriptionEndsAt || null;
        } else if (currentRank > 0 && incomingRank > 0 && incomingRank < currentRank && currentStillActive && !incomingIsAfterCurrent) {
          // Stale event for a tier we already replaced. Don't rewrite the
          // user row, don't queue a phantom downgrade. Do still record the
          // originalTransactionId so future events on this chain (refunds,
          // late renewal pings) can still find this user for reconciliation.
          updateData.appleOriginalTransactionId = originalTransactionId;
          console.warn(
            `[IAP sync] STALE-LOWER-TIER ignored: user ${userId} on ${currentUser?.subscriptionTier} ` +
            `(expires ${currentUser?.subscriptionEndsAt?.toISOString?.() || 'n/a'}) received sync for lower ${tier} ` +
            `with expires ${expiresAt?.toISOString?.() || 'n/a'} — incoming is NOT after current, treating as replay of ` +
            `replaced subscription. Recording originalTxn=${originalTransactionId} for reconciliation; skipping tier write.`,
          );
        } else {
          updateData.subscriptionTier = tier;
          updateData.subscriptionStatus = "active";
          updateData.subscriptionEndsAt = expiresAt;
          updateData.appleOriginalTransactionId = originalTransactionId;
          // Clear any queued downgrade — either the user re-upgraded, the
          // downgrade actually landed (incomingRank == currentRank with
          // tier change already reflected), or this is a fresh subscribe.
          updateData.pendingTier = null;
          updateData.pendingTierEffectiveAt = null;
          console.log(
            `[IAP sync] applying tier write: ${currentUser?.subscriptionTier || '(none)'} → ${tier} ` +
            `(currentRank=${currentRank}, incomingRank=${incomingRank}, currentStillActive=${currentStillActive}, ` +
            `currentEndsAt=${currentUser?.subscriptionEndsAt?.toISOString?.() || 'n/a'})`,
          );
          // AUTO-UNBLOCK STRANDED ADD-ONS on upgrade to Elite. If the user
          // had previously downgraded while Apple still kept billing for
          // an add-on, our DB has it as inactive (status='inactive') with
          // a future apple_*_expires_at. The moment they're back on Elite
          // they're entitled to use it again — Apple is already billing,
          // and forcing them to "buy again" would create a duplicate
          // subscription. Re-activate any add-on whose Apple expiry is
          // still in the future. Webhook keeps the expiry fresh from now
          // on; this just closes the activation gap so the feature lights
          // up immediately. Pull the full row to read the addon expiries
          // (currentUser only selected the tier-related columns above).
          if (tier === "elite") {
            try {
              const [fullUser] = await db.select().from(users).where(eq(users.id, userId));
              const nowMsLocal = Date.now();
              for (const [addonKey, addonCols] of Object.entries(ADDON_USER_COLUMNS) as [AppleAddon, typeof ADDON_USER_COLUMNS[AppleAddon]][]) {
                const addonExpiresAt = fullUser?.[addonCols.expiresAtCol] as Date | null | undefined;
                const addonStatus = fullUser?.[addonCols.statusCol] as string | null | undefined;
                if (
                  addonStatus !== "active" &&
                  addonExpiresAt &&
                  new Date(addonExpiresAt).getTime() > nowMsLocal
                ) {
                  updateData[addonCols.statusCol] = "active";
                  console.log(
                    `[IAP sync ${reqId}] AUTO_UNBLOCK_ADDON userId=${userId} addon=${addonKey} ` +
                    `was status=${addonStatus} expires=${new Date(addonExpiresAt).toISOString()} → activated ` +
                    `(tier upgrade to Elite re-grants access; Apple is still billing it).`,
                  );
                }
              }
            } catch (unblockErr: any) {
              console.warn(`[IAP sync ${reqId}] addon auto-unblock check failed (non-fatal): ${unblockErr?.message || unblockErr}`);
            }
          }
        }
      } else if (addon) {
        const cols = ADDON_USER_COLUMNS[addon];
        // Always persist the originalTransactionId so the webhook can find
        // this user later and so support can reconcile.
        updateData[cols.txnIdCol] = originalTransactionId;
        // STRANDED-ADDON VISIBILITY: always record the Apple expiry too,
        // even when activation is blocked. Add-ons live in their own
        // subscription groups, so a user can sit on Starter (which doesn't
        // grant the add-on) while Apple keeps billing the add-on every
        // month. Without an expiry stored we have no way to surface a
        // "Apple is still billing you for X" warning, and the user only
        // discovers the rogue charge on their statement. Recording the
        // expiry here lets the Billing UI flag it, give the user a clear
        // path to cancel, and prevents stale "ghost" rows after the
        // subscription actually lapses (UI can ignore expired ones).
        if (expiresAt) {
          updateData[cols.expiresAtCol] = expiresAt;
        }
        const [currentUser] = await db.select().from(users).where(eq(users.id, userId));
        blockedReason = currentUser ? addonActivationBlockedReason(addon, currentUser) : "user not found";
        if (blockedReason) {
          activated = false;
          console.warn(
            `[IAP] Add-on ${addon} purchase by user ${userId} blocked: ${blockedReason} ` +
            `(originalTxn=${originalTransactionId} expires=${expiresAt?.toISOString?.() || 'unknown'} stored for reconciliation/UI warning)`,
          );
        } else {
          updateData[cols.statusCol] = "active";
        }
      }
      console.log(
        `[IAP sync ${reqId}] DB_WRITE_BEGIN userId=${userId} updateData=${JSON.stringify(updateData, (_k, v) => v instanceof Date ? v.toISOString() : v)}`,
      );
      await db.update(users).set(updateData).where(eq(users.id, userId));
      console.log(
        `[IAP sync ${reqId}] DB_WRITE_OK userId=${userId} ${tier ? `tier=${tier}` : `addon=${addon}`} activated=${activated} expires=${expiresAt?.toISOString() || "unknown"} originalTxn=${originalTransactionId}`,
      );

      // QUEUED-CHANGE RECONCILE (tier only).
      //
      // The transaction JWS we just verified only carries the CURRENT
      // period's data — it has no field telling us what tier the user has
      // queued for next renewal. Apple exposes that solely via the
      // `signedRenewalInfo` JWS, which lives on the SubscriptionStatuses
      // endpoint and on the DID_CHANGE_RENEWAL_PREF / DOWNGRADE webhook.
      // Webhook delivery can lag minutes (especially in sandbox), so the
      // user can sit on "Elite Active" with no "Switching to Starter on
      // May 15 / Keep Elite" banner even though Apple already recorded
      // their downgrade. Hit Apple's API right here and patch
      // pendingTier / pendingTierEffectiveAt accordingly so the banner
      // appears the moment the client returns from a tier sync — without
      // waiting for the webhook.
      if (tier && originalTransactionId) {
        try {
          const statuses = await fetchAppleSubscriptionStatuses(originalTransactionId);
          const lastTxns = statuses?.data?.flatMap((g) => g.lastTransactions || []) || [];
          // Find the entry that matches our originalTransactionId — that's
          // the user's tier subscription group. Filter to subscription
          // statuses we trust for queued-tier info: 1=active, 3=billing
          // retry, 4=grace period. Status 2 (expired) and 5 (revoked) are
          // skipped — their renewal info is historical and would re-set
          // a stale pendingTier on a sub the user no longer has.
          const TRUSTED_STATUSES = new Set([1, 3, 4]);
          const match = lastTxns.find(
            (t) => t.originalTransactionId === originalTransactionId && TRUSTED_STATUSES.has(t.status),
          );
          if (match?.signedRenewalInfo) {
            const renewal: any = await verifyAppleSignedPayload(match.signedRenewalInfo);
            const autoRenewProductId: string = renewal?.autoRenewProductId || "";
            const autoRenewStatus: number | undefined = typeof renewal?.autoRenewStatus === "number" ? renewal.autoRenewStatus : undefined;
            const queuedTier = autoRenewProductId ? tierFromAppleProductId(autoRenewProductId) : null;
            // Refetch the row AFTER the tier write above, because the
            // earlier branches (QUEUED-DOWNGRADE at ~17730, STALE-LOWER-
            // TIER at ~17746, regular write at ~17758) each leave the
            // user row in different states. Comparing against the actual
            // post-write tier — not the incoming `tier` variable — is
            // what correctly distinguishes "user has a real queued
            // change" from "Apple confirms renewal stays put".
            const [postWrite] = await db
              .select({
                subscriptionTier: users.subscriptionTier,
                subscriptionEndsAt: users.subscriptionEndsAt,
                pendingTier: users.pendingTier,
              })
              .from(users)
              .where(eq(users.id, userId));
            const dbTier = postWrite?.subscriptionTier || null;
            const dbEndsAt = postWrite?.subscriptionEndsAt || null;
            const dbPendingTier = postWrite?.pendingTier || null;
            console.log(
              `[IAP sync ${reqId}] RENEWAL_INFO originalTxn=${originalTransactionId} status=${match.status} ` +
              `autoRenewProductId=${autoRenewProductId || "-"} autoRenewStatus=${autoRenewStatus ?? "-"} ` +
              `incomingTier=${tier} dbTier=${dbTier || "-"} dbPendingTier=${dbPendingTier || "-"} queuedTier=${queuedTier || "-"}`,
            );
            if (autoRenewStatus === 0) {
              // Auto-renew is OFF — user cancelled. There's no "queued
              // tier change", just an upcoming end-of-access. Clear any
              // stale pendingTier so the cancellation banner (driven by
              // subscriptionEndsAt + cancelled status) is the only thing
              // shown. Skip the write when there's nothing to clear.
              if (dbPendingTier) {
                await db.update(users).set({
                  pendingTier: null,
                  pendingTierEffectiveAt: null,
                }).where(eq(users.id, userId));
                console.log(
                  `[IAP sync ${reqId}] PENDING_TIER_CLEAR (autoRenew OFF) userId=${userId} ` +
                  `cleared stale pendingTier=${dbPendingTier}`,
                );
              }
            } else if (autoRenewStatus === 1 && queuedTier && dbTier && queuedTier !== dbTier) {
              // Real queued change: Apple says next renewal will switch
              // tiers. Effective date is the current period's end on the
              // user row (which the QUEUED-DOWNGRADE branch leaves as the
              // higher tier's expiry, and the regular-write branch sets
              // to expiresAt). Fall back to expiresAt if dbEndsAt is
              // missing.
              const effectiveAt = dbEndsAt || expiresAt;
              if (effectiveAt) {
                await db.update(users).set({
                  pendingTier: queuedTier,
                  pendingTierEffectiveAt: effectiveAt,
                }).where(eq(users.id, userId));
                console.log(
                  `[IAP sync ${reqId}] PENDING_TIER_SET userId=${userId} ` +
                  `dbTier=${dbTier} → queued ${queuedTier} effectiveAt=${effectiveAt.toISOString()} ` +
                  `(detected via Apple SubscriptionStatuses, ahead of webhook)`,
                );
              }
            } else if (autoRenewStatus === 1 && queuedTier && dbTier && queuedTier === dbTier && dbPendingTier) {
              // Apple confirms next renewal stays on the current tier —
              // any pendingTier on the row is stale (e.g. the user
              // queued a downgrade then re-upgraded, cancelling it).
              // Only clear when there's actually something to clear, so
              // we don't trample a concurrent webhook write that just
              // applied newer state.
              await db.update(users).set({
                pendingTier: null,
                pendingTierEffectiveAt: null,
              }).where(eq(users.id, userId));
              console.log(
                `[IAP sync ${reqId}] PENDING_TIER_CLEAR userId=${userId} ` +
                `Apple confirms next renewal stays on ${dbTier}, cleared stale pendingTier=${dbPendingTier}`,
              );
            }
          } else {
            console.log(
              `[IAP sync ${reqId}] RENEWAL_INFO no trusted-status match for originalTxn=${originalTransactionId} ` +
              `in ${lastTxns.length} lastTransactions (skipping pendingTier reconcile)`,
            );
          }
        } catch (renewalErr: any) {
          // Non-fatal: webhook will eventually correct this. Log so we can
          // tell apart "Apple API down" from "user genuinely has no queued
          // change" when debugging missing banners.
          console.warn(
            `[IAP sync ${reqId}] RENEWAL_RECONCILE_FAILED (non-fatal): ${renewalErr?.message || renewalErr}`,
          );
        }
      }

      // Push subscription change to the client over WebSocket so the
      // paywall reconciles instantly without waiting for polling. Critical
      // for cross-grade flows where Apple sends the "real" tier through
      // the webhook seconds-to-minutes after the initial JWS sync.
      try {
        emitToUser(userId, userId, {
          type: "subscription.changed",
          tenantId: userId,
          source: "iap.sync",
          tier: tier || undefined,
          addon: addon || undefined,
          activated,
        });
      } catch (emitErr) {
        console.warn("[IAP sync] emitToUser failed (non-fatal):", emitErr);
      }

      if (!activated) {
        console.warn(`[IAP sync ${reqId}] RESPOND 409 addon=${addon} reason=${blockedReason}`);
        return res.status(409).json({
          synced: false,
          addon,
          status: "inactive",
          message: blockedReason || "Add-on cannot be activated. Please contact support.",
          reqId,
        });
      }

      console.log(`[IAP sync ${reqId}] RESPOND 200 synced=true ${tier ? "tier=" + tier : "addon=" + addon}`);
      res.json({
        synced: true,
        tier: tier || undefined,
        addon: addon || undefined,
        status: "active",
        reqId,
      });
    } catch (error: any) {
      console.error(`[IAP sync ${reqId}] UNCAUGHT_ERROR:`, error?.stack || error);
      res.status(500).json({ message: "Failed to sync subscription", reqId, error: String(error?.message || error) });
    }
  });

  // App Store Server Notifications V2 — configure in App Store Connect:
  //   App Information → App Store Server Notifications →
  //   Production Server URL: https://app.fusephone.com/api/iap/webhook
  //   Sandbox    Server URL: https://app.fusephone.com/api/iap/webhook
  // Apple POSTs { signedPayload: "<JWS>" }; we verify the chain rooted at
  // Apple Root CA G3 before trusting any state mutation.
  app.post("/api/iap/webhook", async (req, res) => {
    try {
      const signedPayload = req.body?.signedPayload;
      if (!signedPayload || typeof signedPayload !== "string") {
        return res.status(400).json({ message: "signedPayload required" });
      }

      const payload = await verifyAppleSignedPayload(signedPayload);
      if (!payload) {
        return res.status(401).json({ message: "Invalid signature" });
      }

      // Idempotency by Apple's notificationUUID
      const notifUUID: string | undefined = payload.notificationUUID;
      if (notifUUID) {
        if (recentIAPEvents.has(notifUUID)) {
          return res.json({ ok: true, deduped: true });
        }
        recentIAPEvents.set(notifUUID, Date.now());
        if (recentIAPEvents.size > 5000) {
          const cutoff = Date.now() - 24 * 60 * 60 * 1000;
          for (const [k, ts] of recentIAPEvents) {
            if (ts < cutoff) recentIAPEvents.delete(k);
          }
        }
      }

      const notificationType: string = payload.notificationType || "";
      const subtype: string = payload.subtype || "";

      // Decode the embedded transaction info (JWS within JWS).
      const data = payload.data || {};
      const signedTxn: string | undefined = data.signedTransactionInfo;
      const txnInfo = signedTxn ? await verifyAppleSignedPayload(signedTxn) : null;
      // RAW envelope log — single line at the very top so you can grep one
      // notification end-to-end. Includes EVERYTHING Apple sent us, even
      // for notification types we currently ignore. Use this to confirm
      // whether Apple actually fired a DID_CHANGE_RENEWAL_PREF / SUBSCRIBED
      // (UPGRADE) when you upgrade between tiers in the same subscription
      // group.
      try {
        console.log(
          `[IAP WH RAW] notificationType=${notificationType || "(missing)"} subtype=${subtype || "-"} ` +
          `notificationUUID=${payload.notificationUUID || "-"} env=${data.environment || "-"} signedDate=${payload.signedDate ? new Date(payload.signedDate).toISOString() : "-"} ` +
          `bundleId=${data.bundleId || "-"} bundleVersion=${data.bundleVersion || "-"} ` +
          `productId=${txnInfo?.productId || "-"} ` +
          `transactionId=${txnInfo?.transactionId || "-"} originalTransactionId=${txnInfo?.originalTransactionId || "-"} ` +
          `appAccountToken=${txnInfo?.appAccountToken || "-"} ` +
          `purchaseDate=${typeof txnInfo?.purchaseDate === "number" ? new Date(txnInfo.purchaseDate).toISOString() : "-"} ` +
          `expiresDate=${typeof txnInfo?.expiresDate === "number" ? new Date(txnInfo.expiresDate).toISOString() : "-"} ` +
          `autoRenewProductId=${data?.signedRenewalInfo ? "(see renewalInfo)" : "-"}`
        );
      } catch (e) {
        console.warn("[IAP WH RAW] log build failed (non-fatal):", e);
      }
      // Decode renewal info too — for DID_CHANGE_RENEWAL_PREF/DOWNGRADE the
      // signedTransactionInfo still describes the CURRENT (higher) tier
      // because Apple keeps the user on it until renewal, so the queued
      // lower tier is only visible via renewalInfo.autoRenewProductId.
      const signedRenewalInfo: string | undefined = data.signedRenewalInfo;
      const renewalInfo = signedRenewalInfo
        ? await verifyAppleSignedPayload(signedRenewalInfo)
        : null;
      const autoRenewProductId: string = renewalInfo?.autoRenewProductId || "";
      const queuedTier = autoRenewProductId
        ? tierFromAppleProductId(autoRenewProductId)
        : null;
      // autoRenewStatus: 0 = user disabled auto-renew (subscription will end
      // at expiresDate, no further charge); 1 = auto-renew on. Apple sends
      // DID_CHANGE_RENEWAL_STATUS whenever this flips. We mirror the bit on
      // our side so the paywall can stop blocking downgrades on add-ons that
      // are already cancelling, and the Billing card can show the end date.
      const autoRenewStatus: number | null =
        typeof renewalInfo?.autoRenewStatus === "number"
          ? renewalInfo.autoRenewStatus
          : null;

      if (!txnInfo) {
        console.log(`[IAP webhook] ${notificationType}/${subtype}: no txn info, skipping`);
        return res.json({ ok: true });
      }

      const originalTransactionId: string | undefined = txnInfo.originalTransactionId;
      const productId: string = txnInfo.productId || "";
      const addon: AppleAddon | null = addonFromAppleProductId(productId);
      const tier = addon ? null : tierFromAppleProductId(productId);
      const expiresMs: number | null =
        typeof txnInfo.expiresDate === "number" ? txnInfo.expiresDate : null;
      const expiresAt: Date | null = expiresMs ? new Date(expiresMs) : null;
      const appAccountToken: string | undefined = txnInfo.appAccountToken;

      // Map back to our user. Preferred: appAccountToken (we set this to the
      // user.id at order time). Fallback: any of the per-product Apple
      // originalTransactionId columns (tier or any add-on).
      let userRow: any = null;
      if (appAccountToken) {
        const rows = await db
          .select()
          .from(users)
          .where(eq(users.id, appAccountToken));
        userRow = rows[0] || null;
      }
      if (!userRow && originalTransactionId) {
        const txnIdCol = addon ? ADDON_USER_COLUMNS[addon].txnIdCol : "appleOriginalTransactionId";
        const rows = await db
          .select()
          .from(users)
          .where(eq((users as any)[txnIdCol], originalTransactionId));
        userRow = rows[0] || null;
      }
      if (!userRow) {
        console.log(
          `[IAP WH MATCH] no_user_found notificationType=${notificationType}/${subtype} ` +
          `appAccountToken=${appAccountToken || "-"} origTxnId=${originalTransactionId || "-"} productId=${productId || "-"}`,
        );
        return res.json({ ok: true });
      }
      // Snapshot of the user row BEFORE we change anything — so the next
      // [IAP WH DECISION] / [IAP WH RESULT] line can be diffed against it.
      console.log(
        `[IAP WH MATCH] user=${userRow.id} email=${userRow.email || "-"} ` +
        `currentTier=${userRow.subscriptionTier || "-"} currentStatus=${userRow.subscriptionStatus || "-"} ` +
        `currentEndsAt=${userRow.subscriptionEndsAt ? new Date(userRow.subscriptionEndsAt).toISOString() : "-"} ` +
        `pendingTier=${userRow.pendingTier || "-"} pendingTierEffectiveAt=${userRow.pendingTierEffectiveAt ? new Date(userRow.pendingTierEffectiveAt).toISOString() : "-"} ` +
        `incomingTier=${tier || "-"} incomingAddon=${addon || "-"} incomingExpires=${expiresAt ? expiresAt.toISOString() : "-"} ` +
        `queuedAutoRenewProductId=${autoRenewProductId || "-"} queuedTier=${queuedTier || "-"}`,
      );

      // Apple Guideline 2.1: the reviewer account must always present the IAP
      // paywall. Sandbox subs renew every ~5 min and would re-activate via this
      // webhook. Skip all DB writes for the reviewer.
      if (isAppleReviewerEmail(userRow.email)) {
        console.log(
          `[IAP webhook] ${notificationType}/${subtype} skipped for Apple reviewer (origTxnId=${originalTransactionId})`,
        );
        return res.json({ ok: true, skipped: true, reason: 'apple_reviewer' });
      }

      // Notification semantics (App Store Server Notifications V2):
      //   SUBSCRIBED, DID_RENEW, OFFER_REDEEMED, DID_CHANGE_RENEWAL_PREF (UPGRADE) → active
      //   EXPIRED, REVOKE, GRACE_PERIOD_EXPIRED                                    → inactive
      //   DID_FAIL_TO_RENEW (BILLING_RETRY), DID_CHANGE_RENEWAL_STATUS (AUTO_RENEW_DISABLED) →
      //     keep active until expiresDate
      const ACTIVE = new Set([
        "SUBSCRIBED",
        "DID_RENEW",
        "OFFER_REDEEMED",
        "DID_CHANGE_RENEWAL_PREF",
        "PRICE_INCREASE",
      ]);
      const REVOKE = new Set(["EXPIRED", "REVOKE", "GRACE_PERIOD_EXPIRED", "REFUND"]);

      const updateData: any = {};
      if (ACTIVE.has(notificationType)) {
        if (tier) {
          // QUEUED-DOWNGRADE: DID_CHANGE_RENEWAL_PREF/DOWNGRADE fires when
          // the user picks a lower tier in StoreKit. The current period is
          // unchanged (signedTransactionInfo still shows the higher tier);
          // only renewalInfo.autoRenewProductId reveals the queued lower
          // tier. Record it for the banner and DO NOT touch the active
          // tier or clear pending fields.
          if (
            notificationType === "DID_CHANGE_RENEWAL_PREF" &&
            subtype === "DOWNGRADE" &&
            queuedTier &&
            queuedTier !== tier
          ) {
            updateData.pendingTier = queuedTier;
            updateData.pendingTierEffectiveAt =
              expiresAt || userRow.subscriptionEndsAt || null;
            if (originalTransactionId)
              updateData.appleOriginalTransactionId = originalTransactionId;
            console.log(
              `[IAP webhook] DID_CHANGE_RENEWAL_PREF/DOWNGRADE recorded queued tier ${queuedTier} ` +
              `(current ${tier}) for user ${userRow.id}, effective ${updateData.pendingTierEffectiveAt}`,
            );
          } else {
            // STALE-WEBHOOK GUARD: Apple's App Store Server Notifications can
            // arrive out of order. After a tier change (e.g. Core → Starter),
            // a delayed DID_RENEW for the OLD higher-tier period can land
            // seconds/minutes later and would otherwise clobber the freshly
            // written newer tier. Mirror the freshness logic in /api/iap/sync:
            // if our stored period is still active and the incoming webhook
            // describes an OLDER period (expires <= currentEndsAt) for a
            // DIFFERENT tier, treat it as stale and skip the tier write.
            const TIER_RANK: Record<string, number> = { starter: 1, core: 2, elite: 3 };
            const currentRank = TIER_RANK[userRow.subscriptionTier || ""] ?? 0;
            const incomingRank = TIER_RANK[tier] ?? 0;
            const currentEndsMs = userRow.subscriptionEndsAt
              ? new Date(userRow.subscriptionEndsAt).getTime()
              : 0;
            const currentStillActive =
              (userRow.subscriptionStatus === "active" ||
                userRow.subscriptionStatus === "trialing") &&
              currentEndsMs > Date.now();
            const incomingEndsMs = expiresAt ? expiresAt.getTime() : 0;
            const incomingIsOlderPeriod =
              incomingEndsMs > 0 && currentEndsMs > 0 && incomingEndsMs <= currentEndsMs;
            if (
              currentStillActive &&
              incomingIsOlderPeriod &&
              currentRank > 0 &&
              incomingRank > 0 &&
              incomingRank !== currentRank
            ) {
              console.log(
                `[IAP webhook] STALE_SKIP ${notificationType}/${subtype} user=${userRow.id} ` +
                `incoming tier=${tier} expires=${expiresAt?.toISOString?.() || 'n/a'} ` +
                `current tier=${userRow.subscriptionTier} expires=${new Date(currentEndsMs).toISOString()} — ` +
                `ignoring out-of-order webhook for older period`,
              );
              // Still record the originalTransactionId for reconciliation, but
              // do NOT touch tier/status/endsAt.
              if (originalTransactionId) {
                updateData.appleOriginalTransactionId = originalTransactionId;
              }
            } else {
              updateData.subscriptionTier = tier;
              updateData.subscriptionStatus = "active";
              if (expiresAt) updateData.subscriptionEndsAt = expiresAt;
              if (originalTransactionId)
                updateData.appleOriginalTransactionId = originalTransactionId;
              // A successful renewal/upgrade implies auto-renew is on again
              // (Apple won't renew otherwise). Clear any prior cancellation
              // flag so the UI stops showing "Cancelling on …".
              updateData.appleAutoRenewOff = false;
              // Only clear the queued-downgrade banner when the tier actually
              // CHANGED on this event (e.g. DID_RENEW landed the queued lower
              // tier, or the user re-upgraded via DID_CHANGE_RENEWAL_PREF/
              // UPGRADE). Same-tier renewals must NOT clear the pending
              // banner that was set earlier.
              if (tier !== userRow.subscriptionTier) {
                updateData.pendingTier = null;
                updateData.pendingTierEffectiveAt = null;
              }
            }
          }
        } else if (addon) {
          const cols = ADDON_USER_COLUMNS[addon];
          // Always persist the originalTransactionId so future webhooks /
          // sync calls can locate this user, even if we can't activate now.
          if (originalTransactionId)
            updateData[cols.txnIdCol] = originalTransactionId;
          const blockedReason = addonActivationBlockedReason(addon, userRow);
          if (blockedReason) {
            console.warn(
              `[IAP webhook] Add-on ${addon} for user ${userRow.id} not activated: ${blockedReason}`,
            );
          } else {
            updateData[cols.statusCol] = "active";
            // ALWAYS keep the expires/renewal date fresh on every webhook so
            // the Billing card can show "Renews on DATE" while active.
            if (expiresAt) updateData[cols.expiresAtCol] = expiresAt;
            // Renewal/upgrade implies auto-renew is on. Clear cancelling.
            updateData[cols.autoRenewOffCol] = false;
          }
        }
      } else if (REVOKE.has(notificationType)) {
        if (tier) {
          updateData.subscriptionStatus = "inactive";
          if (expiresAt) updateData.subscriptionEndsAt = expiresAt;
          updateData.appleAutoRenewOff = false;
        } else if (addon) {
          const cols = ADDON_USER_COLUMNS[addon];
          updateData[cols.statusCol] = "inactive";
          updateData[cols.expiresAtCol] = null;
          updateData[cols.autoRenewOffCol] = false;
        }
      } else if (notificationType === "DID_FAIL_TO_RENEW") {
        // Apple keeps access until expiresDate. Don't flip status yet.
        if (tier && expiresAt) updateData.subscriptionEndsAt = expiresAt;
        if (addon && expiresAt) updateData[ADDON_USER_COLUMNS[addon].expiresAtCol] = expiresAt;
      } else if (notificationType === "DID_CHANGE_RENEWAL_STATUS") {
        // The user toggled auto-renew in iOS Settings → Subscriptions.
        // autoRenewStatus=0 means it's now OFF (will not renew at expiresDate).
        // autoRenewStatus=1 means it's back ON. Status column stays 'active'
        // either way until the period actually expires (REVOKE branch above).
        if (tier) {
          if (expiresAt) updateData.subscriptionEndsAt = expiresAt;
          if (autoRenewStatus === 0) {
            updateData.appleAutoRenewOff = true;
          } else if (autoRenewStatus === 1) {
            updateData.appleAutoRenewOff = false;
          }
        } else if (addon) {
          const cols = ADDON_USER_COLUMNS[addon];
          // Always refresh the period end date so UI can label it
          // accurately (renews vs ends).
          if (expiresAt) updateData[cols.expiresAtCol] = expiresAt;
          if (autoRenewStatus === 0) {
            updateData[cols.autoRenewOffCol] = true;
          } else if (autoRenewStatus === 1) {
            updateData[cols.autoRenewOffCol] = false;
          }
        }
      }

      if (Object.keys(updateData).length > 0) {
        await db.update(users).set(updateData).where(eq(users.id, userRow.id));
        console.log(
          `[IAP webhook] ${notificationType}/${subtype} → user ${userRow.id}: ${JSON.stringify(updateData)}`,
        );
        // Push the change to the client so paywalls / banners reconcile
        // instantly. This is the bridge that closes the "polling timed out
        // before Apple's webhook arrived" gap on cross-grade purchases.
        try {
          emitToUser(userRow.id, userRow.id, {
            type: "subscription.changed",
            tenantId: userRow.id,
            source: "iap.webhook",
            notificationType,
            subtype: subtype || undefined,
            tier: updateData.subscriptionTier || undefined,
            addon: addon || undefined,
          });
        } catch (emitErr) {
          console.warn("[IAP webhook] emitToUser failed (non-fatal):", emitErr);
        }
      } else {
        console.log(
          `[IAP webhook] ${notificationType}/${subtype} → user ${userRow.id}: no-op`,
        );
      }

      res.json({ ok: true });
    } catch (error) {
      console.error("[IAP webhook] error:", error);
      res.status(500).json({ message: "Webhook error" });
    }
  });

  // === Google Play Billing (Android) ===
  // POST /api/iap/google/verify
  // Body: { productId: string, purchaseToken: string }
  // Mirrors /api/iap/sync: first-writer-wins, stale-transaction guard,
  // tier vs add-on routing, add-on activation gating, queued-downgrade
  // logic. The cordova-plugin-purchase client posts here right after
  // Play hands back an approved transaction. We fetch the authoritative
  // state from the Play Developer API, persist it, then acknowledge.
  app.post("/api/iap/google/verify", isAuthenticated, async (req, res) => {
    const reqId = `gpv_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
    try {
      const userId = getUserId(req);
      const purchaseToken = String(req.body?.purchaseToken || "").trim();
      const claimedProductId = String(req.body?.productId || "").trim();
      console.log(
        `[GP verify ${reqId}] ENTRY userId=${userId} productId=${claimedProductId} tokenLen=${purchaseToken.length}`,
      );
      if (!purchaseToken) {
        return res.status(400).json({ message: "purchaseToken required", reqId });
      }
      if (!isGoogleIAPConfigured()) {
        console.warn(`[GP verify ${reqId}] REJECT: Google Play Billing not configured on server`);
        return res.status(503).json({
          message:
            "Google Play Billing is not configured on the server yet. Ask the operator to set GOOGLE_PLAY_PACKAGE_NAME and GOOGLE_PLAY_SERVICE_ACCOUNT_KEY.",
          reqId,
        });
      }

      // Skip writes for the Google Play reviewer account so the reviewer
      // always sees the paywall (Play policy mirror of the Apple flow).
      try {
        const [u] = await db.select({ email: users.email }).from(users).where(eq(users.id, userId));
        if (u?.email && u.email.toLowerCase() === "googlereviewfusephone@gmail.com") {
          console.log(`[GP verify ${reqId}] SKIP google-reviewer userId=${userId}`);
          return res.json({ synced: false, skipped: true, reason: "google_reviewer", reqId });
        }
      } catch (e) {
        console.error(`[GP verify ${reqId}] reviewer lookup failed:`, e);
      }

      const sub = await fetchGoogleSubscription(purchaseToken, claimedProductId);
      if (!sub) {
        console.warn(`[GP verify ${reqId}] REJECT: fetchGoogleSubscription returned null`);
        return res.status(401).json({
          message: "Could not verify this purchase with Google Play.",
          reqId,
        });
      }
      const productId = sub.productId || claimedProductId;
      const addon: GoogleAddon | null = addonFromGoogleProductId(productId);
      const tier = addon ? null : tierFromGoogleProductId(productId);
      console.log(
        `[GP verify ${reqId}] FETCHED productId=${productId} state=${sub.state} expiresAt=${sub.expiryTimeMs ? new Date(sub.expiryTimeMs).toISOString() : "null"} oeai=${sub.obfuscatedExternalAccountId || "-"} tier=${tier || "-"} addon=${addon || "-"}`,
      );
      if (!tier && !addon) {
        return res.status(400).json({ message: "Unrecognized product", reqId, productId });
      }

      // SECURITY: enforce account binding from Play. We pass userId as
      // applicationUsername / obfuscatedExternalAccountId at order time
      // (see client/src/lib/iap-android.ts → store.applicationUsername).
      // If Play returns a different id than the caller's session, the
      // purchaseToken belongs to another FusePhone account — refuse it,
      // even before the first-writer-wins DB check. This closes a token
      // replay window where an attacker who scraped a stranger's token
      // could attach it to their own account before the legit user's
      // verify call lands.
      if (sub.obfuscatedExternalAccountId && sub.obfuscatedExternalAccountId !== userId) {
        console.warn(
          `[GP verify ${reqId}] REJECT account-binding mismatch: token bound to ${sub.obfuscatedExternalAccountId}, caller is ${userId}`,
        );
        return res.status(403).json({
          synced: false,
          blockedReason: "account_binding_mismatch",
          message:
            "This Google Play subscription is tied to a different FusePhone account. Sign in to that account, or cancel the subscription in the Play Store before subscribing on a new account.",
          reqId,
        });
      }

      // FIRST-WRITER-WINS across both Apple and Google token columns.
      // The Play purchaseToken is Google's equivalent of Apple's
      // originalTransactionId — STAYS the same across renewals — so a
      // single token uniquely identifies an entitlement chain forever.
      try {
        const conflictRows = await db.execute(sql`
          SELECT id, email FROM users
          WHERE id <> ${userId}
            AND (
              google_original_purchase_token = ${purchaseToken}
              OR google_white_label_purchase_token = ${purchaseToken}
              OR google_ai_assistant_purchase_token = ${purchaseToken}
            )
          LIMIT 1
        `);
        if (conflictRows.rows.length > 0) {
          const other = conflictRows.rows[0] as { id: string; email: string };
          const maskOwnerEmail = (e: string | null | undefined): string => {
            if (!e || typeof e !== "string") return "***";
            const at = e.indexOf("@");
            if (at <= 0) return "***";
            const local = e.slice(0, at);
            const domain = e.slice(at + 1);
            if (local.length <= 2) return `${local[0] || "*"}***@${domain}`;
            return `${local.slice(0, 2)}***${local.slice(-1)}@${domain}`;
          };
          const masked = maskOwnerEmail(other.email);
          console.warn(
            `[GP verify ${reqId}] REJECT first-writer-wins: purchaseToken already owned by ${other.id} (${other.email})`,
          );
          return res.status(409).json({
            synced: false,
            blockedReason: "owned_by_other_account",
            otherAccountEmail: masked,
            message: `This Google account's subscription is already linked to ${masked}. Sign in to that account to use it, or cancel the subscription in the Play Store before subscribing on a new account.`,
            reqId,
          });
        }
      } catch (conflictErr) {
        console.error(`[GP verify ${reqId}] conflict check FAILED (continuing):`, conflictErr);
      }

      // Stale-transaction guard: a live subscription has an expiryTime in
      // the future AND a state in ACTIVE / IN_GRACE_PERIOD. Anything else
      // (CANCELED-and-expired, EXPIRED, REVOKED, PAUSED past expiry) must
      // not grant entitlement.
      const expiresMs = sub.expiryTimeMs || null;
      const isLive =
        !!expiresMs &&
        expiresMs > Date.now() &&
        (sub.state === "SUBSCRIPTION_STATE_ACTIVE" ||
          sub.state === "SUBSCRIPTION_STATE_IN_GRACE_PERIOD" ||
          sub.state === "SUBSCRIPTION_STATE_CANCELED"); // CANCELED but still entitled until expiry
      if (!isLive) {
        console.warn(
          `[GP verify ${reqId}] REJECT stale-transaction state=${sub.state} expires=${expiresMs ? new Date(expiresMs).toISOString() : "null"}`,
        );
        return res.status(409).json({
          message: "This purchase is no longer active. Please subscribe again.",
          reqId,
          blockedReason: "stale_transaction",
        });
      }

      const expiresAt = expiresMs ? new Date(expiresMs) : null;
      const updateData: any = { googlePlayUserId: sub.obfuscatedExternalAccountId || userId };
      let activated = true;
      let blockedReason: string | null = null;

      if (tier) {
        const TIER_RANK: Record<string, number> = { starter: 1, core: 2, elite: 3 };
        const [currentUser] = await db.select({
          subscriptionTier: users.subscriptionTier,
          subscriptionStatus: users.subscriptionStatus,
          subscriptionEndsAt: users.subscriptionEndsAt,
        }).from(users).where(eq(users.id, userId));
        const currentRank = TIER_RANK[currentUser?.subscriptionTier || ""] ?? 0;
        const incomingRank = TIER_RANK[tier] ?? 0;
        const currentEndsMs = currentUser?.subscriptionEndsAt ? new Date(currentUser.subscriptionEndsAt).getTime() : 0;
        const currentStillActive =
          (currentUser?.subscriptionStatus === "active" || currentUser?.subscriptionStatus === "trialing") &&
          currentEndsMs > Date.now();
        const STALE_SKEW_MS = 60 * 1000;
        const incomingIsAfterCurrent = !!(expiresMs && currentEndsMs && expiresMs > currentEndsMs + STALE_SKEW_MS);
        if (currentRank > 0 && incomingRank > 0 && incomingRank < currentRank && currentStillActive && incomingIsAfterCurrent) {
          // Queued downgrade: Play keeps the higher tier until renewal.
          updateData.googleOriginalPurchaseToken = purchaseToken;
          updateData.pendingTier = tier;
          updateData.pendingTierEffectiveAt = currentUser?.subscriptionEndsAt || null;
          console.warn(
            `[GP verify ${reqId}] QUEUED-DOWNGRADE: keeping ${currentUser?.subscriptionTier}, scheduling ${tier} at ${updateData.pendingTierEffectiveAt}`,
          );
        } else if (currentRank > 0 && incomingRank > 0 && incomingRank < currentRank && currentStillActive && !incomingIsAfterCurrent) {
          // Stale replay of an old/replaced sub. Just record the token.
          updateData.googleOriginalPurchaseToken = purchaseToken;
          console.warn(`[GP verify ${reqId}] STALE-LOWER-TIER ignored (replay of replaced sub)`);
        } else {
          updateData.subscriptionTier = tier;
          updateData.subscriptionStatus = "active";
          updateData.subscriptionEndsAt = expiresAt;
          updateData.googleOriginalPurchaseToken = purchaseToken;
          updateData.pendingTier = null;
          updateData.pendingTierEffectiveAt = null;
          // Auto-unblock stranded add-ons on upgrade to Elite.
          if (tier === "elite") {
            try {
              const [fullUser] = await db.select().from(users).where(eq(users.id, userId));
              const nowMsLocal = Date.now();
              for (const [addonKey, addonCols] of Object.entries(GOOGLE_ADDON_USER_COLUMNS) as [GoogleAddon, typeof GOOGLE_ADDON_USER_COLUMNS[GoogleAddon]][]) {
                const addonExpiresAt = fullUser?.[addonCols.expiresAtCol] as Date | null | undefined;
                const addonStatus = fullUser?.[addonCols.statusCol] as string | null | undefined;
                if (addonStatus !== "active" && addonExpiresAt && new Date(addonExpiresAt).getTime() > nowMsLocal) {
                  updateData[addonCols.statusCol] = "active";
                  console.log(`[GP verify ${reqId}] AUTO_UNBLOCK_ADDON addon=${addonKey} activated`);
                }
              }
            } catch (unblockErr: any) {
              console.warn(`[GP verify ${reqId}] addon auto-unblock failed (non-fatal): ${unblockErr?.message || unblockErr}`);
            }
          }
        }
      } else if (addon) {
        const cols = GOOGLE_ADDON_USER_COLUMNS[addon];
        updateData[cols.tokenCol] = purchaseToken;
        if (expiresAt) updateData[cols.expiresAtCol] = expiresAt;
        const [currentUser] = await db.select().from(users).where(eq(users.id, userId));
        blockedReason = currentUser ? addonActivationBlockedReason(addon as any, currentUser) : "user not found";
        if (blockedReason) {
          activated = false;
          console.warn(`[GP verify ${reqId}] addon ${addon} blocked: ${blockedReason}`);
        } else {
          updateData[cols.statusCol] = "active";
        }
      }

      console.log(
        `[GP verify ${reqId}] DB_WRITE_BEGIN updateData=${JSON.stringify(updateData, (_k, v) => v instanceof Date ? v.toISOString() : v)}`,
      );
      await db.update(users).set(updateData).where(eq(users.id, userId));
      console.log(`[GP verify ${reqId}] DB_WRITE_OK`);

      // Acknowledge with Google (idempotent). Required within 3 days or
      // Play auto-refunds. The client also acks via tx.finish() — this
      // is a safety net.
      try {
        await acknowledgeGoogleSubscription(purchaseToken, productId);
      } catch (ackErr) {
        console.warn(`[GP verify ${reqId}] acknowledge failed (non-fatal):`, ackErr);
      }

      try {
        emitToUser(userId, userId, {
          type: "subscription.changed",
          tenantId: userId,
          source: "iap.google.verify",
          tier: tier || undefined,
          addon: addon || undefined,
          activated,
        } as any);
      } catch (emitErr) {
        console.warn(`[GP verify ${reqId}] emitToUser failed (non-fatal):`, emitErr);
      }

      if (!activated) {
        return res.status(409).json({
          synced: false,
          addon,
          status: "inactive",
          message: blockedReason || "Add-on cannot be activated. Please contact support.",
          reqId,
        });
      }
      return res.json({
        synced: true,
        tier: tier || undefined,
        addon: addon || undefined,
        status: "active",
        reqId,
      });
    } catch (error: any) {
      console.error(`[GP verify ${reqId}] UNCAUGHT_ERROR:`, error?.stack || error);
      res.status(500).json({ message: "Failed to verify Google purchase", reqId, error: String(error?.message || error) });
    }
  });

  // POST /api/iap/google/webhook — Pub/Sub HTTP push target for Real-Time
  // Developer Notifications. Google sends a JWT-signed envelope; we
  // verify it, base64-decode the inner Pub/Sub message data, then refresh
  // state from the Play Developer API (RTDN itself does NOT carry the
  // updated state — just "something changed for this token").
  app.post("/api/iap/google/webhook", async (req, res) => {
    try {
      const verified = await verifyGoogleRtdnJwt(req.headers.authorization);
      if (!verified) {
        return res.status(401).json({ message: "Invalid Pub/Sub JWT" });
      }
      const envelope = req.body || {};
      const messageId: string | undefined = envelope?.message?.messageId;
      const dataB64: string | undefined = envelope?.message?.data;
      if (!dataB64) {
        // Pub/Sub also sends empty pushes on subscription creation.
        return res.json({ ok: true, empty: true });
      }

      // Idempotency by Pub/Sub messageId.
      if (messageId) {
        if (recentIAPEvents.has(messageId)) {
          return res.json({ ok: true, deduped: true });
        }
        recentIAPEvents.set(messageId, Date.now());
      }

      let payload: GoogleRtdnPayload;
      try {
        payload = JSON.parse(Buffer.from(dataB64, "base64").toString("utf8"));
      } catch (parseErr) {
        console.warn("[GP webhook] failed to parse base64 payload:", parseErr);
        return res.status(400).json({ message: "bad payload" });
      }

      console.log(
        `[GP WH RAW] messageId=${messageId || "-"} pkg=${payload.packageName} eventTime=${payload.eventTimeMillis} ` +
        `subType=${payload.subscriptionNotification?.notificationType || "-"} ` +
        `subToken=${payload.subscriptionNotification?.purchaseToken?.slice(0, 12) || "-"}… ` +
        `subId=${payload.subscriptionNotification?.subscriptionId || "-"} ` +
        `test=${payload.testNotification ? "yes" : "no"} ` +
        `voided=${payload.voidedPurchaseNotification ? "yes" : "no"}`,
      );

      if (payload.testNotification) {
        return res.json({ ok: true, test: true });
      }

      const sn = payload.subscriptionNotification;
      const vn = payload.voidedPurchaseNotification;

      // Voided (refund) notification — revoke entitlement on whichever
      // column holds this token.
      if (vn?.purchaseToken) {
        const token = vn.purchaseToken;
        try {
          const matched = await db.execute(sql`
            UPDATE users SET
              subscription_status = CASE WHEN google_original_purchase_token = ${token} THEN 'inactive' ELSE subscription_status END,
              white_label_status   = CASE WHEN google_white_label_purchase_token   = ${token} THEN 'inactive' ELSE white_label_status END,
              ai_assistant_status  = CASE WHEN google_ai_assistant_purchase_token  = ${token} THEN 'inactive' ELSE ai_assistant_status END
            WHERE google_original_purchase_token = ${token}
               OR google_white_label_purchase_token = ${token}
               OR google_ai_assistant_purchase_token = ${token}
            RETURNING id
          `);
          console.log(`[GP webhook] VOIDED token=${token.slice(0, 12)}… affected=${matched.rows.length}`);
        } catch (e) {
          console.error("[GP webhook] voided update failed:", e);
        }
        return res.json({ ok: true });
      }

      if (!sn?.purchaseToken) {
        return res.json({ ok: true, skipped: "no_subscription_notification" });
      }

      const sub = await fetchGoogleSubscription(sn.purchaseToken, sn.subscriptionId);
      if (!sub) {
        console.warn(`[GP webhook] fetchGoogleSubscription returned null for token=${sn.purchaseToken.slice(0, 12)}…`);
        return res.json({ ok: true });
      }
      const productId = sub.productId || sn.subscriptionId;
      const addon: GoogleAddon | null = addonFromGoogleProductId(productId);
      const tier = addon ? null : tierFromGoogleProductId(productId);

      // Map back to our user. Preferred: obfuscatedExternalAccountId
      // (set to user.id at order time). Fallback: any of the token cols.
      let userRow: any = null;
      if (sub.obfuscatedExternalAccountId) {
        const rows = await db.select().from(users).where(eq(users.id, sub.obfuscatedExternalAccountId));
        userRow = rows[0] || null;
      }
      if (!userRow) {
        const rows = await db.execute(sql`
          SELECT * FROM users
          WHERE google_original_purchase_token = ${sn.purchaseToken}
             OR google_white_label_purchase_token = ${sn.purchaseToken}
             OR google_ai_assistant_purchase_token = ${sn.purchaseToken}
          LIMIT 1
        `);
        userRow = rows.rows[0] || null;
      }
      if (!userRow) {
        console.log(`[GP webhook] no user found for token=${sn.purchaseToken.slice(0, 12)}… product=${productId}`);
        return res.json({ ok: true });
      }
      if (userRow.email && String(userRow.email).toLowerCase() === "googlereviewfusephone@gmail.com") {
        console.log(`[GP webhook] skipped for Google reviewer`);
        return res.json({ ok: true, skipped: "google_reviewer" });
      }

      const nType = sn.notificationType;
      const expiresAt = sub.expiryTimeMs ? new Date(sub.expiryTimeMs) : null;
      const nowMs = Date.now();
      const updateData: any = {};

      // Drive the entitlement decision off the AUTHORITATIVE sub.state
      // (the Play Developer API tells us exactly where the user stands
      // right now). The notification type is just a "what kind of change
      // happened" hint — for stateful fields we trust .state.
      //
      // Play subscription state semantics (per developer.android.com):
      //   ACTIVE                – paid, entitled
      //   IN_GRACE_PERIOD       – payment failed but still entitled
      //   CANCELED              – auto-renew off, entitled until expiry
      //   ON_HOLD               – payment failed past grace; NOT entitled
      //   PAUSED                – user paused subscription;   NOT entitled
      //   EXPIRED               – over, not entitled
      //   REVOKED (incl. refund)– immediately not entitled
      //   PENDING               – first purchase pending; not yet entitled
      const entitled =
        (sub.state === "SUBSCRIPTION_STATE_ACTIVE" ||
          sub.state === "SUBSCRIPTION_STATE_IN_GRACE_PERIOD" ||
          sub.state === "SUBSCRIPTION_STATE_CANCELED") &&
        !!expiresAt && expiresAt.getTime() > nowMs;
      const autoRenewOff =
        sub.state === "SUBSCRIPTION_STATE_CANCELED" ||
        sub.state === "SUBSCRIPTION_STATE_PAUSED" ||
        sub.state === "SUBSCRIPTION_STATE_ON_HOLD";

      if (tier) {
        if (entitled) {
          updateData.subscriptionTier = tier;
          updateData.subscriptionStatus = "active";
          if (expiresAt) updateData.subscriptionEndsAt = expiresAt;
          updateData.googleOriginalPurchaseToken = sn.purchaseToken;
          // Don't blow away pending tier on RENEWED — only clear it on
          // explicit PURCHASED / RESTARTED so a queued downgrade isn't
          // forgotten by a routine renewal of the CURRENT tier.
          if (
            nType === GOOGLE_RTDN_TYPE.PURCHASED ||
            nType === GOOGLE_RTDN_TYPE.RESTARTED ||
            nType === GOOGLE_RTDN_TYPE.RECOVERED
          ) {
            updateData.pendingTier = null;
            updateData.pendingTierEffectiveAt = null;
          }
        } else {
          // ON_HOLD / PAUSED / EXPIRED / REVOKED — strip entitlement now.
          updateData.subscriptionStatus = "inactive";
          if (expiresAt) updateData.subscriptionEndsAt = expiresAt;
        }
      } else if (addon) {
        const cols = GOOGLE_ADDON_USER_COLUMNS[addon];
        updateData[cols.tokenCol] = sn.purchaseToken;
        if (expiresAt) updateData[cols.expiresAtCol] = expiresAt;
        if (entitled) {
          // Only flip to active if the user is currently entitled
          // (Elite tier) — gating mirrors the verify route.
          const blocked = addonActivationBlockedReason(addon as any, userRow);
          if (!blocked) updateData[cols.statusCol] = "active";
        } else {
          updateData[cols.statusCol] = "inactive";
        }
        updateData[cols.autoRenewOffCol] = autoRenewOff;
      }

      if (Object.keys(updateData).length > 0) {
        await db.update(users).set(updateData).where(eq(users.id, userRow.id));
        console.log(
          `[GP webhook] type=${nType} user=${userRow.id} update=${JSON.stringify(updateData, (_k, v) => v instanceof Date ? v.toISOString() : v)}`,
        );
        try {
          emitToUser(userRow.id, userRow.id, {
            type: "subscription.changed",
            tenantId: userRow.id,
            source: "iap.google.webhook",
            tier: updateData.subscriptionTier || undefined,
            addon: addon || undefined,
          } as any);
        } catch (emitErr) {
          console.warn("[GP webhook] emitToUser failed (non-fatal):", emitErr);
        }
      } else {
        console.log(`[GP webhook] type=${nType} user=${userRow.id}: no-op`);
      }
      return res.json({ ok: true });
    } catch (error: any) {
      console.error("[GP webhook] error:", error?.stack || error);
      res.status(500).json({ message: "Webhook error" });
    }
  });

  app.post("/api/promo/validate", isAuthenticated, async (req, res) => {
    try {
      const { code } = req.body;
      if (!code) return res.status(400).json({ message: "Promo code required" });

      const [promo] = await db.select().from(promoCodes)
        .where(and(eq(promoCodes.code, code.toUpperCase()), eq(promoCodes.active, true)));

      if (!promo) return res.json({ valid: false, message: "Invalid promo code" });

      if (promo.expiresAt && promo.expiresAt < new Date()) {
        return res.json({ valid: false, message: "Promo code has expired" });
      }
      if (promo.maxUses && promo.currentUses && promo.currentUses >= promo.maxUses) {
        return res.json({ valid: false, message: "Promo code has reached maximum uses" });
      }

      res.json({
        valid: true,
        discountType: promo.discountType,
        discountAmount: promo.discountAmount,
        description: promo.description,
        tier: promo.tier,
        trialDays: promo.trialDays,
        durationMonths: promo.durationMonths,
        appliesTo: promo.appliesTo,
      });
    } catch (error) {
      console.error("Error validating promo code:", error);
      res.status(500).json({ message: "Failed to validate promo code" });
    }
  });

