  app.post("/api/admin/merge-duplicate-contacts", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const { userId, dryRun } = req.body;
      if (!userId) return res.status(400).json({ message: "userId required" });

      const allContacts = await storage.getContacts(userId);
      const normalizePhone = (p: string) => (p || '').replace(/\D/g, '').slice(-10);

      const byPhone: Record<string, typeof allContacts> = {};
      for (const c of allContacts) {
        const norm = normalizePhone(c.phone);
        if (norm.length < 7) continue;
        if (!byPhone[norm]) byPhone[norm] = [];
        byPhone[norm].push(c);
      }

      const dupeGroups = Object.entries(byPhone).filter(([_, g]) => g.length > 1);
      const results: any[] = [];

      for (const [phone, group] of dupeGroups) {
        const projectCounts: Record<number, number> = {};
        const commCounts: Record<number, number> = {};
        for (const c of group) {
          const [projRows] = await db.execute(sql`SELECT COUNT(*)::int as cnt FROM projects WHERE contact_id = ${c.id} AND user_id = ${userId}`);
          const [commRows] = await db.execute(sql`SELECT COUNT(*)::int as cnt FROM communications WHERE contact_id = ${c.id} AND user_id = ${userId}`);
          projectCounts[c.id] = (projRows as any)?.cnt || 0;
          commCounts[c.id] = (commRows as any)?.cnt || 0;
        }

        const isPlaceholderName = (name: string) => {
          const lower = (name || '').toLowerCase().trim();
          return !lower || lower === 'new lead' || lower === 'newly' || lower === 'unknown' || lower === 'new' || /^\+?\d[\d\s()-]*$/.test(lower);
        };

        const scored = group.map(c => {
          let score = 0;
          if (!isPlaceholderName(c.name)) score += 100;
          score += (projectCounts[c.id] || 0) * 50;
          score += (commCounts[c.id] || 0) * 10;
          if (c.email && c.email !== 'noemail@invalid.com' && c.email !== 'none@none.com' && c.email !== 'invalid@invalid.com' && c.email !== 'email@gmail.com' && c.email !== '@gmail.com' && c.email !== 'gmail.com' && c.email !== 'none@gmail.com' && c.email !== 'g@gmail.com' && c.email !== 'gt@gmail.com' && c.email !== 's@gmail.com') score += 20;
          if (c.address) score += 10;
          if (c.city) score += 5;
          return { contact: c, score, projects: projectCounts[c.id] || 0, comms: commCounts[c.id] || 0 };
        });
        scored.sort((a, b) => b.score - a.score);

        const keeper = scored[0];
        const dupes = scored.slice(1);

        const mergeInfo: any = {
          phone: `+1${phone}`,
          keeper: { id: keeper.contact.id, name: keeper.contact.name, projects: keeper.projects, messages: keeper.comms, score: keeper.score },
          merged: dupes.map(d => ({ id: d.contact.id, name: d.contact.name, projects: d.projects, messages: d.comms, score: d.score })),
        };

        if (!dryRun) {
          for (const dupe of dupes) {
            const dupeId = dupe.contact.id;
            const keeperId = keeper.contact.id;

            await db.execute(sql`UPDATE projects SET contact_id = ${keeperId} WHERE contact_id = ${dupeId} AND user_id = ${userId}`);
            await db.execute(sql`UPDATE communications SET contact_id = ${keeperId} WHERE contact_id = ${dupeId} AND user_id = ${userId}`);
            await db.execute(sql`UPDATE appointments SET contact_id = ${keeperId} WHERE contact_id = ${dupeId} AND user_id = ${userId}`);
            await db.execute(sql`UPDATE documents SET contact_id = ${keeperId} WHERE contact_id = ${dupeId} AND user_id = ${userId}`);

            if (isPlaceholderName(keeper.contact.name) && !isPlaceholderName(dupe.contact.name)) {
              await storage.updateContact(userId, keeperId, { name: dupe.contact.name });
              keeper.contact.name = dupe.contact.name;
            }
            if (!keeper.contact.email && dupe.contact.email) {
              await storage.updateContact(userId, keeperId, { email: dupe.contact.email });
            }
            if (!keeper.contact.address && dupe.contact.address) {
              await storage.updateContact(userId, keeperId, { address: dupe.contact.address });
            }

            await storage.deleteContact(userId, dupeId);
            mergeInfo.merged.find((m: any) => m.id === dupeId).deleted = true;
          }
        }

        results.push(mergeInfo);
      }

      res.json({ dryRun: !!dryRun, duplicateGroups: results.length, results });
    } catch (err: any) {
      console.error('[Admin] Merge duplicates error:', err);
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/admin/cleanup-user-data", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const { email } = req.body;
      if (!email) return res.status(400).json({ message: "Email required" });

      const [targetUser] = await db.select().from(users).where(eq(users.email, email));
      if (!targetUser) return res.status(404).json({ message: `User not found: ${email}` });

      const userId = targetUser.id;
      const results: Record<string, number> = {};

      await db.transaction(async (tx) => {
        const projectRows = await tx.select({ id: projects.id }).from(projects).where(eq(projects.userId, userId));
        const projectIds = projectRows.map(p => p.id);
        results.projectsFound = projectIds.length;

        const contactRows = await tx.select({ id: contacts.id }).from(contacts).where(eq(contacts.userId, userId));
        const contactIds = contactRows.map(c => c.id);
        results.contactsFound = contactIds.length;

        if (projectIds.length > 0) {
          const projectDeps = [
            'project_activities', 'project_recipients', 'project_crew_assignments',
            'project_expenses', 'time_entries', 'scheduled_automations',
            'ai_message_drafts', 'ai_actions', 'color_submissions',
            'notifications', 'game_plan_queue', 'ai_assistant_calls', 'work_orders',
          ];
          for (const tableName of projectDeps) {
            try {
              const r = await tx.execute(sql`DELETE FROM ${sql.identifier(tableName)} WHERE project_id = ANY(${projectIds})`);
              results[tableName] = Number((r as any).rowCount || 0);
            } catch (e) {
              console.log(`[Cleanup] Skip ${tableName}:`, (e as Error).message);
            }
          }

          const docRows = await tx.execute(sql`SELECT id FROM documents WHERE project_id = ANY(${projectIds}) OR contact_id = ANY(${contactIds})`);
          const docIds = (docRows as any).rows?.map((d: any) => d.id) || [];
          if (docIds.length > 0) {
            for (const depTable of ['document_views', 'payments', 'document_photos', 'document_recipients']) {
              try {
                await tx.execute(sql`DELETE FROM ${sql.identifier(depTable)} WHERE document_id = ANY(${docIds})`);
              } catch (e) {
                console.log(`[Cleanup] Skip ${depTable}:`, (e as Error).message);
              }
            }
            await tx.execute(sql`DELETE FROM documents WHERE id = ANY(${docIds})`);
            results.documents = docIds.length;
          }

          await tx.delete(projects).where(inArray(projects.id, projectIds));
        }

        if (contactIds.length > 0) {
          const contactDeps = [
            'communications', 'booking_requests', 'jobs', 'appointments',
            'scheduled_messages', 'campaign_messages',
          ];
          for (const tableName of contactDeps) {
            try {
              const r = await tx.execute(sql`DELETE FROM ${sql.identifier(tableName)} WHERE contact_id = ANY(${contactIds})`);
              results[tableName] = Number((r as any).rowCount || 0);
            } catch (e) {
              console.log(`[Cleanup] Skip ${tableName}:`, (e as Error).message);
            }
          }

          await tx.delete(contacts).where(inArray(contacts.id, contactIds));
        }

        results.projectsDeleted = projectIds.length;
        results.contactsDeleted = contactIds.length;
      });

      console.log(`[Admin Cleanup] Deleted data for ${email}:`, results);
      res.json({ success: true, email, results });
    } catch (error) {
      console.error("[Admin Cleanup] Error:", error);
      res.status(500).json({ message: (error as Error).message || "Cleanup failed" });
    }
  });

  // Admin: Update user subscription
  app.patch("/api/admin/users/:id/subscription", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const targetUserId = req.params.id;
      const {
        tier,
        status,
        trialDaysExtension,
        trialEndsAt,
        subscriptionEndsAt,
        action,
      } = req.body;

      const updates: any = {};
      if (tier) updates.subscriptionTier = tier;
      if (status) updates.subscriptionStatus = status;

      if (trialDaysExtension) {
        const [targetUser] = await db.select().from(users).where(eq(users.id, targetUserId));
        const baseDate = targetUser?.trialEndsAt && targetUser.trialEndsAt > new Date()
          ? targetUser.trialEndsAt
          : new Date();
        updates.trialEndsAt = new Date(baseDate.getTime() + trialDaysExtension * 24 * 60 * 60 * 1000);
        updates.subscriptionStatus = 'trialing';
        updates.subscriptionTier = 'elite';
      }

      // Set exact trial end date (ISO string) or null to clear
      if (trialEndsAt !== undefined) {
        updates.trialEndsAt = trialEndsAt ? new Date(trialEndsAt) : null;
      }

      // Set exact subscription end date (scheduled cancel) or null to clear
      if (subscriptionEndsAt !== undefined) {
        updates.subscriptionEndsAt = subscriptionEndsAt ? new Date(subscriptionEndsAt) : null;
      }

      // Shortcut actions
      if (action === 'end_trial_now') {
        updates.trialEndsAt = new Date(Date.now() - 60 * 1000);
        updates.subscriptionStatus = 'canceled';
      } else if (action === 'end_subscription_now') {
        updates.subscriptionEndsAt = new Date();
        updates.subscriptionStatus = 'canceled';
      } else if (action === 'reactivate') {
        updates.subscriptionStatus = 'active';
        updates.subscriptionEndsAt = null;
      }

      if (Object.keys(updates).length > 0) {
        await db.update(users).set(updates).where(eq(users.id, targetUserId));
      }
      res.json({ success: true });
    } catch (error) {
      console.error("Error updating user subscription:", error);
      res.status(500).json({ message: "Failed to update subscription" });
    }
  });

  // Admin: Update user FuseAI status / grant trial
  app.patch("/api/admin/users/:id/fuse-ai", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const targetUserId = req.params.id;
      const { action, trialDays } = req.body;
      const updates: any = {};

      if (action === 'grant_trial') {
        const days = parseInt(trialDays) || 30;
        const [targetUser] = await db.select().from(users).where(eq(users.id, targetUserId));
        const baseDate = targetUser?.fuseAiTrialEndsAt && targetUser.fuseAiTrialEndsAt > new Date()
          ? targetUser.fuseAiTrialEndsAt
          : new Date();
        updates.fuseAiTrialEndsAt = new Date(baseDate.getTime() + days * 24 * 60 * 60 * 1000);
        updates.fuseAiStatus = 'active';
      } else if (action === 'activate') {
        updates.fuseAiStatus = 'active';
      } else if (action === 'deactivate') {
        updates.fuseAiStatus = 'inactive';
        updates.fuseAiTrialEndsAt = null;
      }

      if (Object.keys(updates).length > 0) {
        await db.update(users).set(updates).where(eq(users.id, targetUserId));
      }
      res.json({ success: true });
    } catch (error) {
      console.error("Error updating user FuseAI:", error);
      res.status(500).json({ message: "Failed to update FuseAI status" });
    }
  });

  app.patch("/api/admin/users/:id/ai-assistant", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const targetUserId = req.params.id;
      const { action } = req.body;
      const enabled = action === 'activate';

      await db.update(users).set({ aiAssistantStatus: enabled ? 'active' : 'inactive' }).where(eq(users.id, targetUserId));

      const [existing] = await db.select({ id: companySettings.id }).from(companySettings).where(eq(companySettings.userId, targetUserId));
      if (existing) {
        await db.update(companySettings).set({ aiAssistantEnabled: enabled }).where(eq(companySettings.userId, targetUserId));
      } else if (enabled) {
        await db.insert(companySettings).values({ userId: targetUserId, aiAssistantEnabled: true });
      }

      res.json({ success: true });
    } catch (error) {
      console.error("Error updating user AI Assistant:", error);
      res.status(500).json({ message: "Failed to update AI Assistant status" });
    }
  });

  // === AI Voice Preview (TTS) ===

  app.post("/api/ai-assistant/voice-preview", isAuthenticated, async (req, res) => {
    try {
      const { voice } = req.body;
      const ttsVoices = ["sage", "shimmer", "echo", "alloy"];
      const realtimeOnlyVoices = ["marin", "cedar", "verse"];
      if (!voice) {
        return res.status(400).json({ message: "Invalid voice" });
      }
      if (realtimeOnlyVoices.includes(voice)) {
        return res.status(400).json({ message: "preview_unavailable" });
      }
      if (!ttsVoices.includes(voice)) {
        return res.status(400).json({ message: "Invalid voice" });
      }

      const userId = await getEffectiveUserId(req);
      const settings = await storage.getCompanySettings(userId);
      const companyName = settings?.companyName || "your company";
      const sampleText = `Hey, thanks for calling ${companyName}! How can I help you today?`;

      const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
      const mp3 = await openai.audio.speech.create({
        model: "tts-1",
        voice: voice as any,
        input: sampleText,
        response_format: "mp3",
      });

      const buffer = Buffer.from(await mp3.arrayBuffer());
      res.set("Content-Type", "audio/mpeg");
      res.set("Content-Length", String(buffer.length));
      res.send(buffer);
    } catch (error: any) {
      console.error("[Voice Preview] Error:", error);
      res.status(500).json({ message: "Failed to generate voice preview" });
    }
  });

  // === Help Center: AI Support Chat ===

  app.post("/api/help/ai-chat", isAuthenticated, async (req, res) => {
    try {
      const { messages } = req.body;
      if (!messages || !Array.isArray(messages)) {
        return res.status(400).json({ message: "Messages array required" });
      }

      const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

      const systemPrompt = `You are FuseAI, the helpful support assistant for Fuse Phone CRM. You help users learn how to use the application.

Fuse Phone is a CRM for small businesses (especially contractors and service businesses) that includes:
- Contact & Lead Management: Import leads from Thumbtack, Facebook Lead Ads, or manually. Track lead sources and statuses. Leads auto-convert to clients.
- 8-Stage Project Pipeline: New Lead → Contacted → Estimate Sent → Proposal Sent → Negotiating → Accepted → In Progress → Completed. Also supports "Lost" status.
- Documents: Create estimates, proposals, invoices, and change orders with line items, digital signatures, and customer portals.
- Communication: SMS messaging, phone calls (via Twilio), email sending, and campaign broadcasts.
- AI Features: FuseAI project assistant for generating line items, AI SMS auto-responder, AI scheduling assistant, floor plan analysis, and AI Virtual Assistant for calls.
- Calendar & Appointments: Booking system with public booking pages, appointment reminders.
- Financial Tools: Revenue tracking, payment processing via Stripe, production rates.
- Settings: Company profile, integrations (Twilio, Google, Stripe, CompanyCam, Thumbtack, Facebook), templates, team/crew management.
- QuickShare: QR code sharing for booking and review links.
- Campaigns: Bulk SMS/email outreach with contact segmentation.

Navigation:
- Dashboard: Overview with metrics, recent activities, and quick actions
- Contacts: /contacts - Manage leads and clients
- Projects: /projects - Pipeline view of all projects
- Documents: /documents - All estimates, proposals, invoices
- Messages: /messages - SMS conversations
- Calls: /calls - Call history and VoIP calling
- Calendar: /calendar - Appointments and scheduling
- Settings: Company Profile, Integrations, Templates, Financial Settings, Billing
- Help: /help - Tutorial videos and this chat

Be friendly, concise, and helpful. If you're unsure about something, say so. If the user has a technical issue you can't solve, suggest they contact support through the chat icon in the bottom-right corner of the app. Never make up features that don't exist.`;

      const response = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [
          { role: "system", content: systemPrompt },
          ...messages.slice(-10).map((m: any) => ({
            role: m.role as "user" | "assistant",
            content: m.content,
          })),
        ],
        max_tokens: 500,
        temperature: 0.7,
      });

      const reply = response.choices[0]?.message?.content || "I'm sorry, I couldn't generate a response. Please try again.";
      res.json({ reply });
    } catch (error) {
      console.error("Error in AI help chat:", error);
      res.status(500).json({ message: "Failed to get AI response" });
    }
  });

