  app.get('/api/companycam/projects', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const settings = await storage.getCompanySettings(userId);
      if (!settings?.companyCamApiToken) {
        return res.status(400).json({ message: 'CompanyCam is not connected' });
      }

      const page = parseInt(req.query.page as string) || 1;
      const search = (req.query.search as string || '').trim().toLowerCase();
      const perPage = search ? 100 : 20;
      const apiRes = await fetch(`https://api.companycam.com/v2/projects?page=${page}&per_page=${perPage}`, {
        headers: { 'Authorization': `Bearer ${settings.companyCamApiToken}` }
      });
      if (!apiRes.ok) {
        const errorText = await apiRes.text();
        return res.status(apiRes.status).json({ message: `CompanyCam API error: ${errorText}` });
      }
      let projects = await apiRes.json();
      if (search && Array.isArray(projects)) {
        projects = projects.filter((p: any) => {
          const name = (p.name || '').toLowerCase();
          const addr = p.address || {};
          const addrStr = [addr.street_address_1, addr.city, addr.state, addr.postal_code].filter(Boolean).join(' ').toLowerCase();
          return name.includes(search) || addrStr.includes(search);
        });
      }
      res.json(projects);
    } catch (err: any) {
      res.status(500).json({ message: err.message || 'Failed to fetch CompanyCam projects' });
    }
  });

  app.get('/api/companycam/projects/:projectId/photos', isAuthenticated, async (req, res) => {
    try {
      const userId = getUserId(req);
      const settings = await storage.getCompanySettings(userId);
      if (!settings?.companyCamApiToken) {
        return res.status(400).json({ message: 'CompanyCam is not connected' });
      }

      const { projectId } = req.params;
      const perPage = 100;
      let page = 1;
      let allPhotos: any[] = [];

      while (true) {
        const apiRes = await fetch(`https://api.companycam.com/v2/projects/${projectId}/photos?page=${page}&per_page=${perPage}`, {
          headers: { 'Authorization': `Bearer ${settings.companyCamApiToken}` }
        });
        if (!apiRes.ok) {
          return res.status(apiRes.status).json({ message: 'Failed to fetch photos' });
        }
        const photos = await apiRes.json();
        if (!Array.isArray(photos) || photos.length === 0) break;
        allPhotos = allPhotos.concat(photos);
        if (photos.length < perPage) break;
        page++;
        if (page > 50) break;
      }

      res.json(allPhotos);
    } catch (err: any) {
      res.status(500).json({ message: err.message || 'Failed to fetch photos' });
    }
  });

