  app.post("/api/crew-groups", async (req, res) => {
    const userId = req.session?.userId;
    if (!userId) return res.status(401).json({ message: "Unauthorized" });
    const { name, memberIds } = req.body;
    if (!name?.trim()) return res.status(400).json({ message: "Group name is required" });
    const [group] = await db.insert(crewGroups).values({ userId, name: name.trim() }).returning();
    if (Array.isArray(memberIds) && memberIds.length > 0) {
      await db.insert(crewGroupMembers).values(
        memberIds.map((tmId: number) => ({ groupId: group.id, teamMemberId: tmId, userId }))
      );
    }
    res.json({ ...group, memberIds: memberIds || [] });
  });

  app.patch("/api/crew-groups/:id", async (req, res) => {
    const userId = req.session?.userId;
    if (!userId) return res.status(401).json({ message: "Unauthorized" });
    const id = parseInt(req.params.id);
    if (isNaN(id)) return res.status(400).json({ message: "Invalid ID" });
    const { name, memberIds } = req.body;
    if (name !== undefined) {
      await db.update(crewGroups).set({ name: name.trim() }).where(and(eq(crewGroups.id, id), eq(crewGroups.userId, userId)));
    }
    if (Array.isArray(memberIds)) {
      await db.delete(crewGroupMembers).where(and(eq(crewGroupMembers.groupId, id), eq(crewGroupMembers.userId, userId)));
      if (memberIds.length > 0) {
        await db.insert(crewGroupMembers).values(
          memberIds.map((tmId: number) => ({ groupId: id, teamMemberId: tmId, userId }))
        );
      }
    }
    const [updated] = await db.select().from(crewGroups).where(and(eq(crewGroups.id, id), eq(crewGroups.userId, userId)));
    const members = await db.select().from(crewGroupMembers).where(and(eq(crewGroupMembers.groupId, id), eq(crewGroupMembers.userId, userId)));
    res.json({ ...updated, memberIds: members.map(m => m.teamMemberId) });
  });

