  app.get("/api/shared-photos/:token", async (req: Request, res: Response) => {
    try {
      const [link] = await db.select().from(sharedPhotoLinks).where(eq(sharedPhotoLinks.token, req.params.token));
      if (!link) return res.status(404).json({ message: "Share link not found" });

      const appHost = 'https://app.fusephone.com';
      const toAbsoluteUrl = (key: string | null) => {
        if (!key) return null;
        if (key.startsWith('http://') || key.startsWith('https://')) return key;
        return key.startsWith('/') ? `${appHost}${key}` : `${appHost}/${key}`;
      };

      // Universal entries-based share (new format). Any mix of doc photos,
      // CompanyCam photos, source/text/area photos can be in one link.
      let safePhotos: Array<{ id: number; fileName: string; storageKey: string; caption: string | null; annotations: any[] | null; annotatedStorageKey: string | null }> = [];
      if (Array.isArray(link.entries) && link.entries.length > 0) {
        const docPhotoIds = link.entries
          .filter((e: any) => e?.kind === 'doc' && typeof e.photoId === 'number')
          .map((e: any) => e.photoId as number);
        const docPhotosById = new Map<number, any>();
        if (docPhotoIds.length > 0) {
          const rows = await db.select().from(documentPhotos)
            .where(and(inArray(documentPhotos.id, docPhotoIds), eq(documentPhotos.userId, link.userId)));
          for (const r of rows) docPhotosById.set(r.id, r);
        }
        let synthIdCounter = -1;
        for (const entry of link.entries as any[]) {
          if (entry?.kind === 'doc' && typeof entry.photoId === 'number') {
            const p = docPhotosById.get(entry.photoId);
            if (!p) continue;
            safePhotos.push({
              id: p.id,
              fileName: p.fileName,
              storageKey: toAbsoluteUrl(p.storageKey)!,
              caption: p.caption,
              annotations: p.annotations || null,
              annotatedStorageKey: toAbsoluteUrl(p.annotatedStorageKey),
            });
          } else if (entry?.kind === 'url' && typeof entry.url === 'string' && entry.url.length > 0) {
            safePhotos.push({
              id: synthIdCounter--,
              fileName: entry.fileName || 'Photo',
              storageKey: toAbsoluteUrl(entry.url)!,
              caption: entry.caption || null,
              annotations: Array.isArray(entry.annotations) ? entry.annotations : null,
              annotatedStorageKey: null,
            });
          }
        }
      } else {
        // Legacy photoIds path (kept so old share links keep working).
        let photos;
        if (link.projectId && (!link.documentId || link.documentId === 0)) {
          photos = await db.select().from(documentPhotos)
            .where(and(
              inArray(documentPhotos.id, link.photoIds),
              eq(documentPhotos.userId, link.userId)
            ))
            .orderBy(desc(documentPhotos.createdAt));
        } else {
          photos = await db.select().from(documentPhotos)
            .where(and(
              inArray(documentPhotos.id, link.photoIds),
              eq(documentPhotos.documentId, link.documentId)
            ))
            .orderBy(desc(documentPhotos.createdAt));
        }
        safePhotos = photos.map(p => ({
          id: p.id,
          fileName: p.fileName,
          storageKey: toAbsoluteUrl(p.storageKey)!,
          caption: p.caption,
          annotations: p.annotations || null,
          annotatedStorageKey: toAbsoluteUrl(p.annotatedStorageKey),
        }));
      }

      const settings = await storage.getCompanySettings(link.userId);
      let docTitle: string | null = null;
      let docType: string | null = null;
      if (link.documentId && link.documentId !== 0) {
        const doc = await db.select({ title: documents.title, type: documents.type }).from(documents).where(eq(documents.id, link.documentId)).then(r => r[0]);
        docTitle = doc?.title || null;
        docType = doc?.type || null;
      } else {
        docTitle = "Project Photos";
        docType = "project";
      }
      const logoUrl = settings?.logo ? toAbsoluteUrl(settings.logo) : null;
      res.json({
        photos: safePhotos,
        companyName: settings?.companyName || null,
        companyLogo: logoUrl,
        documentTitle: docTitle,
        documentType: docType,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

