  app.post("/api/projects/:id/photos", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = req.user?.claims?.sub;
      const projectId = parseInt(req.params.id);
      const project = await db.select({ id: projects.id }).from(projects)
        .where(and(eq(projects.id, projectId), eq(projects.userId, userId)))
        .then(r => r[0]);
      if (!project) return res.status(404).json({ message: "Project not found" });

      const photoQuota = await checkPhotoQuota(userId, projectId, null);
      if (!photoQuota.allowed) {
        return res.status(403).json({
          message: `Your plan allows ${photoQuota.limit} photos per project. You're already at ${photoQuota.current}. Upgrade for more.`,
          code: 'PHOTO_LIMIT_REACHED',
          current: photoQuota.current,
          limit: photoQuota.limit,
        });
      }

      const { fileName, storageKey, caption, sortOrder } = req.body;
      if (!fileName || !storageKey) {
        return res.status(400).json({ message: "fileName and storageKey required" });
      }

      const normalizedKey = objectStorageService.normalizeObjectEntityPath(storageKey);
      try {
        await objectStorageService.trySetObjectEntityAclPolicy(normalizedKey, {
          owner: userId,
          visibility: "public",
        });
      } catch (e) {
        console.log("Could not set ACL for photo, continuing:", e);
      }

      const [photo] = await db.insert(documentPhotos).values({
        projectId,
        documentId: null,
        userId: userId!,
        fileName,
        storageKey: normalizedKey,
        caption: caption || null,
        sortOrder: sortOrder ?? 0,
        source: "project_upload",
      }).returning();

      res.json(photo);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // Register an already-uploaded room/area photo into the project pool so it
  // surfaces in the project photo picker for cross-block reuse. Idempotent:
  // returns the existing pool row when the storageKey is already linked.
  // Skips quota because the underlying file already exists.
  app.post("/api/projects/:id/photos/link-area", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = req.user?.claims?.sub;
      const projectId = parseInt(req.params.id);
      const project = await db.select({ id: projects.id }).from(projects)
        .where(and(eq(projects.id, projectId), eq(projects.userId, userId)))
        .then(r => r[0]);
      if (!project) return res.status(404).json({ message: "Project not found" });

      const { storageKey, fileName, annotations } = req.body || {};
      if (!storageKey || typeof storageKey !== "string") {
        return res.status(400).json({ message: "storageKey required" });
      }
      // Guardrail: only accept keys that look like our object-storage paths.
      // Prevents arbitrary string spam in the project pool table.
      const validKey = /^(\/objects\/|uploads\/|https:\/\/storage\.googleapis\.com\/)/.test(storageKey);
      if (!validKey) {
        return res.status(400).json({ message: "invalid storageKey shape" });
      }

      // Normalize for storage (full GS URLs collapse to /objects/...; other
      // shapes pass through unchanged).
      const normalizedKey = objectStorageService.normalizeObjectEntityPath(storageKey);

      // Canonical form for dedupe only — treat /objects/foo and foo as the
      // same physical photo. We still persist storageKey as-given so the
      // frontend renders the same URL it already uses inline.
      const canon = (k: string) => (k || "").replace(/^\/objects\//, "");
      const targetCanon = canon(normalizedKey);

      const existingRows = await db.select().from(documentPhotos)
        .where(and(
          eq(documentPhotos.projectId, projectId),
          eq(documentPhotos.userId, userId!),
        ));
      const dup = existingRows.find((r) => canon(r.storageKey) === targetCanon);
      if (dup) return res.json(dup);

      const [photo] = await db.insert(documentPhotos).values({
        projectId,
        documentId: null,
        userId: userId!,
        fileName: fileName || "Area photo",
        storageKey: normalizedKey,
        caption: null,
        annotations: Array.isArray(annotations) ? annotations : null,
        sortOrder: 0,
        source: "area_photo",
      }).returning();

      res.json(photo);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

