  // Universal photo share endpoint — accepts ANY mix of photo sources:
  //   - Uploaded document photos (kind: 'doc', photoId)
  //   - CompanyCam, source/text photos, area photos (kind: 'url', url, caption?, fileName?, annotations?)
  // The frontend always uses this endpoint now; the older project/document
  // share endpoints stay only for backward compat with anything still calling them.
  app.post("/api/photo-share", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = await getEffectiveUserId(req);
      const { entries, projectId, documentId } = req.body || {};
      if (!Array.isArray(entries) || entries.length === 0) {
        return res.status(400).json({ message: "entries array required" });
      }

      // Optional ownership check on projectId/documentId so a malicious caller
      // can't claim a share belongs to someone else's project.
      if (projectId) {
        const [proj] = await db.select({ id: projects.id }).from(projects)
          .where(and(eq(projects.id, Number(projectId)), eq(projects.userId, userId)));
        if (!proj) return res.status(404).json({ message: "Project not found" });
      }
      if (documentId) {
        const [doc] = await db.select({ id: documents.id }).from(documents)
          .where(and(eq(documents.id, Number(documentId)), eq(documents.userId, userId)));
        if (!doc) return res.status(404).json({ message: "Document not found" });
      }

      // Validate entries and check ownership of any doc photos referenced.
      const cleanedEntries: any[] = [];
      const docPhotoIds: number[] = [];
      for (const raw of entries) {
        if (!raw || typeof raw !== 'object') continue;
        if (raw.kind === 'doc' && typeof raw.photoId === 'number') {
          cleanedEntries.push({ kind: 'doc', photoId: raw.photoId });
          docPhotoIds.push(raw.photoId);
        } else if (raw.kind === 'url' && typeof raw.url === 'string' && raw.url.length > 0) {
          cleanedEntries.push({
            kind: 'url',
            url: raw.url,
            caption: raw.caption ?? null,
            fileName: raw.fileName ?? null,
            annotations: Array.isArray(raw.annotations) ? raw.annotations : null,
          });
        }
      }
      if (cleanedEntries.length === 0) {
        return res.status(400).json({ message: "No valid entries" });
      }
      if (docPhotoIds.length > 0) {
        const owned = await db.select({ id: documentPhotos.id }).from(documentPhotos)
          .where(and(inArray(documentPhotos.id, docPhotoIds), eq(documentPhotos.userId, userId)));
        if (owned.length !== docPhotoIds.length) {
          return res.status(403).json({ message: "Some photos not found or not owned" });
        }
      }

      const { nanoid } = await import("nanoid");
      const token = nanoid(16);
      await db.insert(sharedPhotoLinks).values({
        userId,
        projectId: projectId ? Number(projectId) : null,
        documentId: documentId ? Number(documentId) : 0,
        token,
        photoIds: [],
        entries: cleanedEntries,
      });

      const settings = await storage.getCompanySettings(userId);
      const host = req.get('host') || 'app.fusephone.com';
      const proto = (host.includes('replit') || host.includes('fusephone')) ? 'https' : req.protocol;
      let shareUrl: string;
      if (settings?.customDomain && settings?.customDomainVerified) {
        shareUrl = `https://${settings.customDomain}/shared-photos/${token}`;
      } else {
        shareUrl = `${proto}://${host}/shared-photos/${token}`;
      }
      res.json({ token, url: shareUrl });
    } catch (err: any) {
      console.error('[Photo Share] Error:', err);
      res.status(500).json({ message: err.message });
    }
  });

