  app.get("/api/projects/:id/source-photos", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = await getEffectiveUserId(req);
      const projectId = parseInt(req.params.id);
      const project = await db.select({ contactId: projects.contactId }).from(projects)
        .where(and(eq(projects.id, projectId), eq(projects.userId, userId)))
        .then(r => r[0]);
      if (!project) return res.status(404).json({ message: "Project not found" });

      const recipientRows = await db.select({ contactId: projectRecipients.contactId })
        .from(projectRecipients)
        .where(and(eq(projectRecipients.projectId, projectId), isNull(projectRecipients.removedAt)));
      const contactIds = Array.from(new Set([project.contactId, ...recipientRows.map(r => r.contactId)].filter((id): id is number => id != null)));

      const result: { source: string; url: string; date: string; contactName?: string; contentType?: string }[] = [];

      if (contactIds.length === 0) return res.json(result);

      const materializedPhotos = await db.select({ caption: documentPhotos.caption, storageKey: documentPhotos.storageKey })
        .from(documentPhotos)
        .where(and(
          eq(documentPhotos.projectId, projectId),
          eq(documentPhotos.userId, userId),
          isNull(documentPhotos.documentId),
          sql`${documentPhotos.source} IN ('customer_message', 'booking_form', 'lead_submission')`
        ));
      const materializedUrls = new Set<string>();
      for (const mp of materializedPhotos) {
        materializedUrls.add(mp.storageKey);
        const srcMatch = mp.caption?.match(/\[src:(.+?)\]/);
        if (srcMatch) materializedUrls.add(srcMatch[1]);
      }

      const contactRows = await db.select({ id: contacts.id, name: contacts.name, phone: contacts.phone })
        .from(contacts)
        .where(and(eq(contacts.userId, userId), inArray(contacts.id, contactIds)));
      const contactMap = new Map(contactRows.map(c => [c.id, c]));

      const isImageUrl2 = (url: string, ct?: string | null, fallbackType?: string | null) => {
        if (!url) return false;
        if (ct && ct.startsWith('image/')) return true;
        if (ct && (ct.startsWith('video/') || ct.startsWith('audio/') || ct === 'application/pdf')) return false;
        if (/\.(jpg|jpeg|png|gif|webp|heic)/i.test(url)) return true;
        if (fallbackType === 'image') return true;
        return false;
      };

      for (const cId of contactIds) {
        const contact = contactMap.get(cId);
        if (!contact) continue;
        const contactName = contact.name || undefined;

        try {
          const msgs = await db.select({
            mediaUrl: communications.mediaUrl,
            mediaUrls: communications.mediaUrls,
            mediaContentTypes: communications.mediaContentTypes,
            mediaType: communications.mediaType,
            timestamp: communications.timestamp,
          }).from(communications)
            .where(and(
              eq(communications.userId, userId),
              eq(communications.contactId, cId),
              or(
                isNotNull(communications.mediaUrl),
                sql`array_length(${communications.mediaUrls}, 1) > 0`
              )
            ))
            .orderBy(desc(communications.timestamp));

          for (const msg of msgs) {
            const ts = msg.timestamp ? new Date(msg.timestamp).toISOString().split('T')[0] : 'unknown';
            if (msg.mediaUrls && Array.isArray(msg.mediaUrls) && msg.mediaUrls.length > 0) {
              const contentTypes = Array.isArray(msg.mediaContentTypes) ? msg.mediaContentTypes : [];
              msg.mediaUrls.forEach((url: string, i: number) => {
                if (!url || materializedUrls.has(url)) return;
                const ct = contentTypes[i] || '';
                if (isImageUrl2(url, ct, msg.mediaType)) {
                  result.push({ source: 'message', url, date: ts, contactName, contentType: ct || 'image/jpeg' });
                }
              });
            } else if (msg.mediaUrl && !materializedUrls.has(msg.mediaUrl) && isImageUrl2(msg.mediaUrl, undefined, msg.mediaType)) {
              result.push({ source: 'message', url: msg.mediaUrl, date: ts, contactName });
            }
          }
        } catch (msgErr) {
          console.error(`[Project Source Photos] Error loading messages for contact ${cId}:`, msgErr);
        }

        try {
          if (contact.phone) {
            const normalizePhone = (p: string) => p.replace(/\D/g, '').slice(-10);
            const cPhone = normalizePhone(contact.phone);
            if (cPhone.length >= 7) {
              const bookings = await db.select({
                uploadedFiles: bookingRequests.uploadedFiles,
                createdAt: bookingRequests.createdAt,
              }).from(bookingRequests)
                .where(and(
                  eq(bookingRequests.userId, userId),
                  or(
                    eq(bookingRequests.contactId, cId),
                    sql`REPLACE(REPLACE(REPLACE(REPLACE(${bookingRequests.phone}, '-', ''), '(', ''), ')', ''), ' ', '') LIKE '%' || ${cPhone}`
                  )
                ))
                .orderBy(desc(bookingRequests.createdAt));

              for (const b of bookings) {
                const ts = b.createdAt ? new Date(b.createdAt).toISOString().split('T')[0] : 'unknown';
                const files = b.uploadedFiles;
                if (files && Array.isArray(files)) {
                  for (const fileUrl of files) {
                    if (typeof fileUrl === 'string' && !materializedUrls.has(fileUrl) && (
                      /\.(jpg|jpeg|png|gif|webp|heic)/i.test(fileUrl) ||
                      fileUrl.startsWith('/uploads/booking-') ||
                      fileUrl.includes('booking-uploads/')
                    )) {
                      result.push({ source: 'form_submission', url: fileUrl, date: ts, contactName });
                    }
                  }
                }
              }
            }
          }
        } catch (bookErr) {
          console.error(`[Project Source Photos] Error loading bookings for contact ${cId}:`, bookErr);
        }
      }

      res.json(result);
    } catch (err: any) {
      console.error('[Project Source Photos] Error:', err);
      res.status(500).json({ message: err.message });
    }
  });

