  const expenseCreateUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 10 * 1024 * 1024 } });
  app.post("/api/projects/:projectId/expenses", expenseCreateUpload.single("receiptImage"), async (req, res) => {
    const userId = req.session?.userId;
    if (!userId) return res.status(401).json({ message: "Unauthorized" });
    const projectId = parseInt(req.params.projectId);
    if (isNaN(projectId)) return res.status(400).json({ message: "Invalid project ID" });
    try {
      const { title, description, amount, category, vendor, receiptDate } = req.body;
      console.log("[Expense] POST projectId:", projectId, "title:", title, "amount:", amount, "hasFile:", !!req.file);
      if (!title) return res.status(400).json({ message: "Title is required" });
      if (amount === undefined || amount === null) return res.status(400).json({ message: "Amount is required" });
      const amountCents = Math.round(Number(amount));

      let receiptImageUrl: string | null = null;
      if (req.file) {
        console.log("[Expense] Receipt image received:", req.file.originalname, (req.file.buffer.length / 1024).toFixed(0) + "KB");
        let imageBuffer = req.file.buffer;
        try {
          const sharp = (await import("sharp")).default;
          const compressed = await sharp(req.file.buffer)
            .resize(600, 600, { fit: "inside", withoutEnlargement: true })
            .jpeg({ quality: 55, mozjpeg: true })
            .toBuffer();
          console.log("[Expense] Compressed:", (req.file.buffer.length / 1024).toFixed(0) + "KB →", (compressed.length / 1024).toFixed(0) + "KB");
          imageBuffer = compressed;
        } catch (e) {
          console.log("[Expense] Compression skipped, using original");
        }
        const { ObjectStorageService } = await import("./replit_integrations/object_storage/objectStorage");
        const objService = new ObjectStorageService();
        const uploadURL = await objService.getObjectEntityUploadURL();
        const putRes = await fetch(uploadURL, { method: "PUT", body: imageBuffer, headers: { "Content-Type": "image/jpeg" } });
        if (!putRes.ok) {
          console.error("[Expense] Upload failed:", putRes.status, putRes.statusText);
        } else {
          receiptImageUrl = objService.normalizeObjectEntityPath(uploadURL);
          console.log("[Expense] Image uploaded, url:", receiptImageUrl);
        }
      }

      const existingExpenses = await storage.getProjectExpenses(userId, projectId);
      const duplicates = existingExpenses.filter((e: any) => {
        if (e.amount !== amountCents) return false;
        if (vendor && e.vendor && e.vendor.toLowerCase() === vendor.toLowerCase()) return true;
        if (receiptDate && e.receiptDate) {
          const existingDate = new Date(e.receiptDate).toISOString().split('T')[0];
          const newDate = new Date(receiptDate).toISOString().split('T')[0];
          if (existingDate === newDate && e.amount === amountCents) return true;
        }
        return false;
      });

      const expense = await storage.createProjectExpense(userId, {
        projectId, title, description: description || null, amount: amountCents,
        category: category || null, vendor: vendor || null,
        receiptDate: receiptDate ? new Date(receiptDate) : null,
        receiptImageUrl,
      });
      console.log("[Expense] Created id:", expense.id, "receiptImageUrl:", receiptImageUrl ? "yes" : "none");

      const receiptDateStr = receiptDate ? ` (receipt: ${new Date(receiptDate).toLocaleDateString()})` : '';
      await storage.createProjectActivity(userId, {
        projectId, type: "system",
        content: `Expense added: ${title} - $${(amountCents / 100).toFixed(2)}${vendor ? ` at ${vendor}` : ''}${receiptDateStr}`,
      });
      emitToUser(userId, userId, { type: "expense.updated", tenantId: userId, projectId });

      const proj = await storage.getProject(userId, projectId);
      if (proj?.stage === 'completed' && proj.costingSnapshot) {
        computeAndSnapshotJobCosting(userId, projectId).catch(e => console.error('[JobCosting] Re-snapshot after expense add:', e));
      }

      res.status(201).json({ ...expense, possibleDuplicates: duplicates.length > 0 ? duplicates.map((d: any) => ({ id: d.id, title: d.title, amount: d.amount, vendor: d.vendor, receiptDate: d.receiptDate, createdAt: d.createdAt })) : undefined });
    } catch (err: any) {
      console.error("[Expense] Error:", err);
      res.status(500).json({ message: err.message });
    }
  });

