  const memUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 10 * 1024 * 1024 } });
  app.post("/api/ai/scan-receipt", memUpload.single("receipt"), async (req: Request, res: Response) => {
    const userId = req.session?.userId;
    if (!userId) return res.status(401).json({ message: "Unauthorized" });
    try {
      const [u] = await db.select({ tier: users.subscriptionTier, isAdmin: users.isAdmin, eliteBonusEndsAt: users.eliteBonusEndsAt }).from(users).where(eq(users.id, userId));
      const isElite = !!u && (u.isAdmin || (u.tier || 'starter') === 'elite' || (u.eliteBonusEndsAt && u.eliteBonusEndsAt > new Date()));
      if (!isElite) {
        return res.status(403).json({ message: "AI receipt scanning is an Elite feature. Receipts can still be uploaded and saved." });
      }
      const file = req.file;
      if (!file) return res.status(400).json({ message: "No receipt image uploaded" });

      const base64Image = file.buffer.toString("base64");
      const mimeType = file.mimetype || "image/jpeg";

      const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
      const response = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [
          {
            role: "system",
            content: `You are a receipt scanner for a painting contractor business. Extract the following from the receipt image and return ONLY valid JSON with these fields:
- "amount": total amount as a number (e.g. 45.99). Use the total/grand total if visible, otherwise the largest amount.
- "vendor": store or vendor name (e.g. "Home Depot", "Sherwin-Williams")
- "category": one of these categories that best fits: "Materials", "Paint & Supplies", "Equipment Rental", "Subcontractor", "Travel/Gas", "Permits", "Dump/Disposal", "Food/Meals", "Other"
- "title": a short 2-5 word description of what was purchased (e.g. "Interior paint supplies", "Primer and rollers")
- "description": optional brief details about items if visible
- "receiptDate": the date on the receipt in ISO format "YYYY-MM-DD" (e.g. "2025-03-15"). Look for date/time printed on the receipt.

If you cannot determine a field, use null. Return ONLY the JSON object, no markdown.`
          },
          {
            role: "user",
            content: [
              { type: "text", text: "Scan this receipt and extract the expense details." },
              { type: "image_url", image_url: { url: `data:${mimeType};base64,${base64Image}` } }
            ]
          }
        ],
        max_tokens: 500,
      });

      const content = response.choices[0]?.message?.content || "{}";
      let parsed;
      try {
        const cleaned = content.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
        parsed = JSON.parse(cleaned);
      } catch {
        parsed = { title: null, amount: null, vendor: null, category: null, description: null };
      }

      res.json({
        title: parsed.title || null,
        amount: parsed.amount != null ? Math.round(Number(parsed.amount) * 100) : null,
        vendor: parsed.vendor || null,
        category: parsed.category || null,
        description: parsed.description || null,
        receiptDate: parsed.receiptDate || null,
      });
    } catch (err: any) {
      console.error("[AI Receipt Scan] Error:", err);
      res.status(500).json({ message: "Failed to scan receipt" });
    }
  });

