  app.post("/api/expenses/:expenseId/photos", expensePhotoUpload.single("photo"), async (req: Request, res: Response) => {
    const userId = req.session?.userId;
    if (!userId) return res.status(401).json({ message: "Unauthorized" });
    const expenseId = parseInt(req.params.expenseId);
    if (isNaN(expenseId)) return res.status(400).json({ message: "Invalid expense ID" });
    try {
      const file = req.file;
      if (!file) return res.status(400).json({ message: "No file uploaded" });

      let imageBuffer = file.buffer;
      let fileName = file.originalname;
      const originalSize = file.buffer.length;
      try {
        const sharp = (await import("sharp")).default;
        const maxDim = 1200;
        imageBuffer = await sharp(file.buffer)
          .resize(maxDim, maxDim, { fit: "inside", withoutEnlargement: true })
          .jpeg({ quality: 55, mozjpeg: true })
          .toBuffer();
        fileName = fileName.replace(/\.[^.]+$/, '.jpg');
        const savings = Math.round((1 - imageBuffer.length / originalSize) * 100);
        console.log(`[Expense Photo] Compressed: ${(originalSize / 1024).toFixed(0)}KB → ${(imageBuffer.length / 1024).toFixed(0)}KB (${savings}% smaller)`);
      } catch (compressErr) {
        console.log(`[Expense Photo] Compression failed, using original:`, compressErr);
      }

      const { ObjectStorageService } = await import("./replit_integrations/object_storage/objectStorage");
      const objService = new ObjectStorageService();
      const uploadURL = await objService.getObjectEntityUploadURL();
      const putRes = await fetch(uploadURL, { method: "PUT", body: imageBuffer, headers: { "Content-Type": "image/jpeg" } });
      if (!putRes.ok) throw new Error(`Upload PUT failed: ${putRes.status}`);
      const storageKey = objService.normalizeObjectEntityPath(uploadURL);
      console.log("[Expense Photo] Uploaded, key:", storageKey);
      const photo = await storage.createProjectExpensePhoto(userId, {
        expenseId,
        fileName,
        storageKey,
        sortOrder: 0,
      });
      res.status(201).json(photo);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

