  app.post("/api/projects/:projectId/schedule-dates", async (req, res) => {
    const userId = req.session?.userId;
    if (!userId) return res.status(401).json({ message: "Unauthorized" });
    const projectId = parseInt(req.params.projectId);
    if (isNaN(projectId)) return res.status(400).json({ message: "Invalid project ID" });
    try {
      const [project] = await db.select({ id: projects.id }).from(projects)
        .where(and(eq(projects.id, projectId), eq(projects.userId, userId)));
      if (!project) return res.status(404).json({ message: "Project not found" });

      const dates = req.body.dates as Array<{ date: string; startTime?: string; endTime?: string; notes?: string }>;
      if (!Array.isArray(dates) || dates.length === 0) {
        return res.status(400).json({ message: "At least one date is required" });
      }
      const inserted = [];
      for (const d of dates) {
        if (!d.date) continue;
        const [row] = await db.insert(jobScheduleDates).values({
          projectId,
          userId,
          date: d.date,
          startTime: d.startTime || null,
          endTime: d.endTime || null,
          notes: d.notes || null,
        }).returning();
        inserted.push(row);
      }

      const dateStrs = dates.map(d => d.date).join(', ');
      await storage.createProjectActivity(userId, {
        projectId,
        type: "system",
        content: `Work days scheduled: ${dateStrs}`,
      });

      try {
        const crewAssignments = await storage.getProjectCrewAssignments(userId, projectId);
        if (crewAssignments.length > 0) {
          const [proj] = await db.select({ title: projects.title }).from(projects)
            .where(and(eq(projects.id, projectId), eq(projects.userId, userId)));
          if (proj) {
            for (const crew of crewAssignments) {
              const [linkedUser] = await db.select({ userId: companyUsers.userId })
                .from(companyUsers)
                .where(and(eq(companyUsers.ownerId, userId), eq(companyUsers.linkedTeamMemberId, crew.teamMemberId)));
              if (linkedUser) {
                await db.insert(notifications).values({
                  userId: linkedUser.userId,
                  projectId,
                  type: 'schedule_updated',
                  title: 'Schedule Updated',
                  message: `New work days added for ${proj.title}: ${dateStrs}`,
                  link: `/my-calendar`,
                });
                emitToUser(linkedUser.userId, linkedUser.userId, { type: "notification.created", tenantId: linkedUser.userId });
                sendPushToUser(linkedUser.userId, {
                  title: "Schedule Updated",
                  body: `New work days added for ${proj.title}: ${dateStrs}`,
                  data: { type: "schedule_updated", projectId: String(projectId) },
                });
              }
            }
          }
        }
      } catch (notifErr) {
        console.error('[Push] Failed to notify crew of schedule update:', notifErr);
      }

      emitToUser(userId, userId, { type: "project.updated", tenantId: userId, projectId });

      res.status(201).json(inserted);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

