  // PIN verification - identifies crew member, returns status and available projects
  app.post("/api/public/crew-clock/by-slug/:slug/verify-pin", async (req, res) => {
    try {
      const settings = await resolveCrewClockBySlug(req.params.slug);
      if (!settings) return res.status(404).json({ message: "Invalid link" });
      const { pin } = req.body;
      if (!pin) return res.status(400).json({ message: "PIN is required" });
      const memberArr = await db.select().from(teamMembers).where(
        and(eq(teamMembers.userId, settings.userId), eq(teamMembers.pin, pin), inArray(teamMembers.role, ["crew", "lead", "helper", "mechanic"]))
      );
      if (memberArr.length === 0) return res.status(403).json({ message: "Invalid PIN" });
      const member = memberArr[0];
      const active = await storage.getActiveTimeEntry(settings.userId, member.id);
      if (active) {
        const elapsed = Math.round((Date.now() - new Date(active.clockIn).getTime()) / 60000);
        return res.json({
          memberId: member.id,
          memberName: member.name,
          status: "clocked_in",
          clockedInSince: active.clockIn,
          elapsedMinutes: elapsed,
          activeEntryId: active.id,
          activeProjectId: active.projectId,
        });
      }
      // Not clocked in - find assigned projects whose schedule overlaps with now
      const tz = settings.timezone || 'America/New_York';
      const now = new Date();
      const todayStr = now.toLocaleDateString('en-CA', { timeZone: tz }); // YYYY-MM-DD
      const assignments = await db.select({ projectId: projectCrewAssignments.projectId })
        .from(projectCrewAssignments)
        .where(and(eq(projectCrewAssignments.teamMemberId, member.id), eq(projectCrewAssignments.userId, settings.userId)));
      const assignedProjectIds = assignments.map(a => a.projectId);
      let availableProjects: { id: number; address: string }[] = [];
      if (assignedProjectIds.length > 0) {
        const assignedProjects = await db.select({
          id: projects.id,
          stage: projects.stage,
          scheduledDate: projects.scheduledDate,
          scheduledEndDate: projects.scheduledEndDate,
          jobAddress: projects.jobAddress,
          jobCity: projects.jobCity,
          jobState: projects.jobState,
          contactId: projects.contactId,
        }).from(projects).where(
          and(
            eq(projects.userId, settings.userId),
            inArray(projects.id, assignedProjectIds),
            inArray(projects.stage, ["accepted", "scheduled", "in_progress"]),
            eq(projects.archived, false)
          )
        );
        for (const proj of assignedProjects) {
          const startDate = proj.scheduledDate || '';
          const endDate = proj.scheduledEndDate || startDate;
          const isOverlapping = startDate && todayStr >= startDate && todayStr <= (endDate || startDate);
          const isInProgress = proj.stage === 'in_progress';
          if (isOverlapping || isInProgress) {
            let address = '';
            if (proj.jobAddress) {
              address = [proj.jobAddress, proj.jobCity, proj.jobState].filter(Boolean).join(', ');
            } else {
              const [contact] = await db.select({ address: contacts.address, city: contacts.city, state: contacts.state })
                .from(contacts).where(eq(contacts.id, proj.contactId));
              if (contact) {
                address = [contact.address, contact.city, contact.state].filter(Boolean).join(', ');
              }
            }
            if (address) {
              availableProjects.push({ id: proj.id, address });
            }
          }
        }
      }
      res.json({
        memberId: member.id,
        memberName: member.name,
        status: "clocked_out",
        projects: availableProjects,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

