  app.patch('/api/scheduled-messages/:id', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const id = parseInt(req.params.id);
      const { scheduledAt, body } = req.body;
      if (!scheduledAt && body === undefined) {
        return res.status(400).json({ message: 'scheduledAt or body is required' });
      }
      const updates: { scheduledAt?: Date; body?: string } = {};
      if (scheduledAt) {
        const parsedDate = new Date(scheduledAt);
        if (isNaN(parsedDate.getTime())) {
          return res.status(400).json({ message: 'Invalid date format' });
        }
        if (parsedDate <= new Date()) {
          return res.status(400).json({ message: 'scheduledAt must be in the future' });
        }
        updates.scheduledAt = parsedDate;
      }
      if (body !== undefined) {
        if (typeof body !== 'string' || !body.trim()) {
          return res.status(400).json({ message: 'body cannot be empty' });
        }
        updates.body = body.trim();
      }
      const updated = await storage.updateScheduledMessage(userId, id, updates);
      if (!updated) return res.status(404).json({ message: 'Not found or already sent' });
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

