  function buildGlobalFeatureOrder(
    packages: { id: number }[],
    allLibraryFeatures: PackageFeatureLibrary[],
    allAssignments: PackageFeatureAssignment[]
  ): number[] {
    const order: number[] = [];
    const seen = new Set<number>();
    for (const pkg of packages) {
      const pkgAssigns = allAssignments.filter(a => a.packageId === pkg.id);
      const assignMap = new Map(pkgAssigns.map(a => [a.featureId, a.included]));
      for (const f of allLibraryFeatures) {
        if (!seen.has(f.id) && assignMap.get(f.id) === true) {
          order.push(f.id);
          seen.add(f.id);
        }
      }
    }
    for (const f of allLibraryFeatures) {
      if (!seen.has(f.id)) {
        order.push(f.id);
        seen.add(f.id);
      }
    }
    return order;
  }

  function materializeAllFeatures(
    globalOrder: number[],
    allLibraryFeatures: PackageFeatureLibrary[],
    pkgAssignments: PackageFeatureAssignment[]
  ): { name: string; included: boolean; description?: string }[] {
    const featureMap = new Map(allLibraryFeatures.map(f => [f.id, f]));
    const assignMap = new Map(pkgAssignments.map(a => [a.featureId, a.included]));
    return globalOrder
      .filter(id => featureMap.has(id))
      .map(id => ({
        name: featureMap.get(id)!.title,
        included: assignMap.get(id) ?? false,
        ...(featureMap.get(id)!.description ? { description: featureMap.get(id)!.description } : {}),
        ...(featureMap.get(id)!.active === false ? { active: false } : {}),
      }));
  }

  async function resyncPackageFeatures(userId: string) {
    const packages = await storage.getProposalPackages(userId);
    if (packages.length === 0) return;
    const allFeatures = await storage.getPackageFeatures(userId);
    const allAssignments = await storage.getFeatureAssignments(packages.map(p => p.id));
    const globalOrder = buildGlobalFeatureOrder(packages, allFeatures, allAssignments);
    for (const pkg of packages) {
      const pkgAssigns = allAssignments.filter(a => a.packageId === pkg.id);
      const features = materializeAllFeatures(globalOrder, allFeatures, pkgAssigns);
      await storage.updateProposalPackage(userId, pkg.id, { features });
    }
  }

  app.patch('/api/package-features/:id', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const id = parseInt(req.params.id);
      const { title, description, active } = req.body;
      const updates: any = {};
      if (typeof title === 'string' && title.trim()) updates.title = title.trim();
      if (description !== undefined) updates.description = typeof description === 'string' ? description.trim() || null : null;
      if (typeof active === 'boolean') updates.active = active;
      if (Object.keys(updates).length === 0) return res.status(400).json({ message: 'No valid fields to update' });
      const feat = await storage.updatePackageFeature(userId, id, updates);
      if (!feat) return res.status(404).json({ message: 'Feature not found' });

      if (updates.active === false) {
        const packages = await storage.getProposalPackages(userId);
        const allAssignments = await storage.getFeatureAssignments(packages.map(p => p.id));
        for (const pkg of packages) {
          const pkgAssigns = allAssignments.filter(a => a.packageId === pkg.id);
          const hadIncluded = pkgAssigns.find(a => a.featureId === id && a.included);
          if (hadIncluded) {
            const newAssigns = pkgAssigns.map(a => ({
              featureId: a.featureId,
              included: a.featureId === id ? false : a.included,
              sortOrder: a.sortOrder,
            }));
            await storage.setFeatureAssignments(pkg.id, newAssigns);
          }
        }
      }

      await resyncPackageFeatures(userId);
      res.json(feat);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

