  app.post('/api/proposal-packages/:id/features/toggle', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const packageId = parseInt(req.params.id);
      const pkg = await storage.getProposalPackage(userId, packageId);
      if (!pkg) return res.status(404).json({ message: 'Package not found' });
      const { featureId, included } = req.body;
      if (typeof featureId !== 'number' || typeof included !== 'boolean') {
        return res.status(400).json({ message: 'featureId (number) and included (boolean) required' });
      }
      const userFeatures = await storage.getPackageFeatures(userId);
      if (!userFeatures.find(f => f.id === featureId)) {
        return res.status(400).json({ message: 'Feature not found' });
      }
      const packages = await storage.getProposalPackages(userId);
      const allAssignments = await storage.getFeatureAssignments(packages.map(p => p.id));
      const pkgAssignments = allAssignments.filter(a => a.packageId === packageId);
      const existingIdx = pkgAssignments.findIndex(a => a.featureId === featureId);

      let newAssignments: { featureId: number; included: boolean; sortOrder: number }[];
      if (existingIdx >= 0) {
        newAssignments = pkgAssignments.map(a => ({
          featureId: a.featureId,
          included: a.featureId === featureId ? included : a.included,
          sortOrder: a.sortOrder,
        }));
      } else {
        newAssignments = [
          ...pkgAssignments.map(a => ({ featureId: a.featureId, included: a.included, sortOrder: a.sortOrder })),
          { featureId, included, sortOrder: pkgAssignments.length },
        ];
      }

      await storage.setFeatureAssignments(packageId, newAssignments);

      await resyncPackageFeatures(userId);

      res.json({ success: true });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

