  // ===== AI SMS AUTO-RESPONDER =====

  async function calculateProjectPnL(userId: string, projectId: number) {
    const docs = await storage.getDocuments(userId, {});
    const projectDocs = docs.filter(d => d.projectId === projectId);
    
    let revenue = 0;
    let laborCost = 0;
    let materialCost = 0;

    for (const doc of projectDocs) {
      if (['proposal', 'estimate', 'change_order'].includes(doc.type)) {
        if (['accepted', 'sent', 'viewed'].includes(doc.status)) {
          revenue += (doc.totalAmount || 0) / 100;
        }
      }
      if (doc.type === 'invoice' && ['paid', 'sent', 'created', 'accepted'].includes(doc.status)) {
        revenue = Math.max(revenue, (doc.totalAmount || 0) / 100);
      }

      const content = doc.content as any;
      if (content?.productionRateBlocks) {
        for (const block of content.productionRateBlocks) {
          if (block.roomBuilderData) {
            laborCost += block.roomBuilderData.totalLaborCost || 0;
            if (!block.roomBuilderData.customerProvidingMaterials) {
              materialCost += block.roomBuilderData.totalMaterialCost || 0;
            }
          }
        }
      }
      if (content?.roomBuilderData) {
        laborCost += content.roomBuilderData.totalLaborCost || 0;
        if (!content.roomBuilderData.customerProvidingMaterials) {
          materialCost += content.roomBuilderData.totalMaterialCost || 0;
        }
      }
    }

    const totalCost = laborCost + materialCost;
    const grossProfit = revenue - totalCost;
    const grossMargin = revenue > 0 ? grossProfit / revenue : 0;

    return { revenue, laborCost, materialCost, grossProfit, grossMargin };
  }

  const aiDraftDebounceTimers = new Map<string, NodeJS.Timeout>();
  const AI_DRAFT_DEBOUNCE_MS = 30000;

  function scheduleAiSmsDraft(userId: string, contactId: number | null, phoneNumber: string, inboundMessageId?: number) {
    const key = `${userId}:${contactId ?? 'none'}:${phoneNumber}`;
    const existing = aiDraftDebounceTimers.get(key);
    if (existing) {
      clearTimeout(existing);
      console.log(`[AI SMS] Debounce: resetting timer for ${key} (new message arrived within window)`);
    }

    const timer = setTimeout(() => {
      aiDraftDebounceTimers.delete(key);
      generateAiSmsDraft(userId, contactId, phoneNumber, inboundMessageId).catch(e => console.error('[AI SMS] Debounced draft error:', e));
    }, AI_DRAFT_DEBOUNCE_MS);

    aiDraftDebounceTimers.set(key, timer);
    console.log(`[AI SMS] Debounce: scheduled draft generation for ${key} in ${AI_DRAFT_DEBOUNCE_MS / 1000}s`);
  }

  async function generateAiSmsDraft(userId: string, contactId: number | null, phoneNumber: string, inboundMessageId?: number) {
    try {
      if (!process.env.OPENAI_API_KEY) {
        console.log('[AI SMS] No OpenAI API key configured, skipping draft generation');
        return;
      }

      if (!await hasFuseAiAccess(userId)) {
        console.log('[AI SMS] User does not have FuseAI subscription, skipping draft generation');
        return;
      }

      const settings = await storage.getCompanySettings(userId);
      const financialSettingsData = await storage.getFinancialSettings(userId);

      let contact: any = null;
      if (contactId) {
        contact = await storage.getContact(userId, contactId);
      }

      const comms = contactId 
        ? await storage.getCommunications(userId, contactId)
        : await storage.getCommunicationsByPhone(userId, phoneNumber);
      const smsHistory = comms
        .filter(c => c.type === 'sms')
        .sort((a, b) => new Date(a.timestamp || 0).getTime() - new Date(b.timestamp || 0).getTime())
        .slice(-20);

      const lastInbound = smsHistory.filter(m => m.direction === 'inbound').slice(-1)[0];
      const lastInboundText = (lastInbound?.content || '').toLowerCase().trim();

      const MARKETING_PATTERNS = [
        /\b(unsubscribe|opt.?out|stop to (?:end|opt|cancel)|reply stop)\b/i,
        /\b(limited.time offer|act now|exclusive deal|special promotion|free quote from)\b/i,
        /\b(we (?:can |will )?help (?:you |your )?(?:business|company|grow|rank|leads|seo|marketing|website))\b/i,
        /\b(buy (?:one|1) get|discount code|promo code|coupon)\b/i,
        /\b(i'?m reaching out|touching base|following up on behalf)\b/i,
        /\b(SEO|digital marketing|lead generation|social media marketing|web design services)\b/i,
        /\b(increase (?:your )?(?:sales|revenue|traffic|leads|visibility))\b/i,
        /\b(we specialize in|our (?:company|team|agency) (?:offers|provides|specializes))\b/i,
        /\b(roofing leads|contractor leads|home improvement leads|painting leads)\b/i,
        /\b(google (?:ads|advertising|ranking)|facebook ads|pay.per.click)\b/i,
      ];

      const isMarketingMessage = MARKETING_PATTERNS.some(pattern => pattern.test(lastInboundText));
      if (isMarketingMessage) {
        console.log(`[AI SMS] Marketing/spam message detected from ${phoneNumber}, skipping draft generation`);
        return;
      }

      const CONVERSATION_ENDED_PATTERNS = [
        /^(ok(?:ay)?|k|got it|sounds good|perfect|great|thanks|thank you|ty|thx|will do|alright|sure|yep|yes|yup|no problem|np|cool|awesome|bet|word|aight|all good)[\s!.]*$/i,
        /\b(see you|see ya|talk (?:to you )?(?:later|soon|then|tomorrow)|have a good|take care|good night|good morning|bye|goodbye|ttyl|later|cya|peace)\b/i,
        /^(ok see you|sounds good see you|great see you|perfect see you|yes see you|yep see you|alright see you)/i,
        /\b((?:we(?:'re| are) )?(?:all )?set|(?:we(?:'re| are) )?confirmed|(?:we(?:'re| are) )?good (?:to go)?|(?:that(?:'s| is) )?(?:all|it|everything))\b.*[\s!.]*$/i,
        /^(ok|okay|k|yep|yes|sure|perfect|great|awesome|sounds good|got it|will do|thank(?:s| you)|ty|thx|cool|alright)[\s,]+((?:see you|talk|have a|take care|bye|good|later|ttyl|tomorrow|then|soon).*)/i,
      ];

      const recentMessages = smsHistory.slice(-4);
      const lastOutboundInRecent = recentMessages.filter(m => m.direction === 'outbound').slice(-1)[0];
      const lastOutboundText = (lastOutboundInRecent?.content || '').toLowerCase().trim();

      if (lastOutboundText && lastInboundText) {
        const outboundWasClosing = CONVERSATION_ENDED_PATTERNS.some(p => p.test(lastOutboundText));
        const inboundIsClosing = CONVERSATION_ENDED_PATTERNS.some(p => p.test(lastInboundText));

        if (outboundWasClosing && inboundIsClosing) {
          console.log(`[AI SMS] Conversation naturally concluded with ${phoneNumber} (both sides closed), skipping draft`);
          return;
        }

        if (inboundIsClosing && lastInboundText.length < 40) {
          const lastOutboundIdx = smsHistory.findIndex(m => m === lastOutboundInRecent);
          const lastInboundIdx = smsHistory.findIndex(m => m === lastInbound);
          if (lastOutboundIdx >= 0 && lastInboundIdx > lastOutboundIdx) {
            console.log(`[AI SMS] Customer sent a closing message to ${phoneNumber} ("${lastInboundText}"), skipping draft`);
            return;
          }
        }
      }

      let project: any = null;
      let pnl: any = null;
      if (contact) {
        project = await storage.getProjectByContact(userId, contact.id);
        if (project) {
          pnl = await calculateProjectPnL(userId, project.id);
        }
      }

      let projectDocs: any[] = [];
      if (project) {
        const allDocs = await storage.getDocuments(userId, {});
        projectDocs = allDocs.filter(d => d.projectId === project.id);
      }

      const contextSnapshot: any = {
        contactName: contact?.name || 'Unknown',
        companyName: settings?.companyName || '',
        recentMessages: smsHistory.map(m => ({
          direction: m.direction,
          content: m.content || '',
          timestamp: m.timestamp ? new Date(m.timestamp).toISOString() : undefined,
        })),
      };

      if (project) {
        contextSnapshot.projectStage = project.stage;
        contextSnapshot.projectTitle = project.title;
      }
      if (pnl) {
        contextSnapshot.projectPnL = pnl;
      }
      if (financialSettingsData?.targetGrossMarginPercentage) {
        contextSnapshot.targetMargin = financialSettingsData.targetGrossMarginPercentage;
      }
      if (financialSettingsData?.aiNegotiationFloor) {
        contextSnapshot.negotiationFloor = financialSettingsData.aiNegotiationFloor;
      }

      const conversationText = smsHistory.map(m => 
        `${m.direction === 'outbound' ? 'Contractor' : 'Customer'}: ${m.content || '[media]'}`
      ).join('\n');

      let projectContext = '';
      if (project) {
        projectContext = `\n\nPROJECT INFO:
- Title: ${project.title}
- Stage: ${project.stage?.replace(/_/g, ' ')}
- Total Amount: $${((project.totalAmount || 0) / 100).toFixed(2)}`;
      }
      if (pnl) {
        projectContext += `\n\nPROJECT P&L:
- Revenue: $${pnl.revenue.toFixed(2)}
- Labor Cost: $${pnl.laborCost.toFixed(2)}
- Material Cost: $${pnl.materialCost.toFixed(2)}
- Gross Profit: $${pnl.grossProfit.toFixed(2)}
- Gross Margin: ${(pnl.grossMargin * 100).toFixed(1)}%`;
      }

      let negotiationContext = '';
      if (financialSettingsData) {
        negotiationContext = `\n\nFINANCIAL GUARDRAILS:
- Target Gross Margin: ${((financialSettingsData.targetGrossMarginPercentage || 0.50) * 100).toFixed(0)}%
- Minimum Acceptable Margin (Floor): ${((financialSettingsData.aiNegotiationFloor || 0.30) * 100).toFixed(0)}%`;
      }

      let docContext = '';
      if (projectDocs.length > 0) {
        const docSummaries = projectDocs.map(d => `- ${d.type}: "${d.title}" ($${((d.totalAmount || 0) / 100).toFixed(2)}) - Status: ${d.status}`);
        docContext = `\n\nDOCUMENTS:\n${docSummaries.join('\n')}`;
      }

      let activityContext = '';
      if (project) {
        try {
          const activities = await storage.getProjectActivities(userId, project.id);
          const recentActivities = [...activities]
            .sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime())
            .filter(a => a.type !== 'sentiment_update')
            .slice(0, 10);
          if (recentActivities.length > 0) {
            activityContext = '\n\nRECENT PROJECT ACTIVITY:';
            for (const act of recentActivities) {
              const date = act.createdAt ? new Date(act.createdAt).toLocaleDateString() : '';
              const maxLen = act.type === 'call_recording' ? 800 : 150;
              activityContext += `\n- [${date}] ${act.type}: ${act.content.substring(0, maxLen)}`;
            }
          }
          if (project.sentimentScore != null) {
            activityContext += `\n\nCUSTOMER SENTIMENT: ${project.sentimentLabel?.replace(/_/g, ' ')} (${project.sentimentScore}/100)`;
          }
        } catch (e) {
          console.error('[AI SMS] Error fetching activity context:', e);
        }
      }

      let pastJobsContext = '';
      if (contact) {
        try {
          const allProjects = await storage.getProjects(userId);
          const contactProjects = allProjects.filter(p => p.contactId === contact.id && p.id !== project?.id);
          if (contactProjects.length > 0) {
            pastJobsContext = `\n\nPAST PROJECTS WITH THIS CUSTOMER (${contactProjects.length}):`;
            for (const pp of contactProjects.slice(0, 5)) {
              pastJobsContext += `\n- "${pp.title}" — ${pp.stage?.replace(/_/g, ' ')} — $${((pp.totalAmount || 0) / 100).toFixed(2)}`;
            }
          }
        } catch (e) {
          console.error('[AI SMS] Error fetching past jobs:', e);
        }
      }

      let schedulingContext = '';
      try {
        const allAppointments = await storage.getAppointments(userId);
        const tz = settings?.timezone || 'America/New_York';
        const now = new Date();
        const todayStr = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(now);
        const lookAheadDays = 14;

        const upcoming = allAppointments
          .filter(a => {
            if (a.status !== 'scheduled') return false;
            const endDate = new Date(now.getTime() + lookAheadDays * 24 * 60 * 60 * 1000);
            const endStr = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(endDate);
            return a.date >= todayStr && a.date <= endStr;
          })
          .sort((a, b) => a.date.localeCompare(b.date) || (a.time || '').localeCompare(b.time || ''));

        let parsedHours: Record<string, any> | null = null;
        if (settings?.workingHours) {
          try { parsedHours = JSON.parse(settings.workingHours); } catch (e) {}
        }

        const dayAbbrevs = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
        const dayFullNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

        const availableSlots: string[] = [];
        if (parsedHours) {
          for (let d = 0; d < 10 && availableSlots.length < 6; d++) {
            const checkDate = new Date(now.getTime() + d * 24 * 60 * 60 * 1000);
            const dateStr = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(checkDate);
            const dayOfWeek = new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short' }).format(checkDate).toLowerCase().slice(0, 3);
            const dayConfig = parsedHours[dayOfWeek];
            if (!dayConfig || !dayConfig.enabled) continue;

            const startHour = parseInt(dayConfig.start?.split(':')[0] || '8');
            const endHour = parseInt(dayConfig.end?.split(':')[0] || '17');

            const bookedTimes = new Set(
              upcoming
                .filter(a => a.date === dateStr && a.time)
                .map(a => parseInt(a.time!.split(':')[0]))
            );

            const dayName = dayFullNames[checkDate.getDay()];
            const monthDay = new Intl.DateTimeFormat('en-US', { timeZone: tz, month: 'short', day: 'numeric' }).format(checkDate);

            const dayLabel = d === 0 ? 'TODAY' : d === 1 ? 'TOMORROW' : dayName;
            for (let h = startHour; h < endHour && availableSlots.length < 6; h++) {
              if (d === 0) {
                const currentHour = parseInt(new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: '2-digit', hour12: false }).format(now));
                if (h <= currentHour) continue;
              }
              if (!bookedTimes.has(h)) {
                const timeStr = h <= 12 ? `${h === 0 ? 12 : h}:00 AM` : `${h - 12 === 0 ? 12 : h - 12}:00 PM`;
                if (h >= 12 && h < 13) {
                  availableSlots.push(`${dayLabel} (${monthDay}) at 12:00 PM`);
                } else {
                  availableSlots.push(`${dayLabel} (${monthDay}) at ${timeStr}`);
                }
              }
            }
          }
        }

        if (availableSlots.length > 0 || parsedHours) {
          schedulingContext = '\n\nSCHEDULING INFO:';
          schedulingContext += `\nTimezone: ${tz}`;
          schedulingContext += `\nToday's date: ${todayStr}`;
          if (availableSlots.length > 0) {
            schedulingContext += '\n\nAvailable time slots (next 10 business days):';
            for (const slot of availableSlots) {
              schedulingContext += `\n- ${slot}`;
            }
          }
          if (upcoming.length > 0) {
            schedulingContext += '\n\nAlready booked:';
            for (const appt of upcoming.slice(0, 10)) {
              schedulingContext += `\n- ${appt.date}${appt.time ? ' at ' + appt.time : ''}: ${appt.type}`;
            }
          }
        }
      } catch (e) {
        console.error('[AI SMS] Error fetching scheduling context:', e);
      }

      const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

      const assistantName = settings?.aiAssistantName;
      const systemPrompt = `You are ${assistantName ? assistantName + ', a team member' : 'a team member'} at "${settings?.companyName || 'the company'}" responding to customer text messages.${assistantName ? ` Your name is ${assistantName}. You may sign off texts with your name when appropriate (e.g., "- ${assistantName}").` : ''} You are NOT an AI — you are part of the team.

RULES:
- Keep responses short and professional (1-3 sentences, SMS-appropriate length)
- Be friendly, warm, and helpful
- Never reveal internal pricing, margins, or financial details to the customer
- If the customer asks about pricing or negotiates, be diplomatic. You know the real margins.
- If the customer asks to lower the price, you can offer small concessions but NEVER go below the minimum acceptable margin floor
- If the customer's request seems outside your knowledge, suggest they call or schedule a meeting
- Match the tone of the conversation - if casual, be casual; if formal, be professional
- Don't use emojis excessively
- Reference specific project details when relevant (e.g., "regarding your kitchen renovation...")
- If the customer seems upset or the topic is very sensitive (complaints, legal issues, major scope changes), flag this as needing human review by starting your response with [NEEDS REVIEW]

SCHEDULING RULES:
- If the customer wants to schedule, meet, set up a time, or asks about availability, check the scheduling info below
- Only suggest times during business hours and when there are no conflicting appointments
- Suggest 2-3 specific available time slots when possible
- Use relative terms when appropriate: say "today" if the slot is today, "tomorrow" if it's tomorrow, and for other days say the day of the week with the date (e.g., "Wednesday the 18th at 10am")
- NEVER suggest a day/date that has already passed or is the current day without saying "today"
- If no scheduling info is available, suggest the customer call to schedule
${projectContext}${negotiationContext}${docContext}${activityContext}${pastJobsContext}${schedulingContext}

CONVERSATION HISTORY:
${conversationText}`;

      const useAdvancedModel = !!(negotiationContext || pnl);
      const smsModel = useAdvancedModel ? "gpt-4o" : "gpt-4o-mini";
      console.log(`[AI SMS] Using model: ${smsModel} (negotiation context: ${!!negotiationContext}, P&L: ${!!pnl})`);

      const unansweredInbound = [];
      let foundLastOutbound = false;
      for (let i = smsHistory.length - 1; i >= 0; i--) {
        if (smsHistory[i].direction === 'outbound') { foundLastOutbound = true; break; }
        if (smsHistory[i].direction === 'inbound') unansweredInbound.unshift(smsHistory[i]);
      }
      if (!foundLastOutbound && unansweredInbound.length === 0) {
        unansweredInbound.push(...smsHistory.filter(m => m.direction === 'inbound'));
      }

      const userPromptText = unansweredInbound.length > 1
        ? `The customer has sent ${unansweredInbound.length} messages since the last reply. Generate ONE consolidated reply that addresses all of their messages together. Do NOT generate separate replies. Return ONLY the text message reply, nothing else.`
        : "Generate a reply to the customer's latest message. Return ONLY the text message reply, nothing else.";

      const response = await openai.chat.completions.create({
        model: smsModel,
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: userPromptText }
        ],
        max_tokens: 300,
        temperature: 0.7,
      });

      let suggestedText = response.choices[0]?.message?.content?.trim() || '';
      if (!suggestedText) {
        console.log('[AI SMS] Empty response from OpenAI, skipping');
        return;
      }

      const needsReview = suggestedText.startsWith('[NEEDS REVIEW]');
      if (needsReview) {
        suggestedText = suggestedText.replace('[NEEDS REVIEW]', '').trim();
      }

      const shouldAutoSend = (settings?.aiSmsMode === 'auto_respond' || settings?.aiAutoRespond) && !needsReview;
      const responseDelayMs = (settings?.aiSmsResponseDelay ?? 30) * 1000;

      const dismissedCount = await storage.dismissPendingDraftsForConversation(userId, contactId || undefined, phoneNumber);
      if (dismissedCount > 0) {
        console.log(`[AI SMS] Auto-dismissed ${dismissedCount} stale pending draft(s) for ${contactId || phoneNumber} before generating new one`);
      }

      const draft = await storage.createAiMessageDraft({
        userId,
        contactId: contactId || undefined,
        projectId: project?.id || undefined,
        phoneNumber,
        inboundMessageId: inboundMessageId || undefined,
        suggestedText,
        contextSnapshot,
        status: shouldAutoSend ? 'approved' : 'pending',
      });

      if (shouldAutoSend) {
        const sendAutoReply = async () => {
          try {
            const twilio = await import('twilio');
            const client = twilio.default(settings!.twilioAccountSid!, settings!.twilioAuthToken!);
            const msgOpts: any = {
              body: suggestedText,
              to: phoneNumber,
            };
            if (settings!.twilioMessagingServiceSid) {
              msgOpts.messagingServiceSid = settings!.twilioMessagingServiceSid;
            } else {
              msgOpts.from = settings!.twilioPhoneNumber;
            }

            const currentDraft = await storage.getAiMessageDraft(userId, draft.id);
            if (currentDraft?.status === 'dismissed') {
              console.log(`[AI SMS] Draft ${draft.id} was dismissed during delay, skipping auto-send`);
              return;
            }

            const sent = await client.messages.create(msgOpts);

            await createOutboundComm(userId, {
              contactId: contactId || undefined,
              phoneNumber,
              type: 'sms',
              direction: 'outbound',
              content: suggestedText,
              messageSid: sent.sid || null,
            });

            await storage.updateAiMessageDraft(userId, draft.id, { status: 'sent' });
            console.log(`[AI SMS] Auto-sent response to ${phoneNumber} (after ${responseDelayMs / 1000}s delay)`);
          } catch (sendErr: any) {
            console.error('[AI SMS] Auto-send failed:', sendErr.message);
            await storage.updateAiMessageDraft(userId, draft.id, { status: 'pending' });
          }
        };

        if (responseDelayMs > 0) {
          console.log(`[AI SMS] Auto-respond scheduled for ${phoneNumber} in ${responseDelayMs / 1000}s`);
          setTimeout(sendAutoReply, responseDelayMs);
        } else {
          await sendAutoReply();
        }
      } else {
        console.log(`[AI SMS] Draft created for approval (id: ${draft.id})`);
        sendPushToUser(userId, {
          title: 'AI Draft Ready',
          body: `Suggested reply for ${contact?.name || phoneNumber}: "${suggestedText.substring(0, 80)}..."`,
          url: contactId ? `/messages?contactId=${contactId}` : `/messages?phone=${encodeURIComponent(phoneNumber)}`,
          tag: `ai-draft-${draft.id}`,
        }).catch(err => console.error('[Push] AI draft notification error:', err));
      }
      // ---- Proactive AI Actions: Check if we should suggest creating a proposal ----
      if (project && contactId && await hasFuseAiAccess(userId)) {
        try {
          const existingActions = await storage.getAiActions(userId, { status: 'pending', limit: 50 });

          const hasProposal = projectDocs.some(d => 
            d.type === 'proposal' || d.type === 'estimate'
          );

          if (!hasProposal) {
            const alreadySuggested = existingActions.some(a => 
              a.type === 'proposal_suggestion' && a.projectId === project.id
            );

            if (!alreadySuggested) {
              const scopeKeywords = /room|bedroom|bathroom|kitchen|living|dining|hallway|stairway|ceiling|wall|door|window|trim|cabinet|deck|fence|exterior|interior|garage|basement|attic|office|closet|paint|color|coat|prep|sand|prime|square\s*f(ee|oo)t|sqft|sq\s*ft|estimate|proposal|quote|price|cost|budget|how\s*much/i;
              const fullConversation = smsHistory.map(m => m.content || '').join(' ');

              if (scopeKeywords.test(fullConversation) && smsHistory.length >= 3) {
                const contactName = contact?.name || 'Unknown';
                await storage.createAiAction({
                  userId,
                  projectId: project.id,
                  contactId,
                  type: 'proposal_suggestion',
                  summary: `Ready to create a proposal for ${contactName}'s project "${project.title}"`,
                  details: {
                    projectTitle: project.title,
                    projectStage: project.stage,
                    contactName,
                    messageCount: smsHistory.length,
                    hasProductionRates: false,
                  },
                  status: 'pending',
                });
                console.log(`[AI Actions] Created proposal suggestion for project ${project.id}`);

                sendPushToUser(userId, {
                  title: 'AI Suggestion',
                  body: `Enough info gathered for ${contactName}'s project — ready to create a proposal`,
                  url: `/projects/${project.id}`,
                  tag: `ai-action-proposal-${project.id}`,
                }).catch(err => console.error('[Push] AI action notification error:', err));
              }
            }
          }

          // Check if customer is asking about scheduling and no appointment exists
          const schedulingIntent = /schedule|appointment|come\s*(out|by|over)|meet|available|when\s*can|what\s*time|free\s*time|book|visit/i;
          const latestMessage = smsHistory[smsHistory.length - 1]?.content || '';
          if (schedulingIntent.test(latestMessage)) {
            const existingAppointments = await storage.getAppointments(userId);
            const hasAppointmentForContact = existingAppointments.some(a => 
              a.contactId === contactId && (a.status === 'scheduled' || a.status === 'pending_ai')
            );

            if (!hasAppointmentForContact) {
              const alreadySuggestedSchedule = existingActions.some(a => 
                a.type === 'scheduling_suggestion' && a.contactId === contactId && a.status === 'pending'
              );
              if (!alreadySuggestedSchedule) {
                const contactName = contact?.name || 'Unknown';
                
                // Try to pick a suggested date/time from the AI response or first available slot
                let suggestedDate: string | null = null;
                let suggestedTime: string | null = null;
                let appointmentType = 'estimate';
                
                if (/walkthrough|walk.?through|final\s*walk/i.test(latestMessage)) appointmentType = 'walkthrough';
                else if (/payment|collect|pay\s*you/i.test(latestMessage)) appointmentType = 'payment';
                else if (/call\s*(me\s*)?back|call\s*you|callback|give.*(a\s*)?call/i.test(latestMessage)) appointmentType = 'callback';
                else if (/text\s*(me\s*)?back|text\s*(you|later)|follow.?up\s*text/i.test(latestMessage)) appointmentType = 'text_schedule';
                else if (/come\s*(out|by|over)|on.?site|visit|stop\s*by|swing\s*by/i.test(latestMessage)) appointmentType = 'site_visit';
                else if (/follow.?up|check.?in|touch\s*base/i.test(latestMessage)) appointmentType = 'follow_up';
                else if (/phone|call/i.test(latestMessage)) appointmentType = 'phone_call';
                else if (/meet/i.test(latestMessage)) appointmentType = 'other';
                
                // Parse date/time from AI's suggested response if it mentions specific times
                const aiText = suggestedText || '';
                const dateMatch = aiText.match(/(\w+day)\s*(?:the\s*)?(\d{1,2})(?:st|nd|rd|th)?/i) ||
                                  aiText.match(/(today|tomorrow)/i);
                if (dateMatch) {
                  const tz = settings?.timezone || 'America/New_York';
                  const now = new Date();
                  if (/today/i.test(dateMatch[0])) {
                    suggestedDate = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(now);
                  } else if (/tomorrow/i.test(dateMatch[0])) {
                    const tmrw = new Date(now.getTime() + 24 * 60 * 60 * 1000);
                    suggestedDate = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(tmrw);
                  } else {
                    // Try to figure out the date from day name + day number
                    for (let d = 0; d < 14; d++) {
                      const checkDate = new Date(now.getTime() + d * 24 * 60 * 60 * 1000);
                      const dayName = new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'long' }).format(checkDate).toLowerCase();
                      if (dayName.startsWith(dateMatch[1]?.toLowerCase().slice(0, 3) || '')) {
                        suggestedDate = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(checkDate);
                        break;
                      }
                    }
                  }
                  // Parse time
                  const timeMatch = aiText.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)/i);
                  if (timeMatch) {
                    let hour = parseInt(timeMatch[1]);
                    if (timeMatch[3]?.toLowerCase() === 'pm' && hour < 12) hour += 12;
                    if (timeMatch[3]?.toLowerCase() === 'am' && hour === 12) hour = 0;
                    suggestedTime = `${hour.toString().padStart(2, '0')}:${timeMatch[2] || '00'}`;
                  }
                }
                
                // Create pending AI appointment
                if (suggestedDate) {
                  const aiApptNotes = `AI-suggested: ${contactName} requested scheduling. "${latestMessage.substring(0, 150)}"`;
                  const aiAppt = await storage.createAppointment(userId, {
                    contactId,
                    type: appointmentType,
                    date: suggestedDate,
                    time: suggestedTime,
                    notes: aiApptNotes,
                    status: 'pending_ai',
                  });
                  await scheduleAppointmentReminders(userId, aiAppt.id, suggestedDate, suggestedTime);
                  syncAppointmentToGoogleCalendar(userId, aiAppt.id, suggestedDate, suggestedTime, contactId, appointmentType, aiApptNotes);
                  emitToUser(userId, userId, { type: 'appointment.updated', tenantId: userId });
                  console.log(`[AI Appointments] Created pending_ai appointment for contact ${contactId} on ${suggestedDate} ${suggestedTime || ''}`);
                }
                
                await storage.createAiAction({
                  userId,
                  contactId,
                  projectId: project.id,
                  type: 'scheduling_suggestion',
                  summary: `${contactName} is asking about scheduling${suggestedDate ? ` — suggested ${suggestedDate}${suggestedTime ? ' at ' + suggestedTime : ''}` : ' — no appointment set yet'}`,
                  details: {
                    contactName,
                    projectTitle: project.title,
                    latestMessage: latestMessage.substring(0, 200),
                    suggestedDate,
                    suggestedTime,
                    appointmentType,
                  },
                  status: 'pending',
                });
                console.log(`[AI Actions] Created scheduling suggestion for contact ${contactId}`);
              }
            }
          }
        } catch (actionErr: any) {
          console.error('[AI Actions] Error checking proactive actions:', actionErr.message);
        }
      }

      // ---- Sentiment Analysis: Update project sentiment based on conversation ----
      if (project && contactId) {
        try {
          const sentimentPrompt = `Analyze the customer sentiment in this conversation between a contractor and their customer. Consider the overall tone, satisfaction level, and engagement.

CONVERSATION:
${conversationText}

PROJECT CONTEXT:
- Stage: ${project.stage?.replace(/_/g, ' ')}
- Title: ${project.title}

Respond with ONLY a JSON object (no markdown, no code blocks):
{"score": <number 1-100>, "label": "<one of: very_negative, negative, neutral, positive, very_positive>", "reason": "<one brief sentence explaining the score>"}

Score guide: 1-20 very_negative (angry, threatening to cancel), 21-40 negative (unhappy, complaining), 41-60 neutral (business-like, no strong emotion), 61-80 positive (happy, engaged, interested), 81-100 very_positive (enthusiastic, praising, eager to proceed)`;

          const sentimentResponse = await openai.chat.completions.create({
            model: "gpt-4o-mini",
            messages: [
              { role: "system", content: "You are a sentiment analysis tool. Return only valid JSON." },
              { role: "user", content: sentimentPrompt }
            ],
            max_tokens: 100,
            temperature: 0.3,
          });

          const sentimentRaw = sentimentResponse.choices[0]?.message?.content?.trim() || '';
          try {
            const cleaned = sentimentRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
            const sentimentData = JSON.parse(cleaned);
            if (sentimentData.score && sentimentData.label) {
              await storage.updateProject(userId, project.id, {
                sentimentScore: Math.max(1, Math.min(100, Math.round(sentimentData.score))),
                sentimentLabel: sentimentData.label,
                sentimentUpdatedAt: new Date(),
              } as any);

              await storage.createProjectActivity(userId, {
                projectId: project.id,
                type: 'sentiment_update',
                content: `Sentiment: ${sentimentData.label.replace(/_/g, ' ')} (${sentimentData.score}/100) — ${sentimentData.reason || ''}`,
                metadata: { score: sentimentData.score, label: sentimentData.label, reason: sentimentData.reason },
              });

              console.log(`[AI Sentiment] Project ${project.id}: ${sentimentData.label} (${sentimentData.score}/100)`);
            }
          } catch (parseErr) {
            console.error('[AI Sentiment] Parse error:', parseErr, 'Raw:', sentimentRaw);
          }
        } catch (sentErr: any) {
          console.error('[AI Sentiment] Error:', sentErr.message);
        }
      }

      // ---- AI Reminders: Detect actionable items in inbound messages and create reminders ----
      if (contactId && await hasFuseAiAccess(userId)) {
        try {
          const latestInbound = smsHistory.filter(m => m.direction === 'inbound').slice(-3);
          if (latestInbound.length > 0) {
            const latestInboundText = latestInbound.map(m => m.content || '').join('\n');
            const contactName = contact?.name || 'Customer';
            const tz = (await storage.getCompanySettings(userId))?.timezone || 'America/New_York';
            const nowDateStr = new Intl.DateTimeFormat('en-US', { 
              timeZone: tz, weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
            }).format(new Date());

            const reminderPrompt = `You are analyzing a customer's recent text messages to a contractor. Extract any actionable items that the contractor should be reminded about.

TODAY'S DATE: ${nowDateStr}
CUSTOMER NAME: ${contactName}

RECENT INBOUND MESSAGES FROM CUSTOMER:
${latestInboundText}

Look for things like:
- Promises to call back at a specific time
- Requests for callbacks
- Scheduled meetings or visits
- Deadlines or dates mentioned
- Requests that need follow-up action
- Commitments the customer made (e.g., "I'll send you photos", "I'll get back to you")

If there are actionable items, respond with a JSON array of reminders (max 2). Each reminder should have:
- "summary": A short, actionable reminder (e.g., "Expect a call from Ray tomorrow night")
- "urgency": "low", "medium", or "high"
- "suggestedDate": The approximate date/time in ISO format if mentioned, or null

If there are NO actionable items (just casual chat, simple confirmations like "ok thanks", etc.), respond with an empty array: []

Respond with ONLY a JSON array (no markdown, no code blocks):`;

            const reminderResponse = await openai.chat.completions.create({
              model: "gpt-4o-mini",
              messages: [
                { role: "system", content: "You are a reminder extraction tool. Return only valid JSON arrays. Be selective — only create reminders for genuinely actionable items, not routine pleasantries." },
                { role: "user", content: reminderPrompt }
              ],
              max_tokens: 300,
              temperature: 0.3,
            });

            const reminderRaw = reminderResponse.choices[0]?.message?.content?.trim() || '[]';
            try {
              const cleanedReminder = reminderRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
              const reminders = JSON.parse(cleanedReminder);
              if (Array.isArray(reminders) && reminders.length > 0) {
                const existingActions = await storage.getAiActions(userId, { status: 'pending', limit: 50 });

                for (const reminder of reminders.slice(0, 2)) {
                  if (!reminder.summary) continue;

                  const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);
                  const allRecentActions = await storage.getAiActions(userId, { limit: 100 });
                  const alreadyExists = allRecentActions.some(a => 
                    a.type === 'reminder' && a.contactId === contactId && 
                    a.summary.toLowerCase() === reminder.summary.toLowerCase() &&
                    new Date(a.createdAt || 0) > oneDayAgo
                  );
                  if (alreadyExists) continue;

                  await storage.createAiAction({
                    userId,
                    projectId: project?.id || null,
                    contactId,
                    type: 'reminder',
                    summary: reminder.summary,
                    details: {
                      contactName,
                      urgency: reminder.urgency || 'medium',
                      suggestedDate: reminder.suggestedDate || null,
                      sourceMessage: latestInboundText.substring(0, 300),
                      projectTitle: project?.title || null,
                    },
                    status: 'pending',
                  });

                  console.log(`[AI Reminder] Created reminder for contact ${contactId}: ${reminder.summary}`);

                  // If reminder has a date and is schedule-related, also create a pending appointment
                  const isScheduleReminder = /schedul|appointment|site visit|walkthrough|call\s*back|follow.?up|meet|come\s*(out|by|over)|visit|check.?in/i.test(reminder.summary);
                  if (isScheduleReminder && reminder.suggestedDate) {
                    try {
                      const reminderDate = new Date(reminder.suggestedDate);
                      if (!isNaN(reminderDate.getTime())) {
                        const existingAppts = await storage.getAppointments(userId);
                        const hasPendingForContact = existingAppts.some(a => 
                          a.contactId === contactId && (a.status === 'pending_ai' || a.status === 'scheduled')
                        );
                        if (!hasPendingForContact) {
                          const apptDate = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(reminderDate);
                          const hours = reminderDate.getHours();
                          const minutes = reminderDate.getMinutes();
                          const apptTime = (hours > 0 || minutes > 0) ? `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}` : null;
                          
                          let apptType = 'other';
                          if (/walkthrough|walk.?through|final\s*walk/i.test(reminder.summary)) apptType = 'walkthrough';
                          else if (/estimate|quote|proposal/i.test(reminder.summary)) apptType = 'estimate';
                          else if (/payment|collect|pay/i.test(reminder.summary)) apptType = 'payment';
                          else if (/call\s*(me\s*)?back|call\s*you|callback|give.*(a\s*)?call/i.test(reminder.summary)) apptType = 'callback';
                          else if (/text\s*(me\s*)?back|text\s*(you|later)|follow.?up\s*text/i.test(reminder.summary)) apptType = 'text_schedule';
                          else if (/come\s*(out|by|over)|on.?site|site\s*visit|stop\s*by|swing\s*by/i.test(reminder.summary)) apptType = 'site_visit';
                          else if (/follow.?up|check.?in|touch\s*base/i.test(reminder.summary)) apptType = 'follow_up';
                          else if (/phone|call/i.test(reminder.summary)) apptType = 'phone_call';
                          
                          const reminderApptNotes = `AI-created from reminder: ${reminder.summary}`;
                          const reminderAppt = await storage.createAppointment(userId, {
                            contactId,
                            type: apptType,
                            date: apptDate,
                            time: apptTime,
                            notes: reminderApptNotes,
                            status: 'pending_ai',
                          });
                          await scheduleAppointmentReminders(userId, reminderAppt.id, apptDate, apptTime);
                          syncAppointmentToGoogleCalendar(userId, reminderAppt.id, apptDate, apptTime, contactId, apptType, reminderApptNotes);
                          emitToUser(userId, userId, { type: 'appointment.updated', tenantId: userId });
                          console.log(`[AI Reminder] Also created pending_ai appointment for contact ${contactId} on ${apptDate}`);
                        }
                      }
                    } catch (apptErr: any) {
                      console.error('[AI Reminder] Error creating appointment from reminder:', apptErr.message);
                    }
                  }

                  if (project?.id) {
                    await storage.createProjectActivity(userId, {
                      projectId: project.id,
                      type: 'ai_reminder',
                      content: reminder.summary,
                      metadata: { 
                        contactName, 
                        urgency: reminder.urgency || 'medium',
                        suggestedDate: reminder.suggestedDate || null,
                      },
                    });
                  }

                  sendPushToUser(userId, {
                    title: 'AI Reminder',
                    body: reminder.summary,
                    url: '/calendar?tab=appointments',
                    tag: `ai-reminder-${contactId}-${Date.now()}`,
                  }).catch(err => console.error('[Push] AI reminder notification error:', err));
                }
              }
            } catch (parseErr) {
              console.error('[AI Reminder] Parse error:', parseErr, 'Raw:', reminderRaw);
            }
          }
        } catch (reminderErr: any) {
          console.error('[AI Reminder] Error:', reminderErr.message);
        }
      }
    } catch (err: any) {
      console.error('[AI SMS] Draft generation error:', err.message);
    }
  }

