  app.post('/api/ai-response/generate', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      if (!await hasFuseAiAccess(userId)) {
        return res.status(403).json({ error: 'FuseAI subscription required' });
      }
      if (!process.env.OPENAI_API_KEY) {
        return res.status(500).json({ error: 'AI not configured' });
      }

      const { contactId, phoneNumber } = req.body;
      if (!contactId && !phoneNumber) {
        return res.status(400).json({ error: 'contactId or phoneNumber required' });
      }

      const settings = await storage.getCompanySettings(userId);
      const financialSettingsData = await storage.getFinancialSettings(userId);

      let contact: any = null;
      if (contactId) {
        contact = await storage.getContact(userId, contactId);
      }

      const comms = contactId
        ? await storage.getCommunications(userId, contactId)
        : await storage.getCommunicationsByPhone(userId, phoneNumber);
      const smsHistory = comms
        .filter(c => c.type === 'sms')
        .sort((a, b) => new Date(a.timestamp || 0).getTime() - new Date(b.timestamp || 0).getTime())
        .slice(-20);

      if (smsHistory.length === 0) {
        return res.status(400).json({ error: 'No message history to respond to' });
      }

      let project: any = null;
      let pnl: any = null;
      if (contact) {
        project = await storage.getProjectByContact(userId, contact.id);
        if (project) {
          pnl = await calculateProjectPnL(userId, project.id);
        }
      }

      const conversationText = smsHistory.map(m =>
        `${m.direction === 'outbound' ? 'Contractor' : 'Customer'}: ${m.content || '[media]'}`
      ).join('\n');

      let projectContext = '';
      if (project) {
        projectContext = `\n\nPROJECT INFO:\n- Title: ${project.title}\n- Stage: ${project.stage?.replace(/_/g, ' ')}\n- Total Amount: $${((project.totalAmount || 0) / 100).toFixed(2)}`;
      }
      if (pnl) {
        projectContext += `\n\nPROJECT P&L:\n- Revenue: $${pnl.revenue.toFixed(2)}\n- Labor Cost: $${pnl.laborCost.toFixed(2)}\n- Material Cost: $${pnl.materialCost.toFixed(2)}\n- Gross Profit: $${pnl.grossProfit.toFixed(2)}\n- Margin: ${(pnl.grossMargin * 100).toFixed(1)}%`;
      }

      let negotiationContext = '';
      if (pnl && financialSettingsData?.aiNegotiationFloor) {
        const floor = financialSettingsData.aiNegotiationFloor;
        negotiationContext = `\n\nNEGOTIATION RULES:\n- Current margin: ${(pnl.grossMargin * 100).toFixed(1)}%\n- Minimum acceptable margin: ${(floor * 100).toFixed(0)}%\n- You can offer small discounts but NEVER go below the floor`;
      }

      let docContext = '';
      if (project) {
        const allDocs = await storage.getDocuments(userId, {});
        const projectDocs = allDocs.filter(d => d.projectId === project.id);
        if (projectDocs.length > 0) {
          docContext = '\n\nDOCUMENTS:';
          for (const doc of projectDocs.slice(0, 5)) {
            docContext += `\n- ${doc.type}: "${doc.title}" — $${((doc.totalAmount || 0) / 100).toFixed(2)} (${doc.status})`;
          }
        }
      }

      let schedulingContext = '';
      try {
        const appointments = await storage.getAppointments(userId);
        const now = new Date();
        const upcoming = appointments
          .filter(a => a.date && new Date(a.date) >= now)
          .sort((a, b) => new Date(a.date!).getTime() - new Date(b.date!).getTime());
        if (upcoming.length > 0) {
          schedulingContext = '\n\nUPCOMING APPOINTMENTS:';
          for (const appt of upcoming.slice(0, 10)) {
            schedulingContext += `\n- ${appt.date}${appt.time ? ' at ' + appt.time : ''}: ${appt.type}`;
          }
        }
      } catch (e) {
        console.error('[AI Response] Error fetching scheduling context:', e);
      }

      const assistantName = settings?.aiAssistantName;
      const systemPrompt = `You are ${assistantName ? assistantName + ', a team member' : 'a team member'} at "${settings?.companyName || 'the company'}" responding to customer text messages.${assistantName ? ` Your name is ${assistantName}. You may sign off texts with your name when appropriate (e.g., "- ${assistantName}").` : ''} You are NOT an AI — you are part of the team.

RULES:
- Keep responses short and professional (1-3 sentences, SMS-appropriate length)
- Be friendly, warm, and helpful
- Never reveal internal pricing, margins, or financial details to the customer
- If the customer asks about pricing or negotiates, be diplomatic
- If the customer's request seems outside your knowledge, suggest they call or schedule a meeting
- Match the tone of the conversation
- Don't use emojis excessively
- Reference specific project details when relevant
- If the customer wants to schedule, suggest 2-3 available time slots during business hours
${projectContext}${negotiationContext}${docContext}${schedulingContext}

CONVERSATION HISTORY:
${conversationText}`;

      const useAdvancedModel = !!(negotiationContext || pnl);
      const smsModel = useAdvancedModel ? "gpt-4o" : "gpt-4o-mini";

      const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
      const response = await openai.chat.completions.create({
        model: smsModel,
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: "Generate a reply to the customer's latest message. Return ONLY the text message reply, nothing else." },
        ],
        temperature: 0.7,
        max_tokens: 300,
      });

      const aiText = response.choices[0]?.message?.content?.trim() || '';
      console.log(`[AI Response] Generated on-demand reply for ${contactId || phoneNumber} (${smsModel})`);
      res.json({ text: aiText });
    } catch (err: any) {
      console.error('[AI Response] Error:', err.message);
      res.status(500).json({ error: 'Failed to generate AI response' });
    }
  });

