  app.post('/api/ai-drafts/:id/approve', isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const draftId = Number(req.params.id);
      const { editedText } = req.body;
      
      const draft = await storage.getAiMessageDraft(userId, draftId);
      if (!draft) return res.status(404).json({ message: 'Draft not found' });
      if (draft.status !== 'pending') return res.status(400).json({ message: 'Draft is not pending' });

      const textToSend = editedText || draft.suggestedText;

      const settings = await storage.getCompanySettings(userId);
      if (!settings?.twilioAccountSid || !settings?.twilioAuthToken || !settings?.twilioPhoneNumber) {
        return res.status(400).json({ message: 'Twilio not configured' });
      }

      const phone = draft.phoneNumber;
      if (!phone) return res.status(400).json({ message: 'No phone number on draft' });

      const twilio = await import('twilio');
      const client = twilio.default(settings.twilioAccountSid, settings.twilioAuthToken);
      const msgOpts: any = { body: textToSend, to: phone };
      if (settings.twilioMessagingServiceSid) {
        msgOpts.messagingServiceSid = settings.twilioMessagingServiceSid;
      } else {
        msgOpts.from = settings.twilioPhoneNumber;
      }
      const sent = await client.messages.create(msgOpts);

      await createOutboundComm(userId, {
        contactId: draft.contactId || undefined,
        phoneNumber: phone,
        type: 'sms',
        direction: 'outbound',
        content: textToSend,
        messageSid: sent.sid || null,
      });

      if (editedText) {
        await storage.updateAiMessageDraft(userId, draftId, { suggestedText: editedText, status: 'sent' });
      } else {
        await storage.updateAiMessageDraft(userId, draftId, { status: 'sent' });
      }

      res.json({ success: true, messageSid: sent.sid });
    } catch (err: any) {
      res.status(500).json({ message: err.message || 'Failed to approve and send' });
    }
  });

