  // ==========================================
  // MATERIALS SUMMARY (Project-Level)
  // ==========================================
  app.get("/api/projects/:id/materials-summary", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const projectId = parseInt(req.params.id);

      const projectDocs = await db.select().from(documents).where(
        and(eq(documents.userId, userId), eq(documents.projectId, projectId))
      );

      const proposalDocs = projectDocs.filter(d =>
        (d.type === 'proposal' || d.type === 'estimate') &&
        d.status !== 'rejected'
      );

      interface GroupAccum {
        paintGroupKey: string;
        label: string;
        totalPaintableSqft: number;
        colorName?: string;
        finish?: string;
        brand?: string;
        itemNames: string[];
      }

      const groups: Record<string, GroupAccum> = {};

      for (const doc of proposalDocs) {
        const content = doc.content as any;
        if (!content?.items) continue;
        for (const item of content.items as UnifiedLineItem[]) {
          if (!item.surfaces || item.surfaces.length === 0) continue;
          for (const surface of item.surfaces) {
            const groupKey = surface.paintGroupKey || 'ungrouped';
            if (!groups[groupKey]) {
              groups[groupKey] = {
                paintGroupKey: groupKey,
                label: groupKey.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()),
                totalPaintableSqft: 0,
                itemNames: [],
              };
            }
            const sqft = (surface.qty || 0) * (surface.coats || 1);
            groups[groupKey].totalPaintableSqft += sqft;
            if (item.name && !groups[groupKey].itemNames.includes(item.name)) {
              groups[groupKey].itemNames.push(item.name);
            }
            if (item.paintAssignment) {
              if (item.paintAssignment.colorName) groups[groupKey].colorName = item.paintAssignment.colorName;
              if (item.paintAssignment.finish) groups[groupKey].finish = item.paintAssignment.finish;
              if (item.paintAssignment.brand) groups[groupKey].brand = item.paintAssignment.brand;
            }
          }
        }
      }

      const userSurfaces = await db.select().from(surfaces).where(eq(surfaces.userId, userId));
      const userMaterials = await db.select().from(materialsTable).where(eq(materialsTable.userId, userId));
      const activeMaterials = userMaterials.filter(m => m.active);

      const defaultCoverage = 350;
      const defaultWaste = 0.10;

      const summary = Object.values(groups).map(g => {
        let coverage = defaultCoverage;
        let waste = defaultWaste;
        let materialName = "Default Paint";
        let materialConfigured = false;

        if (activeMaterials.length > 0) {
          const paint = activeMaterials.find(m => m.type === 'paint' && m.coverageSqftPerGallon);
          if (paint) {
            coverage = paint.coverageSqftPerGallon || defaultCoverage;
            waste = paint.wastePercentage || defaultWaste;
            materialName = paint.materialName;
            materialConfigured = true;
          }
        }

        const gallonsExact = (g.totalPaintableSqft / coverage) * (1 + waste);
        const gallonsToBuy = Math.ceil(gallonsExact);

        return {
          ...g,
          gallonsExact: parseFloat(gallonsExact.toFixed(2)),
          gallonsToBuy,
          materialName,
          materialConfigured,
          coverage,
          waste,
        };
      });

      res.json(summary);
    } catch (error: any) {
      console.error("[MaterialsSummary] Error:", error);
      res.status(500).json({ message: error.message });
    }
  });

