  app.get("/api/portal/:token/color-submissions", async (req: Request, res: Response) => {
    try {
      const doc = await db.select().from(documents).where(eq(documents.publicToken, req.params.token)).then(r => r[0]);
      if (!doc) return res.status(404).json({ message: "Document not found" });
      const subs = await db.select().from(colorSubmissions).where(
        eq(colorSubmissions.documentId, doc.id)
      ).orderBy(desc(colorSubmissions.createdAt));

      if (subs.length === 0) {
        return res.json(null);
      }

      const latest = subs[0];
      const docStatus = doc.colorSubmissionStatus;
      let status = latest.status;
      if (docStatus === 'pending_approval') status = 'pending_approval';
      else if (docStatus === 'approved') status = 'approved';
      else if (docStatus === 'needs_update') status = 'needs_update';

      res.json({
        status,
        entries: latest.entries as any[],
        rejectionNote: latest.reviewNote || undefined,
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/portal/:token/color-submissions", async (req: Request, res: Response) => {
    try {
      const doc = await db.select().from(documents).where(eq(documents.publicToken, req.params.token)).then(r => r[0]);
      if (!doc) return res.status(404).json({ message: "Document not found" });
      if (!doc.signedAt) return res.status(400).json({ message: "Proposal must be signed first" });
      if (!doc.allowClientColorSubmission) return res.status(400).json({ message: "Color submission not enabled" });
      if (doc.colorSubmissionStatus === 'approved') return res.status(400).json({ message: "Colors already approved and locked" });

      const { entries } = req.body as { entries: ColorSubmissionEntry[] };
      if (!entries || !Array.isArray(entries)) return res.status(400).json({ message: "Invalid entries" });

      const [submission] = await db.insert(colorSubmissions).values({
        documentId: doc.id,
        projectId: doc.projectId,
        userId: doc.userId,
        entries,
        status: 'pending',
        submittedAt: new Date(),
      }).returning();

      await db.update(documents).set({
        colorSubmissionStatus: 'pending_approval',
        updatedAt: new Date(),
      }).where(eq(documents.id, doc.id));

      if (doc.projectId) {
        await db.execute(sql`
          INSERT INTO project_activities (project_id, user_id, type, description, created_at)
          VALUES (${doc.projectId}, ${doc.userId}, 'client_submitted_colors', 'Client submitted paint color selections for review', NOW())
        `);
      }

      const [notification] = await db.insert(notifications).values({
        userId: doc.userId,
        documentId: doc.id,
        projectId: doc.projectId,
        type: 'color_submission',
        title: '🎨 Paint Colors Submitted',
        message: 'A client submitted their paint color selections for your review.',
        link: `/projects/${doc.projectId}?tab=colors`,
        metadata: { submissionId: submission.id },
      }).returning();

      sendPushToUser(doc.userId, {
        title: 'Paint Colors Submitted',
        body: 'A client submitted paint color selections for your review.',
        url: `/projects/${doc.projectId}?tab=colors`,
        tag: `color-submission-${doc.id}`,
      }).catch(err => console.error('[Push] Error sending color submission notification:', err));

      res.json(submission);
    } catch (error: any) {
      console.error("[ColorSubmission] Error:", error);
      res.status(500).json({ message: error.message });
    }
  });

