  app.patch("/api/documents/:id/color-settings", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const documentId = parseInt(req.params.id);
      const { allowClientColorSubmission, colorAreas } = req.body;

      const [doc] = await db.select().from(documents).where(
        and(eq(documents.id, documentId), eq(documents.userId, userId))
      );
      if (!doc) return res.status(404).json({ message: "Document not found" });

      const updateData: any = { updatedAt: new Date() };

      if (typeof allowClientColorSubmission === 'boolean') {
        updateData.allowClientColorSubmission = allowClientColorSubmission;
        updateData.colorSubmissionStatus = allowClientColorSubmission ? 'not_submitted' : 'not_requested';

        if (allowClientColorSubmission) {
          const content = (doc.content as any) || {};
          const hasPaintGroups = content.items?.some((item: any) =>
            item.surfaces?.some((s: any) => s.paintGroupKey)
          );
          if (!hasPaintGroups && !content.colorAreas) {
            updateData.content = {
              ...content,
              colorAreas: [
                { key: 'walls', label: 'Walls' },
                { key: 'trim', label: 'Trim' },
                { key: 'ceiling', label: 'Ceiling' },
              ],
            };
          }
        }
      }

      if (Array.isArray(colorAreas)) {
        const content = (doc.content as any) || {};
        updateData.content = { ...content, ...(updateData.content || {}), colorAreas };
      }

      await db.update(documents).set(updateData)
        .where(and(eq(documents.id, documentId), eq(documents.userId, userId)));

      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

