  app.get("/api/notifications", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const limit = parseInt(req.query.limit as string) || 50;

      const resolved = await resolveUserCapabilities(userId);

      if (resolved.isOwner) {
        const notifs = await db.select().from(notifications)
          .where(eq(notifications.userId, userId))
          .orderBy(desc(notifications.createdAt))
          .limit(limit);
        return res.json(notifs);
      }

      const ownNotifs = await db.select().from(notifications)
        .where(eq(notifications.userId, userId))
        .orderBy(desc(notifications.createdAt))
        .limit(limit);

      const ownerNotifs = await db.select().from(notifications)
        .where(eq(notifications.userId, resolved.ownerId))
        .orderBy(desc(notifications.createdAt))
        .limit(limit);

      const NOTIF_TYPE_TO_CAPABILITY: Record<string, string> = {
        document_signed: 'viewDocuments',
        color_submission: 'viewDocuments',
        booking_received: 'manageCalendar',
        thumbtack_lead: 'viewContacts',
        thumbtack_message: 'viewContacts',
        facebook_lead: 'viewContacts',
        team_message: 'viewTeamMessages',
        schedule_updated: 'viewAssignedJobs',
        appointment_reminder: 'viewAssignedJobs',
      };

      const OWNER_ONLY_TYPES = new Set(['gameplan_suggestion', 'trial_ending_reminder', 'thumbtack_debug']);

      const filteredOwnerNotifs = ownerNotifs.filter(n => {
        if (OWNER_ONLY_TYPES.has(n.type)) return false;
        const requiredCap = NOTIF_TYPE_TO_CAPABILITY[n.type];
        if (requiredCap && !resolved.capabilities[requiredCap]) return false;
        return true;
      });

      const seenIds = new Set(ownNotifs.map(n => n.id));
      const merged = [...ownNotifs, ...filteredOwnerNotifs.filter(n => !seenIds.has(n.id))];
      merged.sort((a, b) => new Date(b.createdAt!).getTime() - new Date(a.createdAt!).getTime());

      res.json(merged.slice(0, limit));
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/notifications/unread-count", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const resolved = await resolveUserCapabilities(userId);

      if (resolved.isOwner) {
        const result = await db.select({ count: count() }).from(notifications)
          .where(and(eq(notifications.userId, userId), isNull(notifications.readAt)));
        return res.json({ count: result[0]?.count || 0 });
      }

      const ownResult = await db.select({ count: count() }).from(notifications)
        .where(and(eq(notifications.userId, userId), isNull(notifications.readAt)));
      const ownCount = ownResult[0]?.count || 0;

      const ownerUnread = await db.select().from(notifications)
        .where(and(eq(notifications.userId, resolved.ownerId), isNull(notifications.readAt)));

      const NOTIF_TYPE_TO_CAPABILITY: Record<string, string> = {
        document_signed: 'viewDocuments',
        color_submission: 'viewDocuments',
        booking_received: 'manageCalendar',
        thumbtack_lead: 'viewContacts',
        thumbtack_message: 'viewContacts',
        facebook_lead: 'viewContacts',
        team_message: 'viewTeamMessages',
        schedule_updated: 'viewAssignedJobs',
        appointment_reminder: 'viewAssignedJobs',
      };
      const OWNER_ONLY_TYPES = new Set(['gameplan_suggestion', 'trial_ending_reminder', 'thumbtack_debug']);

      const filteredCount = ownerUnread.filter(n => {
        if (OWNER_ONLY_TYPES.has(n.type)) return false;
        const requiredCap = NOTIF_TYPE_TO_CAPABILITY[n.type];
        if (requiredCap && !resolved.capabilities[requiredCap]) return false;
        return true;
      }).length;

      res.json({ count: Number(ownCount) + filteredCount });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

