  app.patch("/api/admin/gameplan/queue/:id", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const item = await storage.updateGamePlanQueueItem(Number(req.params.id), req.body);
      if (!item) return res.status(404).json({ error: "Queue item not found" });
      if (req.body.status === 'approved') {
        await storage.updateGamePlanQueueItem(item.id, { reviewedAt: new Date() } as any);
        await storage.createGamePlanHistoryEntry({ entityType: 'queue', entityId: item.id, action: 'approved', summary: `Approved: ${item.title}` });
      } else if (req.body.status === 'rejected') {
        await storage.updateGamePlanQueueItem(item.id, { reviewedAt: new Date() } as any);
        await storage.createGamePlanHistoryEntry({ entityType: 'queue', entityId: item.id, action: 'rejected', summary: `Rejected: ${item.title}` });
      } else if (req.body.status === 'published') {
        if ((item as any).publishBlocked && !req.body.forcePublish) {
          const reasons = (item as any).publishBlockReasons || ['SEO score too low or issues detected'];
          return res.status(400).json({ error: 'Publish blocked', reasons, message: 'Run SEO check and fix issues before publishing. Use forcePublish: true to override.' });
        }
        const settings = await storage.getGamePlanSettings();
        let wpResult: any = null;
        if (settings?.wpBaseUrl && settings?.wpUsername && settings?.wpAppPassword) {
          const baseUrl = settings.wpBaseUrl.replace(/\/+$/, '');
          const authHeader = 'Basic ' + Buffer.from(`${settings.wpUsername}:${settings.wpAppPassword}`).toString('base64');
          const wpHeaders: Record<string, string> = { 'Authorization': authHeader, 'Content-Type': 'application/json' };

          const isPage = item.type === 'city_page' || item.type === 'website_page' || ['home_page', 'service_page', 'location_page', 'service_location_page'].includes((item as any).pageType || '');
          const endpoint = isPage ? `${baseUrl}/wp-json/wp/v2/pages` : `${baseUrl}/wp-json/wp/v2/posts`;
          const wpStatus = req.body.wpPublishAs || (settings.wpPublishMode === 'auto_publish' ? 'publish' : 'draft');

          let publishContent = item.generatedContent || '';
          const imgSlots = item.imageSlots as any;
          if (imgSlots) {
            if (imgSlots.mid?.url) {
              publishContent = publishContent.replace(
                /<!--\s*IMAGE:mid\s*-->/i,
                `<figure class="wp-block-image"><img src="${imgSlots.mid.url}" alt="${imgSlots.mid.alt || ''}" />${imgSlots.mid.caption ? `<figcaption>${imgSlots.mid.caption}</figcaption>` : ''}</figure>`
              );
            }
            if (imgSlots.supporting?.url) {
              publishContent = publishContent.replace(
                /<!--\s*IMAGE:supporting\s*-->/i,
                `<figure class="wp-block-image"><img src="${imgSlots.supporting.url}" alt="${imgSlots.supporting.alt || ''}" />${imgSlots.supporting.caption ? `<figcaption>${imgSlots.supporting.caption}</figcaption>` : ''}</figure>`
              );
            }
          }

          if (settings.reviewsWidgetCode) {
            publishContent = publishContent.replace(
              /<!--\s*REVIEWS_WIDGET\s*-->/gi,
              settings.reviewsWidgetCode
            );
          }

          const metaMatch = publishContent.match(/<!--\s*META_DESCRIPTION:\s*(.+?)\s*-->/);
          const metaDescription = metaMatch ? metaMatch[1].trim() : '';

          const wpContent = '<!-- wp:html -->\n' + publishContent + '\n<!-- /wp:html -->';

          const wpBody: any = {
            title: item.title,
            content: wpContent,
            status: wpStatus,
            excerpt: metaDescription || '',
            template: 'elementor_canvas',
          };

          if (isPage && item.targetCityId) {
            const city = await storage.getGamePlanTargetCity(item.targetCityId);
            if (city?.wpSlug) wpBody.slug = city.wpSlug;
            if (city?.market === 'NASSAU' && settings.wpNassauParentId) {
              wpBody.parent = settings.wpNassauParentId;
            } else if (city?.market === 'BROOKLYN' && settings.wpBrooklynParentId) {
              wpBody.parent = settings.wpBrooklynParentId;
            } else if (settings.wpLocationsParentId) {
              wpBody.parent = settings.wpLocationsParentId;
            }
          }

          if (item.wpFeaturedMediaId) {
            wpBody.featured_media = item.wpFeaturedMediaId;
          }

          const existingWpId = item.wpPostId;
          const method = existingWpId ? 'PUT' : 'POST';
          const finalEndpoint = existingWpId ? `${endpoint}/${existingWpId}` : endpoint;
          console.log(`[GamePlan Publish] ${method}ing to ${finalEndpoint} as ${wpStatus} (existing WP ID: ${existingWpId || 'none'})`);
          try {
            const wpResponse = await fetch(finalEndpoint, { method, headers: wpHeaders, body: JSON.stringify(wpBody) });
            const rawText = await wpResponse.text();
            console.log(`[GamePlan Publish] WP response status=${wpResponse.status} body=${rawText.substring(0, 500)}`);
            let wpJson: any;
            try { wpJson = JSON.parse(rawText); } catch { wpJson = rawText; }

            if (wpResponse.ok) {
              wpResult = {
                success: true,
                wpPostId: wpJson.id,
                wpStatus: wpJson.status,
                editLink: `${baseUrl}/wp-admin/post.php?post=${wpJson.id}&action=edit`,
                link: wpJson.link,
              };
              await storage.updateGamePlanQueueItem(item.id, { wpPostId: wpJson.id, publishedAt: new Date() } as any);

              // Update the city record if it's a city page
              if (isPage && item.targetCityId) {
                await storage.updateGamePlanTargetCity(item.targetCityId, {
                  wpPageId: wpJson.id,
                  wpPageUrl: wpJson.link,
                  pageStatus: wpStatus === 'publish' ? 'published' : 'generated',
                } as any);

                // Cross-link: queue updates for other published pages that reference this city
                try {
                  const publishedCity = await storage.getGamePlanTargetCity(item.targetCityId);
                  if (publishedCity) {
                    const newCityName = publishedCity.city;
                    const newCitySlug = publishedCity.wpSlug || `painter-${newCityName.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-')}-ny`;
                    const newCityUrl = wpJson.link || `/${newCitySlug}/`;
                    const crossLinkUpdates: Array<{ cityName: string; queueId: number }> = [];

                    // Find all other published queue items (city pages)
                    const allQueueItems = await storage.getGamePlanQueue();
                    const otherPublished = allQueueItems.filter(q =>
                      q.id !== item.id &&
                      q.type === 'city_page' &&
                      q.status === 'published' &&
                      q.generatedContent
                    );

                    for (const otherItem of otherPublished) {
                      try {
                        let content = otherItem.generatedContent || '';
                        if (!content) continue;

                        let updated = content;
                        let changed = false;

                        // Convert <span class="hood-badge">CityName</span> to <a> link
                        const spanPattern = new RegExp(
                          `<span\\s+class="hood-badge"\\s*>${newCityName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}</span>`,
                          'gi'
                        );
                        if (spanPattern.test(updated)) {
                          updated = updated.replace(spanPattern,
                            `<a href="/${newCitySlug}/" class="hood-badge" style="text-decoration:none;">${newCityName}</a>`
                          );
                          changed = true;
                        }

                        // Also fix any existing dead links to placeholder slugs
                        const deadLinkPattern = new RegExp(
                          `href="/${newCitySlug.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}/"`,
                          'g'
                        );
                        if (!changed && deadLinkPattern.test(updated)) {
                          changed = true;
                        }

                        if (changed) {
                          // Create a queue entry for the updated page instead of directly modifying WP
                          const otherCity = otherItem.targetCityId ? await storage.getGamePlanTargetCity(otherItem.targetCityId) : null;
                          const updateTitle = `${otherCity?.city || otherItem.title} — Link Update (added ${newCityName})`;

                          const newQueueItem = await storage.createGamePlanQueueItem({
                            type: 'city_page',
                            title: updateTitle,
                            slug: otherItem.slug,
                            targetCityId: otherItem.targetCityId,
                            generatedContent: updated,
                            previewHtml: updated,
                            status: 'draft',
                            wpPostId: otherItem.wpPostId,
                          } as any);

                          crossLinkUpdates.push({ cityName: otherCity?.city || 'Unknown', queueId: newQueueItem.id });
                          console.log(`[GamePlan CrossLink] Queued link update for ${otherCity?.city || otherItem.slug}: added ${newCityName} link (queue #${newQueueItem.id})`);
                        }
                      } catch (crossErr: any) {
                        console.error(`[GamePlan CrossLink] Error processing ${otherItem.slug}:`, crossErr.message);
                      }
                    }

                    // Also update the NEWLY published page itself — link to all already-published cities
                    try {
                      let newPageContent = item.generatedContent || '';
                      let newPageChanged = false;
                      for (const otherItem of otherPublished) {
                        if (!otherItem.targetCityId) continue;
                        const otherCity = await storage.getGamePlanTargetCity(otherItem.targetCityId);
                        if (!otherCity?.wpSlug) continue;
                        const otherCityName = otherCity.city;
                        const otherCitySlug = otherCity.wpSlug;

                        const otherSpanPattern = new RegExp(
                          `<span\\s+class="hood-badge"\\s*>${otherCityName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}</span>`,
                          'gi'
                        );
                        if (otherSpanPattern.test(newPageContent)) {
                          newPageContent = newPageContent.replace(otherSpanPattern,
                            `<a href="/${otherCitySlug}/" class="hood-badge" style="text-decoration:none;">${otherCityName}</a>`
                          );
                          newPageChanged = true;
                        }
                      }
                      if (newPageChanged) {
                        // Update the WP page with corrected links
                        const wpUpdateContent = '<!-- wp:html -->\n' + newPageContent + '\n<!-- /wp:html -->';
                        await fetch(`${endpoint}/${wpJson.id}`, {
                          method: 'POST', headers: wpHeaders,
                          body: JSON.stringify({ content: wpUpdateContent }),
                        });
                        // Also update the queue item's stored content
                        await storage.updateGamePlanQueueItem(item.id, {
                          generatedContent: newPageContent,
                          previewHtml: newPageContent,
                        } as any);
                        console.log(`[GamePlan CrossLink] Updated newly published ${newCityName} page with links to existing published cities`);
                      }
                    } catch (selfLinkErr: any) {
                      console.error(`[GamePlan CrossLink] Self-link error:`, selfLinkErr.message);
                    }

                    if (crossLinkUpdates.length > 0) {
                      await storage.createGamePlanHistoryEntry({
                        entityType: 'queue', entityId: item.id, action: 'cross_link_queued',
                        summary: `Cross-link updates queued for ${crossLinkUpdates.length} page(s): ${crossLinkUpdates.map(u => u.cityName).join(', ')}`,
                        metadata: { updates: crossLinkUpdates },
                      });
                    }
                  }
                } catch (crossLinkErr: any) {
                  console.error('[GamePlan CrossLink] Cross-link update error:', crossLinkErr.message);
                }
              }

              await storage.createGamePlanHistoryEntry({
                entityType: 'queue', entityId: item.id, action: 'published',
                summary: `Published to WP as ${wpStatus}: ${item.title} (WP ID: ${wpJson.id})`,
                metadata: wpResult,
              });
            } else {
              wpResult = { success: false, status: wpResponse.status, error: wpJson };
              console.error('[GamePlan Publish] WP error:', JSON.stringify(wpJson).substring(0, 500));
              await storage.updateGamePlanQueueItem(item.id, { publishedAt: new Date() } as any);
              await storage.createGamePlanHistoryEntry({
                entityType: 'queue', entityId: item.id, action: 'publish_failed',
                summary: `WP publish failed (${wpResponse.status}): ${item.title}`,
                metadata: wpResult,
              });
            }
          } catch (fetchErr: any) {
            console.error('[GamePlan Publish] Fetch error:', fetchErr.message);
            wpResult = { success: false, error: fetchErr.message };
            await storage.updateGamePlanQueueItem(item.id, { publishedAt: new Date() } as any);
            await storage.createGamePlanHistoryEntry({
              entityType: 'queue', entityId: item.id, action: 'publish_failed',
              summary: `WP publish fetch error: ${fetchErr.message}`,
              metadata: wpResult,
            });
          }
        } else {
          // No WP credentials - just mark as published locally
          await storage.updateGamePlanQueueItem(item.id, { publishedAt: new Date() } as any);
          await storage.createGamePlanHistoryEntry({ entityType: 'queue', entityId: item.id, action: 'published', summary: `Marked published (no WP credentials): ${item.title}` });
          wpResult = { success: false, error: 'WordPress credentials not configured' };
        }

        return res.json({ ...item, wpResult });
      }
      res.json(item);
    } catch (e: any) { res.status(500).json({ error: e.message }); }
  });

  app.post("/api/admin/gameplan/check-duplicates", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const { queueItemId } = req.body;
      if (!queueItemId) return res.status(400).json({ error: "queueItemId is required" });

      const item = await storage.getGamePlanQueueItem(queueItemId);
      if (!item) return res.status(404).json({ error: "Queue item not found" });
      if (item.type !== 'city_page') return res.json({ duplicates: [], passed: true });

      const content = item.generatedContent || '';
      if (!content) return res.json({ duplicates: [], passed: true });

      const extractSection = (html: string, pattern: RegExp): string => {
        const match = html.match(pattern);
        return match ? match[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase() : '';
      };

      const stripTags = (s: string) => s.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();

      const heroPattern = /class="gp-hero-text"[^>]*>([\s\S]*?)<\/div>/i;
      const ownerQuotePattern = /class="owner-quote"[^>]*>([\s\S]*?)<\/(?:blockquote|div)>/i;
      const localInsightPattern = /Local Homeowner Insight[\s\S]*?<p[^>]*>([\s\S]*?)<\/p>/i;
      const faqPattern = /"@type"\s*:\s*"FAQPage"[\s\S]*?"mainEntity"\s*:\s*(\[[\s\S]*?\])\s*\}/i;
      const metaPattern = /<!--\s*META_DESCRIPTION:\s*(.+?)\s*-->/i;

      const currentHero = extractSection(content, heroPattern);
      const currentOwnerQuote = extractSection(content, ownerQuotePattern);
      const currentInsight = extractSection(content, localInsightPattern);
      const currentMeta = (content.match(metaPattern)?.[1] || '').toLowerCase().trim();

      let currentFaqs: string[] = [];
      const faqMatch = content.match(faqPattern);
      if (faqMatch) {
        try {
          const parsed = JSON.parse(faqMatch[1]);
          currentFaqs = parsed.map((f: any) => stripTags(f.acceptedAnswer?.text || f.name || ''));
        } catch {}
      }

      const allQueueItems = await storage.getGamePlanQueue({ type: 'city_page' });
      const publishedItems = allQueueItems.filter(q =>
        q.id !== item.id &&
        q.type === 'city_page' &&
        (q.status === 'published' || q.status === 'approved') &&
        q.generatedContent
      );

      const jaccardSimilarity = (a: string, b: string): number => {
        if (!a || !b) return 0;
        const wordsA = new Set(a.split(/\s+/).filter(w => w.length > 3));
        const wordsB = new Set(b.split(/\s+/).filter(w => w.length > 3));
        if (wordsA.size === 0 || wordsB.size === 0) return 0;
        let intersection = 0;
        for (const w of wordsA) if (wordsB.has(w)) intersection++;
        return intersection / (wordsA.size + wordsB.size - intersection);
      };

      const warnings: Array<{ section: string; similarTo: string; similarity: number }> = [];
      const THRESHOLD = 0.6;

      for (const other of publishedItems) {
        const otherContent = other.generatedContent || '';
        const otherCity = other.city || other.title;

        const otherHero = extractSection(otherContent, heroPattern);
        const heroSim = jaccardSimilarity(currentHero, otherHero);
        if (heroSim > THRESHOLD) warnings.push({ section: 'Hero intro', similarTo: otherCity, similarity: Math.round(heroSim * 100) });

        const otherOwnerQuote = extractSection(otherContent, ownerQuotePattern);
        const quoteSim = jaccardSimilarity(currentOwnerQuote, otherOwnerQuote);
        if (quoteSim > THRESHOLD) warnings.push({ section: 'Meet the Owner quote', similarTo: otherCity, similarity: Math.round(quoteSim * 100) });

        const otherInsight = extractSection(otherContent, localInsightPattern);
        const insightSim = jaccardSimilarity(currentInsight, otherInsight);
        if (insightSim > THRESHOLD) warnings.push({ section: 'Local homeowner insight', similarTo: otherCity, similarity: Math.round(insightSim * 100) });

        const otherMeta = (otherContent.match(metaPattern)?.[1] || '').toLowerCase().trim();
        const metaSim = jaccardSimilarity(currentMeta, otherMeta);
        if (metaSim > THRESHOLD) warnings.push({ section: 'Meta description', similarTo: otherCity, similarity: Math.round(metaSim * 100) });

        const otherFaqMatch = otherContent.match(faqPattern);
        if (otherFaqMatch && currentFaqs.length > 0) {
          try {
            const otherParsed = JSON.parse(otherFaqMatch[1]);
            const otherFaqs = otherParsed.map((f: any) => stripTags(f.acceptedAnswer?.text || f.name || ''));
            for (let i = 0; i < currentFaqs.length; i++) {
              for (let j = 0; j < otherFaqs.length; j++) {
                const faqSim = jaccardSimilarity(currentFaqs[i], otherFaqs[j]);
                if (faqSim > THRESHOLD) {
                  warnings.push({ section: `FAQ #${i + 1}`, similarTo: otherCity, similarity: Math.round(faqSim * 100) });
                }
              }
            }
          } catch {}
        }
      }

      res.json({
        duplicates: warnings,
        passed: warnings.length === 0,
        checkedAgainst: publishedItems.length,
      });
    } catch (e: any) {
      console.error("[GamePlan] Duplicate check error:", e);
      res.status(500).json({ error: e.message });
    }
  });

