  app.post("/api/admin/gameplan/city-projects/:cityId/generate-section", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const cityId = Number(req.params.cityId);
      const city = await storage.getGamePlanTargetCity(cityId);
      if (!city) return res.status(404).json({ error: "City not found" });

      const projects = await storage.getGamePlanCityProjects(cityId);
      if (projects.length === 0) return res.status(400).json({ error: "No completed projects for this city" });

      const displayProjects = projects.slice(0, 6);

      const projectEntries = displayProjects.map((p, idx) => {
        const imgs = (p.projectImages || []).slice(0, 6);
        const baImgs = (p.beforeAfterImages || []) as Array<{ before: string; after: string; label?: string }>;
        return `
PROJECT ${idx + 1}:
Title: ${p.projectTitle}
City: ${p.projectCity}
${p.completionDate ? `Completed: ${p.completionDate}` : ''}
${p.propertyType ? `Property: ${p.propertyType}` : ''}
${p.roomsOrAreas ? `Rooms/Areas: ${p.roomsOrAreas}` : ''}
Summary: ${p.projectSummary || ''}
Scope: ${(p.scopeOfWork || []).join(', ')}
${(p.productsUsed || []).length > 0 ? `Products: ${p.productsUsed!.join(', ')}` : ''}
${p.projectTimeline ? `Timeline: ${p.projectTimeline}` : ''}
Result: ${p.projectResult || ''}
${p.testimonial ? `Testimonial: "${p.testimonial}"` : ''}
Images: ${imgs.length > 0 ? imgs.map((img, i) => `Image ${i + 1}: ${img}`).join('\n') : 'None'}
${baImgs.length > 0 ? `Before/After: ${baImgs.map((ba, i) => `Pair ${i + 1}: Before=${ba.before} After=${ba.after}${ba.label ? ` (${ba.label})` : ''}`).join('\n')}` : ''}`;
      }).join('\n---\n');

      const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
      const prompt = `You are an expert SEO copywriter for a premium interior painting company. Generate a "Recent Projects" HTML section for a location page.

Company: Gama Interior Painting
City: ${city.city}, ${city.state}
Phone: (888) 971-6033
Contact: https://gamainteriorpainting.com/contact-us/

COMPLETED PROJECTS DATA:
${projectEntries}

Generate an HTML section using our design system classes. The section should:

1. Section wrapper: <section class="recent-projects-section">
2. Title: <h2 class="section-title">Recent Interior Painting & Repair Projects in ${city.city}</h2>
   <div class="red-divider"></div>
3. For each project, create a <div class="project-entry card" style="margin-bottom:30px;padding:24px;">:
   - <h3> with the project title
   - <p class="project-meta"> with completion date and property type if available
   - <p> with the summary (expand it slightly for SEO — mention ${city.city} and services naturally)
   - Scope of work as <ul class="scope-list"> with <li> items
   - If images exist: <div class="gallery-grid"> with <img class="gallery-img" src="..." alt="..."> (alt text MUST include ${city.city} + room + service)
   - If before/after images exist: <div class="before-after-grid"> with labeled before/after pairs
   - If products used: <p class="products-used"> mentioning them naturally
   - If timeline: <p> mentioning the timeline
   - Result paragraph with <p class="project-result">
   - If testimonial exists: <blockquote class="project-testimonial"> with the quote and "— Homeowner in ${city.city}"

SEO RULES:
- Mention ${city.city} naturally 1-2 times per project entry
- Reference services performed (interior painting, drywall repair, cabinet painting, skim coating, etc.)
- Use descriptive alt text on all images
- Keep content natural — not keyword-stuffed
- Newest projects appear first (they are already sorted)

Show most recent ${displayProjects.length} project(s). Order: newest first.

Return ONLY the <section> HTML. No wrapper divs, no <style> tags, no explanation.`;

      const response = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [{ role: "user", content: prompt }],
        temperature: 0.7,
        max_tokens: 4000,
      });

      const generatedHtml = response.choices[0]?.message?.content || '';
      res.json({ html: generatedHtml, projectCount: displayProjects.length });
    } catch (e: any) {
      console.error("[GamePlan] City project section generation error:", e);
      res.status(500).json({ error: e.message });
    }
  });

  app.post("/api/admin/gameplan/city-projects/:cityId/append-to-page", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const cityId = Number(req.params.cityId);
      const { projectSectionHtml } = req.body;
      if (!projectSectionHtml) return res.status(400).json({ error: "projectSectionHtml is required" });

      const city = await storage.getGamePlanTargetCity(cityId);
      if (!city) return res.status(404).json({ error: "City not found" });

      const allQueue = await storage.getGamePlanQueue({ type: 'city_page' });
      const publishedItem = allQueue.find(q =>
        q.targetCityId === cityId &&
        q.status === 'published' &&
        q.wpPostId
      );

      if (!publishedItem) {
        return res.status(400).json({ error: "No published page found for this city. Generate a location page first." });
      }

      let pageContent = publishedItem.generatedContent || '';

      const existingProjectsMatch = pageContent.match(/<section class="recent-projects-section">[\s\S]*?<\/section>/);
      if (existingProjectsMatch) {
        pageContent = pageContent.replace(existingProjectsMatch[0], projectSectionHtml);
      } else {
        const contactBarMatch = pageContent.match(/<div class="contact-bar">/);
        const locBannerMatch = pageContent.match(/<div class="locations-banner">/);
        const trustFooterMatch = pageContent.match(/<div[^>]*>[\s\S]*?Why Homeowners Trust Gama/);

        let insertBefore = contactBarMatch || locBannerMatch || trustFooterMatch;
        if (insertBefore && insertBefore.index !== undefined) {
          pageContent = pageContent.slice(0, insertBefore.index) +
            '\n' + projectSectionHtml + '\n\n' +
            pageContent.slice(insertBefore.index);
        } else {
          pageContent += '\n' + projectSectionHtml;
        }
      }

      await storage.updateGamePlanQueueItem(publishedItem.id, {
        generatedContent: pageContent,
        previewHtml: pageContent,
      } as any);

      const settings = await storage.getGamePlanSettings();
      const wpBase = (settings as any)?.wpBaseUrl;
      const wpUser = (settings as any)?.wpUsername;
      const wpPass = (settings as any)?.wpAppPassword;

      let wpUpdated = false;
      if (wpBase && wpUser && wpPass && publishedItem.wpPostId) {
        try {
          const wpContent = `<!-- wp:html -->\n${pageContent}\n<!-- /wp:html -->`;
          const wpResp = await fetch(`${wpBase}/wp-json/wp/v2/pages/${publishedItem.wpPostId}`, {
            method: 'PUT',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Basic ' + Buffer.from(`${wpUser}:${wpPass}`).toString('base64'),
            },
            body: JSON.stringify({ content: wpContent }),
          });
          wpUpdated = wpResp.ok;
        } catch (e) {
          console.error("[GamePlan] WP page update failed:", e);
        }
      }

      const projects = await storage.getGamePlanCityProjects(cityId);
      const renderedProjects = projects.slice(0, 6);
      for (const p of renderedProjects) {
        await storage.updateGamePlanCityProject(p.id, { publishedToPage: true } as any);
      }

      await storage.createGamePlanHistoryEntry({
        entityType: 'city_project',
        entityId: cityId,
        action: 'appended_to_page',
        summary: `Updated ${city.city} location page with ${renderedProjects.length} completed project(s)${wpUpdated ? ' — WordPress updated' : ''}`,
      });

      res.json({
        success: true,
        wpUpdated,
        queueItemId: publishedItem.id,
        message: wpUpdated
          ? `Projects appended and WordPress page updated for ${city.city}`
          : `Projects appended to queue content for ${city.city}. Republish to update WordPress.`,
      });
    } catch (e: any) {
      console.error("[GamePlan] Append to page error:", e);
      res.status(500).json({ error: e.message });
    }
  });

  app.post("/api/admin/gameplan/automation/trigger", isAuthenticated, async (req, res) => {
    try {
      const { trigger, projectId, contactName, city, serviceTypes, imageUrl } = req.body;
      if (!trigger || !['estimate_created', 'project_started', 'project_completed'].includes(trigger)) {
        return res.status(400).json({ error: "Invalid trigger type" });
      }

      const settings = await storage.getGamePlanSettings();
      if (!settings) return res.status(400).json({ error: "GamePlan not configured" });

      const triggerEnabled =
        (trigger === 'estimate_created' && settings.autoTriggerEstimate) ||
        (trigger === 'project_started' && settings.autoTriggerProjectStarted) ||
        (trigger === 'project_completed' && settings.autoTriggerProjectCompleted);

      if (!triggerEnabled) {
        return res.json({ skipped: true, reason: `Automation trigger '${trigger}' is not enabled` });
      }

      const triggerLabels: Record<string, string> = {
        estimate_created: 'New Estimate',
        project_started: 'Project Started',
        project_completed: 'Project Completed',
      };

      const services = serviceTypes?.join(', ') || 'Interior Painting';
      const cityName = city || 'your area';
      const customerName = contactName || '';

      let postType = 'automation_post';
      let title = '';
      let aiPrompt = '';

      if (trigger === 'estimate_created') {
        title = `We're in ${cityName}! Free Estimates Available`;
        aiPrompt = `Write a short, engaging social media post for "Gama Interior Painting" announcing they're providing a ${services} estimate in ${cityName}, NY. Mention they're available for free estimates in the neighborhood. Keep it under 200 words. Professional but approachable tone.`;
      } else if (trigger === 'project_started') {
        title = `New ${services} Project Underway in ${cityName}`;
        aiPrompt = `Write a short, engaging social media post for "Gama Interior Painting" announcing they've just started a new ${services} project in ${cityName}, NY. Build excitement about the transformation. Keep it under 200 words. Professional but approachable tone.`;
      } else if (trigger === 'project_completed') {
        title = `${services} Transformation Complete in ${cityName}!`;
        aiPrompt = `Write a short, engaging social media post for "Gama Interior Painting" showcasing a recently completed ${services} project in ${cityName}, NY. Highlight the quality of work and customer satisfaction. Include a call to action for free estimates. Keep it under 200 words. Professional but approachable tone.`;
      }

      if (settings.brandVoiceNotes) {
        aiPrompt += `\nBrand Voice: ${settings.brandVoiceNotes}`;
      }
      if (settings.defaultCta) {
        aiPrompt += `\nCTA: ${settings.defaultCta}`;
      }

      let generatedContent = '';
      let socialCaptions: any = {};

      try {
        const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
        const contentResponse = await openai.chat.completions.create({
          model: "gpt-4o-mini",
          messages: [{ role: "user", content: aiPrompt }],
          temperature: 0.7,
          max_tokens: 500,
        });
        generatedContent = contentResponse.choices[0]?.message?.content || '';

        const socialPrompt = `Based on this content by Gama Interior Painting, generate platform-specific social media captions:

${generatedContent}

Return a JSON object with exactly these keys:
- "gbp": Google Business Profile post (150-250 chars). Short, local SEO focused. Include city name and service type. No hashtags.
- "facebook": Facebook post (200-400 chars). Engaging hook. Conversational but professional. 2-3 hashtags at end.
- "instagram": Instagram caption (200-500 chars). Visual-focused. End with 8-12 hashtags.

Return ONLY valid JSON, no markdown.`;

        const socialResponse = await openai.chat.completions.create({
          model: "gpt-4o-mini",
          messages: [{ role: "user", content: socialPrompt }],
          temperature: 0.7,
          max_tokens: 800,
        });
        try {
          const raw = socialResponse.choices[0]?.message?.content || '{}';
          socialCaptions = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, ''));
        } catch { socialCaptions = {}; }
      } catch (aiErr: any) {
        console.error('[GamePlan Automation] AI generation failed:', aiErr.message);
        generatedContent = `<p>${title}</p>`;
      }

      const automationUserId = await getEffectiveUserId(req);
      const queueItem = await storage.createGamePlanQueueItem({
        userId: automationUserId,
        type: postType,
        projectId: projectId || null,
        city: cityName,
        title,
        generatedContent,
        previewHtml: generatedContent,
        primaryImageUrl: imageUrl || null,
        socialCaptions,
        status: 'draft',
        automationTrigger: trigger,
      });

      await storage.createGamePlanHistoryEntry({
        entityType: 'automation',
        entityId: queueItem.id,
        action: 'triggered',
        summary: `${triggerLabels[trigger]}: ${title}`,
      });

      if (trigger === 'project_completed' && cityName && cityName !== 'your area') {
        try {
          const allCities = await storage.getGamePlanTargetCities();
          const normalizedCity = cityName.trim().toLowerCase();
          const matchedCity = allCities.find(c =>
            c.city.trim().toLowerCase() === normalizedCity ||
            (c.zipCodes || []).some(z => z.trim() === (req.body.zipCode || '').trim())
          );
          if (matchedCity) {
            if (matchedCity.pageStatus === 'not_created') {
              await db.insert(notifications).values({
                userId: automationUserId,
                type: 'gameplan_suggestion',
                title: 'Service Area Page Opportunity',
                message: `Project completed in ${cityName} — create a service area page to boost local SEO for this area.`,
                link: '/gameplan?tab=service_areas',
                projectId: projectId || null,
              });
            } else {
              const queueItems = await storage.getGamePlanQueue({ type: 'city_page' });
              const publishedForCity = queueItems.filter(q => q.targetCityId === matchedCity.id && q.status === 'published' && q.publishedAt);
              const lastPub = matchedCity.lastPublishedAt || (publishedForCity.length > 0
                ? publishedForCity.sort((a, b) => new Date(b.publishedAt!).getTime() - new Date(a.publishedAt!).getTime())[0]?.publishedAt
                : null);
              if (lastPub) {
                const daysSince = Math.floor((Date.now() - new Date(lastPub).getTime()) / (1000 * 60 * 60 * 24));
                if (daysSince >= 21) {
                  await db.insert(notifications).values({
                    userId: automationUserId,
                    type: 'gameplan_suggestion',
                    title: 'Update Service Area Page',
                    message: `New project completed in ${cityName} — your service area page is ${daysSince} days old. Add this project to keep it fresh.`,
                    link: '/gameplan?tab=service_areas',
                    projectId: projectId || null,
                  });
                }
              }
            }
          } else {
            await db.insert(notifications).values({
              userId: automationUserId,
              type: 'gameplan_suggestion',
              title: 'New Service Area Detected',
              message: `Project completed in ${cityName} — this city isn't in your target areas yet. Add it to start building local SEO.`,
              link: '/gameplan?tab=cities',
              projectId: projectId || null,
            });
          }
        } catch (notifErr) {
          console.error('[GamePlan] Notification creation error:', notifErr);
        }
      }

      console.log(`[GamePlan Automation] ${trigger} triggered for project ${projectId}, queue item ${queueItem.id}`);
      res.json({ success: true, queueItem });
    } catch (e: any) {
      console.error("[GamePlan Automation] Trigger error:", e);
      res.status(500).json({ error: e.message });
    }
  });

  const thumbnailUpload = multer({
    storage: multer.diskStorage({
      destination: (_req, _file, cb) => cb(null, 'client/public/thumbnails'),
      filename: (_req, file, cb) => {
        const slug = _req.body.slug || file.originalname.replace(/\.[^.]+$/, '').replace(/[^a-z0-9-]/gi, '-').toLowerCase();
        const ext = file.originalname.match(/\.[^.]+$/)?.[0] || '.png';
        cb(null, `${slug}${ext}`);
      },
    }),
    limits: { fileSize: 5 * 1024 * 1024 },
    fileFilter: (_req: any, file: any, cb: any) => {
      if (/^image\/(jpeg|png|webp|jpg)$/.test(file.mimetype)) cb(null, true);
      else cb(new Error('Only image files allowed'));
    },
  });

