  app.get("/api/admin/gameplan/wp-pages", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const settings = await storage.getGamePlanSettings();
      if (!settings?.wpBaseUrl || !settings?.wpUsername || !settings?.wpAppPassword) {
        return res.status(400).json({ error: "WordPress credentials not configured. Go to Settings tab to add them." });
      }
      const baseUrl = settings.wpBaseUrl.replace(/\/+$/, '');
      const authHeader = 'Basic ' + Buffer.from(`${settings.wpUsername}:${settings.wpAppPassword}`).toString('base64');
      const perPage = 100;
      let page = 1;
      let allPages: any[] = [];
      let hasMore = true;
      while (hasMore) {
        const wpRes = await fetch(`${baseUrl}/wp-json/wp/v2/pages?per_page=${perPage}&page=${page}&_fields=id,title,slug,link,status,modified,excerpt`, {
          headers: { 'Authorization': authHeader },
        });
        if (!wpRes.ok) {
          const errText = await wpRes.text();
          return res.status(wpRes.status).json({ error: `WordPress API error: ${errText.substring(0, 200)}` });
        }
        const pages = await wpRes.json();
        allPages = allPages.concat(pages);
        const totalPages = parseInt(wpRes.headers.get('x-wp-totalpages') || '1');
        hasMore = page < totalPages;
        page++;
      }
      res.json({ pages: allPages.map((p: any) => ({ id: p.id, title: p.title?.rendered || '', slug: p.slug, link: p.link, status: p.status, modified: p.modified, excerpt: p.excerpt?.rendered || '' })) });
    } catch (e: any) {
      console.error("[GamePlan] WP pages fetch error:", e);
      res.status(500).json({ error: e.message });
    }
  });

  app.get("/api/admin/gameplan/site-overview", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const settings = await storage.getGamePlanSettings();
      if (!settings?.wpBaseUrl || !settings?.wpUsername || !settings?.wpAppPassword) {
        return res.json({ synced: false, pages: [], stats: {} });
      }
      const baseUrl = settings.wpBaseUrl.replace(/\/+$/, '');
      const authHeader = 'Basic ' + Buffer.from(`${settings.wpUsername}:${settings.wpAppPassword}`).toString('base64');
      let page = 1;
      let allPages: any[] = [];
      let hasMore = true;
      while (hasMore) {
        const wpRes = await fetch(`${baseUrl}/wp-json/wp/v2/pages?per_page=100&page=${page}&_fields=id,title,slug,link,status,modified,excerpt`, {
          headers: { 'Authorization': authHeader },
          signal: AbortSignal.timeout(15000),
        });
        if (!wpRes.ok) {
          return res.status(wpRes.status).json({ error: `WordPress API error (${wpRes.status})` });
        }
        const pages = await wpRes.json();
        allPages = allPages.concat(pages);
        const totalPages = parseInt(wpRes.headers.get('x-wp-totalpages') || '1');
        hasMore = page < totalPages;
        page++;
      }

      let allPosts: any[] = [];
      try {
        let postPage = 1;
        let hasMorePosts = true;
        while (hasMorePosts) {
          const wpRes = await fetch(`${baseUrl}/wp-json/wp/v2/posts?per_page=100&page=${postPage}&_fields=id,title,slug,link,status,modified,excerpt`, {
            headers: { 'Authorization': authHeader },
            signal: AbortSignal.timeout(15000),
          });
          if (wpRes.ok) {
            const posts = await wpRes.json();
            allPosts = allPosts.concat(posts);
            const totalPages = parseInt(wpRes.headers.get('x-wp-totalpages') || '1');
            hasMorePosts = postPage < totalPages;
            postPage++;
          } else {
            hasMorePosts = false;
          }
        }
      } catch {}

      const queue = await storage.getGamePlanQueue();
      const queueByWpId = new Map<number, any>();
      const queueBySlug = new Map<string, any>();
      for (const q of queue) {
        if (q.wpPostId) queueByWpId.set(q.wpPostId, q);
        if (q.slug) queueBySlug.set(q.slug.toLowerCase(), q);
      }

      const categorize = (slug: string, title: string) => {
        const s = slug.toLowerCase();
        const t = title.toLowerCase();
        if (s.includes('paint') || s.includes('interior') || t.includes('painting') || t.includes('interior')) {
          if (s.includes('service') || t.includes('service')) return 'service';
          return 'location';
        }
        if (s.includes('blog') || s.includes('news') || s.includes('article')) return 'blog';
        if (s === '' || s === 'home' || t.includes('home')) return 'service';
        return 'other';
      };

      const enrichPage = (p: any, type: 'page' | 'post') => {
        const title = p.title?.rendered || p.title || '';
        const slug = p.slug || '';
        const matched = queueByWpId.get(p.id) || queueBySlug.get(slug.toLowerCase());
        return {
          wpId: p.id,
          title,
          slug,
          link: p.link || '',
          wpStatus: p.status,
          modified: p.modified,
          excerpt: (p.excerpt?.rendered || '').replace(/<[^>]*>/g, '').trim().substring(0, 150),
          category: type === 'post' ? 'blog' : categorize(slug, title),
          wpType: type,
          inQueue: !!matched,
          queueId: matched?.id || null,
          queueStatus: matched?.status || null,
          seoScore: matched?.seoScore || null,
          seoWarnings: matched?.seoWarnings || [],
        };
      };

      const enrichedPages = allPages.map(p => enrichPage(p, 'page'));
      const enrichedPosts = allPosts.map(p => enrichPage(p, 'post'));
      const allEnriched = [...enrichedPages, ...enrichedPosts];

      const locationPages = allEnriched.filter(p => p.category === 'location');
      const servicePages = allEnriched.filter(p => p.category === 'service');
      const blogPages = allEnriched.filter(p => p.category === 'blog');
      const otherPages = allEnriched.filter(p => p.category === 'other');

      const scoredItems = queue.filter(q => q.seoScore !== null && q.seoScore !== undefined);
      const avgSeoScore = scoredItems.length > 0 ? Math.round(scoredItems.reduce((sum, q) => sum + (q.seoScore || 0), 0) / scoredItems.length) : null;

      res.json({
        synced: true,
        pages: allEnriched,
        groups: {
          location: locationPages,
          service: servicePages,
          blog: blogPages,
          other: otherPages,
        },
        stats: {
          totalPages: allEnriched.length,
          locationCount: locationPages.length,
          serviceCount: servicePages.length,
          blogCount: blogPages.length,
          otherCount: otherPages.length,
          inQueueCount: allEnriched.filter(p => p.inQueue).length,
          avgSeoScore,
          scoredCount: scoredItems.length,
        },
      });
    } catch (e: any) {
      console.error("[GamePlan] Site overview error:", e);
      res.status(500).json({ error: e.message });
    }
  });

