  app.post("/api/admin/gameplan/queue/:id/ai-edit", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const { instructions } = req.body;
      if (!instructions) return res.status(400).json({ error: "Edit instructions are required" });

      const item = await storage.getGamePlanQueueItem(id);
      if (!item) return res.status(404).json({ error: "Queue item not found" });

      const currentContent = item.generatedContent || item.previewHtml || '';
      if (!currentContent) return res.status(400).json({ error: "No content to edit" });

      const userId = await getEffectiveUserId(req);
      const companyInfo = await storage.getCompanySettings(userId);
      const brandColor = companyInfo?.brandColor || '#e4181d';
      const companyName = companyInfo?.companyName || 'Our Company';

      const gpSettings = await storage.getGamePlanSettings();
      const dynamicRules = getDesignSystemRules((gpSettings as any)?.serviceThumbnails);

      const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

      const contentLength = currentContent.length;
      const useTargetedEdit = contentLength > 15000;

      let response;
      if (useTargetedEdit) {
        response = await openai.chat.completions.create({
          model: "gpt-4o-mini",
          messages: [
            {
              role: "system",
              content: `You are an expert web designer editing a website page for "${companyName}". Brand color: ${brandColor}. The page HTML is very large, so instead of returning the full page, return ONLY a JSON array of find-and-replace operations. Each operation should be: {"find": "exact string to find", "replace": "replacement string"}. Be precise with the find strings — use enough context to be unique. Return valid JSON only, no markdown.\n\n${dynamicRules}`
            },
            {
              role: "user",
              content: `Here is the current page HTML:\n\n${currentContent}\n\n---\n\nEdit instructions: ${instructions}\n\nReturn a JSON array of find-and-replace operations to apply these edits.`
            }
          ],
          temperature: 0.3,
          max_tokens: 4000,
        });

        let opsText = response.choices[0]?.message?.content || '[]';
        opsText = opsText.replace(/^```json\n?/, '').replace(/^```\n?/, '').replace(/\n?```$/, '');
        try {
          const ops = JSON.parse(opsText);
          let result = currentContent;
          for (const op of ops) {
            if (op.find && op.replace !== undefined) {
              result = result.replace(op.find, op.replace);
            }
          }
          response = { choices: [{ message: { content: result } }] } as any;
        } catch (parseErr) {
          console.error('[AI Edit] Failed to parse targeted edit ops, falling back to full edit');
          response = await openai.chat.completions.create({
            model: "gpt-4o-mini",
            messages: [
              {
                role: "system",
                content: `You are an expert web designer editing an existing website page for "${companyName}". The brand color is ${brandColor}. You must preserve ALL existing CSS classes and HTML structure. Only modify the content as instructed. Return the COMPLETE updated HTML — do not return partial snippets. Keep all <style> tags exactly as they are. Do not add new <style> tags.\n\nYou MUST follow these design system rules when making any edits:\n${dynamicRules}`
              },
              {
                role: "user",
                content: `Here is the current page HTML:\n\n${currentContent}\n\n---\n\nEdit instructions: ${instructions}\n\nReturn the COMPLETE updated page HTML with your edits applied. Keep all existing structure and styling. Only change what was requested.`
              }
            ],
            temperature: 0.5,
            max_tokens: 16384,
          });
        }
      } else {
        response = await openai.chat.completions.create({
          model: "gpt-4o-mini",
          messages: [
            {
              role: "system",
              content: `You are an expert web designer editing an existing website page for "${companyName}". The brand color is ${brandColor}. You must preserve ALL existing CSS classes and HTML structure. Only modify the content as instructed. Return the COMPLETE updated HTML — do not return partial snippets. Keep all <style> tags exactly as they are. Do not add new <style> tags.\n\nYou MUST follow these design system rules when making any edits:\n${dynamicRules}`
            },
            {
              role: "user",
              content: `Here is the current page HTML:\n\n${currentContent}\n\n---\n\nEdit instructions: ${instructions}\n\nReturn the COMPLETE updated page HTML with your edits applied. Keep all existing structure and styling. Only change what was requested.`
            }
          ],
          temperature: 0.5,
          max_tokens: 16384,
        });
      }

      let updatedContent = response.choices[0]?.message?.content || '';
      if (updatedContent.startsWith('```html')) {
        updatedContent = updatedContent.replace(/^```html\n?/, '').replace(/\n?```$/, '');
      }
      if (updatedContent.startsWith('```')) {
        updatedContent = updatedContent.replace(/^```\n?/, '').replace(/\n?```$/, '');
      }

      const previousContent = item.generatedContent;
      await storage.updateGamePlanQueueItem(id, {
        generatedContent: updatedContent,
        previewHtml: updatedContent,
        previousContent,
      } as any);

      await storage.createGamePlanHistoryEntry({
        entityType: (item as any).pageType || item.type,
        entityId: id,
        action: 'ai_edited',
        summary: `AI edit: ${instructions.substring(0, 100)}`,
      });

      res.json({ success: true, content: updatedContent });
    } catch (e: any) {
      console.error("[GamePlan] AI edit error:", e);
      res.status(500).json({ error: e.message });
    }
  });

