  // === Publish to GBP (standalone) ===
  app.post("/api/admin/gameplan/queue/:id/publish-gbp", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const item = await storage.getGamePlanQueueItem(Number(req.params.id));
      if (!item) return res.status(404).json({ error: "Queue item not found" });

      const settings = await storage.getGamePlanSettings();
      const accessToken = await refreshGbpToken(settings);
      if (!accessToken) {
        return res.status(400).json({ error: "GBP not connected. Complete OAuth first." });
      }

      // Route to the correct location based on market
      const market = ((item as any).market || '').toLowerCase();
      let locationName = '';
      let locationLabel = '';
      if (market.includes('nassau')) {
        locationName = (settings as any)?.gbpLocationIdNassau || settings?.gbpLocationId || '';
        locationLabel = 'Nassau';
      } else if (market.includes('brooklyn')) {
        locationName = (settings as any)?.gbpLocationIdBrooklyn || settings?.gbpLocationId || '';
        locationLabel = 'Brooklyn';
      } else {
        // Fallback to Nassau or old single location
        locationName = (settings as any)?.gbpLocationIdNassau || settings?.gbpLocationId || '';
        locationLabel = 'Default';
      }

      if (!locationName) {
        return res.status(400).json({ error: `No GBP location configured for market: ${market || 'unknown'}` });
      }

      const caption = (item.socialCaptions as any)?.gbp || item.title;
      // Use the new Business Profile API v1 format
      const postUrl = `https://mybusiness.googleapis.com/v4/${locationName.includes('/') ? locationName : `accounts/${settings?.gbpAccountId}/locations/${locationName}`}/localPosts`;

      const postData: any = {
        languageCode: 'en-US',
        summary: caption,
        topicType: 'STANDARD',
      };

      if (item.primaryImageUrl) {
        postData.media = [{ mediaFormat: 'PHOTO', sourceUrl: item.primaryImageUrl }];
      }

      const callToActionUrl = item.type === 'city_page' && item.wpPostId
        ? `${settings.wpBaseUrl?.replace(/\/+$/, '')}/?p=${item.wpPostId}`
        : settings.wpBaseUrl || undefined;
      if (callToActionUrl) {
        postData.callToAction = { actionType: 'LEARN_MORE', url: callToActionUrl };
      }

      console.log(`[GamePlan GBP Publish] POSTing to GBP (${locationLabel}) for item ${item.id}: ${item.title}`);
      const gbpResponse = await fetch(postUrl, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(postData),
      });
      const rawText = await gbpResponse.text();
      console.log(`[GamePlan GBP Publish] status=${gbpResponse.status} body=${rawText.substring(0, 500)}`);
      let gbpBody: any;
      try { gbpBody = JSON.parse(rawText); } catch { gbpBody = rawText; }

      if (gbpResponse.ok) {
        const result = { success: true, postName: gbpBody.name, state: gbpBody.state, searchUrl: gbpBody.searchUrl, location: locationLabel };
        await storage.createGamePlanHistoryEntry({ entityType: 'queue', entityId: item.id, action: 'published_gbp', summary: `Published to GBP (${locationLabel}): ${item.title}`, metadata: result });
        res.json(result);
      } else {
        const result = { success: false, status: gbpResponse.status, error: gbpBody };
        await storage.createGamePlanHistoryEntry({ entityType: 'queue', entityId: item.id, action: 'gbp_publish_failed', summary: `GBP publish failed (${gbpResponse.status}): ${item.title}`, metadata: result });
        res.status(gbpResponse.status >= 500 ? 502 : 400).json(result);
      }
    } catch (e: any) {
      console.error('[GamePlan GBP Publish] Error:', e);
      res.status(500).json({ error: e.message });
    }
  });

  // === Publish to Facebook ===
  app.post("/api/admin/gameplan/queue/:id/publish-facebook", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const item = await storage.getGamePlanQueueItem(Number(req.params.id));
      if (!item) return res.status(404).json({ error: "Queue item not found" });

      const settings = await storage.getGamePlanSettings();
      if (!settings?.metaAccessToken || !settings?.metaPageId) {
        return res.status(400).json({ error: "Facebook credentials not configured" });
      }

      const caption = (item.socialCaptions as any)?.facebook || item.title;
      const link = item.wpPostId && settings.wpBaseUrl ? `${settings.wpBaseUrl.replace(/\/+$/, '')}/?p=${item.wpPostId}` : undefined;

      const fbUrl = `https://graph.facebook.com/v22.0/${settings.metaPageId}/feed`;
      const body: any = { message: caption, access_token: settings.metaAccessToken };
      if (link) body.link = link;

      console.log(`[GamePlan FB Publish] POSTing to Facebook for item ${item.id}: ${item.title}`);
      const fbResponse = await fetch(fbUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const rawText = await fbResponse.text();
      console.log(`[GamePlan FB Publish] status=${fbResponse.status} body=${rawText.substring(0, 500)}`);
      let fbBody: any;
      try { fbBody = JSON.parse(rawText); } catch { fbBody = rawText; }

      if (!fbBody.error && fbBody.id) {
        const result = { success: true, postId: fbBody.id };
        await storage.createGamePlanHistoryEntry({ entityType: 'queue', entityId: item.id, action: 'published_facebook', summary: `Published to Facebook: ${item.title} (Post ID: ${fbBody.id})`, metadata: result });
        res.json(result);
      } else {
        const result = { success: false, status: fbResponse.status, error: fbBody.error || fbBody };
        await storage.createGamePlanHistoryEntry({ entityType: 'queue', entityId: item.id, action: 'fb_publish_failed', summary: `Facebook publish failed: ${item.title}`, metadata: result });
        res.status(400).json(result);
      }
    } catch (e: any) {
      console.error('[GamePlan FB Publish] Error:', e);
      res.status(500).json({ error: e.message });
    }
  });

  // === Publish to Instagram ===
  app.post("/api/admin/gameplan/queue/:id/publish-instagram", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const item = await storage.getGamePlanQueueItem(Number(req.params.id));
      if (!item) return res.status(404).json({ error: "Queue item not found" });

      const settings = await storage.getGamePlanSettings();
      if (!settings?.metaAccessToken || !settings?.igBusinessAccountId) {
        return res.status(400).json({ error: "Instagram credentials not configured. Set Page Access Token and IG Business Account ID." });
      }

      if (!item.primaryImageUrl) {
        return res.status(400).json({ error: "Instagram requires an image URL. Set a primary image on this queue item first." });
      }

      const caption = (item.socialCaptions as any)?.instagram || (item.socialCaptions as any)?.facebook || item.title;

      // Step 1: Create media container
      const containerUrl = `https://graph.facebook.com/v22.0/${settings.igBusinessAccountId}/media`;
      const containerBody = {
        image_url: item.primaryImageUrl,
        caption: caption,
        access_token: settings.metaAccessToken,
      };

      console.log(`[GamePlan IG Publish] Step 1: Create media container for item ${item.id}`);
      const containerResponse = await fetch(containerUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(containerBody),
      });
      const containerRaw = await containerResponse.text();
      console.log(`[GamePlan IG Publish] container status=${containerResponse.status} body=${containerRaw.substring(0, 500)}`);
      let containerJson: any;
      try { containerJson = JSON.parse(containerRaw); } catch { containerJson = containerRaw; }

      if (containerJson.error || !containerJson.id) {
        const result = { success: false, step: 'create_container', error: containerJson.error || containerJson };
        await storage.createGamePlanHistoryEntry({ entityType: 'queue', entityId: item.id, action: 'ig_publish_failed', summary: `Instagram container creation failed: ${item.title}`, metadata: result });
        return res.status(400).json(result);
      }

      const containerId = containerJson.id;

      // Step 2: Publish the container
      const publishUrl = `https://graph.facebook.com/v22.0/${settings.igBusinessAccountId}/media_publish`;
      const publishBody = { creation_id: containerId, access_token: settings.metaAccessToken };

      console.log(`[GamePlan IG Publish] Step 2: Publish container ${containerId}`);
      const publishResponse = await fetch(publishUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(publishBody),
      });
      const publishRaw = await publishResponse.text();
      console.log(`[GamePlan IG Publish] publish status=${publishResponse.status} body=${publishRaw.substring(0, 500)}`);
      let publishJson: any;
      try { publishJson = JSON.parse(publishRaw); } catch { publishJson = publishRaw; }

      if (publishJson.error || !publishJson.id) {
        const result = { success: false, step: 'publish_container', containerId, error: publishJson.error || publishJson };
        await storage.createGamePlanHistoryEntry({ entityType: 'queue', entityId: item.id, action: 'ig_publish_failed', summary: `Instagram publish failed: ${item.title}`, metadata: result });
        return res.status(400).json(result);
      }

      const result = { success: true, mediaId: publishJson.id, containerId };
      await storage.createGamePlanHistoryEntry({ entityType: 'queue', entityId: item.id, action: 'published_instagram', summary: `Published to Instagram: ${item.title} (Media ID: ${publishJson.id})`, metadata: result });
      res.json(result);
    } catch (e: any) {
      console.error('[GamePlan IG Publish] Error:', e);
      res.status(500).json({ error: e.message });
    }
  });

  app.post("/api/admin/gameplan/queue/:id/upload-media", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const itemId = Number(req.params.id);
      const item = await storage.getGamePlanQueueItem(itemId);
      if (!item) return res.status(404).json({ error: "Queue item not found" });

      const settings = await storage.getGamePlanSettings();
      if (!settings?.wpBaseUrl || !settings?.wpUsername || !settings?.wpAppPassword) {
        return res.status(400).json({ error: "WordPress credentials not configured" });
      }

      const { imageUrl, slot, alt, caption } = req.body;
      if (!imageUrl || !slot || !['featured', 'mid', 'supporting'].includes(slot)) {
        return res.status(400).json({ error: "imageUrl and valid slot (featured/mid/supporting) required" });
      }

      const baseUrl = settings.wpBaseUrl.replace(/\/+$/, '');
      const authHeader = 'Basic ' + Buffer.from(`${settings.wpUsername}:${settings.wpAppPassword}`).toString('base64');

      const imgResponse = await fetch(imageUrl);
      if (!imgResponse.ok) return res.status(400).json({ error: "Failed to download image from URL" });
      const imgBuffer = Buffer.from(await imgResponse.arrayBuffer());
      const contentType = imgResponse.headers.get('content-type') || 'image/jpeg';
      const ext = contentType.includes('png') ? '.png' : contentType.includes('webp') ? '.webp' : '.jpg';
      const filename = `gameplan-${slot}-${itemId}${ext}`;

      const wpUploadRes = await fetch(`${baseUrl}/wp-json/wp/v2/media`, {
        method: 'POST',
        headers: {
          'Authorization': authHeader,
          'Content-Disposition': `attachment; filename="${filename}"`,
          'Content-Type': contentType,
        },
        body: imgBuffer,
      });
      const wpMediaJson = await wpUploadRes.json();
      if (!wpUploadRes.ok) {
        return res.status(500).json({ error: "WordPress media upload failed", details: wpMediaJson });
      }

      const currentSlots: any = item.imageSlots || {};
      currentSlots[slot] = {
        url: wpMediaJson.source_url || imageUrl,
        wpMediaId: wpMediaJson.id,
        alt: alt || wpMediaJson.alt_text || '',
        caption: caption || '',
      };

      await storage.updateGamePlanQueueItem(itemId, {
        imageSlots: currentSlots,
        ...(slot === 'featured' ? { wpFeaturedMediaId: wpMediaJson.id } : {}),
      } as any);

      await storage.createGamePlanHistoryEntry({
        entityType: 'queue', entityId: itemId, action: 'media_uploaded',
        summary: `Uploaded ${slot} image for: ${item.title} (WP Media ID: ${wpMediaJson.id})`,
        metadata: { slot, wpMediaId: wpMediaJson.id, url: wpMediaJson.source_url },
      });

      res.json({ success: true, slot, wpMediaId: wpMediaJson.id, url: wpMediaJson.source_url, imageSlots: currentSlots });
    } catch (e: any) {
      console.error('[GamePlan Media Upload] Error:', e);
      res.status(500).json({ error: e.message });
    }
  });

  app.post("/api/admin/gameplan/queue/:id/upload-file", isAuthenticated, isAdmin, upload.single('file'), async (req, res) => {
    try {
      const itemId = Number(req.params.id);
      const item = await storage.getGamePlanQueueItem(itemId);
      if (!item) return res.status(404).json({ error: "Queue item not found" });

      const slot = req.body.slot;
      if (!slot || !['featured', 'mid', 'supporting'].includes(slot)) {
        return res.status(400).json({ error: "Valid slot (featured/mid/supporting) required" });
      }
      if (!req.file) return res.status(400).json({ error: "No file uploaded" });

      const fileUrl = `/uploads/${req.file.filename}`;
      const fullUrl = `${req.protocol}://${req.get('host')}${fileUrl}`;

      const settings = await storage.getGamePlanSettings();
      let wpMediaId: number | null = null;
      let finalUrl = fullUrl;

      if (settings?.wpBaseUrl && settings?.wpUsername && settings?.wpAppPassword) {
        try {
          const baseUrl = settings.wpBaseUrl.replace(/\/+$/, '');
          const authHeader = 'Basic ' + Buffer.from(`${settings.wpUsername}:${settings.wpAppPassword}`).toString('base64');
          const imgBuffer = await fs.promises.readFile(req.file.path);
          const contentType = req.file.mimetype || 'image/jpeg';
          const filename = `gameplan-${slot}-${itemId}-${Date.now()}${path.extname(req.file.originalname) || '.jpg'}`;

          const wpUploadRes = await fetch(`${baseUrl}/wp-json/wp/v2/media`, {
            method: 'POST',
            headers: {
              'Authorization': authHeader,
              'Content-Disposition': `attachment; filename="${filename}"`,
              'Content-Type': contentType,
            },
            body: imgBuffer,
          });
          const wpMediaJson = await wpUploadRes.json() as any;
          if (wpUploadRes.ok && wpMediaJson.id) {
            wpMediaId = wpMediaJson.id;
            finalUrl = wpMediaJson.source_url || fullUrl;
          }
        } catch (e: any) {
          console.log('[GamePlan File Upload] WP upload failed (non-critical), using local URL:', e.message);
        }
      }

      const currentSlots: any = item.imageSlots || {};
      currentSlots[slot] = {
        url: finalUrl,
        wpMediaId: wpMediaId,
        alt: req.body.alt || '',
        caption: '',
      };

      await storage.updateGamePlanQueueItem(itemId, {
        imageSlots: currentSlots,
        ...(slot === 'featured' && wpMediaId ? { wpFeaturedMediaId: wpMediaId } : {}),
      } as any);

      if (slot === 'featured') {
        await storage.updateGamePlanQueueItem(itemId, { primaryImageUrl: finalUrl } as any);
      }

      await storage.createGamePlanHistoryEntry({
        entityType: 'queue', entityId: itemId, action: 'media_uploaded',
        summary: `Uploaded ${slot} image for: ${item.title}${wpMediaId ? ` (WP Media ID: ${wpMediaId})` : ' (local)'}`,
        metadata: { slot, wpMediaId, url: finalUrl },
      });

      res.json({ success: true, slot, wpMediaId, url: finalUrl, imageSlots: currentSlots });
    } catch (e: any) {
      console.error('[GamePlan File Upload] Error:', e);
      res.status(500).json({ error: e.message });
    }
  });

  app.post("/api/admin/gameplan/queue/:id/calculate-seo", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const itemId = Number(req.params.id);
      const item = await storage.getGamePlanQueueItem(itemId);
      if (!item) return res.status(404).json({ error: "Queue item not found" });

      const content = item.generatedContent || '';
      const title = item.title || '';
      const cityName = item.city || '';
      const pageType = (item as any).pageType || item.type || '';
      const isLocationPage = pageType === 'location_page' || pageType === 'service_location_page' || item.type === 'city_page';

      const stripHtml = (html: string) => html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
      const jaccardSim = (a: string, b: string): number => {
        if (!a || !b) return 0;
        const wA = new Set(a.toLowerCase().split(/\s+/).filter(w => w.length > 3));
        const wB = new Set(b.toLowerCase().split(/\s+/).filter(w => w.length > 3));
        if (wA.size === 0 || wB.size === 0) return 0;
        let inter = 0;
        for (const w of wA) if (wB.has(w)) inter++;
        return inter / (wA.size + wB.size - inter);
      };

      const makeSec = (score: number, maxScore: number, details: string[]): { score: number; maxScore: number; status: 'pass' | 'warning' | 'fail'; details: string[] } => {
        const pct = maxScore > 0 ? score / maxScore : 0;
        return { score, maxScore, status: pct >= 0.7 ? 'pass' : pct >= 0.4 ? 'warning' : 'fail', details };
      };

      const sections: any = {};

      // 1. Title tag (10 pts)
      {
        let s = 0; const d: string[] = [];
        const primaryKw = cityName ? `${cityName.toLowerCase()}` : '';
        if (title.length >= 30 && title.length <= 65) { s += 2; } else { d.push(`Title length ${title.length} — aim for 30-65 chars`); }
        if (primaryKw && title.toLowerCase().includes(primaryKw)) { s += 4; } else if (primaryKw) { d.push(`Title missing city name "${cityName}"`); }
        if (title.toLowerCase().includes('gama') || title.toLowerCase().includes('painting')) { s += 2; } else { d.push('Title missing brand name'); }
        if (!/^[A-Z]/.test(title) || title === title.toUpperCase()) { d.push('Title should use natural casing'); } else { s += 2; }
        sections.title = makeSec(s, 10, d);
      }

      // 2. Meta description (10 pts)
      {
        let s = 0; const d: string[] = [];
        const metaMatch = content.match(/<!--\s*META_DESCRIPTION:\s*(.+?)\s*-->/i);
        const meta = metaMatch?.[1]?.trim() || '';
        if (meta.length >= 120 && meta.length <= 160) { s += 3; } else if (meta.length > 0) { s += 1; d.push(`Meta description ${meta.length} chars — aim for 120-160`); } else { d.push('Missing meta description'); }
        if (cityName && meta.toLowerCase().includes(cityName.toLowerCase())) { s += 1; }
        if (/paint|interior|service/i.test(meta)) { s += 2; } else if (meta) { d.push('Meta missing service keyword'); }
        if (/call|contact|estimate|book|schedule/i.test(meta)) { s += 2; } else if (meta) { d.push('Meta missing CTA intent'); }
        // Unique vs other pages checked in duplicate section
        s += meta ? 2 : 0;
        sections.metaDescription = makeSec(s, 10, d);
      }

      // 3. H1 (10 pts)
      {
        let s = 0; const d: string[] = [];
        const h1Match = content.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
        const h1Text = h1Match ? stripHtml(h1Match[1]) : '';
        const h1Count = (content.match(/<h1/gi) || []).length;
        if (h1Count === 1) { s += 3; } else if (h1Count > 1) { s += 1; d.push(`${h1Count} H1 tags — should be exactly 1`); } else { d.push('No H1 tag found'); }
        if (isLocationPage && cityName && h1Text.toLowerCase().includes(cityName.toLowerCase())) { s += 3; } else if (isLocationPage && cityName) { d.push(`H1 missing city name "${cityName}"`); } else { s += 3; }
        if (/paint|interior|service|renovation/i.test(h1Text)) { s += 2; } else if (h1Text) { d.push('H1 missing service keyword'); }
        if (h1Text.length >= 20 && h1Text.length <= 80) { s += 2; } else if (h1Text) { s += 1; d.push(`H1 length ${h1Text.length} — aim for 20-80 chars`); }
        sections.h1 = makeSec(s, 10, d);
      }

      // 4. Hero (10 pts)
      {
        let s = 0; const d: string[] = [];
        const hasHero = /class="hero"/i.test(content);
        const heroTextMatch = content.match(/class="(?:hero|subtitle|gp-hero-text)"[^>]*>([\s\S]*?)<\/(?:div|p)>/i);
        const heroText = heroTextMatch ? stripHtml(heroTextMatch[1]) : '';
        if (cityName && heroText.toLowerCase().includes(cityName.toLowerCase())) { s += 2; } else if (cityName && hasHero) { d.push('Hero text missing city name'); }
        if (/paint|interior|service/i.test(heroText)) { s += 2; } else if (hasHero) { d.push('Hero missing service mention'); }
        if (/licensed|insured|guarantee|certified|trusted|award/i.test(content.substring(0, 3000))) { s += 2; } else { d.push('Hero missing trust signal'); }
        // Not duplicate — checked separately
        s += hasHero ? 4 : 0;
        if (!hasHero) d.push('No hero section found');
        sections.hero = makeSec(s, 10, d);
      }

      // 5. Local content depth (15 pts)
      {
        let s = 0; const d: string[] = [];
        const textContent = stripHtml(content).toLowerCase();
        const localTerms = ['homes', 'homeowner', 'neighborhood', 'architecture', 'colonial', 'brownstone', 'plaster', 'wallpaper', 'trim', 'co-op', 'rental', 'apartment', 'paneling', 'victorian', 'cape cod', 'tudor', 'ranch', 'split-level', 'condo'];
        const localHits = localTerms.filter(t => textContent.includes(t));
        if (localHits.length >= 5) { s += 5; } else if (localHits.length >= 2) { s += 3; d.push(`Only ${localHits.length} local housing terms — add more specific detail`); } else { s += 1; d.push('Very little local housing detail'); }
        const genericPhrases = ['beautiful homes', 'close-knit community', 'lovely neighborhood', 'charming area', 'wonderful place'];
        const genericHits = genericPhrases.filter(p => textContent.includes(p));
        if (genericHits.length === 0) { s += 5; } else { s += 2; d.push(`Generic filler detected: ${genericHits.join(', ')}`); }
        if (cityName && isLocationPage) {
          const cityMentions = (textContent.match(new RegExp(cityName.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g')) || []).length;
          if (cityMentions >= 8) { s += 5; } else if (cityMentions >= 4) { s += 3; d.push(`City mentioned ${cityMentions} times — aim for 8+`); } else { s += 1; d.push(`City mentioned only ${cityMentions} times`); }
        } else { s += 5; }
        sections.localContent = makeSec(s, 15, d);
      }

      // 6. Project showcase (15 pts)
      {
        let s = 0; const d: string[] = [];
        const hasShowcase = /project.*showcase|showcase|gallery-img|before.*after|scope.*work/i.test(content);
        if (hasShowcase) { s += 5; } else if (isLocationPage) { d.push('Missing project showcase — required for location pages'); } else { s += 3; }
        const imgCount = (content.match(/<img/gi) || []).length;
        const slots = item.imageSlots as any;
        const slotCount = slots ? Object.keys(slots).filter(k => (slots as any)[k]?.url).length : 0;
        const totalImages = imgCount + slotCount;
        if (totalImages >= 3) { s += 3; } else if (totalImages >= 1) { s += 1; d.push(`Only ${totalImages} image(s) — aim for 3+`); } else { d.push('No images found'); }
        if (/scope|rooms|areas completed|work performed|timeline/i.test(content)) { s += 3; } else if (hasShowcase) { d.push('Project showcase missing scope/detail breakdown'); }
        if (/result|outcome|transformed|completed|finished/i.test(content)) { s += 2; } else if (hasShowcase) { d.push('Project showcase missing result/outcome'); }
        if (cityName && hasShowcase && stripHtml(content).toLowerCase().includes(cityName.toLowerCase())) { s += 2; } else if (hasShowcase && cityName) { d.push('Project showcase missing city relevance'); } else { s += 2; }
        sections.projectShowcase = makeSec(s, 15, d);
      }

      // 7. Services section (5 pts)
      {
        let s = 0; const d: string[] = [];
        const hasServices = /class="grid-3"|service.*card|card-accent/i.test(content);
        const serviceTerms = ['interior painting', 'exterior painting', 'cabinet', 'color consultation', 'commercial', 'specialty', 'venetian', 'limewash', 'wallpaper'];
        const serviceHits = serviceTerms.filter(t => stripHtml(content).toLowerCase().includes(t));
        if (hasServices && serviceHits.length >= 3) { s += 2; } else if (hasServices) { s += 1; d.push('Services section could list more services'); } else { d.push('No services section found'); }
        if (isLocationPage && cityName) {
          const servicesSection = content.match(/services[\s\S]{0,3000}?(?=<\/section|<div class="stats|$)/i)?.[0] || '';
          if (servicesSection.toLowerCase().includes(cityName.toLowerCase())) { s += 3; } else { s += 1; d.push('Services section missing city-specific tailoring'); }
        } else { s += 3; }
        sections.services = makeSec(s, 5, d);
      }

      // 8. Internal linking (10 pts)
      {
        let s = 0; const d: string[] = [];
        const nearbyLinks = content.match(/class="neighborhood-tag"[^>]*>[\s\S]*?<\/(?:a|div|span)>/gi) || [];
        const allInternalLinks = (content.match(/<a[^>]*href="(?:https?:\/\/gamainteriorpainting\.com)?\/[^"]*"[^>]*>/gi) || []).length;
        const plainTextCities = content.match(/class="neighborhood-tag"(?!.*<a)/gi) || [];
        if (nearbyLinks.length >= 3) { s += 5; } else if (nearbyLinks.length >= 1) { s += 3; d.push(`Only ${nearbyLinks.length} nearby area links — aim for 3+`); } else if (isLocationPage) { d.push('No nearby area links found'); }
        if (allInternalLinks >= 3) { s += 3; } else if (allInternalLinks >= 1) { s += 1; d.push(`Only ${allInternalLinks} internal link(s) — aim for 3+`); } else { d.push('No internal links found'); }
        if (plainTextCities.length === 0) { s += 2; } else { d.push(`${plainTextCities.length} nearby area(s) not linked — all must be clickable`); }
        sections.internalLinking = makeSec(s, 10, d);
      }

      // 9. FAQ (10 pts)
      {
        let s = 0; const d: string[] = [];
        const faqItems = content.match(/class="faq-item"/gi) || [];
        const faqCount = faqItems.length;
        const hasSchema = /FAQPage/i.test(content) && /application\/ld\+json/i.test(content);
        if (faqCount >= 4 && faqCount <= 8) { s += 3; } else if (faqCount >= 2) { s += 2; d.push(`Only ${faqCount} FAQ(s) — aim for 4-6`); } else if (faqCount > 0) { s += 1; d.push(`Only ${faqCount} FAQ — needs 4-6`); } else { d.push('No FAQ section found'); }
        if (cityName && isLocationPage) {
          const faqSection = content.match(/FAQ[\s\S]*?(?=<div class="locations|<div class="contact-bar|$)/i)?.[0] || '';
          const faqText = stripHtml(faqSection).toLowerCase();
          if (faqText.includes(cityName.toLowerCase())) { s += 3; } else if (faqCount > 0) { s += 1; d.push('FAQ missing city-specific questions'); }
        } else { s += 3; }
        if (/cost|price|how much|how long|permit|paint brand/i.test(stripHtml(content).toLowerCase())) { s += 2; } else if (faqCount > 0) { d.push('FAQ missing pricing/timing topics'); }
        if (hasSchema) { s += 2; } else if (faqCount > 0) { d.push('FAQ missing JSON-LD schema'); }
        sections.faq = makeSec(s, 10, d);
      }

      // 10. Image SEO (5 pts)
      {
        let s = 0; const d: string[] = [];
        const imgTags = content.match(/<img[^>]*>/gi) || [];
        const alts = imgTags.map(tag => {
          const m = tag.match(/alt="([^"]*)"/i);
          return m ? m[1] : '';
        });
        const withAlt = alts.filter(a => a.length > 0);
        const withCity = alts.filter(a => cityName && a.toLowerCase().includes(cityName.toLowerCase()));
        const withService = alts.filter(a => /paint|interior|room|kitchen|living|bedroom|bathroom|cabinet|stair/i.test(a));
        if (imgTags.length > 0 && withAlt.length === imgTags.length) { s += 2; } else if (imgTags.length > 0) { d.push(`${imgTags.length - withAlt.length} image(s) missing alt text`); }
        if (withCity.length > 0) { s += 2; } else if (imgTags.length > 0 && cityName) { d.push('No image alt text includes city name'); }
        if (withService.length > 0) { s += 1; } else if (imgTags.length > 0) { d.push('No image alt text includes service/room details'); }
        sections.imageSeo = makeSec(s, 5, d);
      }

      // 11. CTA (5 pts)
      {
        let s = 0; const d: string[] = [];
        const ctaButtons = content.match(/class="(?:btn|cta-btn|cta)[^"]*"[^>]*>[^<]*(?:estimate|call|contact|book|schedule|quote)[^<]*/gi) || [];
        const ctaCount = ctaButtons.length;
        const hasContactBar = /class="contact-bar"/i.test(content);
        if (cityName && /(?:estimate|call|book).*[^<]*/.test(content) && stripHtml(content).toLowerCase().includes(cityName.toLowerCase())) { s += 2; } else if (ctaCount > 0) { s += 1; d.push('CTA could reference city/service'); }
        if (ctaCount >= 2) { s += 2; } else if (ctaCount >= 1) { s += 1; d.push('Only 1 CTA button — aim for 2+'); } else { d.push('No CTA buttons found'); }
        if (hasContactBar || /tel:\d/i.test(content)) { s += 1; } else { d.push('Missing phone/contact CTA'); }
        sections.cta = makeSec(s, 5, d);
      }

      // 12. Duplicate content check
      {
        let s = 0; const d: string[] = [];
        const dupWarnings: Array<{ section: string; similarTo: string; similarity: number }> = [];

        if (item.type === 'city_page' && content) {
          const extractSec = (html: string, pat: RegExp): string => {
            const m = html.match(pat);
            return m ? stripHtml(m[1]).toLowerCase() : '';
          };
          const heroP = /class="(?:gp-hero-text|subtitle)"[^>]*>([\s\S]*?)<\/(?:div|p)>/i;
          const ownerP = /class="owner-quote"[^>]*>([\s\S]*?)<\/(?:blockquote|div)>/i;
          const insightP = /Local Homeowner Insight[\s\S]*?<p[^>]*>([\s\S]*?)<\/p>/i;
          const faqP = /"@type"\s*:\s*"FAQPage"[\s\S]*?"mainEntity"\s*:\s*(\[[\s\S]*?\])\s*\}/i;
          const metaP = /<!--\s*META_DESCRIPTION:\s*(.+?)\s*-->/i;
          const ctaSectionP = /class="contact-bar"[^>]*>([\s\S]*?)<\/div>/i;

          const curHero = extractSec(content, heroP);
          const curQuote = extractSec(content, ownerP);
          const curInsight = extractSec(content, insightP);
          const curMeta = (content.match(metaP)?.[1] || '').toLowerCase().trim();
          const curCta = extractSec(content, ctaSectionP);
          let curFaqs: string[] = [];
          const fm = content.match(faqP);
          if (fm) { try { curFaqs = JSON.parse(fm[1]).map((f: any) => stripHtml(f.acceptedAnswer?.text || f.name || '').toLowerCase()); } catch {} }

          const allQ = await storage.getGamePlanQueue({ type: 'city_page' });
          const otherItems = allQ.filter(q => q.id !== item.id && q.type === 'city_page' && (q.status === 'published' || q.status === 'approved' || q.status === 'draft') && q.generatedContent);

          const WARN_THRESHOLD = 0.3;
          const FAIL_THRESHOLD = 0.5;
          for (const other of otherItems) {
            const oc = other.generatedContent || '';
            const oCity = other.city || other.title;

            const checkSec = (name: string, cur: string, otherVal: string) => {
              const sim = jaccardSim(cur, otherVal);
              if (sim > FAIL_THRESHOLD) dupWarnings.push({ section: name, similarTo: oCity, similarity: Math.round(sim * 100) });
              else if (sim > WARN_THRESHOLD) dupWarnings.push({ section: `${name} (warning)`, similarTo: oCity, similarity: Math.round(sim * 100) });
            };

            checkSec('Hero intro', curHero, extractSec(oc, heroP));
            checkSec('Owner quote', curQuote, extractSec(oc, ownerP));
            checkSec('Local insight', curInsight, extractSec(oc, insightP));
            checkSec('Meta description', curMeta, (oc.match(metaP)?.[1] || '').toLowerCase().trim());
            checkSec('CTA section', curCta, extractSec(oc, ctaSectionP));

            const ofm = oc.match(faqP);
            if (ofm && curFaqs.length > 0) {
              try {
                const oFaqs = JSON.parse(ofm[1]).map((f: any) => stripHtml(f.acceptedAnswer?.text || f.name || '').toLowerCase());
                for (let i = 0; i < curFaqs.length; i++) {
                  for (let j = 0; j < oFaqs.length; j++) {
                    const sim = jaccardSim(curFaqs[i], oFaqs[j]);
                    if (sim > FAIL_THRESHOLD) dupWarnings.push({ section: `FAQ #${i + 1}`, similarTo: oCity, similarity: Math.round(sim * 100) });
                    else if (sim > WARN_THRESHOLD) dupWarnings.push({ section: `FAQ #${i + 1} (warning)`, similarTo: oCity, similarity: Math.round(sim * 100) });
                  }
                }
              } catch {}
            }
          }
        }

        const criticalDups = dupWarnings.filter(w => !w.section.includes('(warning)'));
        const warnDups = dupWarnings.filter(w => w.section.includes('(warning)'));
        if (criticalDups.length === 0 && warnDups.length === 0) {
          s = 5; d.push('No duplicate content detected');
        } else if (criticalDups.length === 0) {
          s = 3; d.push(`${warnDups.length} section(s) with mild similarity — consider varying`);
        } else {
          s = 0;
          for (const dup of criticalDups) d.push(`${dup.section} too similar to ${dup.similarTo} (${dup.similarity}%)`);
        }
        sections.duplicateContent = { ...makeSec(s, 5, d), duplicateWarnings: dupWarnings };
      }

      const totalScore = Math.min(100, Object.values(sections).reduce((sum: number, sec: any) => sum + (sec.score || 0), 0));
      const allWarnings = Object.entries(sections).flatMap(([key, sec]: [string, any]) =>
        sec.details.filter((d: string) => sec.status !== 'pass').map((d: string) => `[${key}] ${d}`)
      );

      const publishBlocked = totalScore < 75 ||
        (sections.duplicateContent?.duplicateWarnings?.filter((w: any) => !w.section.includes('(warning)')).length > 0) ||
        (isLocationPage && sections.hero?.status === 'fail') ||
        (isLocationPage && sections.localContent?.status === 'fail') ||
        (isLocationPage && sections.faq?.status === 'fail');

      const publishBlockReasons: string[] = [];
      if (totalScore < 75) publishBlockReasons.push(`SEO score ${totalScore} — minimum 75 required`);
      if (sections.duplicateContent?.duplicateWarnings?.filter((w: any) => !w.section.includes('(warning)')).length > 0) publishBlockReasons.push('Critical duplicate content detected');
      if (isLocationPage && sections.hero?.status === 'fail') publishBlockReasons.push('Hero section missing or failed');
      if (isLocationPage && sections.localContent?.status === 'fail') publishBlockReasons.push('Local content too weak');
      if (isLocationPage && sections.faq?.status === 'fail') publishBlockReasons.push('FAQ section missing');

      await storage.updateGamePlanQueueItem(itemId, {
        seoScore: totalScore,
        seoWarnings: allWarnings,
        seoDetails: sections,
        publishBlocked: publishBlocked,
        publishBlockReasons: publishBlockReasons,
      } as any);

      res.json({
        score: totalScore,
        sections,
        warnings: allWarnings,
        publishBlocked,
        publishBlockReasons,
        interpretation: totalScore >= 90 ? 'Excellent' : totalScore >= 75 ? 'Publishable' : totalScore >= 60 ? 'Improve before publishing' : 'Blocked — too weak to publish',
      });
    } catch (e: any) {
      console.error('[GamePlan SEO] Error:', e);
      res.status(500).json({ error: e.message });
    }
  });

  app.post("/api/admin/gameplan/queue/:id/validate", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const itemId = Number(req.params.id);
      const item = await storage.getGamePlanQueueItem(itemId);
      if (!item) return res.status(404).json({ error: "Queue item not found" });

      const settings = await storage.getGamePlanSettings();
      const missing: string[] = [];

      if (!item.title) missing.push('Title is required');
      if (!item.generatedContent) missing.push('Content has not been generated');

      if (item.type === 'city_page') {
        if (!item.targetCityId) missing.push('No target city linked');
        else {
          const city = await storage.getGamePlanTargetCity(item.targetCityId);
          if (!city) missing.push('Target city not found');
          else {
            if (!city.serviceTypes?.length) missing.push('City has no service types');
            if (!city.zipCodes?.length) missing.push('City has no ZIP codes');
          }
        }
      }

      if (!settings?.wpBaseUrl) missing.push('WordPress URL not configured');
      if (!settings?.wpUsername) missing.push('WordPress username not configured');
      if (!settings?.wpAppPassword) missing.push('WordPress app password not configured');

      const warnings: string[] = [];
      const slots = item.imageSlots as any;
      if (!slots?.featured?.url) warnings.push('Featured image not set (recommended but not required)');

      if ((item as any).publishBlocked) {
        const reasons = (item as any).publishBlockReasons || [];
        if (reasons.length > 0) {
          missing.push(...reasons.map((r: string) => `BLOCKED: ${r}`));
        } else {
          missing.push('BLOCKED: Run SEO check first — score too low or issues detected');
        }
      }

      const ready = missing.length === 0;
      res.json({ ready, missing, warnings, seoDetails: (item as any).seoDetails || null, publishBlocked: (item as any).publishBlocked || false });
    } catch (e: any) { res.status(500).json({ error: e.message }); }
  });

  app.get("/api/admin/gameplan/service-areas", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const cities = await storage.getGamePlanTargetCities();
      const queue = await storage.getGamePlanQueue();
      const allProjects = await storage.getProjects(userId);

      const STALE_DAYS = 21;
      const now = new Date();

      const areas = cities.map(city => {
        const cityLower = city.city.toLowerCase();
        const cityZips = new Set((city.zipCodes || []).map(z => z.trim()));

        const matchedProjects = allProjects.filter(p => {
          const pCity = (p.jobCity || '').toLowerCase().trim();
          const pZip = (p.jobZipCode || '').trim();
          return pCity === cityLower || cityZips.has(pZip);
        });

        const completedProjects = matchedProjects.filter(p => p.stage === 'completed');
        const recentProjects = completedProjects
          .sort((a, b) => {
            const da = a.stageChangedAt ? new Date(a.stageChangedAt).getTime() : 0;
            const db = b.stageChangedAt ? new Date(b.stageChangedAt).getTime() : 0;
            return db - da;
          })
          .slice(0, 5)
          .map(p => ({
            id: p.id,
            title: p.title || `Project #${p.projectNumber}`,
            contactName: (p as any).contact ? `${(p as any).contact.firstName || ''} ${(p as any).contact.lastName || ''}`.trim() : '',
            completedAt: p.stageChangedAt,
            totalAmount: p.totalAmount,
            jobCity: p.jobCity,
            jobZipCode: p.jobZipCode,
          }));

        const publishedQueueItems = queue.filter(q =>
          q.type === 'city_page' && q.targetCityId === city.id && q.status === 'published'
        );
        const lastPublished = city.lastPublishedAt || (publishedQueueItems.length > 0
          ? publishedQueueItems.sort((a, b) => {
              const da = a.publishedAt ? new Date(a.publishedAt).getTime() : 0;
              const db = b.publishedAt ? new Date(b.publishedAt).getTime() : 0;
              return db - da;
            })[0]?.publishedAt
          : null);

        const daysSinceUpdate = lastPublished
          ? Math.floor((now.getTime() - new Date(lastPublished).getTime()) / (1000 * 60 * 60 * 24))
          : null;

        const isStale = daysSinceUpdate !== null && daysSinceUpdate >= STALE_DAYS;
        const isMissing = city.pageStatus === 'not_created';
        const hasNewProjects = completedProjects.some(p => {
          if (!p.stageChangedAt || !lastPublished) return isMissing && completedProjects.length > 0;
          return new Date(p.stageChangedAt).getTime() > new Date(lastPublished).getTime();
        });

        let freshness: 'fresh' | 'stale' | 'missing' = 'fresh';
        if (isMissing) freshness = 'missing';
        else if (isStale) freshness = 'stale';

        return {
          id: city.id,
          city: city.city,
          market: city.market,
          state: city.state,
          zipCodes: city.zipCodes,
          pageStatus: city.pageStatus,
          wpPageUrl: city.wpPageUrl,
          wpPageId: city.wpPageId,
          lastPublishedAt: lastPublished,
          daysSinceUpdate,
          freshness,
          isStale,
          hasNewProjects,
          totalProjects: matchedProjects.length,
          completedProjects: completedProjects.length,
          recentProjects,
          serviceTypes: city.serviceTypes,
          isPremium: city.isPremium,
          active: city.active,
          needsUpdate: city.needsUpdate,
          updateNotes: city.updateNotes,
        };
      });

      const notifications: Array<{ type: string; severity: 'info' | 'warning' | 'action'; city: string; cityId: number; message: string }> = [];

      for (const area of areas) {
        if (area.freshness === 'missing' && area.completedProjects > 0) {
          notifications.push({
            type: 'missing_page',
            severity: 'action',
            city: area.city,
            cityId: area.id,
            message: `${area.city} has ${area.completedProjects} completed project(s) but no service area page — create one to boost local SEO`,
          });
        } else if (area.freshness === 'missing') {
          notifications.push({
            type: 'missing_page',
            severity: 'info',
            city: area.city,
            cityId: area.id,
            message: `${area.city} does not have a service area page yet`,
          });
        }

        if (area.isStale) {
          notifications.push({
            type: 'stale_page',
            severity: 'warning',
            city: area.city,
            cityId: area.id,
            message: `${area.city} page hasn't been updated in ${area.daysSinceUpdate} days — consider refreshing with recent project data`,
          });
        }

        if (area.hasNewProjects && area.freshness !== 'missing') {
          notifications.push({
            type: 'new_project',
            severity: 'action',
            city: area.city,
            cityId: area.id,
            message: `New completed project(s) in ${area.city} since last page update — add a project showcase to the service area page`,
          });
        }
      }

      notifications.sort((a, b) => {
        const severityOrder = { action: 0, warning: 1, info: 2 };
        return severityOrder[a.severity] - severityOrder[b.severity];
      });

      res.json({
        areas: areas.sort((a, b) => {
          const freshnessOrder = { missing: 0, stale: 1, fresh: 2 };
          return freshnessOrder[a.freshness] - freshnessOrder[b.freshness];
        }),
        notifications,
        summary: {
          total: areas.length,
          withPages: areas.filter(a => a.pageStatus !== 'not_created').length,
          missing: areas.filter(a => a.freshness === 'missing').length,
          stale: areas.filter(a => a.freshness === 'stale').length,
          fresh: areas.filter(a => a.freshness === 'fresh').length,
          staleDays: STALE_DAYS,
        },
      });
    } catch (e: any) {
      console.error("[GamePlan] Service areas error:", e);
      res.status(500).json({ error: e.message });
    }
  });

  app.post("/api/admin/gameplan/wp-sync", isAuthenticated, isAdmin, async (_req, res) => {
    try {
      const settings = await storage.getGamePlanSettings();
      if (!settings?.wpBaseUrl || !settings?.wpUsername || !settings?.wpAppPassword) {
        return res.status(400).json({ error: "WordPress credentials not configured" });
      }
      const baseUrl = settings.wpBaseUrl.replace(/\/+$/, '');
      const authHeader = 'Basic ' + Buffer.from(`${settings.wpUsername}:${settings.wpAppPassword}`).toString('base64');

      if (!baseUrl.startsWith('https://')) {
        return res.status(400).json({ error: "WordPress URL must use HTTPS" });
      }

      let page = 1;
      let allPages: any[] = [];
      let hasMore = true;
      while (hasMore) {
        const wpRes = await fetch(`${baseUrl}/wp-json/wp/v2/pages?per_page=100&page=${page}&_fields=id,title,slug,link,status,modified`, {
          headers: { 'Authorization': authHeader },
          signal: AbortSignal.timeout(15000),
        });
        if (!wpRes.ok) {
          const errText = await wpRes.text().catch(() => '');
          return res.status(wpRes.status).json({ error: `WordPress API error (${wpRes.status}): ${errText.substring(0, 200)}` });
        }
        const pages = await wpRes.json();
        allPages = allPages.concat(pages);
        const totalPages = parseInt(wpRes.headers.get('x-wp-totalpages') || '1');
        hasMore = page < totalPages;
        page++;
      }

      const cities = await storage.getGamePlanTargetCities();
      const queue = await storage.getGamePlanQueue();
      let synced = 0;
      const matchedWpIds = new Set<number>();

      for (const city of cities) {
        const citySlug = city.wpSlug;
        const cityName = city.city.toLowerCase();

        const matchedPage = allPages.find(p => {
          const pSlug = (p.slug || '').toLowerCase();
          if (citySlug && pSlug === citySlug.toLowerCase()) return true;
          const pTitle = (p.title?.rendered || '').toLowerCase();
          if (pTitle.includes(cityName) && (pTitle.includes('painting') || pTitle.includes('interior'))) return true;
          return false;
        });

        if (matchedPage) {
          matchedWpIds.add(matchedPage.id);
          const isLive = matchedPage.status === 'publish';
          const newStatus = isLive ? 'published' : 'generated';
          if (city.pageStatus !== newStatus || !city.wpPageId || city.wpPageId !== String(matchedPage.id)) {
            await storage.updateGamePlanTargetCity(city.id, {
              pageStatus: newStatus,
              wpPageId: String(matchedPage.id),
              wpPageUrl: matchedPage.link || `${baseUrl}/${matchedPage.slug}/`,
              wpSlug: matchedPage.slug,
            } as any);

            const queueMatch = queue.find(q => q.targetCityId === city.id || (q.slug && citySlug && q.slug === citySlug));
            if (queueMatch && isLive && queueMatch.status !== 'published') {
              await storage.updateGamePlanQueueItem(queueMatch.id, {
                status: 'published',
                wpPostId: matchedPage.id,
                publishedAt: new Date(matchedPage.modified || Date.now()),
              } as any);
            }
            synced++;
          }
        }
      }

      const livePagesNotInCities = allPages.filter(p => {
        if (matchedWpIds.has(p.id)) return false;
        const pSlug = (p.slug || '').toLowerCase();
        return pSlug.includes('paint') || pSlug.includes('interior');
      });

      res.json({
        synced,
        totalWpPages: allPages.length,
        totalCities: cities.length,
        unmatchedServicePages: livePagesNotInCities.map(p => ({
          id: p.id,
          title: p.title?.rendered || '',
          slug: p.slug,
          link: p.link,
          status: p.status,
        })),
      });
    } catch (e: any) {
      console.error("[GamePlan] WP sync error:", e);
      res.status(500).json({ error: e.message });
    }
  });

  app.get("/api/admin/gameplan/project-photos", isAuthenticated, isAdmin, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const { cityId, projectId: reqProjectId } = req.query;
      const allProjects = await storage.getProjects(userId);

      let targetProjects = allProjects;
      if (reqProjectId) {
        targetProjects = allProjects.filter(p => p.id === Number(reqProjectId));
      } else if (cityId) {
        const city = await storage.getGamePlanTargetCity(Number(cityId));
        if (city) {
          const cityLower = city.city.toLowerCase();
          const cityZips = new Set((city.zipCodes || []).map(z => z.trim()));
          targetProjects = allProjects.filter(p => {
            const pCity = (p.jobCity || '').toLowerCase().trim();
            const pZip = (p.jobZipCode || '').trim();
            return pCity === cityLower || cityZips.has(pZip);
          });
        }
      }

      const completedProjects = targetProjects
        .filter(p => p.stage === 'completed' || p.stage === 'follow_up')
        .sort((a, b) => {
          const da = a.stageChangedAt ? new Date(a.stageChangedAt).getTime() : 0;
          const dbTime = b.stageChangedAt ? new Date(b.stageChangedAt).getTime() : 0;
          return dbTime - da;
        });

      const projectPhotosResult: Array<{
        projectId: number;
        projectTitle: string;
        jobCity: string;
        completedAt: Date | null;
        photos: Array<{ id: number; fileName: string; storageKey: string; caption: string | null; url: string }>;
      }> = [];

      for (const project of completedProjects.slice(0, 20)) {
        const projectDocs = await db.select({ id: documents.id })
          .from(documents)
          .where(and(eq(documents.projectId, project.id), eq(documents.userId, userId)));

        const allPhotos: any[] = [];
        for (const doc of projectDocs) {
          const photos = await db.select().from(documentPhotos)
            .where(eq(documentPhotos.documentId, doc.id))
            .orderBy(desc(documentPhotos.createdAt));
          allPhotos.push(...photos);
        }

        if (allPhotos.length > 0) {
          projectPhotosResult.push({
            projectId: project.id,
            projectTitle: project.title || `Project #${project.projectNumber}`,
            jobCity: project.jobCity || '',
            completedAt: project.stageChangedAt,
            photos: allPhotos.map(p => ({
              id: p.id,
              fileName: p.fileName,
              storageKey: p.storageKey,
              caption: p.caption,
              url: p.annotatedStorageKey
                ? `/api/photos/annotated/${p.id}`
                : `/api/documents/${p.documentId}/photos/${p.id}/file`,
            })),
          });
        }
      }

      res.json({ projectPhotos: projectPhotosResult });
    } catch (e: any) {
      console.error("[GamePlan] Project photos error:", e);
      res.status(500).json({ error: e.message });
    }
  });

  app.get("/api/admin/gameplan/stats", isAuthenticated, isAdmin, async (_req, res) => {
    try {
      const cities = await storage.getGamePlanTargetCities();
      const queue = await storage.getGamePlanQueue();
      const history = await storage.getGamePlanHistory(50);

      const scoredItems = queue.filter(q => q.seoScore !== null && q.seoScore !== undefined);
      const avgSeoScore = scoredItems.length > 0 ? Math.round(scoredItems.reduce((sum, q) => sum + (q.seoScore || 0), 0) / scoredItems.length) : null;
      const lowSeoItems = scoredItems.filter(q => (q.seoScore || 0) < 70).map(q => ({
        id: q.id, title: q.title, seoScore: q.seoScore, seoWarnings: q.seoWarnings,
      }));

      const stats = {
        totalCities: cities.length,
        nassauCities: cities.filter(c => c.market === 'NASSAU').length,
        brooklynNeighborhoods: cities.filter(c => c.market === 'BROOKLYN').length,
        pagesGenerated: cities.filter(c => c.pageStatus !== 'not_created').length,
        pagesPublished: cities.filter(c => c.pageStatus === 'published').length,
        queuePending: queue.filter(q => q.status === 'draft' || q.status === 'needs_review').length,
        queueApproved: queue.filter(q => q.status === 'approved').length,
        queuePublished: queue.filter(q => q.status === 'published').length,
        queueRejected: queue.filter(q => q.status === 'rejected').length,
        totalQueueItems: queue.length,
        avgSeoScore,
        scoredItemsCount: scoredItems.length,
        lowSeoItems,
        recentHistory: history.slice(0, 10),
      };

      res.json(stats);
    } catch (e: any) { res.status(500).json({ error: e.message }); }
  });

