  app.post("/api/campaigns/ai-draft", isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      if (!await hasFuseAiAccess(userId)) {
        return res.status(403).json({ message: 'FuseAI add-on required for AI campaign drafting' });
      }
      if (!process.env.OPENAI_API_KEY) {
        return res.status(500).json({ message: 'AI not configured' });
      }

      const { description, channel, segment } = req.body;
      if (!description) return res.status(400).json({ message: 'Description is required' });

      const settings = await storage.getCompanySettings(userId);
      const companyName = settings?.companyName || 'the company';

      const tagsList = campaignsEngine.AVAILABLE_TAGS.map(t => `${t.tag} - ${t.description}`).join('\n');

      const audienceDesc = segment === 'active_leads' ? 'potential customers (leads)' : segment === 'sent_estimates' ? 'people who received estimates' : segment === 'active_projects' ? 'current project clients' : segment === 'completed_jobs' ? 'past customers (completed jobs)' : 'all contacts';

      const prompt = `You are a marketing copywriter for a small business called "${companyName}".
Based on this description, write BOTH an email version AND an SMS version:
"${description}"

Target audience: ${audienceDesc}.

Available merge tags you can use to personalize the message:
${tagsList}

Use merge tags where appropriate to personalize the message. Always greet the contact by name using {{first_name}} or {{contact_name}}.
Sign off with {{salesperson}} from {{company_name}}.

Rules:
- email_body: Write a warm, professional email body. Keep it concise but compelling.
- email_subject: Write a compelling, short subject line for the email.
- sms_body: Write a very short SMS version (under 160 characters). Be punchy and direct. No formal greetings - just get to the point. Include a CTA.

Respond in JSON format:
{"email_subject": "...", "email_body": "...", "sms_body": "..."}`;

      const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
      const completion = await openai.chat.completions.create({
        model: 'gpt-4o-mini',
        messages: [{ role: 'user', content: prompt }],
        temperature: 0.7,
        max_tokens: 600,
        response_format: { type: 'json_object' },
      });

      const content = completion.choices[0]?.message?.content;
      if (!content) return res.status(500).json({ message: 'AI returned empty response' });

      const parsed = JSON.parse(content);
      res.json(parsed);
    } catch (err: any) {
      console.error('[Campaigns AI] Error:', err.message);
      res.status(500).json({ message: err.message });
    }
  });

