  app.get('/api/unsubscribe/:token', async (req, res) => {
    try {
      const { verifyUnsubscribeToken } = await import('./campaigns');
      const result = verifyUnsubscribeToken(req.params.token);
      if (!result) return res.status(400).json({ message: 'Invalid or expired unsubscribe link' });

      const [contact] = await db.select({ id: contacts.id, name: contacts.name, unsubscribedAt: contacts.unsubscribedAt })
        .from(contacts)
        .where(and(eq(contacts.id, result.contactId), eq(contacts.userId, result.userId)));

      if (!contact) return res.status(404).json({ message: 'Contact not found' });

      const [settings] = await db.select({ companyName: companySettings.companyName })
        .from(companySettings)
        .where(eq(companySettings.userId, result.userId));

      res.json({
        contactName: contact.name,
        companyName: settings?.companyName || 'this business',
        alreadyUnsubscribed: !!contact.unsubscribedAt,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

