  app.post("/api/team/messages/upload-image", isAuthenticated, async (req, res) => {
    try {
      const userId = req.user?.claims?.sub as string;
      const resolved = await resolveUserCapabilities(userId);
      if (!resolved.isOwner && !resolved.capabilities.sendMessages) {
        return res.status(403).json({ message: "You don't have permission to send messages" });
      }
      const { imageData, contentType: ct } = req.body;
      if (!imageData) {
        return res.status(400).json({ message: "No image data received" });
      }
      const contentType = ct || "image/jpeg";
      const base64Data = imageData.replace(/^data:image\/\w+;base64,/, "");
      const imageBuffer = Buffer.from(base64Data, "base64");

      if (imageBuffer.length > 10 * 1024 * 1024) {
        return res.status(400).json({ message: "Image too large (max 10MB)" });
      }

      const { ObjectStorageService } = await import("./replit_integrations/object_storage/objectStorage");
      const objService = new ObjectStorageService();
      const uploadURL = await objService.getObjectEntityUploadURL();
      const putRes = await fetch(uploadURL, { method: "PUT", body: imageBuffer, headers: { "Content-Type": contentType } });
      if (!putRes.ok) throw new Error(`Upload failed: ${putRes.status}`);
      const imageUrl = objService.normalizeObjectEntityPath(uploadURL);
      res.json({ imageUrl });
    } catch (err: any) {
      console.error("[Team Chat] Image upload error:", err);
      res.status(500).json({ message: err.message });
    }
  });

