  app.post("/api/admin/sync-dev-to-prod", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = req.session?.userId;
      if (!userId) return res.status(401).json({ message: "Unauthorized" });

      const [user] = await db.select().from(users).where(eq(users.id, userId));
      if (!user?.isAdmin) return res.status(403).json({ message: "Admin only" });

      const { targetEmail, data } = req.body;
      if (!targetEmail || !data) return res.status(400).json({ message: "targetEmail and data required" });

      const [targetUser] = await db.select().from(users).where(eq(users.email, targetEmail));
      if (!targetUser) return res.status(404).json({ message: "Target user not found" });

      const tId = targetUser.id;
      const results: any = { contacts: 0, documents: 0, projects: 0, teamMembers: 0, teamChannels: 0, teamMessages: 0 };

      const contactIdMap = new Map<number, number>();

      if (data.contacts?.length) {
        for (const c of data.contacts) {
          const existing = await db.select().from(contacts).where(and(eq(contacts.userId, tId), eq(contacts.email, c.email)));
          if (existing.length > 0) {
            contactIdMap.set(c.id, existing[0].id);
            continue;
          }
          const [created] = await db.insert(contacts).values({
            userId: tId, name: c.name, email: c.email, phone: c.phone,
            address: c.address, city: c.city, state: c.state, zipCode: c.zipCode,
            type: c.type, status: c.status, leadSource: c.leadSource, notes: c.notes,
            metadata: c.metadata,
          }).returning();
          contactIdMap.set(c.id, created.id);
          results.contacts++;
        }
      }

      const projectIdMap = new Map<number, number>();

      if (data.projects?.length) {
        for (const p of data.projects) {
          const newContactId = contactIdMap.get(p.contactId);
          if (!newContactId) continue;
          const existing = await db.select().from(projects).where(and(eq(projects.userId, tId), eq(projects.title, p.title), eq(projects.contactId, newContactId)));
          if (existing.length > 0) {
            projectIdMap.set(p.id, existing[0].id);
            continue;
          }
          const [created] = await db.insert(projects).values({
            userId: tId, contactId: newContactId, title: p.title, description: p.description,
            stage: p.stage, totalAmount: p.totalAmount,
            jobAddress: p.jobAddress, jobCity: p.jobCity, jobState: p.jobState, jobZipCode: p.jobZipCode,
            scheduledDate: p.scheduledDate, scheduledTime: p.scheduledTime,
            source: p.source, projectNumber: p.projectNumber,
          }).returning();
          projectIdMap.set(p.id, created.id);
          results.projects++;
        }
      }

      if (data.documents?.length) {
        for (const d of data.documents) {
          const newContactId = contactIdMap.get(d.contactId);
          if (!newContactId) continue;
          const existing = await db.select().from(documents).where(and(eq(documents.userId, tId), eq(documents.title, d.title), eq(documents.contactId, newContactId)));
          if (existing.length > 0) continue;
          const newProjectId = d.projectId ? projectIdMap.get(d.projectId) : null;
          await db.insert(documents).values({
            userId: tId, contactId: newContactId, type: d.type, title: d.title,
            content: d.content, totalAmount: d.totalAmount, status: d.status,
            jobAddress: d.jobAddress, jobCity: d.jobCity, jobState: d.jobState, jobZipCode: d.jobZipCode,
            jobAddressSameAsBilling: d.jobAddressSameAsBilling,
            signature: d.signature, signedAt: d.signedAt,
            projectId: newProjectId || undefined, documentNumber: d.documentNumber,
          });
          results.documents++;
        }
      }

      if (data.teamMembers?.length) {
        for (const tm of data.teamMembers) {
          const existing = await db.select().from(teamMembers).where(and(eq(teamMembers.userId, tId), eq(teamMembers.email, tm.email)));
          if (existing.length > 0) continue;
          await db.insert(teamMembers).values({
            userId: tId, name: tm.name, role: tm.role, phone: tm.phone, email: tm.email,
            isActive: tm.isActive, hourlyRate: tm.hourlyRate, pin: tm.pin,
            employeeType: tm.employeeType, activeForPricing: tm.activeForPricing,
            payrollBurdenPercentage: tm.payrollBurdenPercentage,
            workersCompPercentage: tm.workersCompPercentage, benefitsPerHour: tm.benefitsPerHour,
          });
          results.teamMembers++;
        }
      }

      const channelIdMap = new Map<number, number>();
      if (data.teamChannels?.length) {
        for (const ch of data.teamChannels) {
          const existing = await db.select().from(teamChannels).where(and(eq(teamChannels.companyOwnerId, tId), eq(teamChannels.type, ch.type), eq(teamChannels.name, ch.name || "General")));
          if (existing.length > 0) {
            channelIdMap.set(ch.id, existing[0].id);
            continue;
          }
          const [created] = await db.insert(teamChannels).values({
            companyOwnerId: tId, name: ch.name, type: ch.type,
            createdById: tId, memberIds: ch.memberIds,
          }).returning();
          channelIdMap.set(ch.id, created.id);
          results.teamChannels++;
        }
      }

      if (data.teamMessages?.length) {
        const existingMsgCount = await db.select({ count: count() }).from(teamMessages).where(eq(teamMessages.companyOwnerId, tId));
        if ((existingMsgCount[0]?.count || 0) === 0) {
          for (const msg of data.teamMessages) {
            const newChannelId = msg.channelId ? channelIdMap.get(msg.channelId) : undefined;
            await db.insert(teamMessages).values({
              companyOwnerId: tId, senderId: msg.senderId,
              recipientId: msg.recipientId, channel: msg.channel,
              channelId: newChannelId || undefined, message: msg.message,
              imageUrl: msg.imageUrl, isRead: true,
            });
            results.teamMessages++;
          }
        }
      }

      res.json({ message: "Sync complete", targetUser: targetEmail, results });
    } catch (err: any) {
      console.error("[Sync] Error:", err);
      res.status(500).json({ message: err.message });
    }
  });

