  app.get("/api/my-jobs", isAuthenticated, async (req, res) => {
    try {
      const userId = req.user?.claims?.sub as string;
      const resolved = await resolveUserCapabilities(userId);

      if (resolved.isOwner) {
        return res.json([]);
      }

      if (!resolved.capabilities.viewAssignedJobs) {
        return res.status(403).json({ message: "You don't have permission to view assigned jobs" });
      }

      if (!resolved.linkedTeamMemberId) {
        return res.json([]);
      }

      const isCrewLead = resolved.role === 'crew_lead';
      let assignedProjectIds: number[] = [];

      if (isCrewLead && resolved.capabilities.manageCrew) {
        const allAssignments = await db.select({ projectId: projectCrewAssignments.projectId })
          .from(projectCrewAssignments)
          .where(eq(projectCrewAssignments.userId, resolved.ownerId));
        assignedProjectIds = [...new Set(allAssignments.map(a => a.projectId))];
      } else {
        const myAssignments = await db.select({ projectId: projectCrewAssignments.projectId })
          .from(projectCrewAssignments)
          .where(and(
            eq(projectCrewAssignments.teamMemberId, resolved.linkedTeamMemberId),
            eq(projectCrewAssignments.userId, resolved.ownerId)
          ));
        assignedProjectIds = myAssignments.map(a => a.projectId);
      }

      if (assignedProjectIds.length === 0) {
        return res.json([]);
      }

      const allAssignedProjects = await db.select().from(projects)
        .where(and(
          eq(projects.userId, resolved.ownerId),
          inArray(projects.id, assignedProjectIds)
        ));

      const now = new Date();
      const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
      const oneWeekOut = new Date(now);
      oneWeekOut.setDate(oneWeekOut.getDate() + 7);
      const oneWeekStr = `${oneWeekOut.getFullYear()}-${String(oneWeekOut.getMonth() + 1).padStart(2, '0')}-${String(oneWeekOut.getDate()).padStart(2, '0')}`;

      const activeStages = ['scheduled', 'in_progress', 'accepted'];
      const assignedProjects = allAssignedProjects.filter(p => {
        if (activeStages.includes(p.stage)) return true;
        if (p.scheduledDate && p.scheduledDate >= todayStr && p.scheduledDate <= oneWeekStr) return true;
        return false;
      });

      const contactIds = [...new Set(assignedProjects.map(p => p.contactId).filter(Boolean))];
      const contactMap: Record<number, any> = {};
      if (contactIds.length > 0) {
        const contactsList = await db.select({
          id: contacts.id,
          name: contacts.name,
          phone: contacts.phone,
          address: contacts.address,
          city: contacts.city,
          state: contacts.state,
        }).from(contacts).where(inArray(contacts.id, contactIds as number[]));
        contactsList.forEach(c => { contactMap[c.id] = c; });
      }

      const crewAssignments = await db.select().from(projectCrewAssignments)
        .where(and(
          eq(projectCrewAssignments.userId, resolved.ownerId),
          inArray(projectCrewAssignments.projectId, assignedProjectIds)
        ));

      const teamMemberIds = [...new Set(crewAssignments.map(a => a.teamMemberId))];
      const teamMemberMap: Record<number, any> = {};
      if (teamMemberIds.length > 0) {
        const members = await db.select({ id: teamMembers.id, name: teamMembers.name, role: teamMembers.role })
          .from(teamMembers).where(inArray(teamMembers.id, teamMemberIds));
        members.forEach(m => { teamMemberMap[m.id] = m; });
      }

      const isLaborer = resolved.role === 'laborer';
      const result = assignedProjects.map(project => {
        const contact = project.contactId ? contactMap[project.contactId] : null;
        const projectCrew = crewAssignments
          .filter(a => a.projectId === project.id)
          .map(a => teamMemberMap[a.teamMemberId])
          .filter(Boolean);

        return {
          id: project.id,
          title: project.title,
          stage: project.stage,
          scheduledDate: project.scheduledDate,
          scheduledTime: project.scheduledTime,
          scheduledEndTime: project.scheduledEndTime || null,
          scheduledEndDate: project.scheduledEndDate || null,
          address: project.address || contact?.address || null,
          city: project.city || contact?.city || null,
          state: project.state || contact?.state || null,
          contactName: contact?.name || null,
          contactPhone: isLaborer ? null : (contact?.phone || null),
          crew: projectCrew,
          notes: project.notes || null,
        };
      });

      res.json(result);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  async function verifyProjectAssignment(resolved: Awaited<ReturnType<typeof resolveUserCapabilities>>, projectId: number): Promise<boolean> {
    if (resolved.isOwner) return true;
    if (!resolved.linkedTeamMemberId) return false;

    const isCrewLead = resolved.role === 'crew_lead' && resolved.capabilities.manageCrew;
    if (isCrewLead) {
      const [anyAssignment] = await db.select({ id: projectCrewAssignments.id })
        .from(projectCrewAssignments)
        .where(and(
          eq(projectCrewAssignments.projectId, projectId),
          eq(projectCrewAssignments.userId, resolved.ownerId)
        )).limit(1);
      return !!anyAssignment;
    }

    const [assignment] = await db.select({ id: projectCrewAssignments.id })
      .from(projectCrewAssignments)
      .where(and(
        eq(projectCrewAssignments.projectId, projectId),
        eq(projectCrewAssignments.teamMemberId, resolved.linkedTeamMemberId),
        eq(projectCrewAssignments.userId, resolved.ownerId)
      )).limit(1);
    return !!assignment;
  }

  app.get("/api/my-jobs/weekly-summary", isAuthenticated, async (req, res) => {
    try {
      const userId = req.user?.claims?.sub as string;
      const resolved = await resolveUserCapabilities(userId);
      if (!resolved.capabilities.clockInOut && !resolved.isOwner) {
        return res.status(403).json({ message: "No access" });
      }
      const linkedId = resolved.linkedTeamMemberId;
      if (!linkedId) {
        return res.json({ hoursThisWeek: 0, earningsThisWeek: 0, hourlyRate: 0, entries: 0 });
      }

      const now = new Date();
      const dayOfWeek = now.getDay();
      const startOfWeek = new Date(now);
      startOfWeek.setDate(now.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));
      startOfWeek.setHours(0, 0, 0, 0);

      const weekEntries = await db.select().from(timeEntries)
        .where(and(
          eq(timeEntries.teamMemberId, linkedId),
          eq(timeEntries.userId, resolved.ownerId),
          gte(timeEntries.clockIn, startOfWeek)
        ));

      let totalMinutes = 0;
      for (const entry of weekEntries) {
        if (entry.totalMinutes) {
          totalMinutes += entry.totalMinutes;
        } else if (entry.clockIn && entry.clockOut) {
          totalMinutes += Math.floor((new Date(entry.clockOut).getTime() - new Date(entry.clockIn).getTime()) / 60000);
        } else if (entry.clockIn && !entry.clockOut) {
          totalMinutes += Math.floor((Date.now() - new Date(entry.clockIn).getTime()) / 60000);
        }
      }

      const [member] = await db.select().from(teamMembers)
        .where(eq(teamMembers.id, linkedId));
      const hourlyRateCents = member?.hourlyRate || 0;
      const hours = totalMinutes / 60;
      const earningsCents = Math.round(hours * hourlyRateCents);

      res.json({
        hoursThisWeek: Math.round(hours * 100) / 100,
        earningsThisWeek: earningsCents,
        hourlyRate: hourlyRateCents,
        entries: weekEntries.length,
      });
    } catch (err: any) {
      console.error("Weekly summary error:", err);
      res.status(500).json({ message: "Failed to fetch weekly summary" });
    }
  });

