  app.get("/api/my-calendar", isAuthenticated, async (req, res) => {
    try {
      const userId = req.user?.claims?.sub as string;
      const resolved = await resolveUserCapabilities(userId);

      if (resolved.isOwner) {
        return res.json([]);
      }

      if (!resolved.capabilities.viewCrewCalendar) {
        return res.status(403).json({ message: "You don't have permission to view the crew calendar" });
      }

      if (!resolved.linkedTeamMemberId) {
        return res.json([]);
      }

      const isCrewLead = resolved.role === 'crew_lead';
      let assignedProjectIds: number[] = [];

      if (isCrewLead && resolved.capabilities.manageCrew) {
        const allAssignments = await db.select({ projectId: projectCrewAssignments.projectId })
          .from(projectCrewAssignments)
          .where(eq(projectCrewAssignments.userId, resolved.ownerId));
        assignedProjectIds = [...new Set(allAssignments.map(a => a.projectId))];
      } else {
        const myAssignments = await db.select({ projectId: projectCrewAssignments.projectId })
          .from(projectCrewAssignments)
          .where(and(
            eq(projectCrewAssignments.teamMemberId, resolved.linkedTeamMemberId),
            eq(projectCrewAssignments.userId, resolved.ownerId)
          ));
        assignedProjectIds = myAssignments.map(a => a.projectId);
      }

      if (assignedProjectIds.length === 0) {
        return res.json([]);
      }

      const assignedProjects = await db.select().from(projects)
        .where(and(
          eq(projects.userId, resolved.ownerId),
          inArray(projects.id, assignedProjectIds)
        ));

      const contactIds = [...new Set(assignedProjects.map(p => p.contactId).filter(Boolean))];
      const contactMap: Record<number, any> = {};
      if (contactIds.length > 0) {
        const contactsList = await db.select({ id: contacts.id, name: contacts.name, address: contacts.address })
          .from(contacts).where(inArray(contacts.id, contactIds as number[]));
        contactsList.forEach(c => { contactMap[c.id] = c; });
      }

      const scheduleDates = await db.select().from(jobScheduleDates)
        .where(and(
          eq(jobScheduleDates.userId, resolved.ownerId),
          inArray(jobScheduleDates.projectId, assignedProjectIds)
        ))
        .orderBy(asc(jobScheduleDates.date), asc(jobScheduleDates.startTime));

      const projectMap: Record<number, typeof assignedProjects[0]> = {};
      assignedProjects.forEach(p => { projectMap[p.id] = p; });

      const calendarEvents: any[] = [];

      const projectsWithScheduleDates = new Set(scheduleDates.map(sd => sd.projectId));

      for (const sd of scheduleDates) {
        const project = projectMap[sd.projectId];
        if (!project) continue;
        const contact = project.contactId ? contactMap[project.contactId] : null;
        calendarEvents.push({
          id: project.id,
          scheduleDateId: sd.id,
          title: project.title,
          date: sd.date,
          time: sd.startTime || null,
          endTime: sd.endTime || null,
          notes: sd.notes || null,
          address: project.jobAddress || project.address || contact?.address || null,
          contactName: contact?.name || null,
          stage: project.stage,
        });
      }

      const projectScheduleDateSets = new Map<number, Set<string>>();
      for (const sd of scheduleDates) {
        if (!projectScheduleDateSets.has(sd.projectId)) {
          projectScheduleDateSets.set(sd.projectId, new Set());
        }
        projectScheduleDateSets.get(sd.projectId)!.add(sd.date);
      }

      for (const project of assignedProjects) {
        if (!project.scheduledDate) continue;
        const dateSet = projectScheduleDateSets.get(project.id);
        if (dateSet && dateSet.has(project.scheduledDate)) continue;
        const contact = project.contactId ? contactMap[project.contactId] : null;
        calendarEvents.push({
          id: project.id,
          title: project.title,
          date: project.scheduledDate,
          time: project.scheduledTime || null,
          endTime: project.scheduledEndTime || null,
          address: project.jobAddress || project.address || contact?.address || null,
          contactName: contact?.name || null,
          stage: project.stage,
        });
      }

      calendarEvents.sort((a, b) => a.date.localeCompare(b.date));

      res.json(calendarEvents);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  const crewPhotoUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 10 * 1024 * 1024 } });
  app.post("/api/my-jobs/:projectId/photos", isAuthenticated, crewPhotoUpload.single("file"), async (req: Request, res: Response) => {
    try {
      const userId = req.user?.claims?.sub as string;
      const projectId = parseInt(req.params.projectId);
      const resolved = await resolveUserCapabilities(userId);

      if (!resolved.capabilities.uploadPhotos && !resolved.isOwner) {
        return res.status(403).json({ message: "You don't have permission to upload photos" });
      }

      const ownerId = resolved.isOwner ? userId : resolved.ownerId;

      if (!resolved.isOwner) {
        const hasAccess = await verifyProjectAssignment(resolved, projectId);
        if (!hasAccess) {
          return res.status(403).json({ message: "You are not assigned to this project" });
        }
      }

      const file = req.file;
      if (!file) return res.status(400).json({ message: "No file uploaded" });

      const relatedDocs = await db.select({ id: documents.id }).from(documents)
        .where(and(eq(documents.userId, ownerId), eq(documents.projectId, projectId)))
        .limit(1);

      if (relatedDocs.length === 0) {
        return res.status(400).json({ message: "No document found for this project to attach photos to" });
      }

      let imageBuffer = file.buffer;
      let fileName = file.originalname;
      try {
        const sharp = (await import("sharp")).default;
        imageBuffer = await sharp(file.buffer)
          .resize(600, 600, { fit: "inside", withoutEnlargement: true })
          .jpeg({ quality: 55, mozjpeg: true })
          .toBuffer();
        fileName = fileName.replace(/\.[^.]+$/, '.jpg');
      } catch {}

      const { ObjectStorageService } = await import("./replit_integrations/object_storage/objectStorage");
      const objService = new ObjectStorageService();
      const uploadURL = await objService.getObjectEntityUploadURL();
      const putRes = await fetch(uploadURL, { method: "PUT", body: imageBuffer, headers: { "Content-Type": "image/jpeg" } });
      if (!putRes.ok) throw new Error(`Upload PUT failed: ${putRes.status}`);
      const storageKey = objService.normalizeObjectEntityPath(uploadURL);

      const [photo] = await db.insert(documentPhotos).values({
        documentId: relatedDocs[0].id,
        userId: ownerId,
        fileName,
        storageKey,
        caption: null,
        sortOrder: 0,
      }).returning();

      const crewProjectDocs = await db.select().from(documents)
        .where(and(eq(documents.projectId, projectId), eq(documents.userId, ownerId)));
      for (const pd of crewProjectDocs) {
        if (pd.type === "proposal" || pd.type === "estimate") {
          const content = (pd.content || {}) as Record<string, unknown>;
          const hiddenIds: number[] = Array.isArray(content.hiddenDocumentPhotoIds)
            ? content.hiddenDocumentPhotoIds as number[]
            : [];
          if (!hiddenIds.includes(photo.id)) {
            hiddenIds.push(photo.id);
            await db.update(documents)
              .set({ content: { ...content, hiddenDocumentPhotoIds: hiddenIds } })
              .where(eq(documents.id, pd.id));
          }
        }
      }

      const [user] = await db.select({ firstName: users.firstName, lastName: users.lastName })
        .from(users).where(eq(users.id, userId));
      const userName = [user?.firstName, user?.lastName].filter(Boolean).join(' ') || 'Team member';
      await storage.createProjectActivity(ownerId, { projectId, type: 'photo', content: `${userName} uploaded a photo` });

      emitToUser(ownerId, ownerId, { type: "document.updated", tenantId: ownerId, documentId: relatedDocs[0].id });
      emitToUser(ownerId, ownerId, { type: "project.updated", tenantId: ownerId, projectId });

      res.status(201).json(photo);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

