  // 4. Owner approves a pending receipt - AI extracts data and creates expense
  app.post("/api/projects/:projectId/receipts/:receiptId/approve", isAuthenticated, async (req, res) => {
    try {
      const userId = req.user?.claims?.sub as string;
      const projectId = parseInt(req.params.projectId);
      const receiptId = parseInt(req.params.receiptId);
      if (isNaN(projectId) || isNaN(receiptId)) return res.status(400).json({ message: "Invalid IDs" });

      const resolved = await resolveUserCapabilities(userId);
      if (!resolved.isOwner) return res.status(403).json({ message: "Only owners can approve receipts" });

      const submission = await storage.getCrewReceiptSubmission(receiptId);
      if (!submission || submission.projectId !== projectId || submission.ownerId !== userId) {
        return res.status(404).json({ message: "Receipt submission not found" });
      }
      if (submission.status !== 'pending') {
        return res.status(400).json({ message: "Receipt is not pending" });
      }

      let extractedData: { title: string | null; amount: number | null; vendor: string | null; category: string | null; receiptDate: string | null } = {
        title: submission.title || null,
        amount: submission.amount || null,
        vendor: submission.vendor || null,
        category: submission.category || null,
        receiptDate: submission.receiptDate ? new Date(submission.receiptDate).toISOString().split('T')[0] : null,
      };

      if (!extractedData.amount) {
        try {
          const objService = new ObjectStorageService();
          const storageKeyPath = submission.storageKey.startsWith('/objects/') ? submission.storageKey : `/objects/${submission.storageKey}`;
          const objectFile = await objService.getObjectEntityFile(storageKeyPath);
          const [imageBufferArr] = await objectFile.download();
          if (imageBufferArr) {
            const imageBuffer = Buffer.from(imageBufferArr);
            const base64Image = imageBuffer.toString("base64");
            const mimeType = "image/jpeg";

            const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
            const aiResponse = await openai.chat.completions.create({
              model: "gpt-4o-mini",
              messages: [
                {
                  role: "system",
                  content: `You are a receipt scanner for a painting contractor business. Extract the following from the receipt image and return ONLY valid JSON with these fields:
- "amount": total amount as a number (e.g. 45.99). Use the total/grand total if visible, otherwise the largest amount.
- "vendor": store or vendor name (e.g. "Home Depot", "Sherwin-Williams")
- "category": one of these categories that best fits: "Materials", "Paint & Supplies", "Equipment Rental", "Subcontractor", "Travel/Gas", "Permits", "Dump/Disposal", "Food/Meals", "Other"
- "title": a short 2-5 word description of what was purchased (e.g. "Interior paint supplies", "Primer and rollers")
- "receiptDate": the date on the receipt in ISO format "YYYY-MM-DD" (e.g. "2025-03-15"). Look for date/time printed on the receipt.

If you cannot determine a field, use null. Return ONLY the JSON object, no markdown.`
                },
                {
                  role: "user",
                  content: [
                    { type: "text", text: "Scan this receipt and extract the expense details." },
                    { type: "image_url", image_url: { url: `data:${mimeType};base64,${base64Image}` } }
                  ]
                }
              ],
              max_tokens: 500,
            });

            const content = aiResponse.choices[0]?.message?.content || "{}";
            try {
              const cleaned = content.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
              const parsed = JSON.parse(cleaned);
              extractedData = {
                title: parsed.title || null,
                amount: parsed.amount != null ? Math.round(Number(parsed.amount) * 100) : null,
                vendor: parsed.vendor || null,
                category: parsed.category || null,
                receiptDate: parsed.receiptDate || null,
              };
            } catch {}
          }
        } catch (aiErr: any) {
          console.error("[Crew Receipts] AI extraction failed (continuing with null values):", aiErr.message);
        }
      }

      const expenseTitle = extractedData.title || 'Receipt submission';
      const expenseAmount = extractedData.amount || 0;

      const [submitter] = await db.select({ firstName: users.firstName, lastName: users.lastName })
        .from(users).where(eq(users.id, submission.userId));
      const submitterName = [submitter?.firstName, submitter?.lastName].filter(Boolean).join(' ') || 'Team member';

      const reimbursementDesc = submission.paidByWorker
        ? `Reimbursement owed to ${submitterName}`
        : null;

      const expense = await storage.createProjectExpense(userId, {
        projectId,
        title: expenseTitle,
        amount: expenseAmount,
        category: extractedData.category || null,
        vendor: extractedData.vendor || null,
        receiptDate: extractedData.receiptDate ? new Date(extractedData.receiptDate) : null,
        receiptImageUrl: submission.storageKey,
        description: reimbursementDesc,
      });

      const updated = await storage.updateCrewReceiptSubmission(receiptId, {
        status: 'approved',
        title: extractedData.title,
        amount: extractedData.amount,
        vendor: extractedData.vendor,
        category: extractedData.category,
        receiptDate: extractedData.receiptDate ? new Date(extractedData.receiptDate) : null,
        expenseId: expense.id,
        workerReimbursementAmount: submission.paidByWorker ? expenseAmount : null,
      });

      const reimbNote = submission.paidByWorker ? ` (reimbursement owed to ${submitterName})` : '';
      await storage.createProjectActivity(userId, {
        projectId, type: 'system',
        content: `Approved receipt from ${submitterName}: ${expenseTitle}${expenseAmount ? ` ($${(expenseAmount / 100).toFixed(2)})` : ''}${reimbNote}`
      });

      emitToUser(userId, userId, { type: "expense.updated", tenantId: userId, projectId });
      emitToUser(userId, userId, { type: "project.updated", tenantId: userId, projectId });
      if (submission.userId !== userId) {
        emitToUser(submission.userId, submission.userId, { type: "expense.updated", tenantId: submission.userId, projectId });
      }

      res.json(updated);
    } catch (err: any) {
      console.error("[Crew Receipts] Approve error:", err);
      res.status(500).json({ message: err.message || "Failed to approve receipt" });
    }
  });

