  app.delete("/api/crew-notes/:id", isAuthenticated, async (req, res) => {
    try {
      const userId = req.user?.claims?.sub as string;
      const resolved = await resolveUserCapabilities(userId);
      if (!resolved.isOwner) return res.status(403).json({ message: "Only owners can delete crew notes" });

      const noteId = parseInt(req.params.id);
      if (isNaN(noteId)) return res.status(400).json({ message: "Invalid ID" });

      const [note] = await db.select().from(projectCrewNotes)
        .where(and(eq(projectCrewNotes.id, noteId), eq(projectCrewNotes.companyOwnerId, userId)))
        .limit(1);
      if (!note) return res.status(404).json({ message: "Note not found" });

      await db.delete(projectCrewNoteReads).where(eq(projectCrewNoteReads.noteId, noteId));
      await db.delete(projectCrewNotes).where(and(eq(projectCrewNotes.id, noteId), eq(projectCrewNotes.companyOwnerId, userId)));

      emitToUser(userId, userId, { type: "crew_note.updated", tenantId: userId });

      res.json({ success: true });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/paint-colors", isAuthenticated, async (req, res) => {
    try {
      const brand = req.query.brand as string | undefined;
      const family = req.query.family as string | undefined;
      const search = req.query.search as string | undefined;

      const conditions = [eq(paintColors.active, true)];
      if (brand) {
        conditions.push(eq(paintColors.brand, brand));
      }
      if (family) {
        conditions.push(eq(paintColors.family, family));
      }
      if (search) {
        conditions.push(
          or(
            ilike(paintColors.name, `%${search}%`),
            ilike(paintColors.code, `%${search}%`)
          )!
        );
      }

      const colors = await db.select().from(paintColors)
        .where(and(...conditions))
        .orderBy(asc(paintColors.family), asc(paintColors.name));

      res.json(colors);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

