  app.post("/api/paint-colors/lookup", isAuthenticated, async (req, res) => {
    try {
      const { query } = req.body;
      if (!query || typeof query !== 'string' || query.trim().length < 2) {
        return res.status(400).json({ message: "Please provide a color name or code to look up" });
      }

      const openai = new OpenAI();
      const completion = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [
          {
            role: "system",
            content: `You are a paint color expert. The user will give you a paint color name, code, or description. Identify the exact paint color and return ONLY a JSON object with these fields:
- brand: the paint brand (e.g. "Benjamin Moore", "Sherwin-Williams", "PPG", "Behr", "Farrow & Ball")
- code: the official color code (e.g. "OC-17", "SW 7015", "2129-60")
- name: the official color name (e.g. "White Dove", "Repose Gray")
- hexColor: the approximate hex color code (e.g. "#f3efe6")
- family: the color family (e.g. "White", "Gray", "Blue", "Green", "Pink", "Red", "Yellow", "Orange", "Purple", "Brown", "Neutral", "Black")

If you cannot identify the exact color, return {"error": "Could not identify this color. Please try a more specific name or code."}.
Return ONLY valid JSON, no markdown or explanation.`
          },
          { role: "user", content: query.trim() }
        ],
        temperature: 0.1,
        max_tokens: 200,
      });

      const raw = completion.choices[0]?.message?.content?.trim() || '';
      let parsed;
      try {
        const jsonStr = raw.replace(/^```json\s*/, '').replace(/```\s*$/, '');
        parsed = JSON.parse(jsonStr);
      } catch {
        return res.status(400).json({ message: "Could not identify this color. Please try a more specific name or code." });
      }

      if (parsed.error) {
        return res.status(400).json({ message: parsed.error });
      }

      if (!parsed.brand || !parsed.code || !parsed.name || !parsed.hexColor) {
        return res.status(400).json({ message: "Could not identify this color. Please try a more specific name or code." });
      }

      const [existing] = await db.select().from(paintColors)
        .where(and(eq(paintColors.code, parsed.code), eq(paintColors.brand, parsed.brand)))
        .limit(1);

      if (existing) {
        return res.json({ ...existing, alreadyExists: true });
      }

      return res.json({
        brand: parsed.brand,
        code: parsed.code,
        name: parsed.name,
        hexColor: parsed.hexColor,
        family: parsed.family || 'Other',
        alreadyExists: false,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  const colorImageUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 10 * 1024 * 1024 } });
  app.post("/api/projects/:id/colors/:selectionId/image", isAuthenticated, colorImageUpload.single("image"), async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const projectId = parseInt(req.params.id);
      const selectionId = parseInt(req.params.selectionId);
      if (isNaN(projectId) || isNaN(selectionId)) return res.status(400).json({ message: "Invalid ID" });

      if (!req.file) return res.status(400).json({ message: "No image provided" });

      const allowedMimes = ["image/jpeg", "image/png", "image/webp", "image/gif"];
      if (!allowedMimes.includes(req.file.mimetype)) {
        return res.status(400).json({ message: "Invalid file type. Only JPEG, PNG, WebP, and GIF are allowed." });
      }

      let imageBuffer = req.file.buffer;
      try {
        const sharp = (await import("sharp")).default;
        const compressed = await sharp(req.file.buffer)
          .resize(600, 600, { fit: "inside", withoutEnlargement: true })
          .jpeg({ quality: 55, mozjpeg: true })
          .toBuffer();
        console.log("[ColorImage] Compressed:", (req.file.buffer.length / 1024).toFixed(0) + "KB →", (compressed.length / 1024).toFixed(0) + "KB");
        imageBuffer = compressed;
      } catch (e) {
        console.log("[ColorImage] Compression skipped, using original");
      }

      const { ObjectStorageService } = await import("./replit_integrations/object_storage/objectStorage.js");
      const objService = new ObjectStorageService();

      const uploadURL = await objService.getObjectEntityUploadURL();

      const putRes = await fetch(uploadURL, {
        method: "PUT",
        body: imageBuffer,
        headers: { "Content-Type": "image/jpeg" },
      });
      if (!putRes.ok) {
        console.error("[ColorImage] Upload PUT failed:", putRes.status);
        return res.status(500).json({ message: "Upload failed" });
      }

      const imageUrl = objService.normalizeObjectEntityPath(uploadURL);

      const [updated] = await db.update(projectColorSelections)
        .set({ customImage: imageUrl })
        .where(and(
          eq(projectColorSelections.id, selectionId),
          eq(projectColorSelections.userId, userId),
          eq(projectColorSelections.projectId, projectId)
        ))
        .returning();

      if (!updated) return res.status(404).json({ message: "Selection not found" });
      res.json(updated);
    } catch (err: any) {
      console.error("[ColorImage] Upload error:", err);
      res.status(500).json({ message: err.message });
    }
  });

