  app.patch("/api/color-groups/:id", isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ message: "Invalid id" });

      const patchSchema = insertProjectColorGroupSchema.partial().omit({ userId: true, projectId: true });
      const parsed = patchSchema.parse(req.body);

      const [existing] = await db.select().from(projectColorGroups)
        .where(and(eq(projectColorGroups.id, id), eq(projectColorGroups.userId, userId)));
      if (!existing) return res.status(404).json({ message: "Group not found" });

      // Enforce surface exclusivity across groups within the same project
      if (Array.isArray(parsed.surfaces) && parsed.surfaces.length > 0) {
        const otherGroups = await db.select().from(projectColorGroups)
          .where(and(
            eq(projectColorGroups.userId, userId),
            eq(projectColorGroups.projectId, existing.projectId),
          ));
        const conflicts = otherGroups
          .filter((g: any) => g.id !== id)
          .flatMap((g: any) => (g.surfaces || []).filter((s: string) => parsed.surfaces!.includes(s)).map((s: string) => ({ surface: s, groupName: g.name })));
        if (conflicts.length > 0) {
          return res.status(409).json({
            message: `Surfaces already in another group: ${conflicts.map(c => `"${c.surface}" (${c.groupName})`).join(', ')}`,
            conflicts,
          });
        }
      }

      const [updated] = await db.update(projectColorGroups)
        .set(parsed)
        .where(and(eq(projectColorGroups.id, id), eq(projectColorGroups.userId, userId)))
        .returning();

      emitToUser(userId, userId, { type: "colors.updated", tenantId: userId, projectId: existing.projectId });
      emitColorReviewForProject(userId, existing.projectId);

      // If color metadata changed, propagate to all surfaces in the group
      const colorFieldsChanged = ['paintColorId', 'customColorName', 'customHex', 'finish'].some(f => f in parsed);
      if (colorFieldsChanged && updated && Array.isArray(updated.surfaces)) {
        for (const area of updated.surfaces) {
          const [existingSel] = await db.select().from(projectColorSelections)
            .where(and(
              eq(projectColorSelections.userId, userId),
              eq(projectColorSelections.projectId, existing.projectId),
              eq(projectColorSelections.area, area),
            ));
          const payload: any = {
            userId,
            projectId: existing.projectId,
            area,
            paintColorId: updated.paintColorId || null,
            customColorName: updated.customColorName || null,
            customHex: updated.customHex || null,
            sheen: updated.finish || null,
            notes: existingSel?.notes || null,
          };
          if (existingSel) {
            await db.update(projectColorSelections).set(payload).where(eq(projectColorSelections.id, existingSel.id));
          } else {
            await db.insert(projectColorSelections).values(payload);
          }
        }
      }

      res.json(updated);
    } catch (err: any) {
      res.status(400).json({ message: err.message });
    }
  });

