  // Contractor-to-customer note for a standalone section card (production-rate room or manual section).
  // Stored on color_submissions.section_notes keyed by sectionId (room.id).
  app.patch("/api/projects/:id/color-submission/section-note", isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const projectId = parseInt(req.params.id);
      if (isNaN(projectId)) return res.status(400).json({ message: "Invalid project ID" });

      const { sectionId, note } = req.body;
      if (!sectionId || typeof sectionId !== 'string') return res.status(400).json({ message: "sectionId required" });
      if (typeof note !== 'string') return res.status(400).json({ message: "note must be a string" });

      const [existingSub] = await db.select().from(colorSubmissions)
        .where(and(eq(colorSubmissions.userId, userId), eq(colorSubmissions.projectId, projectId)))
        .orderBy(desc(colorSubmissions.createdAt))
        .limit(1);

      if (!existingSub) return res.status(404).json({ message: "No color submission found" });

      const current = (existingSub.sectionNotes as Record<string, string> | null) || {};
      const next = { ...current };
      const trimmed = note.slice(0, 500);
      if (trimmed === '') delete next[sectionId];
      else next[sectionId] = trimmed;

      await db.update(colorSubmissions)
        .set({ sectionNotes: next })
        .where(eq(colorSubmissions.id, existingSub.id));

      emitToUser(userId, userId, { type: "colors.updated", tenantId: userId, projectId });
      emitColorReviewForProject(userId, projectId);
      res.json({ success: true });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/projects/:id/color-submission/:subId/send", isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const projectId = parseInt(req.params.id);
      const subId = parseInt(req.params.subId);
      if (isNaN(subId) || isNaN(projectId)) return res.status(400).json({ message: "Invalid ID" });

      const [submission] = await db.select().from(colorSubmissions)
        .where(and(eq(colorSubmissions.id, subId), eq(colorSubmissions.userId, userId), eq(colorSubmissions.projectId, projectId)));
      if (!submission) return res.status(404).json({ message: "Submission not found" });

      const settings = await storage.getCompanySettings(userId);
      const link = buildColorSubmissionLink(req, submission.customerToken || '', settings);

      const project = await storage.getProject(userId, projectId);
      const contact = project?.contactId ? await storage.getContact(userId, project.contactId) : null;

      const { viaSms, viaEmail, smsMessage, emailSubject, emailBody } = req.body;

      const smsBody = smsMessage || `Hi ${contact?.name || 'there'}, your color selections are ready for review: ${link}`;
      const emailBodyText = emailBody || `Hi ${contact?.name || 'there'},\n\nYour color selections for your project are ready for review. Please click the button below to view and approve them.`;
      const emailSubjectText = emailSubject || 'Your Color Selections Are Ready';

      const existingLog3: any[] = (submission.activityLog as any[]) || [];
      const methods: string[] = [];
      if (viaSms) methods.push('SMS');
      if (viaEmail) methods.push('email');
      const logEntry3 = { action: 'sent_to_customer', timestamp: new Date().toISOString(), actor: 'contractor', note: methods.length > 0 ? 'Sending via ' + methods.join(' & ') : 'Link shared' };

      const sendUpdateData: any = { status: 'sent', activityLog: [...existingLog3, logEntry3] };
      if ((submission as any).customerApproved) {
        sendUpdateData.customerApproved = false;
        sendUpdateData.customerApprovedAt = null;
      }
      await db.update(colorSubmissions)
        .set(sendUpdateData)
        .where(eq(colorSubmissions.id, subId));

      emitToUser(userId, userId, { type: "colors.updated", tenantId: userId, projectId });
      emitColorReviewForProject(userId, projectId);
      res.json({ smsOk: !!viaSms, emailOk: !!viaEmail, link });

      const sendTasks: Promise<void>[] = [];

      if (viaSms && contact?.phone) {
        sendTasks.push((async () => {
          try {
            const { sendSms: sendSmsFn } = await import('./sms-provider.js');
            const result = await sendSmsFn(settings, {
              to: toE164(contact.phone),
              body: smsBody,
            });
            const comm = await createOutboundComm(userId, {
              contactId: contact.id,
              phoneNumber: contact.phone,
              type: 'sms',
              direction: 'outbound',
              content: smsBody,
              messageSid: result?.sid || null,
            });
            emitToUser(userId, userId, {
              type: "message.created",
              tenantId: userId,
              contactId: contact.id,
              projectId: null,
              payload: { id: comm?.id, contactId: contact.id, content: smsBody, direction: 'outbound', type: 'sms', timestamp: new Date().toISOString(), projectId: null },
            });
          } catch (err: any) {
            console.error('[ColorSubmission] SMS send failed:', err.message);
          }
        })());
      }

      if (viaEmail && contact?.email) {
        sendTasks.push((async () => {
          try {
            const smtpEmail = await import('./smtpEmail.js');
            const html = wrapEmailInTemplate(emailBodyText, {
              companyName: settings?.companyName || '',
              companyLogo: settings?.logoUrl || undefined,
              companyPhone: settings?.phone || undefined,
              companyEmail: settings?.email || undefined,
              companyWebsite: settings?.website || undefined,
              accentColor: settings?.brandColor || '#2563eb',
              ctaText: 'View Color Selections',
              ctaUrl: link,
            });
            await smtpEmail.sendEmailWithFallback(userId, {
              to: contact.email,
              subject: emailSubjectText,
              html,
            }, settings);
            const comm = await createOutboundComm(userId, {
              contactId: contact.id,
              phoneNumber: contact.email,
              type: 'email',
              direction: 'outbound',
              content: `[Color Selections] ${emailSubjectText}\n\n${emailBodyText}`,
            });
            emitToUser(userId, userId, {
              type: "message.created",
              tenantId: userId,
              contactId: contact.id,
              projectId: null,
              payload: { id: comm?.id, contactId: contact.id, content: `[Color Selections] ${emailSubjectText}`, direction: 'outbound', type: 'email', timestamp: new Date().toISOString(), projectId: null },
            });
          } catch (err: any) {
            console.error('[ColorSubmission] Email send failed:', err.message);
          }
        })());
      }

      Promise.all(sendTasks).then(async () => {
        const sentMethods: string[] = [];
        if (viaSms) sentMethods.push('SMS');
        if (viaEmail) sentMethods.push('email');
        if (sentMethods.length > 0) {
          await logProjectActivity(userId, projectId, 'color_submission_sent', `Color selection form sent via ${sentMethods.join(' & ')}${contact?.name ? ` to ${contact.name}` : ''}`);
        }
      }).catch(err => console.error('[ColorSubmission] Post-send tasks failed:', err));
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.patch("/api/projects/:id/color-submission/:subId/deadline", isAuthenticated, async (req, res) => {
    try {
      const userId = await getEffectiveUserId(req);
      const projectId = parseInt(req.params.id);
      const subId = parseInt(req.params.subId);
      if (isNaN(subId) || isNaN(projectId)) return res.status(400).json({ message: "Invalid ID" });
      const { deadline } = req.body;
      if (!deadline) return res.status(400).json({ message: "Deadline is required" });
      const deadlineVal = new Date(deadline);
      if (isNaN(deadlineVal.getTime())) return res.status(400).json({ message: "Invalid deadline date" });
      await db.update(colorSubmissions)
        .set({ deadline: deadlineVal })
        .where(and(
          eq(colorSubmissions.id, subId),
          eq(colorSubmissions.userId, userId),
          eq(colorSubmissions.projectId, projectId)
        ));
      res.json({ success: true, deadline: deadlineVal });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

