      const [updated] = await db.update(colorSubmissions)
        .set({
          customerApproved: true,
          customerApprovedAt: new Date(),
          customerNote: note || submission.customerNote || null,
          customerSignature: signature || null,
          customerSignedAt: new Date(),
          status: newStatus,
          activityLog: [...existingLog2, logEntry2],
        })
        .where(eq(colorSubmissions.id, submission.id))
        .returning();

