  // ===== TEMPORARY: One-time DripJobs import endpoint =====
  app.post('/api/admin/import-dripjobs', isAuthenticated, async (req, res) => {
    const sessionUserId = await getEffectiveUserId(req);
    if (sessionUserId !== GAMA_USER_ID_ARCHIVE) {
      return res.status(403).json({ error: 'Unauthorized' });
    }
    const userId = GAMA_USER_ID_ARCHIVE;

    try {
      let csvData = req.body.csvData as string;
      if (!csvData) {
        const fs = await import('fs');
        const csvPath = 'attached_assets/Jobs_List_20260408_111323_1775735129949.csv';
        if (fs.existsSync(csvPath)) {
          csvData = fs.readFileSync(csvPath, 'utf-8');
        } else {
          return res.status(400).json({ error: 'csvData required and CSV file not found on disk' });
        }
      }

      function parseCSVLine(line: string): string[] {
        const result: string[] = [];
        let current = '';
        let inQuotes = false;
        for (let i = 0; i < line.length; i++) {
          const ch = line[i];
          if (ch === '"') { inQuotes = !inQuotes; }
          else if (ch === ',' && !inQuotes) { result.push(current.trim()); current = ''; }
          else { current += ch; }
        }
        result.push(current.trim());
        return result;
      }

      function parseDollar(val: string): number {
        const cleaned = val.replace(/[$,()]/g, '').trim();
        const num = parseFloat(cleaned);
        return isNaN(num) ? 0 : Math.round(num * 100);
      }

      function parseDate(val: string): Date | null {
        if (!val || val === 'Accepted without signature' || val === 'N/A') return null;
        const d = new Date(val);
        return isNaN(d.getTime()) ? null : d;
      }

      function normalizePhone(phone: string): string {
        return phone.replace(/\D/g, '').slice(-10);
      }

      function estimateEndDate(startDate: Date, amountCents: number): string {
        const amount = amountCents / 100;
        let days: number;
        if (amount < 1000) days = 1;
        else if (amount < 2000) days = 2;
        else if (amount < 4000) days = 3;
        else if (amount < 6000) days = 5;
        else if (amount < 10000) days = 10;
        else if (amount < 20000) days = 15;
        else days = 21;
        const end = new Date(startDate);
        end.setDate(end.getDate() + days);
        return end.toISOString().split('T')[0];
      }

      const lines = csvData.split('\n').filter((l: string) => l.trim());
      const dataLines = lines.slice(1);

      const allContacts = await storage.getContacts(userId);
      const contactByPhone = new Map<string, any>();
      for (const c of allContacts) {
        const norm = normalizePhone(c.phone);
        if (norm.length >= 10) contactByPhone.set(norm, c);
      }

      const notMatched: any[] = [];
      const imported: any[] = [];
      const skippedRows: any[] = [];
      let projectsCreated = 0;
      let invoicesCreated = 0;

      for (let i = 0; i < dataLines.length; i++) {
        const fields = parseCSVLine(dataLines[i]);
        if (fields.length < 22) continue;

        const [status, label, jobName, firstName, lastName, email, phone,
          salesperson, projectManager, crew, proposalId, invoiceId,
          invoiceStatus, amount, paid, balance, dealStage, dealStageDate,
          proposalSignedDate, jobScheduleDate, jobStartDate, jobCompletionDate] = fields;

        const fullName = `${firstName} ${lastName}`.trim();

        const isVoided = invoiceStatus === 'Voided' || invoiceStatus === 'Cancelled';

        const normPhone = normalizePhone(phone);
        const contact = contactByPhone.get(normPhone);

        if (!contact) {
          notMatched.push({ line: i + 2, name: fullName, phone, email });
          continue;
        }

        const amountCents = parseDollar(amount);
        const signedDate = parseDate(proposalSignedDate);
        const stageDate = parseDate(dealStageDate);
        const startDate = signedDate || stageDate || new Date('2023-01-01');
        const scheduledDateStr = startDate.toISOString().split('T')[0];
        const endDateStr = estimateEndDate(startDate, amountCents);
        const completionDate = stageDate || signedDate || new Date();

        const project = await storage.createProject(userId, {
          contactId: contact.id,
          title: jobName || `${fullName} - DripJobs Import`,
          stage: isVoided ? 'cancelled' : 'completed',
          source: contact.leadSource || 'other',
          totalAmount: amountCents,
          scheduledDate: scheduledDateStr,
          scheduledEndDate: endDateStr,
        } as any);

        await db.update(projects).set({
          stageChangedAt: completionDate,
          createdAt: startDate,
          updatedAt: completionDate,
        }).where(eq(projects.id, project.id));

        projectsCreated++;

        await storage.createProjectActivity(userId, {
          projectId: project.id,
          type: 'system',
          content: `Imported from DripJobs (Proposal #${proposalId}${invoiceId ? `, Invoice ${invoiceId}` : ''})`,
        });

        if (invoiceId && invoiceId.trim()) {
          const projectTitle = jobName || `${fullName} - DripJobs Import`;
          const paymentSchedule = {
            depositRequired: false,
            depositType: 'fixed' as const,
            depositAmount: 0,
            schedule: [{
              label: 'Full Payment',
              amount: amountCents / 100,
              dueCondition: 'Upon completion',
              paid: true,
              paidAt: completionDate.toISOString(),
            }],
            showPaymentSchedule: false,
          };

          const docContent = {
            items: [{
              id: crypto.randomUUID(),
              description: projectTitle,
              quantity: 1,
              unitPrice: amountCents,
              total: amountCents,
            }],
            notes: `Imported from DripJobs. Original Invoice: ${invoiceId}`,
            paymentSettings: paymentSchedule,
          };

          const doc = await storage.createDocument(userId, {
            contactId: contact.id,
            projectId: project.id,
            type: 'invoice',
            status: 'paid',
            title: `Invoice - ${projectTitle}`,
            content: docContent as any,
            totalAmount: amountCents,
          } as any);

          await db.update(documents).set({
            signedAt: signedDate,
            createdAt: startDate,
            updatedAt: completionDate,
          }).where(eq(documents.id, doc.id));

          invoicesCreated++;
        }

        imported.push({ name: fullName, amount, contactId: contact.id, projectId: project.id });
      }

      res.json({
        success: true,
        projectsCreated,
        invoicesCreated,
        skipped: skippedRows,
        notMatched,
        imported: imported.length,
        importedDetails: imported,
      });
    } catch (err: any) {
      console.error('[DripJobs Import] Error:', err);
      res.status(500).json({ error: err.message });
    }
  });
  // ===== TEMPORARY: DripJobs Archive Portal =====
  const GAMA_USER_ID_ARCHIVE = 'd919045f-db56-4f2b-abfc-6bdfe83e27b5';
  const archiveSessions = new Map<string, { email: string; expiresAt: number }>();

  function createArchiveToken(): string {
    const { randomBytes } = require('crypto');
    return randomBytes(32).toString('hex');
  }

  function getArchiveToken(req: any): string | null {
    const auth = req.headers['x-archive-token'] as string;
    return auth || null;
  }

  async function isArchiveAuthorized(req: any): Promise<boolean> {
    const sessionUserId = (req.session as any)?.userId;
    if (sessionUserId) {
      const [u] = await db.select({ isAdmin: users.isAdmin }).from(users).where(eq(users.id, sessionUserId));
      if (u?.isAdmin) return true;
    }
    const token = getArchiveToken(req);
    if (token && archiveSessions.has(token)) {
      const session = archiveSessions.get(token)!;
      if (session.expiresAt > Date.now()) return true;
      archiveSessions.delete(token);
    }
    return false;
  }

  app.get('/api/archive/auth-status', async (req, res) => {
    const token = getArchiveToken(req);
    if (token && archiveSessions.has(token)) {
      const session = archiveSessions.get(token)!;
      if (session.expiresAt > Date.now()) {
        return res.json({ authenticated: true, email: session.email, isOwner: false });
      }
      archiveSessions.delete(token);
    }
    const sessionUserId = (req.session as any)?.userId;
    if (sessionUserId) {
      const [u] = await db.select({ isAdmin: users.isAdmin }).from(users).where(eq(users.id, sessionUserId));
      if (u?.isAdmin) {
        return res.json({ authenticated: true, email: 'owner', isOwner: true });
      }
    }
    return res.json({ authenticated: false });
  });

  function parseFreelancerEmails(raw: string | null): string[] {
    if (!raw) return [];
    try {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed.map((e: string) => e.toLowerCase().trim()).filter(Boolean);
    } catch {}
    if (raw.includes('@')) return [raw.toLowerCase().trim()];
    return [];
  }

