  app.post('/api/archive/send-otp', async (req, res) => {
    const { email } = req.body;
    if (!email || typeof email !== 'string') return res.status(400).json({ error: 'Email required' });
    const normalizedEmail = email.toLowerCase().trim();

    const [settings] = await db.select({ archiveFreelancerEmail: companySettings.archiveFreelancerEmail }).from(companySettings).where(eq(companySettings.userId, GAMA_USER_ID_ARCHIVE));
    const allowedEmails = parseFreelancerEmails(settings?.archiveFreelancerEmail || null);
    if (!allowedEmails.includes(normalizedEmail)) {
      return res.status(403).json({ error: 'This email is not authorized for archive access.' });
    }

    const { generateOTP, sendOtpEmail } = await import("./otp");
    const ip = (req.headers['x-forwarded-for'] as string || req.ip || '').split(',')[0].trim();
    const result = await generateOTP(normalizedEmail, ip);
    if (!result.success) return res.status(429).json({ error: result.error });

    const sent = await sendOtpEmail(normalizedEmail, result.code!);
    if (!sent) return res.status(500).json({ error: 'Failed to send email. Try again.' });

    res.json({ success: true });
  });

  app.post('/api/archive/verify-otp', async (req, res) => {
    const { email, code } = req.body;
    if (!email || !code) return res.status(400).json({ error: 'Email and code required' });
    const normalizedEmail = email.toLowerCase().trim();

    const [settings] = await db.select({ archiveFreelancerEmail: companySettings.archiveFreelancerEmail }).from(companySettings).where(eq(companySettings.userId, GAMA_USER_ID_ARCHIVE));
    const allowedEmails2 = parseFreelancerEmails(settings?.archiveFreelancerEmail || null);
    if (!allowedEmails2.includes(normalizedEmail)) {
      return res.status(403).json({ error: 'Unauthorized' });
    }

    const { verifyOTP } = await import("./otp");
    const result = await verifyOTP(normalizedEmail, code);
    if (!result.valid) return res.status(400).json({ error: result.error, remainingAttempts: result.remainingAttempts });

    const token = createArchiveToken();
    archiveSessions.set(token, { email: normalizedEmail, expiresAt: Date.now() + 4 * 60 * 60 * 1000 });
    res.json({ success: true, token });
  });

